// Maps stream from the disc's WORLD.PAK at runtime (no longer baked into the
// EXE). MAP_BUF holds either one temporary texture chunk or one resident map
// chunk; build.rs sizes it from data/rooms. The Rust asset build cooks room N as
// room_<2N>.psxc (resident HLMF) and room_<2N+1>.psxc (temporary HLTX textures).
const MAP_WORDS: usize = room_budget::MAP_WORDS;
const MODEL_WORDS: usize = room_budget::MODEL_WORDS;
// The map and the model pool share ONE arena instead of owning a fixed buffer
// each. Both used to be sized by their own fleet-worst map, but those worsts sit
// on different maps: the biggest BSP (c2a4c) carries a light roster and the
// heaviest roster (c1a2b) sits on a small BSP, so sizing them separately paid
// for a map that does not exist. The arena is still MAP_WORDS + MODEL_WORDS, so
// a map that fills the staging capacity outright still gets exactly the old
// pool -- but the pool starts where the *loaded* map ends, so a 603 KiB map on a
// 928 KiB arena gets 325 KiB of models instead of 219. Every map is >= its old
// budget and most are far above it; nothing shrank to pay for it.
const ARENA_WORDS: usize = MAP_WORDS + MODEL_WORDS;
static mut WORLD_ARENA: [u32; ARENA_WORDS] = [0; ARENA_WORDS];
/// First arena word owned by the model pool. Conservative (= the full staging
/// capacity, i.e. the old fixed split) until a map is resident, because model
/// streaming only ever runs after `Map::load`.
static mut MODEL_BASE_WORDS: usize = MAP_WORDS;

#[inline(always)]
unsafe fn arena_ptr() -> *mut u32 {
    core::ptr::addr_of_mut!(WORLD_ARENA).cast::<u32>()
}

/// Map staging window: the arena head, at the capacity build.rs sized from the
/// largest cooked room and streamed extra.
#[inline(always)]
unsafe fn map_buf() -> &'static mut [u32] {
    core::slice::from_raw_parts_mut(arena_ptr(), MAP_WORDS)
}

#[inline(always)]
unsafe fn model_ptr() -> *mut u32 {
    arena_ptr().add(MODEL_BASE_WORDS)
}

/// Words the model pool may use on the currently loaded map.
#[inline(always)]
unsafe fn model_capacity() -> usize {
    ARENA_WORDS - MODEL_BASE_WORDS
}
static mut ACTIVE_SFX_CHUNK: u32 = 0;
// NPC/item geometry is no longer baked into the EXE: every model type streams
// from WORLD.PAK per-map into MODEL_BUF via the model pool (see stream_map_models).

// World ordering table. sz (view depth) tops out near FAR_VIEW; otz = sz>>OT_SHIFT
// indexes the table, back-to-front. Four-unit buckets keep close, layered studio
// meshes (limbs/torso, face/teeth, glasses/head) out of the same bucket, where
// the OT's prepend semantics can reverse their intended near/far relationship.
// Keep the same shift for world and models so an actor also sorts correctly
// against nearby BSP geometry. The GPU submit DMA walks the whole chain every
// frame, so keep only the slots the chosen far plane actually needs. 320
// covers 1200>>2 plus the backdrop bias without reducing depth precision.
const OT_LEN: usize = ordering::OT_LEN;
const OT_SHIFT: u32 = ordering::OT_SHIFT;
const HUD_OT_LEN: usize = 1;
const FX_OT_LEN: usize = 1;
const MAX_VERTS: usize = room_budget::MAX_VERTS; // auto-sized to the biggest cooked map
const MAX_MODEL_VERTS: usize = room_budget::MAX_MODEL_VERTS;
// One aligned u32 XY word plus one u16 depth per model vertex, rounded to the
// u32 storage used by both BSS scratch and the MODEL_BUF viewmodel overlay.
const MODEL_PROJECTED_WORDS: usize = MAX_MODEL_VERTS + MAX_MODEL_VERTS.div_ceil(2);
const SCI_FACE_CAP: usize = 768;
const BARNEY_FACE_CAP: usize = 800;
const HEADCRAB_FACE_CAP: usize = 512;
const SUIT_ITEM_FACE_CAP: usize = 448;
const BATTERY_ITEM_FACE_CAP: usize = 160;
// World/brush packets retain their existing fixed arena. Studio actors borrow
// the unused map/model arena tail when it is larger, so dense BSP views cannot
// consume their entire packet budget before the actor pass begins.
#[cfg(not(any(
    feature = "reference-trace",
    feature = "performance-telemetry",
    feature = "emulator-telemetry"
)))]
const MAX_RENDER_PACKETS: usize = 1432;
// Diagnostic code and trace storage retain their smaller packet budgets.
#[cfg(any(
    feature = "reference-trace",
    feature = "performance-telemetry",
    feature = "emulator-telemetry"
))]
const BEAM_FX_TRIM: usize = 331;
#[cfg(any(
    feature = "reference-trace",
    feature = "performance-telemetry",
    feature = "emulator-telemetry"
))]
const MODEL_STREAM_CODE_TRIM: usize = 37;

#[cfg(feature = "reference-trace")]
const MAX_RENDER_PACKETS: usize = 1472 - BEAM_FX_TRIM - MODEL_STREAM_CODE_TRIM;
// Telemetry and its interpolation state displace packet storage. Packet-drop
// counters expose that diagnostic trade; release discs keep the full budget.
#[cfg(feature = "decoupled-present")]
const DECOUPLED_PACKET_TRIM: usize = 135;
#[cfg(not(feature = "decoupled-present"))]
const DECOUPLED_PACKET_TRIM: usize = 0;
#[cfg(all(
    not(feature = "reference-trace"),
    any(feature = "performance-telemetry", feature = "emulator-telemetry")
))]
const MAX_RENDER_PACKETS: usize =
    1580 - DECOUPLED_PACKET_TRIM - BEAM_FX_TRIM - MODEL_STREAM_CODE_TRIM;

// Telemetry statics displace the intro-tram exact-view cache instead of the
// packet arena: 1,409 arena slots measurably starves the world plan on heavy
// views (16.6 vs 28.6 route fps), while a short tram cache merely renders the
// intro ride uncached.
// The c0a0 car emits far more than the old 84-triangle cap (341 faces plus
// near-clip fans), so the cache overflowed and invalidated EVERY frame of the
// intro ride -- the ride profile showed ~28% of parked CPU re-emitting the
// same car. Sized to hold the worst view; overflow still falls back safely.
#[cfg(any(feature = "performance-telemetry", feature = "emulator-telemetry"))]
const MAX_TRAM_CACHE_TRIS: usize = 128;
#[cfg(not(any(feature = "performance-telemetry", feature = "emulator-telemetry")))]
// The two targeted floor quads can each produce four GT4 cells. Their clipped
// fallback cells add only a handful of GT3s in the reproduced views, so retain
// triangle headroom while funding the complete eight-cell quad cache.
// 310 -> 128: instrumenting the whole c0a0 ride measured a PEAK of 25 cached
// triangles with zero overflow, so 310 reserved 3.7 KB that nothing used. The
// reclaimed RAM buys the decoupled build its full packet arena, which matters
// on vista views. Overflow remains graceful: the cache simply goes invalid
// and the car re-emits, exactly as it does when the camera key changes.
const MAX_TRAM_CACHE_TRIS: usize = 128;
const MAX_TRAM_CACHE_QUADS: usize = 8;
const TRAM_PACKET_CACHE: bool = true;
// Retail first-person peak is the .357 at 1,075 source triangles. Viewmodels
// use a compact u16 linked bucket sort rather than a resident packet per face,
// so every authored triangle can survive without spending ~47 KB on OT tags.
const MAX_WEAPON_TRIS: usize = 1152;
const VM_SORT_BUCKETS: usize = 64;
// Eleven bits address every authored viewmodel triangle; 0x7ff is the link
// terminator. The remaining record bits retain texture + precomputed shade.
const VM_SORT_LINK_BITS: u32 = 11;
const VM_SORT_LINK_MASK: u32 = (1 << VM_SORT_LINK_BITS) - 1;
const VM_SORT_TEX_SHIFT: u32 = VM_SORT_LINK_BITS;
const VM_SORT_SHADE_SHIFT: u32 = VM_SORT_TEX_SHIFT + 8;
const VM_SORT_NONE: u16 = VM_SORT_LINK_MASK as u16;
const MAX_TEX_SLOTS: usize = room_budget::MAX_TEX_SLOTS;
const MAX_FACES: usize = room_budget::MAX_FACES;
const MAX_FACE_GROUPS: usize = room_budget::MAX_FACE_GROUPS;
const MAX_LEAVES: usize = room_budget::MAX_LEAVES;
const MAX_ENTS: usize = room_budget::MAX_ENTS;

const MAX_PVS_FACE_RECS: usize = 1024;
const MAX_PROPS: usize = 128;
// CPU-only render scratch. Persistent viewmodel bucket heads live at the floor;
// the two face-group bitsets occupy the remaining live world-pass range. Once
// tram/world emission ends, their 896-byte tail is reused as a guarded stack
// for model projection without touching the still-live bucket heads.
const RENDER_GROUP_WORDS: usize = MAX_FACE_GROUPS / 32;
const VM_HEADS_SCRATCH_OFFSET: usize = 0;
const GROUP_VIS_SCRATCH_OFFSET: usize =
    VM_HEADS_SCRATCH_OFFSET + VM_SORT_BUCKETS * core::mem::size_of::<u16>();
const GROUP_SEEN_SCRATCH_OFFSET: usize =
    GROUP_VIS_SCRATCH_OFFSET + RENDER_GROUP_WORDS * core::mem::size_of::<u32>();
const RENDER_SCRATCH_BYTES: usize =
    GROUP_SEEN_SCRATCH_OFFSET + RENDER_GROUP_WORDS * core::mem::size_of::<u32>();

#[repr(C)]
#[derive(Clone, Copy)]
struct AffineFaceCandidate {
    face: u16,
    previous_level: u8,
    selected_level: u8,
    score_q8: u32,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct AffinePatchCandidate {
    indices: [u16; 4],
    uv: [u16; 4],
    key0: u32,
    near_depth: u16,
    screen_span: u16,
    was_split: u8,
    kind: u8,
}

const EMPTY_AFFINE_PATCH_CANDIDATE: AffinePatchCandidate = AffinePatchCandidate {
    indices: [u16::MAX; 4],
    uv: [0; 4],
    key0: u32::MAX,
    near_depth: u16::MAX,
    screen_span: 0,
    was_split: 0,
    kind: 0,
};

const AFFINE_PATCH_KIND_NATIVE: u8 = 0;
const AFFINE_PATCH_KIND_SEAMED_PAIR: u8 = 1;
const EMPTY_AFFINE_FACE_CANDIDATE: AffineFaceCandidate = AffineFaceCandidate {
    face: u16::MAX,
    previous_level: 0,
    selected_level: 0,
    score_q8: 0,
};
const AFFINE_CANDIDATE_CAP: usize = 32;
const AFFINE_SELECTED_CAP: usize = AFFINE_CANDIDATE_CAP;
const AFFINE_EDGE_CAP: usize = AFFINE_CANDIDATE_CAP * 4;
const AFFINE_EDGE_BLOOM_WORDS: usize = 8;
const AFFINE_EDGE_BLOOM_MASK: usize = AFFINE_EDGE_BLOOM_WORDS * 32 - 1;
// One selected patch emits three extra packets. Each of its four edge-sharing
// neighbours may also need a regular 2x2 grid to keep the mesh conforming, for
// a strict worst case of fifteen extra packets per request. Keep a wider proof
// window than the six-request maximum admission budget: exact affine error is
// evaluated only after this cheap shortlist is complete.
// Regression telemetry deliberately fails if the window is ever too small to
// prove that no closer eligible patch was skipped.
const AFFINE_PATCH_CANDIDATE_CAP: usize = 16;
// One-texel buckets over 0..127 texels. This used to be 64 quarter-texel
// buckets, whose top bucket meant ">= 15.75 texels" -- but measured edge error
// reaches 91, so every reported P95/P99 saturated at 15.75 and was blind to
// the entire population the correction exists to fix. Thresholds tuned against
// that signal were tuned against a clipped number.
const AFFINE_ERROR_BUCKETS: usize = 128;
// The visibility bitsets remain live through world emission. Their 184-byte
// scratchpad tail is reserved for generated 3D midpoint/projection vertices;
// the bounded ranking table itself lives in ordinary RAM.
const AFFINE_WORKSPACE_SCRATCH_OFFSET: usize = RENDER_SCRATCH_BYTES;
const _: () = assert!(MAX_FACE_GROUPS % 32 == 0);
const _: () = assert!(RENDER_SCRATCH_BYTES <= scratchpad::SIZE);
// Fifteen transition records borrow the prop-neighbour rows that campaign
// cooks never reach. Runtime live props are capped at 113, so a final tick can
// neither read nor overwrite the mailbox after the changelevel snapshot.
const CARRY_CAPACITY: usize = 15;
const CARRY_MAILBOX_FIRST: usize = MAX_PROPS - CARRY_CAPACITY;
const CARRY_GLOBAL_BIT: u16 = 0x8000;
const CARRY_ID_NONE: u16 = u16::MAX;
const CARRY_TRAIN_TAG: u8 = 0xfe;
const _: () = assert!(CARRY_MAILBOX_FIRST == 113);
const _: () = assert!(CARRY_CAPACITY <= logic_state::CARRY_COUNT_MASK as usize);
const MAX_SPRITE_INSTANCES: usize = 160;
const SPRITE_STATE_WORDS: usize = MAX_SPRITE_INSTANCES.div_ceil(32);
const MAX_NAV_NODES: usize = 255;
// PROP_NEAR_ENTS keeps current MOVERS slots in each u16's low byte and uses
// the otherwise-dead high byte for the per-prop navigation memo below. Mover
// membership changes invalidate every shortlist before tick_props, so the
// packed slot always selects the current pose without storing another id.
const _: () = assert!(MAX_ENTS + 1 <= 256);
const MAX_LOGIC: usize = 384;
const MAX_LOGIC_EVENTS: usize = 64;
// Script logic indices need nine bits (MAX_LOGIC=384). While an actor owns a
// script, the otherwise-unused high nibbles of LI and authored yaw retain its
// signed-Q4 Z/X movement remainders. This is actor-local and never aliases the
// transition mailbox.
const PROP_SCRIPT_LI_MASK: u16 = 0x01FF;
const PROP_SCRIPT_LI_RESIDUE_SHIFT: u32 = 9;
const PROP_SCRIPT_YAW_MASK: u16 = 0x0FFF;
const PROP_SCRIPT_YAW_RESIDUE_SHIFT: u32 = 12;
const PROP_SCRIPT_RESIDUE_MASK: u16 = 0xF;
const _: () = assert!(MAX_LOGIC <= PROP_SCRIPT_LI_MASK as usize + 1);
// Fast-path near gate. MUST equal render::NEAR_Z: the soft path clips its
// rebuilt triangles at NEAR_Z, so if the fast path accepts closer vertices the
// two paths disagree along shared edges and the mismatch band renders as black
// wedges when looking down or hugging walls.
const NEAR: u16 = render::NEAR_Z as u16;
const CULL: bool = true; // backface cull (keep area > 0; winding verified)
const H_PROJ: u16 = 160; // ~90 deg horizontal FOV at 320px
const CROSSBOW_PROJ_H: u16 = 908; // 160 / tan(20deg / 2): GoldSrc's 20-degree zoom
const WORLD_QUAD_PAIRING: bool = true; // pair two-triangle BSP quads when safe
                                       // Keep a rejected cooked quad four-sided through the near/guard clip instead of
                                       // handing its two triangles to the recursive splitter. A/B switch: false
                                       // restores the old fan for comparison captures.
const WORLD_QUAD_SOFT_SPLIT: bool = true;
// Cold PVS classification lets ordinary opaque faces share one zero
// material/light context. Keep this as an explicit A/B switch so deterministic
// performance captures can prove the gain without changing cooked assets.
const WORLD_OPAQUE_STREAM_FAST: bool = true;
const WORLD_BOUNDS_CULL: bool = true; // face AABB frustum test before projection
                                      // PS1 POLY_GT3/GT4 packets interpolate UVs affinely. The cooker removes most
                                      // visible error with shared UV-grid cuts, but its strict per-map RAM budget
                                      // deliberately leaves fallback faces. Correct only the remaining polygons
                                      // whose projected midpoint error is both measurable and large on screen.
                                      // One source triangle/quad becomes four packets (+3); the hard parent cap and
                                      // arena reserve keep actor, weapon, and effect capacity deterministic.
                                      // Cook-time UV-grid refinement is the production affine correction. The
                                      // recursive runtime pass can multiply one already-refined face into hundreds
                                      // of packets in close/grazing views, overwhelming both the R3000 and GPU.
                                      // Keep the runtime pass off; raw BSP topology remains GT3 and the cooker still
                                      // supplies the shared-edge tessellation that fixed the original hallway warp.
                                      // Near-plane straddlers cannot use the native GT4 patch path: clipping first
                                      // turns them into a small triangle fan. Correct only that rare fan in view
                                      // space, independently of the disabled legacy all-world recursive pass. One
                                      // adaptive level costs at most three extra packets per clipped triangle and
                                      // cannot reproduce the old close-wall packet explosion.
const WORLD_AFFINE_NEAR_SUBDIVISION: bool = true;
// Native cooked quad patches get one measured 2x2 split. Unlike the legacy
// recursive triangle path this can add at most three packets per selected
// patch and preserves the source surface's four-sided structure.
const WORLD_NATIVE_PATCH_SUBDIVISION: bool = true;
// Visual-quality checkpoint: measure every fresh visible face and spend the
// available packet headroom on the geometry that still has visible affine
// error. Performance is deliberately secondary on this branch; the limits
// remain finite so actors/effects cannot corrupt the primitive arena.
const WORLD_AFFINE_ENTER_ERROR_TEXELS: i32 = 2;
const WORLD_AFFINE_LEAVE_ERROR_TEXELS: i32 = 1;
// The soft fallback is traversed in BSP order and cannot retain a frame-wide
// candidate list in PS1 RAM. Admit only severe root fans before recursively
// chasing the normal one-texel target; otherwise several mildly warped early
// surfaces consume the dense-view budget before the foreground floor/wall.
const WORLD_AFFINE_NEAR_ENTER_ERROR_TEXELS: u32 = 2;
/// A quad with any corner closer than this enters the near refinement
/// quadtree (both the near-plane crossers and the fully-in-front warp band).
const SOFT_NEAR_BAND_Z: i32 = 8;
/// Recursion ceiling for the near quadtree. The error rule alone converges
/// (each split roughly quarters an edge's affine error), the cap only bounds
/// the pathological corner-on-the-near-plane case.
const SOFT_SPLIT_MAX_DEPTH: usize = 6;
/// Target leaf-cell screen span for the near refinement tree: a cell axis
/// splits while it would project wider than this many pixels at the cell's
/// nearest depth. Uniform screen-size leaves make the level count rise
/// directly with proximity, and bound total work by screen area
/// (~(320/32)x(240/32) cells) instead of world geometry.
const SOFT_SPLIT_TARGET_SPAN_PX: i32 = 96;
/// The ranked shortlist also admits big CLOSE patches whose affine error is
/// low (head-on walls): within this depth and above this screen span, a patch
/// competes for the fixed refinement budget so near geometry reads uniformly
/// refined instead of only where perspective warps. Patches with cook-blocked
/// edges still cannot enter the shortlist (their split would reopen authored
/// T-junctions) -- lifting that safely is the noted follow-up.
const RANKED_NEAR_PRESENCE_Z: i32 = 512;
const RANKED_NEAR_PRESENCE_SPAN_PX: i32 = 96;
const WORLD_AFFINE_MIN_EDGE_PIXELS: i32 = 6;
// Irregular source-boundary fragments share the existing extra-packet budget.
// Four roots left large wall residues untouched even with 100+ packets free.
const WORLD_AFFINE_RESIDUE_ROOT_CAP: u8 = 16;
/// The single subdivision rule: refine while measured affine error exceeds
/// this many texels. Replaces the screen-span enter/leave gates.
const WORLD_AFFINE_SPLIT_ERROR_TEXELS: u32 = 2;
/// Classic stateless selection (camera-space subdivided affine rendering).
/// Every eligible
/// native patch whose measured error crosses the rule above splits 2x2 THIS
/// frame, every frame -- no 16-slot shortlist, no cross-frame edge set, no
/// rank/hold cadence for native patches. Coverage is total by construction
/// (the old budget corrected ~6 patches/frame against thousands of
/// candidates); the packet-arena headroom check in the emitter is the only
/// cap, and the near-to-far band walk sheds the FARTHEST refinements first
/// under pressure. Neighbour T-junctions are papered by the existing
/// patch underlay skirt, exactly the classic underdraw policy. The ranked
/// shortlist machinery stays in place for seamed GT3 pairs.
const WORLD_CLASSIC_AFFINE_SELECTION: bool = true;
/// Second classic band: a split-worthy patch whose measured edge error still
/// exceeds this many texels routes to the recursive screen-bounded quadtree
/// (`emit_soft_quad_split`) instead of the flat 2x2 -- one 2x2 level halves
/// edge spans and roughly quarters the error, so a parent at four texels
/// lands its children at about one; anything worse needs the deeper lattice.
/// This is the analog of the classic path's two-level near topology.
const WORLD_CLASSIC_SEVERE_ERROR_TEXELS: u32 = 4;
/// Classic coverage includes cook-blocked patches: their split reopens an
/// authored T-junction, but the patch underlay skirt papers exactly that
/// boundary class (the classic underdraw policy). Measured toggle.
const WORLD_CLASSIC_SPLIT_BLOCKED: bool = true;
/// Aggregate bound on the second band: at most this many severe patches per
/// frame take the recursive quadtree (nearest-first, the band walk is
/// near-to-far); the rest fall back to the flat 2x2. Without this the
/// quadtree leaves (which push unconditionally) can drain the arena to zero
/// on vista scenes -- measured 52k packet drops over the anomalous-entry
/// route, against 3.8k at baseline. Classic topology must stay BOUNDED.
const WORLD_CLASSIC_SOFT_ROUTE_CAP: u16 = 12;
/// Loop-face near crossers may take at most this many of the classic soft
/// routes a frame, and only while the arena still holds this much: a close
/// Hazard Course wall of loop quads otherwise drains the arena (regress
/// `hazard-ordering-yaw`).
const LOOP_SOFT_ROUTE_CAP: u16 = 4;
const LOOP_SOFT_ROUTE_ARENA_FLOOR: usize = 700;
/// No classic split (2x2 or quadtree) is taken once arena headroom falls to
/// this floor -- a backstop so coverage can never starve entities/actors/HUD.
/// The primary bound is the counted budget below (a floor alone binds too
/// late: the walk is near-to-far, so splits spend FIRST and what would drop
/// at the arena is far plain geometry -- measured killing the lab win while
/// leaving entry's drops).
const WORLD_CLASSIC_ARENA_FLOOR: usize = 256;
/// Counted per-frame budget for classic split extras, spent through
/// WORLD_AFFINE_EXTRA_BUDGET_LEFT by the native 2x2 (actual extras) and the
/// severe quadtree route (flat charge). Twice the old shortlist budget: the
/// old policy already spent ~165 of its 176 at these poses but was capped
/// near 20 resident patches by the edge-set; total coverage wants ~350 where
/// it wins (lab 51 patches, entry 54). Exact aggregate bound, unlike the
/// floor.
/// 352 is the measured quality configuration (entry saturated warp -66%,
/// world-subdivision -23%, ride cost -13% moving fps, prims +41%). A
/// like-for-like 176 was MEASURED WORSE than the old ranked shortlist on
/// quality (hallway saturated +43%): under a constrained budget, frame-wide
/// worst-first ranking beats stateless walk-order spending, so the classic
/// policy only pays at (near-)total coverage. There is no cheap middle;
/// lower this only together with restoring a ranking pass.
const WORLD_CLASSIC_EXTRA_PACKETS: u16 = 352;
/// Overflow/banded frames must retain enough headroom for the complete
/// unrefined far-band stream. The old bucket scatter accidentally discarded
/// two emitter classes and hid this pressure. Reserving 64 classic extras on
/// those rare frames keeps every base surface and the later actor/HUD reserve;
/// ordinary frames retain the full measured 352-packet quality budget.
const WORLD_CLASSIC_BANDED_EXTRA_PACKETS: u16 = WORLD_CLASSIC_EXTRA_PACKETS - 64;
/// Flat budget charge for one severe->quadtree route (leaves are emitted by
/// the tree itself and bounded by its span rule; this keeps the aggregate
/// accountable without threading counters through the recursion).
const WORLD_CLASSIC_SOFT_ROUTE_COST: u16 = 16;
/// Conservative pre-culls only: reject faces that cannot contain a qualifying
/// quad before paying to project their corners. These bound the search, they
/// do not decide refinement -- the measured error above does that.
const WORLD_AFFINE_CULL_MAX_DEPTH: i32 = 640;
const WORLD_AFFINE_CULL_MIN_SPAN_PIXELS: i32 = 40;
// Runtime correction is deliberately local: only a quad that is both large on
// screen and close to the current camera may enter the 2x2 path. Separate
// leave thresholds keep a corrected patch stable while the player moves near
// either boundary instead of alternating every visual frame.
// A full 2x2 grid reserves 15 against this budget, so 96 corrected only about
// six patches per frame -- against thousands of candidates in a dense view.
// That is why the worst edge of a frame was measurably untouched: coverage,
// not ranking (projected_priority_inversion is 0 everywhere) and not the
// blocked-edge gate (relaxing that made coverage worse, see findings).
const WORLD_AFFINE_MAX_EXTRA_PACKETS: u16 = 176;
// Ordinary cooked-patch refinement is encountered in BSP traversal order.
// Preserve eight four-way splits for the later soft path so a floor/wall that
// crosses the camera frustum cannot lose all correction merely because less
// objectionable distant patches happened to draw first. This is carved out of
// the existing 96-packet ceiling: it changes priority, never worst-case load.
const WORLD_AFFINE_NEAR_PACKET_RESERVE: u16 = 24;
// Each eligible GT4 is refined into a 2x2 grid.
const WORLD_AFFINE_NATIVE_GRID_PACKETS: usize = 4;

const WORLD_AFFINE_NATIVE_EXTRA_PACKETS: u16 = (WORLD_AFFINE_NATIVE_GRID_PACKETS - 1) as u16;
// Selecting one patch can force each of its four edge-sharing neighbours onto
// the same regular grid. Reserve the complete worst case before publishing the
// edge policy, exactly as the existing 2x2 implementation does.
const WORLD_AFFINE_NATIVE_EDGE_RESERVATION: u16 = WORLD_AFFINE_NATIVE_EXTRA_PACKETS * 5;
// A seamed GT3 pair expands from two to eight triangles (+6), and may force
// four native neighbours to conform to the selected grid.
const WORLD_AFFINE_SEAMED_EDGE_RESERVATION: u16 = 6 + WORLD_AFFINE_NATIVE_EXTRA_PACKETS * 4;
#[cfg(not(feature = "affine-heatmap"))]
const WORLD_AFFINE_NATIVE_EMIT_PACKETS: usize = WORLD_AFFINE_NATIVE_GRID_PACKETS;
// Heatmap mode replaces each GT4 child with its two hardware triangles.
#[cfg(feature = "affine-heatmap")]
const WORLD_AFFINE_NATIVE_EMIT_PACKETS: usize = WORLD_AFFINE_NATIVE_GRID_PACKETS * 2;
const _: () = assert!(WORLD_AFFINE_NATIVE_EDGE_RESERVATION <= WORLD_AFFINE_MAX_EXTRA_PACKETS);
// Deeper adaptive levels are cheap in already-cooked corridor cells and remove
// the last large affine wedges on long floor/ceiling runs. Every child remains
// gated by measured error and the dynamically available packet budget.
const WORLD_AFFINE_MAX_DEPTH: u8 = 2;
// Soft fallback polygons are first clipped geometrically to the visible
// frustum. Two screen-balanced levels then cap a full-screen edge near 80 px,
// while the measured UV/depth error gate avoids splitting harmless geometry.
const WORLD_AFFINE_NEAR_MAX_DEPTH: u8 = 3;
