const PROP_YAW_MASK: u16 = 0x0FFF;
const PROP_BODY_SHIFT: u16 = 12;

#[inline(always)]
fn prop_yaw_value(packed: u16) -> u16 {
    packed & PROP_YAW_MASK
}

#[inline(always)]
fn prop_body_value(packed: u16) -> u8 {
    (packed >> PROP_BODY_SHIFT) as u8
}

#[inline(always)]
fn prop_with_yaw(packed: u16, yaw: u16) -> u16 {
    (packed & !PROP_YAW_MASK) | (yaw & PROP_YAW_MASK)
}

#[inline(never)]
fn prop_model_rotation(yaw: u16, tilt: u16) -> Mat3I16 {
    let yaw = ((yaw.wrapping_sub(1024) & PROP_YAW_MASK) >> 4) as u32;
    if tilt == 0 {
        return Mat3I16::rotate_y(yaw as u16);
    }
    // Conjugated GoldSrc studio transform: Ry(-yaw) * Rz(-pitch) * Rx(-roll).
    let packed = (tilt as u32 & 0xff) | (yaw << 8) | ((tilt as u32 & 0xff00) << 8);
    phys::packed_euler_rotation(packed)
}

#[inline(always)]
fn prop_authored_tilt(m: &Map, pi: usize) -> u16 {
    if pi < m.n_props {
        ((m.prop_orientation(pi) as u32) >> 16) as u16
    } else {
        0
    }
}
