const C1A2B_ZOMBIE_TEXTURE_CHUNK: u32 = 1918;
const PRESSURE_ISLAVE_MODEL_CHUNK: u32 = 1820;
const PRESSURE_ISLAVE_TEXTURE_CHUNK: u32 = 1920;
const C4A1B_GARG_MODEL_CHUNK: u32 = 1817;
const C4A1B_GARG_TEXTURE_CHUNK: u32 = 1917;
const C4A3_GARG_MODEL_CHUNK: u32 = 1816;
