// Large bosses, G-Man, the construction loader, and bodygroup-heavy human
// streams retain split geometry/texture chunks. Their texture is staged over
// the dead triangle tail after face bake, avoiding a transient peak in scratch.
#[inline(always)]
const fn split_model_stream(ty: usize) -> bool {
    matches!(ty, 0 | 1 | 15 | 16 | 17 | 25 | 52 | 54)
}

/// Sparse build-generated map/type -> deduplicated HMD8 chunk lookup. Entries
/// are packed as three bytes so all 103 maps cost roughly 2.5 KiB of read-only
/// RAM rather than a 103x57 u16 matrix. Clip slots remain map-local and are
/// already baked into that room's scripted-sequence tokens.
#[inline]
fn map_model_variant_chunk(map_index: usize, ty: usize) -> Option<u32> {
    let offsets = &room_budget::MODEL_VARIANT_OFFSETS;
    if map_index + 1 >= offsets.len() || ty >= N_MODEL_TYPES {
        return None;
    }
    let mut entry = offsets[map_index] as usize;
    let end = offsets[map_index + 1] as usize;
    while entry < end {
        let offset = entry * 3;
        let bytes = &room_budget::MODEL_VARIANT_BYTES;
        if offset + 2 >= bytes.len() {
            return None;
        }
        let entry_ty = bytes[offset] as usize;
        if entry_ty == ty {
            return Some(u16::from_le_bytes([bytes[offset + 1], bytes[offset + 2]]) as u32);
        }
        if entry_ty > ty {
            return None;
        }
        entry += 1;
    }
    None
}
const AI_ITEM: u8 = 0; // static pickup
const AI_FLEE: u8 = 1; // scientist
const AI_ALLY: u8 = 2; // barney
const AI_MELEE: u8 = 3; // approach + bite (headcrab and friends)
const AI_IDLE: u8 = 4; // render only (flyers/ceiling/bosses until they get real AI)
const AI_RANGED: u8 = 5; // approach to range, then fire (grunts, vorts, agrunt, controller)
const AI_TURRET: u8 = 6; // stationary: rotate to face + fire (sentry/turret/miniturret)

#[derive(Clone, Copy)]
struct ModelDef {
    health: u8,
    target_h: i32,
    radius: i32,
    ai: u8,
    speed: u8,        // move speed (world units/tick); 0 = stationary
    atk_range: u16,   // attack engage distance (world units)
    atk_damage: u8,   // HP per hit
    atk_cooldown: u8, // ticks between attacks (20 Hz)
}
const fn mdef(health: u8, target_h: i32, radius: i32, ai: u8) -> ModelDef {
    ModelDef {
        health,
        target_h,
        radius,
        ai,
        speed: 0,
        atk_range: 0,
        atk_damage: 0,
        atk_cooldown: 0,
    }
}
const fn mdef_atk(
    health: u8,
    target_h: i32,
    radius: i32,
    ai: u8,
    speed: u8,
    atk_range: u16,
    atk_damage: u8,
    atk_cooldown: u8,
) -> ModelDef {
    ModelDef {
        health,
        target_h,
        radius,
        ai,
        speed,
        atk_range,
        atk_damage,
        atk_cooldown,
    }
}
