#[inline]
fn model_def(ty: u8) -> ModelDef {
    MODEL_DEFS[(ty as usize).min(N_MODEL_TYPES - 1)]
}

/// Legacy fallback for an old or missing model stream with no cooked studio
/// boxes. New actor chunks use their source MDL hitboxes below.
#[inline]
fn prop_hit_extent(ty: u8) -> (i32, i32) {
    match ty {
        2 => (12, 12),           // headcrab (-12,-12,0)..(12,12,24)
        6 => (16, 18),           // houndeye
        7 | 10 | 19 => (32, 32), // bullsquid / agrunt / ichthyosaur
        11 => (16, 24),          // controller
        12 => (16, 18),          // barnacle
        13 | 24 => (8, 8),       // leech / flyer
        14 => (4, 4),            // cockroach
        16 => (32, 64),          // gargantua
        17 => (48, 80),          // nihilanth
        18 => (40, 60),          // bigmomma
        20 => (16, 32),          // sentry
        21 => (32, 32),          // turret
        22 => (16, 16),          // miniturret
        23 => (48, 32),          // apache
        25 => (16, 26),          // sitting scientist
        50 => (32, 80),          // tentacle
        _ => (16, 36),           // human hull (-16,-16,0)..(16,16,72)
    }
}

/// Actors that GoldSrc's player-allies treat as enemies and that this runtime
/// currently simulates as combatants.  Keep this tied to the behavior class,
/// rather than a single model id: c1a1's Barney must shoot the monstermaker
/// zombie just as he shoots a headcrab, and later maps reuse the same search
/// for ranged aliens, soldiers, assassins, and turrets.
#[inline(always)]
fn prop_is_combat_hostile(ty: u8) -> bool {
    matches!(model_def(ty).ai, AI_MELEE | AI_RANGED | AI_TURRET)
}

