static mut PROJ_TOKEN: u16 = 1; // shared world/submodel projection token
static mut ROOM_PROJECTED_COUNT: u32 = 0;
#[derive(Clone, Copy, PartialEq, Eq)]
struct WorldProjectionKey {
    room_id: u16,
    projection_h: u16,
    rot: [[i16; 3]; 3],
    base_t: [i32; 3],
}
static mut WORLD_PROJECTION_KEY: WorldProjectionKey = WorldProjectionKey {
    room_id: u16::MAX,
    projection_h: 0,
    rot: [[0; 3]; 3],
    base_t: [0; 3],
};
static mut WORLD_PROJECTION_TOKEN: u16 = 0;
const PVS_LINK_END: u16 = u16::MAX;
const PVS_GROUP_LIQUID: u16 = 0x8000;
const PVS_GROUP_FACE_MASK: u16 = 0x7fff;
#[derive(Clone, Copy)]
struct PvsFaceRec {
    first: u16,
    // Low 14 bits are the loop/triangle/patch record count. Bit 14 marks a
    // face whose material/light state needs the generic setup path; bit 15 is
    // the backed-cutout ordering flag. Cooked face counts are far below 16K,
    // so the cold PVS builder can preclassify the hot stream without growing
    // this record or the resident room arena.
    count: u16,
    center: [i16; 3],
    radius: u16,
    tex: u8,  // per-face texture (loop faces store tex on the FaceRec)
    meta: u8, // band[2:0] | loop<<3 | liquid<<4 | refined<<5 | backdrop<<6 | patch<<7
}
const PVS_FACE_BAND_MASK: u8 = 0x07;
const PVS_FACE_LOOP: u8 = 0x08;
const PVS_FACE_TRANSLUCENT: u8 = 0x10;
const PVS_FACE_REFINED_TOPOLOGY: u8 = 0x20;
const PVS_FACE_COPLANAR_BACKDROP: u8 = 0x40;
const PVS_FACE_PATCH: u8 = 0x80;
const PVS_FACE_COUNT_MASK: u16 = 0x3fff;
const PVS_FACE_SPECIAL: u16 = 0x4000;
const PVS_FACE_CUTOUT: u16 = 0x8000;

impl PvsFaceRec {
    #[inline(always)]
    fn band(self) -> u8 {
        self.meta & PVS_FACE_BAND_MASK
    }

    #[inline(always)]
    fn count(self) -> usize {
        (self.count & PVS_FACE_COUNT_MASK) as usize
    }

    #[inline(always)]
    fn cutout(self) -> bool {
        self.count & PVS_FACE_CUTOUT != 0
    }

    #[inline(always)]
    fn special(self) -> bool {
        self.count & PVS_FACE_SPECIAL != 0
    }

    #[inline(always)]
    fn set_band(&mut self, band: u8) {
        self.meta = (self.meta & !PVS_FACE_BAND_MASK) | (band & PVS_FACE_BAND_MASK);
    }

    #[inline(always)]
    fn is_loop(self) -> bool {
        self.meta & PVS_FACE_LOOP != 0
    }

    #[inline(always)]
    fn is_patch(self) -> bool {
        self.meta & PVS_FACE_PATCH != 0
    }

    #[inline(always)]
    fn liquid(self) -> bool {
        self.meta & PVS_FACE_TRANSLUCENT != 0
    }

    #[inline(always)]
    fn refined_topology(self) -> bool {
        self.meta & PVS_FACE_REFINED_TOPOLOGY != 0
    }

    #[inline(always)]
    fn coplanar_backdrop(self) -> bool {
        self.meta & PVS_FACE_COPLANAR_BACKDROP != 0
    }
}

// Packing three one-byte fields into `meta` saves 4 KiB across the 2,048-face
// cache without reducing either visibility or GPU packet capacity.
const _: () = assert!(core::mem::size_of::<PvsFaceRec>() == 14);
const EMPTY_PVS_FACE_REC: PvsFaceRec = PvsFaceRec {
    first: 0,
    count: 0,
    center: [0; 3],
    radius: 0,
    tex: 0,
    meta: 0,
};
static mut VIS_BITS: [u8; MAX_LEAVES / 8] = [0; MAX_LEAVES / 8];
static mut PVS_LEAF_COUNT: usize = 0;
// The live PVS uses u16 links. Four-byte alignment lets the unused suffix hold
// native u32 GPU packet words without unaligned R3000 loads; the cache begins at
// the next even link index, so the live representation and byte count are
// unchanged.
#[repr(C, align(4))]
struct AlignedPvsFaceLinks([u16; MAX_FACES]);
static mut PVS_FACE_INDEX: AlignedPvsFaceLinks = AlignedPvsFaceLinks([0; MAX_FACES]);
// Sentinel-filled at boot by `init_pvs_link_sentinels`, not by a static
// initializer: a non-zero initializer would put these tables in `.data`, which
// is stored in the executable and copied to RAM at load, where `.bss` costs
// neither. Nothing reads them before boot fills them.
static mut PVS_FACE_NEXT: AlignedPvsFaceLinks = AlignedPvsFaceLinks([0; MAX_FACES]);
#[repr(C, align(4))]
struct AlignedPvsFaceRecs([PvsFaceRec; MAX_PVS_FACE_RECS]);
static mut PVS_FACE_REC: AlignedPvsFaceRecs =
    AlignedPvsFaceRecs([EMPTY_PVS_FACE_REC; MAX_PVS_FACE_RECS]);
static mut PVS_FACE_COUNT: usize = 0;

const PVS_FACE_MARK_WORDS: usize = MAX_FACES.div_ceil(32);
static mut PVS_FACE_MARK: [u32; PVS_FACE_MARK_WORDS] = [0; PVS_FACE_MARK_WORDS];
static mut PVS_GROUP_FIRST: [u16; MAX_FACE_GROUPS] = [0; MAX_FACE_GROUPS];
static mut PVS_GROUP_FACE: [u16; MAX_FACE_GROUPS] = [0; MAX_FACE_GROUPS];

/// Install the `PVS_LINK_END` sentinel that the link tables above would
/// otherwise carry as a static initializer. Call once, before any PVS use.
unsafe fn init_data_defaults() {
    for ent in ENT_CACHE.iter_mut() {
        *ent = EMPTY_ENT;
    }
    for phase in ENT_RENDER_PHASE.iter_mut() {
        *phase = i32::MIN;
    }
    for mover in MOVERS.iter_mut() {
        *mover = phys::NO_MOVER;
    }
    for slot in TEX_SLOTS.iter_mut() {
        *slot = EMPTY_SLOT;
    }
    for slot in VM_SLOTS.iter_mut() {
        *slot = EMPTY_SLOT;
    }
}

unsafe fn init_pvs_link_sentinels() {
    for link in PVS_FACE_NEXT.0.iter_mut() {
        *link = PVS_LINK_END;
    }
    for first in PVS_GROUP_FIRST.iter_mut() {
        *first = PVS_LINK_END;
    }
    for face in PVS_GROUP_FACE.iter_mut() {
        *face = PVS_LINK_END;
    }
}
static mut PVS_GROUP_ACTIVE: [u16; MAX_FACE_GROUPS] = [0; MAX_FACE_GROUPS];
static mut PVS_GROUP_COUNT: usize = 0;
// Set during the cold PVS rebuild. Static world packets only depend on the
// eight-frame liquid phase when this view can actually emit a liquid face;
// otherwise including WAVE_DU/WAVE_DV in the cache key causes a needless full
// room rebuild every eighth visual frame.
static mut PVS_HAS_TRANSLUCENT: bool = false;
// Same gating for GoldSrc animated textures (+0../+9, +a../+j chains): only a
// view that can actually emit a chain-member world face keys the room cache on
// the 10 Hz animation generation.
static mut PVS_HAS_TEXANIM: bool = false;
// Bit i = compact texture i belongs to an animation chain (per-map, built at
// load from the HLMF chain section).
static mut TEX_ANIM_MASK: [u32; map::TEX_ANIM_MAX / 32] = [0; map::TEX_ANIM_MAX / 32];
// Subset of TEX_ANIM_MASK referenced by faces in the current PVS. A chain
// elsewhere in the map must not evict an otherwise reusable room packet cache.
static mut PVS_TEX_ANIM_MASK: [u32; map::TEX_ANIM_MAX / 32] = [0; map::TEX_ANIM_MAX / 32];
// Bit ei = the brush submodel contains an animated face, so its cached packets
// must rebuild when the animation generation advances (frame-0 chains cycle
// even while the entity itself never moves -- blinking computer banks).
static mut ENT_TEXANIM: [u32; MAX_ENTS.div_ceil(32)] = [0; MAX_ENTS.div_ceil(32)];
// Bumped whenever a 10 Hz step actually changes a display frame; folded into
// the world/brush cache keys so stationary views pick up the new frame.
static mut TEX_ANIM_GEN: u8 = 0;
// PVS-local counterpart used by static room packets. This advances once per
// animation tick only when a changed display row is referenced by this PVS.
static mut PVS_TEX_ANIM_GEN: u8 = 0;
static mut TEX_ANIM_TENTH: u16 = u16::MAX;

#[inline(always)]
unsafe fn tex_is_animated(tex: usize) -> bool {
    let i = tex & (map::TEX_ANIM_MAX - 1);
    TEX_ANIM_MASK[i >> 5] & (1u32 << (i & 31)) != 0
}

#[inline(always)]
unsafe fn pvs_has_texanim(tex: usize) -> bool {
    let i = tex & (map::TEX_ANIM_MAX - 1);
    PVS_TEX_ANIM_MASK[i >> 5] & (1u32 << (i & 31)) != 0
}

#[inline(always)]
unsafe fn ent_has_texanim(ei: usize) -> bool {
    ei < MAX_ENTS && ENT_TEXANIM[ei >> 5] & (1u32 << (ei & 31)) != 0
}

/// Per-map animated-texture setup: identity display tables, the chain-member
/// mask, and per-entity animated flags (walked once from the cooked chain
/// section + submodel face lists).
unsafe fn tex_anim_init(m: &Map, nents: usize) {
    #[cfg(feature = "emulator-telemetry")]
    telemetry::debug_log(if m.n_tex_anim == 0 {
        "hl-psx: tex_anim NONE"
    } else {
        "hl-psx: tex_anim present"
    });
    map::tex_anim_reset();
    TEX_ANIM_MASK = [0; map::TEX_ANIM_MAX / 32];
    PVS_TEX_ANIM_MASK = [0; map::TEX_ANIM_MAX / 32];
    ENT_TEXANIM = [0; MAX_ENTS.div_ceil(32)];
    TEX_ANIM_GEN = 0;
    PVS_TEX_ANIM_GEN = 0;
    TEX_ANIM_TENTH = u16::MAX;
    if m.n_tex_anim == 0 {
        return;
    }
    for c in 0..m.n_tex_anim {
        let (primary, alt) = m.tex_anim_chain(c);
        for &id in primary.iter().chain(alt.iter()) {
            TEX_ANIM_MASK[(id >> 5) as usize] |= 1u32 << (id & 31);
        }
    }
    for ei in 0..nents.min(MAX_ENTS) {
        let (ff, nf) = m.submodel(ENT_CACHE[ei].submodel);
        for f in ff..(ff + nf).min(m.n_faces) {
            if tex_is_animated(m.face_tex(f)) {
                ENT_TEXANIM[ei >> 5] |= 1u32 << (ei & 31);
            }
        }
    }
    tex_anim_tick(m); // seat the frame-0 display tables before the first draw
}

/// Advance the texture-animation clock. GoldSrc samples a 10 Hz timebase but
/// assigns two tenths to each brush-texture frame (`ANIM_CYCLE = 2`), so the
/// visible +0/+1 chain advances at 5 fps. Rebuilds the two display rows:
/// frame-state 0 shows a face's own chain, frame-state 1 the other chain.
unsafe fn tex_anim_tick(m: &Map) {
    if m.n_tex_anim == 0 {
        return;
    }
    let tenth = SIM_NOW >> 1;
    if tenth == TEX_ANIM_TENTH {
        return;
    }
    TEX_ANIM_TENTH = tenth;
    let mut changed = false;
    let mut pvs_changed = false;
    for c in 0..m.n_tex_anim {
        let (primary, alt) = m.tex_anim_chain(c);
        let pcur = primary
            .get(map::tex_anim_frame_index(tenth, primary.len()))
            .copied()
            .unwrap_or(0);
        let acur = alt
            .get(map::tex_anim_frame_index(tenth, alt.len()))
            .copied()
            .unwrap_or(0);
        for &id in primary {
            let id_changed =
                map::tex_anim_set(id as usize, pcur, if alt.is_empty() { pcur } else { acur });
            changed |= id_changed;
            pvs_changed |= id_changed && pvs_has_texanim(id as usize);
        }
        for &id in alt {
            let id_changed = map::tex_anim_set(
                id as usize,
                acur,
                if primary.is_empty() { acur } else { pcur },
            );
            changed |= id_changed;
            pvs_changed |= id_changed && pvs_has_texanim(id as usize);
        }
    }
    if changed {
        TEX_ANIM_GEN = TEX_ANIM_GEN.wrapping_add(1);
    }
    if pvs_changed {
        PVS_TEX_ANIM_GEN = PVS_TEX_ANIM_GEN.wrapping_add(1);
    }
}
// Per-frame group backface verdicts (bit per ACTIVE-list index): the banded
// walk used to redo every group's plane dot and every face's depth dot per
// band; the pre-pass computes both once per frame. Both this verdict set and
// its companion "seen" set live in the CPU-local scratchpad.
#[inline(always)]
unsafe fn group_vis_bits() -> *mut u32 {
    unsafe { scratchpad::ptr_at::<u32>(GROUP_VIS_SCRATCH_OFFSET) }
}

#[inline(always)]
unsafe fn group_seen_bits() -> *mut u32 {
    unsafe { scratchpad::ptr_at::<u32>(GROUP_SEEN_SCRATCH_OFFSET) }
}

#[inline(always)]
unsafe fn scratch_bit(bits: *mut u32, index: usize) -> bool {
    let word = unsafe { bits.add(index >> 5).read() };
    word & (1u32 << (index & 31)) != 0
}

#[inline(always)]
unsafe fn scratch_bit_assign(bits: *mut u32, index: usize, value: bool) {
    let address = unsafe { bits.add(index >> 5) };
    let mask = 1u32 << (index & 31);
    let old = unsafe { address.read() };
    unsafe { address.write(if value { old | mask } else { old & !mask }) };
}

#[inline(always)]
unsafe fn clear_group_bits(bits: *mut u32) {
    let mut i = 0usize;
    while i < RENDER_GROUP_WORDS {
        unsafe { bits.add(i).write(0) };
        i += 1;
    }
}
static mut PVS_TRI_REF_COUNT: usize = 0;
static mut PVS_ENTS: [u16; MAX_ENTS] = [0; MAX_ENTS];
static mut PVS_ENT_COUNT: usize = 0;
