    debug_assert!(p[0] >= i16::MIN as i32 && p[0] <= i16::MAX as i32);
    debug_assert!(p[1] >= i16::MIN as i32 && p[1] <= i16::MAX as i32);
    debug_assert!(p[2] >= i16::MIN as i32 && p[2] <= i16::MAX as i32);
