// fast-path neighbour pushed -- no cross-projector seam.
static mut SOFT_CACHED_SCREEN: [Option<(i16, i16)>; 3] = [None; 3];
static mut SOFT_CACHED_CV: [[i32; 3]; 3] = [[0; 3]; 3];
