// re-parsing the full 64 B LogicEnt from the uncached blob.
static mut LOGIC_KIND: [u8; MAX_LOGIC] = [0; MAX_LOGIC];
// func_monsterclip AABBs (world mins/maxs): NPC pathing refuses steps inside
// them; the player never tests them, so it walks through freely.
const MAX_MONSTERCLIP: usize = 32;
static mut MONSTERCLIP: [([i32; 3], [i32; 3]); MAX_MONSTERCLIP] =
    [([0; 3], [0; 3]); MAX_MONSTERCLIP];
static mut MONSTERCLIP_N: usize = 0;

/// True when `p` is inside any func_monsterclip volume (NPC-only blocker).
unsafe fn in_monsterclip(p: [i32; 3]) -> bool {
    let mut i = 0usize;
    while i < MONSTERCLIP_N {
        let (mn, mx) = MONSTERCLIP[i];
        if p[0] >= mn[0]
            && p[0] <= mx[0]
            && p[1] >= mn[1]
            && p[1] <= mx[1]
            && p[2] >= mn[2]
            && p[2] <= mx[2]
        {
            return true;
        }
        i += 1;
    }
    false
}
static mut TELEPORT_REQUEST: Option<([i32; 3], u16)> = None; // dest pos + yaw, applied post-touch

// A face's render behaviour is one atomic value. Older code stored these bits
// in five unrelated globals, so a fast PVS/static-brush path could update
// blend and depth bias while accidentally retaining the previous face's
// cutout ordering. That made backed grates disappear depending on traversal
// history. Keep the hot representation to one byte and derive it from the
// canonical face index at every face boundary; PVS records stay unchanged.
#[derive(Clone, Copy, PartialEq, Eq)]
#[repr(transparent)]
struct EmitPolicy(u8);

impl EmitPolicy {
    const BLEND_MASK: u8 = 0x03;
    const WAVE: u8 = 0x04;
    const CUTOUT: u8 = 0x08;
    const LOCAL_DEPTH: u8 = 0x10;
    const COPLANAR_BACKDROP: u8 = 0x20;
    const TRAM_GRID: u8 = 0x40;
    const OPAQUE: Self = Self(0);

    #[inline(always)]
    const fn from_surface(
        liquid: bool,
        translucent: bool,
        cutout: bool,
        coplanar_backdrop: bool,
        blend_override: u8,
    ) -> Self {
        let blend = if blend_override != 0 {
            blend_override & Self::BLEND_MASK
        } else {
            translucent as u8
        };
        Self(
            blend
                | if liquid { Self::WAVE } else { 0 }
                | if cutout { Self::CUTOUT } else { 0 }
                | if coplanar_backdrop {
                    Self::COPLANAR_BACKDROP
                } else {
                    0
                },
        )
    }

    #[inline(always)]
    unsafe fn for_face(m: &Map, face: usize, blend_override: u8) -> Self {
        Self::from_surface(
            m.face_liquid(face),
            m.face_translucent(face),
            m.face_cutout_backed(face),
            m.face_coplanar_backdrop(face),
            blend_override,
        )
    }

    #[inline(always)]
    const fn blend(self) -> u8 {
        self.0 & Self::BLEND_MASK
    }

    #[inline(always)]
    const fn wave(self) -> bool {
        self.0 & Self::WAVE != 0
    }

    #[inline(always)]
    const fn cutout(self) -> bool {
        self.0 & Self::CUTOUT != 0
    }

    #[inline(always)]
    const fn local_depth(self) -> bool {
        self.0 & Self::LOCAL_DEPTH != 0
    }

    #[inline(always)]
    const fn coplanar_backdrop(self) -> bool {
        self.0 & Self::COPLANAR_BACKDROP != 0
    }

    #[inline(always)]
    const fn tram_grid(self) -> bool {
        self.0 & Self::TRAM_GRID != 0
    }

    /// Force the Average blend on a liquid surface seen from inside it.
    #[inline(always)]
    const fn with_underwater_blend(self, under: bool) -> Self {
        if under && self.wave() && self.blend() == visibility_logic::BRUSH_RENDER_OPAQUE {
            Self((self.0 & !Self::BLEND_MASK) | visibility_logic::BRUSH_RENDER_AVERAGE)
        } else {
            self
        }
    }

    #[inline(always)]
    const fn with_local_depth(self, enabled: bool) -> Self {
        if enabled {
            Self(self.0 | Self::LOCAL_DEPTH)
        } else {
            Self(self.0 & !Self::LOCAL_DEPTH)
        }
    }

    #[inline(always)]
    const fn with_tram_grid(self) -> Self {
        Self(self.0 | Self::TRAM_GRID)
    }
}

// Compile-time path invariants: every entry route must observe the same packed
// semantics for an identical cooked face, and the temporary topology bit must
// not disturb its material/ordering attributes.
const _: () = {
    let backed_grate = EmitPolicy::from_surface(false, false, true, false, 0);
    assert!(backed_grate.blend() == 0);
    assert!(!backed_grate.wave());
    assert!(backed_grate.cutout());
    assert!(backed_grate.with_local_depth(true).cutout());
    assert!(backed_grate.with_local_depth(true).local_depth());

    let liquid_glass = EmitPolicy::from_surface(true, true, false, true, 2);
    assert!(liquid_glass.blend() == 2);
    assert!(liquid_glass.wave());
    assert!(!liquid_glass.cutout());
    assert!(liquid_glass.coplanar_backdrop());
};

static mut EMIT_POLICY: EmitPolicy = EmitPolicy::OPAQUE;
// Moving brushes which touch an actor need depth samples across their faces.
// The fixed cap also bounds the cost when several doors overlap a crowd.
static mut SUBMODEL_ACTOR_OVERLAP: bool = false;
static mut SUBMODEL_OCCLUSION_EXTRAS: u16 = 0;
const RESIDUE_OWN_BUDGET: u8 = 0x80;

#[inline(always)]
fn face_needs_generic_emit(m: &Map, face: usize) -> bool {
    m.face_liquid(face)
        || m.face_cutout_backed(face)
        || m.face_coplanar_backdrop(face)
        || m.face_lightstyle(face) != 0
}

#[inline(always)]
unsafe fn set_emit_face(m: &Map, face: usize, blend_override: u8) {
    EMIT_POLICY =
        EmitPolicy::for_face(m, face, blend_override).with_underwater_blend(EMIT_EYE_UNDER_LIQUID);
    m.select_dynamic_face(face, LIGHTSTYLE_ACTIVE_MASK);
}

#[inline(always)]
unsafe fn set_emit_cached_face(m: &Map, face: usize, rec: PvsFaceRec) {
    // The compact PVS record already carries the hot translucent/backdrop
    // bits, including backed cutout in the spare count bit. The hot path stays
    // cache-only while retaining the exact same 14-byte record layout.
    EMIT_POLICY = EmitPolicy::from_surface(
        rec.liquid(),
        m.water_alpha_supported() && rec.liquid(),
        rec.cutout(),
        rec.coplanar_backdrop(),
        0,
    )
    .with_underwater_blend(EMIT_EYE_UNDER_LIQUID);
    m.select_dynamic_face(face, LIGHTSTYLE_ACTIVE_MASK);
}

#[inline(always)]
unsafe fn reset_emit_policy() {
    EMIT_POLICY = EmitPolicy::OPAQUE;
    Map::reset_dynamic_face();
}

// Refined UV-grid children use their own centroid depth. Only a cook-tagged
// regular cell may share that local key across its two explicitly coplanar
// triangles, and the quad path still rejects a pair whose child keys diverge.
static mut WAVE_DU: u8 = 0;
static mut WAVE_DV: u8 = 0;
// Adaptive near-first world ordering. Bit 0 requests bands for this frame;
// bit 1 records a room packet overflow while emitting this frame.
const WORLD_BAND_NEEDS: u8 = 1;
const WORLD_BAND_OVERFLOW: u8 = 2;
static mut WORLD_BAND_STATE: u8 = 0;
// Gentle 128-frame sway cycle for liquid surfaces (+-4 texels; the GP0-E2
// texture window wraps coordinates, so the byte add is always safe).
const WAVE_TAB: [i8; 16] = [0, 2, 3, 4, 4, 4, 3, 2, 0, -2, -3, -4, -4, -4, -3, -2];

// Exact one-view world packet cache. Static room packets occupy the arena's
// prefix and survive its zero-cost per-frame cursor reset. A hit relinks that
// unchanged prefix into the cleared OT and resumes allocation after it, keeping
// addresses, arena pressure, and same-OTZ tie ordering identical to a fresh
// render. Only packet-kind/OTZ metadata uses the otherwise-idle band-order tail;
// no duplicate packet payload or second arena is reserved in RAM.
const WORLD_PACKET_CACHE: bool = true;
const WORLD_CACHE_NONE: u8 = 0;
const WORLD_CACHE_BUILD: u8 = 1;
const WORLD_CACHE_HIT: u8 = 2;
const WORLD_CACHE_BRUSH_REBUILD: u8 = 3;
const WORLD_CACHE_CANDIDATE_ARMED: u8 = 1;
const WORLD_CACHE_CANDIDATE_REJECTED: u8 = 2;
// OT_LEN needs nine bits. Bit 9 stores packet kind. Cached packet payloads are
// immutable: animated textures and liquid UV phases participate in the cache
// key instead of rewriting packets that the GPU may still be consuming.
const WORLD_CACHE_OTZ_MASK: u16 = 0x01ff;
const WORLD_CACHE_QUAD_META: u16 = 0x0200;
// A resident command reserves an arena slot even when it culls or falls back
// to appended legacy packets. Replay advances over that unchanged hole without
// linking it into the OT.
const WORLD_CACHE_SKIP_META: u16 = 0x0400;
const WORLD_CACHE_SLOT_BYTES: usize =
    core::mem::size_of::<RenderPacketScratch>() / MAX_RENDER_PACKETS;
const _: () = assert!(core::mem::size_of::<TriTexturedGouraud>() <= WORLD_CACHE_SLOT_BYTES);
const _: () = assert!(core::mem::size_of::<QuadTexturedGouraud>() <= WORLD_CACHE_SLOT_BYTES);
const _: () = assert!(OT_LEN <= (WORLD_CACHE_OTZ_MASK as usize + 1));
const _: () = assert!(OT_LEN <= (u16::MAX as usize + 1));

#[cfg(any(feature = "emulator-telemetry", feature = "performance-telemetry"))]
static mut RENDER_PACKET_DROPS: u32 = 0;
#[cfg(any(feature = "emulator-telemetry", feature = "performance-telemetry"))]
static mut MODEL_PACKET_DROPS: u32 = 0;

#[inline(always)]
unsafe fn note_render_packet_drop(model: bool) {
    #[cfg(any(feature = "emulator-telemetry", feature = "performance-telemetry"))]
    {
        RENDER_PACKET_DROPS = RENDER_PACKET_DROPS.saturating_add(1);
        if model {
            MODEL_PACKET_DROPS = MODEL_PACKET_DROPS.saturating_add(1);
        }
    }
    #[cfg(not(any(feature = "emulator-telemetry", feature = "performance-telemetry")))]
    let _ = model;
}

#[derive(Clone, Copy, PartialEq, Eq)]
struct WorldPacketCacheKey {
    leaf: i32,
    projection_h: u16,
    // Lit packets depend on the traced beam reach. This occupies the existing
    // alignment hole, so torch-correct invalidation costs no cache RAM.
    flashlight_state: u16,
    static_brush_state: u32,
    rot: [[i16; 3]; 3],
    base_t: [i32; 3],
    eye: [i32; 3],
    wave_du: u8,
    wave_dv: u8,
    // 10 Hz animated-texture generation, keyed only when the view can emit a
    // chain-member world face (mirrors the wave gating above).
    tex_anim: u8,
    band_mode: u8,
    affine_generation: u16,
}
const _: () = assert!(core::mem::size_of::<WorldPacketCacheKey>() == 60);

impl WorldPacketCacheKey {
    const EMPTY: Self = Self {
        leaf: -1,
        projection_h: 0,
        flashlight_state: 0,
        static_brush_state: 0,
        rot: [[0; 3]; 3],
        base_t: [0; 3],
        eye: [0; 3],
        wave_du: 0,
        wave_dv: 0,
        tex_anim: 0,
        band_mode: 0,
        affine_generation: 0,
    };

    #[inline(never)]
    fn same_view(&self, other: &Self) -> bool {
        self.leaf == other.leaf
            && self.projection_h == other.projection_h
            && self.flashlight_state == other.flashlight_state
            && self.rot == other.rot
            && self.base_t == other.base_t
            && self.eye == other.eye
            && self.band_mode == other.band_mode
            && self.affine_generation == other.affine_generation
    }
}

#[inline(always)]
unsafe fn static_brush_cacheable(ei: usize, e: map::Ent) -> bool {
    // An axial door may stop across a moving actor. Keep its local depth
    // samples live while that overlap exists, including the final open pose.
    if e.kind == 7 {
        let pivot_radius =
            ENT_RADIUS[ei] + e.center[0].abs() + e.center[1].abs() + e.center[2].abs();
        if brush_touches_actor(e.origin, pivot_radius, e.origin) {
            return false;
        }
    }
    let train_slot = ENT_TRAIN_SLOT[ei] as usize;
    let running_train = train_slot < TRAIN_COUNT
        && TRAIN_STATE[train_slot] & TRAIN_ACTIVE_BIT != 0
        && TRAIN_STATE[train_slot] & TRAIN_WAITING_BIT == 0;
    // Continuous fans/pendulums and running brush trains must rebuild every
    // visual. A train's transform advances through TRAIN_OFF rather than
    // ENT_PHASE; admitting it to the reusable prefix can leave its collision
    // and rider at the live stop while the cached mesh stays at the old one.
    // Waiting/stopped trains, doors, plats, pushables and rotating doors are
    // safe because their exact phase + draw offset participate in the key.
    !running_train
        && !((e.kind == 5 || e.kind == ENT_KIND_PENDULUM) && e.mv[0] != 0)
        && ENT_PHASE[ei] == ENT_RENDER_PHASE[ei]
}

/// Compact invalidation key for the repeatable brush prefix. Geometry and
/// materials live in the current map blob; active/phase/offset are the complete
/// mutable render state for every entity admitted by static_brush_cacheable.
#[inline(never)]
unsafe fn static_brush_state(have_pvs: bool, nents: usize) -> u32 {
    let count = if have_pvs { PVS_ENT_COUNT } else { nents };
    let mut hash = 0x811c_9dc5u32;
    let mut bi = 0usize;
    while bi < count {
        let ei = if have_pvs { PVS_ENTS[bi] as usize } else { bi };
        let e = ENT_CACHE[ei];
        if have_pvs
            && !visibility_logic::pvs_visible_now(
                entity_uses_live_pvs(ei, e),
                true,
                live_entity_pvs_visible(ei),
            )
        {
            bi += 1;
            continue;
        }
        if static_brush_cacheable(ei, e) {
            hash ^= ((ei as u32) << 1) | ((e.blend as u32) << 16) | (ENT_ACTIVE[ei] != 0) as u32;
            hash = hash.wrapping_mul(0x0100_0193);
            hash ^= ENT_PHASE[ei] as u32;
            hash = hash.wrapping_mul(0x0100_0193);
            // A brush with chain-member textures repaints at 10 Hz even while
            // it never moves (blinking screens); fold the animation generation
            // in so the cached prefix rebuilds on each frame step.
            if ent_has_texanim(ei) {
                hash ^= (TEX_ANIM_GEN as u32) << 8;
                hash = hash.wrapping_mul(0x0100_0193);
            }
            let off = ent_draw_offset(ei);
            hash ^= off[0] as u32;
            hash = hash.wrapping_mul(0x0100_0193);
            hash ^= off[1] as u32;
            hash = hash.wrapping_mul(0x0100_0193);
            hash ^= off[2] as u32;
            hash = hash.wrapping_mul(0x0100_0193);
        }
        bi += 1;
    }
    hash
}

