static mut TALKING_PROP: u8 = TALKING_PROP_NONE;
static mut TALKING_UNTIL: u16 = 0;
static mut TALKING_VOICE: u8 = 0;
static mut MAP_VOICE_PREFIX: u8 = 0;
static mut MAP_TALK_IDS: [u8; 6] = [u8::MAX; 6];
const _: () = assert!(room_budget::TALK_VOICES.len() == menu::MAPS.len());
const TALKING_VOICE_ID_MASK: u8 = 0x3f;
const TALKING_VOICE_AUTONOMOUS: u8 = 0x80;
// A 20 Hz speech envelope for the one streamed dialogue channel. Geometry and
// controller range are source-exact; this small deterministic envelope avoids
// retaining decoded PCM in main RAM after the sample is uploaded to SPU RAM.
const MOUTH_ENVELOPE: [u8; 16] = [0, 31, 55, 22, 46, 63, 17, 39, 8, 52, 28, 60, 14, 44, 24, 4];
// Exact per-map prop hotlists live in the otherwise-unused tails above
// PROP_COUNT, so they add no BSS.  The first tail byte is the count and the
// following bytes are prop indices; 0xFF requests the original full scan.
//
//   PROP_AI_TARGET tail: humans (scientist/barney, plus seated scientists that
//                        may turn into standing scientists at runtime)
//   PROP_KIND tail:      headcrabs (barney/scientist threat searches)
//   PROP_ACTIVE tail:    pickups
//
// Every indexed loop retains the same live predicates as its old full scan, so
// deaths, dormant monster makers, seated-scientist wakeups, and collected items
// keep precisely the existing behavior.
const PROP_HOT_FALLBACK: u8 = 0xFF;
#[inline(always)]
fn prop_hotlist_count(raw: u8, nprops: usize) -> Option<usize> {
    let count = raw as usize;
    if raw != PROP_HOT_FALLBACK && count <= nprops && nprops + 1 + count <= MAX_PROPS {
        Some(count)
    } else {
        None
    }
}
// AI target re-acquisition is staggered: each prop re-runs the (BSP-trace-heavy)
// find_*_target only every AI_REACQUIRE_INTERVAL sim-ticks, keeping its cached
// PROP_AI_TARGET between -- cuts the per-frame line-of-sight trace count ~Nx on
// enemy-dense maps. At 20 Hz a 4-tick lag is ~200 ms (imperceptible). The same
// stagger now owns the target LOS verdict as well: tracing the unchanged target
// every intervening tick was over half of c2a4e's actor-update cost.
static mut AI_TICK: u32 = 0;
const AI_REACQUIRE_INTERVAL: u32 = 4;
#[inline]
unsafe fn ai_reacquire(pi: usize) -> bool {
    (pi as u32).wrapping_add(AI_TICK) % AI_REACQUIRE_INTERVAL == 0
}
