#[inline]
unsafe fn sprite_is_visible(i: usize) -> bool {
    i < SPRITE_COUNT
        && SPRITE_REMOVED[i >> 5] & (1 << (i & 31)) == 0
        && SPRITE_VISIBLE[i >> 5] & (1 << (i & 31)) != 0
}

#[inline]
unsafe fn sprite_set_visible(i: usize, visible: bool, now: u16) {
    if i >= SPRITE_COUNT || SPRITE_REMOVED[i >> 5] & (1 << (i & 31)) != 0 {
        return;
    }
    let mask = 1u32 << (i & 31);
    if visible {
        SPRITE_VISIBLE[i >> 5] |= mask;
        SPRITE_STARTED[i] = now;
    } else {
        SPRITE_VISIBLE[i >> 5] &= !mask;
    }
}

#[inline]
unsafe fn sprite_remove(i: usize) {
    if i < SPRITE_COUNT {
        let mask = 1u32 << (i & 31);
        SPRITE_VISIBLE[i >> 5] &= !mask;
        SPRITE_REMOVED[i >> 5] |= mask;
    }
}

// ---- DEBUG: crosshair triangle pick (find the world tri under screen centre) ----
// Toggle DEBUG_XHAIR. Each frame the nearest world triangle containing the screen
// centre is recorded into XHAIR + outlined on screen, and its leaf / PVS state is
// resolved. Press L1 to dump XHAIR + camera state to the guest debug log, so the
// same triangle can be compared between a frame where it shows and one where it
// is missing. XHAIR is also peekable in RAM (see captures/hl-psx.map).
const DEBUG_XHAIR: bool = false;
#[repr(C)]
#[derive(Clone, Copy)]
struct XhairHit {
    valid: u32,
    tt: u32,
    idx: [u32; 3],
    v: [[i32; 3]; 3],
    sv: [(i16, i16); 3],
    leaf: i32,
    pvs_visible: u32,
    depth: u32,
    tex: u32,
}
const EMPTY_XHAIR: XhairHit = XhairHit {
    valid: 0,
    tt: 0,
    idx: [0; 3],
    v: [[0; 3]; 3],
    sv: [(0, 0); 3],
    leaf: -1,
    pvs_visible: 0,
    depth: u32::MAX,
    tex: u32::MAX,
};
static mut XHAIR: XhairHit = EMPTY_XHAIR;
static mut XHAIR_DUMP_PREV: bool = false;
static mut XHAIR_DUMP_LAST: u32 = u32::MAX; // last auto-dumped key (tt, or sentinel)

/// World->view rotation. `yaw` is stored in player-space convention, where
/// positive yaw turns the forward vector toward +world X. A view matrix is the
/// inverse of that camera rotation, so negate yaw before building rotY. Pitch is
/// still camera-space so looking up/down while turned doesn't roll the horizon.
/// Rows 0/1 are negated for the GPU's Y-down screen.
/// Aim-stick response curve: ~45% linear + ~55% cubic, so small tilts turn slowly
/// (fine aim) and full tilt gives the full rate. `v` is a raw axis in ~-128..127.
#[inline]
fn aim_curve(v: i32) -> i32 {
    let s = v.signum();
    let a = v.abs().min(128);
    let cubic = a * a / 128 * a / 128; // a^3 / 128^2, back in 0..128
    s * ((a * 45 + cubic * 55) / 100)
}

/// Convert one clean DualShock sample to the cross-engine HLINPUT1 command.
/// Keep this outlined: the reference build is close to MIPS-I's PC16 branch
/// span inside `play`, while the conversion is needed only once per fixed tick.
#[cfg(not(feature = "semantic-input"))]
#[inline(never)]
fn live_semantic_sample(pad: psx_pad::PadState) -> semantic_input::Sample {
    let (mut fwd, mut strafe, mut turn, mut look) = (0i32, 0i32, 0i32, 0i32);
    if pad.is_analog() {
        let (lx, ly) = pad.sticks.left_centered();
        let (rx, ry) = pad.sticks.right_centered();
        let deadzone = settings::analog_deadzone();
        if deadzone.outside(lx, ly) {
            fwd = -(ly as i32);
            strafe = lx as i32;
        }
        if deadzone.outside(rx, ry) {
            turn = aim_curve(rx as i32);
            look = aim_curve(-(ry as i32));
        }
    }
    // PSoXide can expose port 1 as a digital pad, and keyboard play commonly
    // drives its D-pad.  The old adapter gated all movement on `is_analog()`
    // and ignored these buttons, leaving a normal player completely rooted
    // while deterministic semantic-input tests still moved correctly.  Let a
    // pressed D-pad axis override the corresponding stick axis; opposing
    // directions cancel through `digital_axis`.
    let digital_fwd = semantic_input::digital_axis(
        pad.buttons.is_held(button::DOWN),
        pad.buttons.is_held(button::UP),
    );
    let digital_strafe = semantic_input::digital_axis(
        pad.buttons.is_held(button::LEFT),
        pad.buttons.is_held(button::RIGHT),
    );
    if digital_fwd != 0 || pad.buttons.is_held(button::UP) || pad.buttons.is_held(button::DOWN) {
        fwd = digital_fwd as i32;
    }
    if digital_strafe != 0
        || pad.buttons.is_held(button::LEFT)
        || pad.buttons.is_held(button::RIGHT)
    {
        strafe = digital_strafe as i32;
    }
    let mut actions = 0u16;
    actions |= (pad.buttons.is_held(button::R2) as u16) * semantic_input::ACTION_ATTACK;
    actions |= (pad.buttons.is_held(button::CROSS) as u16) * semantic_input::ACTION_JUMP;
    actions |= (pad.buttons.is_held(button::TRIANGLE) as u16) * semantic_input::ACTION_DUCK;
    actions |= (pad.buttons.is_held(button::SQUARE) as u16) * semantic_input::ACTION_USE;
    actions |= (pad.buttons.is_held(button::L2) as u16) * semantic_input::ACTION_ATTACK2;
    actions |= (pad.buttons.is_held(button::CIRCLE) as u16) * semantic_input::ACTION_RELOAD;
    actions |= (pad.buttons.is_held(button::R1) as u16) * semantic_input::ACTION_NEXT_WEAPON;
    actions |= (pad.buttons.is_held(button::L1) as u16) * semantic_input::ACTION_PREV_WEAPON;
    actions |= (pad.buttons.is_held(button::L3) as u16) * semantic_input::ACTION_FLASHLIGHT;
    semantic_input::Sample {
        forward: fwd.clamp(i8::MIN as i32, i8::MAX as i32) as i8,
        strafe: strafe.clamp(i8::MIN as i32, i8::MAX as i32) as i8,
        turn: turn.clamp(i8::MIN as i32, i8::MAX as i32) as i8,
        look: look.clamp(i8::MIN as i32, i8::MAX as i32) as i8,
        actions,
    }
}

/// Simulation-tick-owned c1a0 benchmark input. Unlike a host/vblank tape, this
/// route reaches the exact same camera states when renderer cost changes, so an
/// optimization cannot accidentally benchmark a different view. Values are
/// the post-deadzone commands produced by the original DualShock tape.
#[cfg(feature = "performance-telemetry")]
#[inline(never)]
fn performance_walk_sample(sim_tick: u32) -> semantic_input::Sample {
    let (forward, strafe, turn) = match sim_tick {
        0..=103 => (-127, 0, 0),
        104..=158 => (-104, 0, 24),
        159..=211 => (-88, 80, 0),
        212..=270 => (-96, 0, -24),
        _ => (0, 0, 0),
    };
    semantic_input::Sample {
        forward,
        strafe,
        turn,
        look: 0,
        actions: 0,
    }
}

#[cfg(not(feature = "semantic-input"))]
enum LiveInputPoll {
    Sample(semantic_input::Sample),
    Resumed,
    MainMenu,
    Chapter(usize),
}

/// Poll/configure the controller and own the pause transaction outside the
/// already branch-span-sensitive gameplay loop.
#[cfg(not(feature = "semantic-input"))]
#[inline(never)]
fn poll_live_semantic_input(
    fb: &mut FrameBuffer,
    last_pad: &mut psx_pad::PadState,
    prev_pause_button: &mut bool,
    next_sim_vblank: &mut u32,
) -> LiveInputPoll {
    let sampled_pad = poll_port1_diag(DEFAULT_SETUP_SPINS, 0).to_state();
    let pad = if sampled_pad.mode == PadMode::Unknown {
        *last_pad
    } else {
        *last_pad = sampled_pad;
        sampled_pad
    };
    let pause_button = pad.buttons.is_held(button::START) || pad.buttons.is_held(button::SELECT);
    if pause_button && !*prev_pause_button {
        telemetry::stage_end(telemetry::stage::UPDATE);
        telemetry::task_end(telemetry::task::FIXED_UPDATE);
        return match run_pause_menu(fb) {
            PauseExit::MainMenu => LiveInputPoll::MainMenu,
            PauseExit::Chapter(room) => LiveInputPoll::Chapter(room),
            // Same relaunch path as a chapter jump: PENDING_RESTORE is already
            // armed, and play() overrides the spawn it computes.
            PauseExit::LoadedSave(room) => LiveInputPoll::Chapter(room),
            PauseExit::Resume => {
                // The pause screen is the only way brightness can move with a
                // map already resident, so the palette re-expansion is paid
                // here rather than tested every frame. Every other exit reloads
                // a map, which expands it anyway.
                if settings::take_brightness_dirty() {
                    map::reapply_brightness();
                }
                let _ = enable_analog_port1();
                *last_pad = poll_port1();
                *prev_pause_button = true;
                *next_sim_vblank = interrupts::vblank_count().wrapping_add(SIM_VBLANKS);
                LiveInputPoll::Resumed
            }
        };
    }
    *prev_pause_button = pause_button;
    if matches!(sampled_pad.mode, PadMode::Digital | PadMode::Config) {
        let _ = enable_analog_port1();
    }
    LiveInputPoll::Sample(live_semantic_sample(pad))
}

fn view_rotation(yaw: u16, pitch: i16) -> Mat3I16 {
    view_rotation_roll(yaw, pitch, 0)
}

/// As `view_rotation` but with a camera ROLL (rotation about the view forward
/// axis) -- GoldSrc's `V_CalcRoll` banks the view slightly when you strafe. `roll`
/// is an 8-bit angle (256 = full turn), applied in view space before the Y-down
/// row flip so it tilts the horizon.
fn view_rotation_roll(yaw: u16, pitch: i16, roll: i16) -> Mat3I16 {
    let view_yaw = 0u16.wrapping_sub(yaw >> 4);
    let mut look = Mat3I16::rotate_x((pitch >> 4) as u16).mul(&Mat3I16::rotate_y(view_yaw));
    if roll != 0 {
        look = Mat3I16::rotate_z(roll as u16).mul(&look);
    }
    let mut r = look;
    let mut j = 0;
    while j < 3 {
        // Negate ONLY row 1 (screen Y, GPU Y-down). Leaving row 0 (screen X)
        // un-negated makes the camera det -1, which cancels the cook's [x,z,y]
        // reflection (det -1): net det +1, so the world renders UN-mirrored (it
        // used to be a mirror image of real HL). The screen-space winding flips
        // with it, so `culled`/`culled_soft` flip their sign to match.
        r.m[1][j] = -r.m[1][j];
        j += 1;
    }
    r
}

#[cfg(feature = "deep-reference-trace")]
#[inline(never)]
fn trace_player_hull_probes(
    map_tick: u32,
    m: &Map,
    movers: &[phys::Mover],
    player: &phys::Player,
    fwd: i32,
    yaw: u16,
    jump: bool,
) {
    if !jump {
        // Airborne fall probe: record the active hull's next ballistic segment.
        // This makes post-ledge divergences attributable to an exact plane and
        // stays entirely out of ordinary/reference builds.
        if !player.on_ground && player.vel[1] < 0 {
            reference_trace::player_hull(
                map_tick,
                3,
                player.hull_probe(m, movers, player.next_fall_delta()),
            );
        }
        return;
    }
    let s = sincos::sin_q12(yaw);
    let c = sincos::sin_q12((yaw + 1024) & 0x0fff);
    let vx = (s * fwd / 128 * 16) >> 12;
    let vz = (c * fwd / 128 * 16) >> 12;
    reference_trace::player_hull(map_tick, 0, player.hull_probe(m, movers, [0, 0, 0]));
    reference_trace::player_hull(map_tick, 1, player.hull_probe(m, movers, [0, 13, 0]));
    reference_trace::player_hull(map_tick, 2, player.hull_probe(m, movers, [vx, 13, vz]));
}

#[inline(always)]
fn dot12(row: [i16; 3], e: [i32; 3]) -> i32 {
    ((row[0] as i32 * e[0]) + (row[1] as i32 * e[1]) + (row[2] as i32 * e[2])) >> 12
}

#[inline(always)]
fn dot12_q5(row: [i16; 3], e: [i32; 3]) -> i32 {
    ((row[0] as i32 * e[0]) + (row[1] as i32 * e[1]) + (row[2] as i32 * e[2]))
        >> (map::PLANE_NORMAL_FRAC_BITS - 5)
}

#[inline(always)]
fn dot_plane(row: [i16; 3], e: [i32; 3]) -> i32 {
    ((row[0] as i32 * e[0]) + (row[1] as i32 * e[1]) + (row[2] as i32 * e[2]))
        >> map::PLANE_NORMAL_FRAC_BITS
}

/// Dot a Q12 direction with a Q14 map plane, returning Q12.
#[inline(always)]
fn dot12_plane(q12: [i16; 3], plane: [i16; 3]) -> i32 {
    ((q12[0] as i32 * plane[0] as i32)
        + (q12[1] as i32 * plane[1] as i32)
        + (q12[2] as i32 * plane[2] as i32))
        >> map::PLANE_NORMAL_FRAC_BITS
}

#[inline(always)]
fn model_local_to_world_q12(raw: u16) -> i32 {
    if raw == 0 {
        4096
    } else {
        raw as i32
    }
}

#[inline(always)]
fn model_local_scale(raw: u16) -> i32 {
    (4096 / model_local_to_world_q12(raw)).max(1)
}

#[inline(always)]
fn model_local_scale_and_shift(raw: u16) -> (i32, u8) {
    let s = model_local_scale(raw);
    match s {
        1 => (1, 0),
        2 => (2, 1),
        4 => (4, 2),
        8 => (8, 3),
        16 => (16, 4),
        // Model::load rejects every other HMD8 scale. Keep a safe release
        // fallback for the static EMPTY model contract without reintroducing
        // a per-face divide path.
        _ => {
            debug_assert!(false, "invalid HMD8 model scale");
            (1, 0)
        }
    }
}

#[inline(always)]
fn model_unscale_depth(depth: u32, shift: u8) -> u32 {
    depth >> shift
}

#[inline(always)]
fn canonical_ram_const<T>(p: *const T) -> *const T {
    #[cfg(target_arch = "mips")]
    {
        (((p as usize) & 0x001f_ffff) | 0x8000_0000) as *const T
    }
    #[cfg(not(target_arch = "mips"))]
    {
        p
    }
}

#[inline(always)]
unsafe fn streamed_map_bytes(len: usize) -> &'static [u8] {
    let ptr = canonical_ram_const(arena_ptr().cast::<u8>());
    unsafe { core::slice::from_raw_parts(ptr, len) }
}

/// Stream the menu bg+logo art chunk into MAP_BUF (free before a map loads) and
/// return the raw blob for `menu::run`/`ending`. These are no longer baked into
/// the EXE (~33 KiB of .rodata reclaimed); re-streamed on every menu entry since
/// play() clobbers MAP_BUF + the menu VRAM. Empty on a failed read -> menu still
/// runs, just unbranded.
#[inline(never)]
unsafe fn stream_menu_assets() -> &'static [u8] {
    let n = cdstream::load_chunk_decompressed(menu::MENU_CHUNK_ID, map_buf())
        .map(|load| load.raw_len)
        .unwrap_or(0);
    streamed_map_bytes(n.max(8))
}

unsafe fn streamed_model_bytes_at(byte_off: usize, len: usize) -> &'static [u8] {
    let ptr = canonical_ram_const(model_ptr().cast::<u8>());
    unsafe { core::slice::from_raw_parts(ptr.add(byte_off), len) }
}

#[inline(always)]
unsafe fn viewmodel_bytes_at(byte_off: usize, len: usize) -> &'static [u8] {
    let ptr = canonical_ram_const(model_ptr().cast::<u8>());
    unsafe { core::slice::from_raw_parts(ptr.add(byte_off), len) }
}

/// Stream one authored viewmodel (geometry -> MODEL_BUF head reserve, textures
/// -> VM_SLOTS). Idempotent for the selected weapon; otherwise replaces the
/// one live geometry stream. The merged chunk stages through the whole reserve,
/// including invalid projected/sort scratch, before its texture tail uploads.
unsafe fn stream_one_viewmodel(
    wm: usize,
    stream_chunks: &mut u32,
    stream_bytes: &mut u32,
    stream_sectors: &mut u32,
) -> bool {
    if wm >= N_VIEWMODELS {
        return false;
    }
    if VM_ENTRY.valid && VM_LIVE_WM as usize == wm {
        return true;
    }
    // A nonzero base means the map-load checkpoint exists. Rewind to word zero
    // on every real switch; retaining several static poses was what forced the
    // old 576-triangle truncation and left no room for authored animation.
    if VM_FILL_BASE_SLOT > 0 {
        vm_cache_store_live();
        vm_evict_selected();
    }
    let word = VM_FILL_WORD;
    let slot = VM_FILL_SLOT;
    if word >= VM_POOL_WORDS || slot >= VM_SLOTS_TOTAL {
        return false;
    }
    let buf_ptr = model_ptr();
    // GPU submission is synchronous before input/update can switch weapons, so
    // no draw can still reference the old geometry or projection scratch.
    invalidate_weapon_tri_cache();
    let wm_chunk = wm as u32;
    // ONE merged chunk per weapon ("HMRG" | u32 geom_len | geom | tex): one
    // CD handshake per switch instead of two.
    let dst = core::slice::from_raw_parts_mut(buf_ptr.add(word), VM_POOL_WORDS - word);
    let Some(load) = load_streamed_chunk(MODEL_CHUNK_V_9MMHANDGUN + wm_chunk, dst) else {
        return false;
    };
    if !vm_publish_streamed(wm, word, slot, load.raw_len) {
        return false;
    }
    account_streamed_chunk(load, stream_chunks, stream_bytes, stream_sectors);
    true
}

/// Shared tail of a viewmodel stream (the blocking map-load path and the
/// switch pump's completion tick): validate the landed "HMRG" chunk at
/// `word`, upload its texture tail, and publish the live entry/model/fill
/// cursors. `clen` is the chunk's raw byte length; `word`/`slot` are the
/// post-evict fill cursors the chunk landed at.
unsafe fn vm_publish_streamed(wm: usize, word: usize, slot: usize, clen: usize) -> bool {
    let buf_ptr = model_ptr();
    if clen < 8
        || word + clen.div_ceil(4) > VM_POOL_WORDS
        || *buf_ptr.add(word) != u32::from_le_bytes(*b"HMRG")
    {
        return false;
    }
    let glen = (*buf_ptr.add(word + 1)) as usize;
    if glen + 8 > clen {
        return false;
    }
    let gw = word + 2;
    let glen_words = glen.div_ceil(4);
    if gw + glen_words > VM_CACHE_START_WORD {
        return false;
    }
    let tex_bytes = viewmodel_bytes_at(gw * 4 + glen, clen - 8 - glen);
    telemetry::stage_begin(telemetry::stage::VRAM_UPLOAD);
    let Some(uploaded) = vram::upload_tex_chunk_append_raw(
        tex_bytes,
        core::ptr::addr_of_mut!(VM_SLOTS)
            .cast::<TexSlot>()
            .add(slot),
        VM_SLOTS_TOTAL - slot,
    ) else {
        telemetry::stage_end(telemetry::stage::VRAM_UPLOAD);
        return false;
    };
    telemetry::stage_end(telemetry::stage::VRAM_UPLOAD);
    let ntex = uploaded.0;
    if ntex == 0 {
        return false;
    }
    if slot + ntex > VM_SLOTS_TOTAL {
        return false;
    }
    let model = Model::load(viewmodel_bytes_at(gw * 4, glen));
    #[cfg(feature = "debug-weapon-gallery")]
    if model.n_verts != room_budget::VIEWMODEL_VERTS[wm] as usize
        || model.n_tris != room_budget::VIEWMODEL_TRIS[wm] as usize
    {
        return false;
    }
    VM_ENTRY = VmEntry {
        valid: true,
        geom_off: gw * 4,
        geom_len: glen,
        slot_start: slot,
        n_slots: ntex,
    };
    VM_MODEL_CACHE = model;
    VM_LIVE_WM = wm as u8;
    VM_LIVE_CHUNK_WORDS = clen.div_ceil(4);
    VM_LIVE_CHUNK_BYTES = clen;
    VM_FILL_WORD = gw + glen_words;
    VM_FILL_SLOT = slot + ntex;
    if word == 0 {
        vm_backup_live_tail();
    }
    true
}

/// Outcome of [`vm_switch_begin`].
#[derive(Clone, Copy, PartialEq, Eq)]
enum VmSwitchBegin {
    /// The requested weapon is already the live geometry; nothing streams.
    Live,
    /// A pump session is open (new or already in flight for this weapon).
    Streaming,
    /// The stream could not be opened (bad id / missing entry / CD error).
    Failed,
}

/// Outcome of one [`vm_switch_pump`] tick.
#[derive(Clone, Copy, PartialEq, Eq)]
enum VmSwitchPump {
    /// No switch stream is in flight.
    Idle,
    /// Sectors are still landing; the viewmodel stays hidden.
    InFlight,
    /// The new weapon published this tick: start its draw animation.
    Ready,
    /// The stream died or the chunk was invalid; fall back to the glock.
    Failed,
}

/// Correctness backstop for an incremental CD session that stalls or lands a
/// corrupt payload. A cold switch may hitch in this exceptional path, but it
/// must never publish the Glock under another weapon's gameplay state. The
/// previous-weapon tail cache remains available for the common back-switch.
unsafe fn vm_switch_retry_blocking(wm: usize) -> bool {
    cdstream::stream_abort();
    VM_STREAM_WM = VM_NONE;
    #[cfg(any(feature = "performance-telemetry", feature = "emulator-telemetry"))]
    tty::println("hl-psx: retrying viewmodel with blocking read");
    let mut chunks = 0;
    let mut bytes = 0;
    let mut sectors = 0;
    stream_one_viewmodel(wm, &mut chunks, &mut bytes, &mut sectors)
}

/// Begin an incremental viewmodel switch (OC-02): evict the live geometry,
/// suspend CDDA once for the session, and open the bounded per-tick CD pump
/// for the weapon's merged chunk. The old blocking path streamed the whole
/// chunk (~38 sectors, ~15 vblanks) inside one fixed-update tick, freezing
/// every render; the pump spreads those sectors across ticks while the
/// player's hands render empty (VM_ENTRY invalid), like a holster window.
/// A newer request supersedes an in-flight stream -- never queued.
#[optimize(size)]
unsafe fn vm_switch_begin(wm: usize) -> VmSwitchBegin {
    if wm >= N_VIEWMODELS {
        return VmSwitchBegin::Failed;
    }
    if VM_ENTRY.valid && VM_LIVE_WM as usize == wm {
        return VmSwitchBegin::Live;
    }
    if VM_STREAM_WM as usize == wm && cdstream::stream_active() {
        return VmSwitchBegin::Streaming; // already streaming this weapon
    }
    if VM_CACHED_WM as usize == wm {
        cdstream::stream_abort();
        VM_STREAM_WM = VM_NONE;
        if vm_cache_swap(wm) {
            return VmSwitchBegin::Live;
        }
    }
    VM_STREAM_WM = VM_NONE;
    // Once per stream session: capture the CDDA resume position and close the
    // audio route. music_apply stays parked while the session owns the drive
    // and replays the cue on the first tick after completion.
    music_suspend_for_stream();
    if VM_FILL_BASE_SLOT > 0 {
        vm_cache_store_live();
        vm_evict_selected();
    }
    let word = VM_FILL_WORD;
    let slot = VM_FILL_SLOT;
    if word >= VM_POOL_WORDS || slot >= VM_SLOTS_TOTAL {
        return VmSwitchBegin::Failed;
    }
    // GPU submission is synchronous before input/update can switch weapons, so
    // no draw can still reference the old geometry or projection scratch.
    invalidate_weapon_tri_cache();
    let buf_ptr = model_ptr();
    if !cdstream::stream_begin(
        MODEL_CHUNK_V_9MMHANDGUN + wm as u32,
        buf_ptr.add(word),
        VM_POOL_WORDS - word,
    ) {
        return VmSwitchBegin::Failed;
    }
    VM_STREAM_WM = wm as u8;
    VmSwitchBegin::Streaming
}

/// Advance the in-flight switch stream by the per-tick sector budget. On the
/// completion tick the texture tail uploads and the new entry publishes; the
/// caller starts the draw animation. Runs under the CD stream telemetry
/// stage, so a switch shows as small per-tick slices instead of one spike.
unsafe fn vm_switch_pump() -> VmSwitchPump {
    if VM_STREAM_WM == VM_NONE {
        return VmSwitchPump::Idle;
    }
    let wm = VM_STREAM_WM as usize;
    telemetry::stage_begin(telemetry::stage::CD_WORLD_PACK_STREAM);
    let pumped = cdstream::stream_pump();
    telemetry::stage_end(telemetry::stage::CD_WORLD_PACK_STREAM);
    match pumped {
        cdstream::StreamPump::InFlight => VmSwitchPump::InFlight,
        cdstream::StreamPump::Done(load) => {
            VM_STREAM_WM = VM_NONE;
            // The fill cursors are stable between begin and completion (only
            // another begin mutates them, and it restarts the stream).
            let published = vm_publish_streamed(wm, VM_FILL_WORD, VM_FILL_SLOT, load.raw_len);
            if published || vm_switch_retry_blocking(wm) {
                VmSwitchPump::Ready
            } else {
                VmSwitchPump::Failed
            }
        }
        // Idle here means the session was closed underneath an armed switch
        // (a blocking load superseded it); treat like a failure -> glock.
        cdstream::StreamPump::Idle | cdstream::StreamPump::Failed => {
            VM_STREAM_WM = VM_NONE;
            if vm_switch_retry_blocking(wm) {
                VmSwitchPump::Ready
            } else {
                VmSwitchPump::Failed
            }
        }
    }
}

/// Reset the viewmodel pool and preload only the glock (the spawn weapon + the
/// fallback). Every other weapon streams in on first switch, so a map load
/// streams one viewmodel instead of all 14. Returns whether the glock loaded.
unsafe fn load_resident_viewmodels(
    stream_chunks: &mut u32,
    stream_bytes: &mut u32,
    stream_sectors: &mut u32,
) -> bool {
    // No switch pump survives a map load; also resolve every viewmodel chunk
    // into the persistent entry cache while the pack table is resident, so
    // later switches never re-read the header sectors.
    cdstream::stream_abort();
    VM_STREAM_WM = VM_NONE;
    cdstream::prime_persistent_entries(MODEL_CHUNK_V_9MMHANDGUN, N_VIEWMODELS);
    VM_ENTRY = VmEntry::NONE;
    VM_LIVE_WM = VM_NONE;
    VM_MODEL_CACHE = Model::EMPTY;
    VM_FILL_WORD = 0;
    VM_FILL_SLOT = 0;
    VM_FILL_BASE_SLOT = 0;
    VM_TAIL_READY = false;
    VM_CACHED_WM = VM_NONE;
    VM_CACHED_CHUNK_WORDS = 0;
    VM_CACHED_CHUNK_BYTES = 0;
    VM_LIVE_CHUNK_WORDS = 0;
    VM_LIVE_CHUNK_BYTES = 0;
    VM_LIVE_TAIL_WORDS = 0;
    MODEL_RESIDENT_WORDS = model_capacity();
    stream_one_viewmodel(0, stream_chunks, stream_bytes, stream_sectors)
}

/// Resolve the one live viewmodel and report its authored model index. A failed
/// selected load is immediately replaced with the Glock before this is called.
unsafe fn viewmodel_for(_wm: usize) -> (Model, usize, usize, usize) {
    if !VM_ENTRY.valid || VM_LIVE_WM == VM_NONE {
        return (Model::EMPTY, 0, 0, 0);
    }
    (
        VM_MODEL_CACHE,
        VM_ENTRY.slot_start,
        VM_ENTRY.n_slots,
        VM_LIVE_WM as usize,
    )
}

#[inline]
unsafe fn loaded_model(slot: usize) -> Model {
    LOADED_MODEL_CACHE[slot]
}

/// Union of studio body values that can be visible for this model stream.
/// Filtering unused heads before the face pool keeps the campaign's audited
/// 8,192-face capacity intact. Barney retains all three gun states because his
/// body changes at runtime; scientist heads are immutable outside the syringe
/// animation, which this runtime does not yet schedule.
unsafe fn model_visible_bodies(
    ty: usize,
    nprops: usize,
    ncarry: usize,
    carry_variant: bool,
    has_body_masks: bool,
) -> u8 {
    if !has_body_masks {
        return 0xff;
    }
    if ty == PROP_TYPE_SODACAN as usize {
        return 0x3f;
    }
    if ty == PROP_TYPE_BARNEY as usize && !carry_variant {
        return 0x07;
    }
    if ty != PROP_TYPE_SCIENTIST as usize
        && ty != PROP_TYPE_BARNEY as usize
        && ty != PROP_TYPE_SITTING_SCI as usize
        && ty != PROP_TYPE_SCRIPTED_SITTING_SCI as usize
    {
        // Other bodygroup-bearing models never change body at runtime and the
        // cooker leaves their authored value at GoldSrc's default body 0.
        return 1;
    }
    let mut mask = 0u8;
    let mut pi = 0usize;
    while pi < nprops {
        if PROP_KIND[pi] as usize == ty {
            mask |= 1u8 << prop_body_value(PROP_YAW[pi]).min(7);
        }
        pi += 1;
    }
    let mut ci = 0usize;
    while ci < ncarry {
        let (kind, _, _, _, _, yaw) = carry_mail_read(ci);
        if kind as usize == ty {
            mask |= 1u8 << prop_body_value(yaw).min(7);
        }
        ci += 1;
    }
    if mask == 0 {
        1
    } else {
        mask
    }
}

/// Stream the model types this map places (distinct prop kinds) into the shared
/// pool: geometry into MODEL_BUF after the viewmodel, render faces into the
/// split POOL_FACE_* streams, textures into VRAM (POOL_TEX). `TYPE_TO_SLOT` maps a type id to
/// its `LOADED_MODELS` entry; types that don't fit the buffers are skipped (the
/// prop simply doesn't render).
#[optimize(size)]
unsafe fn stream_map_models(
    weapon_len: usize,
    carry_count: u8,
    map_index: usize,
    stream_chunks: &mut u32,
    stream_bytes: &mut u32,
    stream_sectors: &mut u32,
) {
    for t in TYPE_TO_SLOT.iter_mut() {
        *t = MODEL_SLOT_NONE;
    }
    for lm in LOADED_MODELS.iter_mut() {
        *lm = LoadedModel::ZERO;
    }
    let buf_ptr = model_ptr();
    let mut geom_word = weapon_len.div_ceil(4); // viewmodel reserves the head
    let mut face_off = 0usize;
    let mut run_off = 0usize;
    let mut tex_off = 0usize;
    let mut slot_idx = 0usize;
    let nprops = PROP_COUNT.min(CARRY_MAILBOX_FIRST);
    let ncarry = logic_state::carry_record_count(carry_count).min(CARRY_CAPACITY);
    // Three passes by importance: combat monsters, then pickups/items, then
    // decorative render-only types (AI_IDLE: bosses, flyers, statues). A heavy
    // roster drops a statue -- never a fighting enemy, and pickups outrank
    // scenery (an invisible medkit still collects, but shouldn't happen).
    let mut pass = 0;
    let mut source = 0; // incoming mailbox first, then the complete live roster
    let mut rank = 0usize;
    let mut pi = 0usize;
    loop {
        let source_len = if source == 0 { ncarry } else { nprops };
        if pi >= source_len {
            if rank + 1 < N_MODEL_TYPES {
                rank += 1;
                pi = 0;
                continue;
            }
            if source == 0 {
                source = 1;
                rank = 0;
                pi = 0;
                continue;
            }
            if pass < 2 {
                pass += 1;
                source = 0;
                rank = 0;
                pi = 0;
                continue;
            }
            break;
        }
        // Carry-only types get first refusal within each importance tier. This
        // prevents a progression actor (Barney/BigMomma/Apache) from losing its
        // model to a destination decoration when a pool is tight.
        let ty = if source == 0 {
            carry_mail_read(pi).0 as usize
        } else {
            PROP_KIND[pi] as usize
        };
        pi += 1;
        if ty != MODEL_STREAM_ORDER[rank] as usize {
            continue;
        }
        if ty >= N_MODEL_TYPES || TYPE_TO_SLOT[ty] != MODEL_SLOT_NONE {
            continue; // out of range, or this type is already resident
        }
        let want_pass = match model_def(ty as u8).ai {
            AI_IDLE => 2,
            AI_ITEM => 1,
            _ => 0,
        };
        if pass != want_pass {
            continue; // wrong pass for this type
        }
        if slot_idx >= MAX_LOADED_MODELS || geom_word >= model_capacity() {
            break;
        }
        // Most types are one `HMRG | geom_len | geom | tex` chunk. Large human
        // bodygroup streams and G-Man stay split: after baking their faces we
        // overwrite the dead triangle tail with HLTX, so geometry and textures
        // never need to coexist in the transient model arena.
        let mut destination_has_type = false;
        let mut destination_pi = 0usize;
        while destination_pi < nprops {
            if PROP_KIND[destination_pi] as usize == ty {
                destination_has_type = true;
                break;
            }
            destination_pi += 1;
        }
        // Restore resets the source map's script state. A destination may still
        // possess the carried actor by targetname; in that case the generated
        // map variant below contains its destination-only clips. Otherwise the
        // compact five-state carry stream remains the fallback.
        let carry_variant = source == 0 && !destination_has_type;
        let per_map_variant = map_model_variant_chunk(map_index, ty);
        let legacy_variant = if per_map_variant.is_none()
            && !carry_variant
            && ty == 5
            && map_index == C1A2B_MAP_INDEX
        {
            Some((C1A2B_ZOMBIE_MODEL_CHUNK, C1A2B_ZOMBIE_TEXTURE_CHUNK))
        } else if per_map_variant.is_none()
            && !carry_variant
            && ty == 9
            && matches!(map_index, C1A2B_MAP_INDEX | C4A3_MAP_INDEX)
        {
            Some((PRESSURE_ISLAVE_MODEL_CHUNK, PRESSURE_ISLAVE_TEXTURE_CHUNK))
        } else if per_map_variant.is_none() && !carry_variant && ty == 16 {
            if map_index == C4A1B_MAP_INDEX {
                Some((C4A1B_GARG_MODEL_CHUNK, C4A1B_GARG_TEXTURE_CHUNK))
            } else if map_index == C4A3_MAP_INDEX {
                Some((C4A3_GARG_MODEL_CHUNK, C4A3_GARG_TEXTURE_CHUNK))
            } else {
                None
            }
        } else if per_map_variant.is_none()
            && !carry_variant
            && ty == 19
            && map_index == C4A3_MAP_INDEX
        {
            Some((C4A3_ICKY_MODEL_CHUNK, C4A3_ICKY_TEXTURE_CHUNK))
        } else {
            None
        };
        let split_model = if per_map_variant.is_some() {
            split_model_stream(ty)
        } else {
            legacy_variant.is_some() || (!carry_variant && split_model_stream(ty))
        };

        let dst =
            core::slice::from_raw_parts_mut(buf_ptr.add(geom_word), model_capacity() - geom_word);
        let chunk_id = if let Some(chunk) = per_map_variant {
            chunk
        } else if let Some((geometry, _)) = legacy_variant {
            geometry
        } else if carry_variant {
            MODEL_CARRY_CHUNK_BASE + ty as u32
        } else {
            MODEL_GEOM_CHUNK_BASE + ty as u32
        };
        let Some(load) = load_streamed_chunk(chunk_id, dst) else {
            continue;
        };
        account_streamed_chunk(load, stream_chunks, stream_bytes, stream_sectors);
        let clen = load.raw_len;
        if clen < 8 || geom_word + clen.div_ceil(4) > model_capacity() {
            continue; // missing chunk or would overflow MODEL_BUF -> skip type
        }
        let (gw, glen) = if split_model {
            let magic = *buf_ptr.add(geom_word);
            if clen < 36 || magic != u32::from_le_bytes(*b"HMD8") {
                continue;
            }
            (geom_word, clen)
        } else {
            if *buf_ptr.add(geom_word) != u32::from_le_bytes(*b"HMRG") {
                continue; // unknown chunk format
            }
            let glen = (*buf_ptr.add(geom_word + 1)) as usize;
            if glen + 8 > clen {
                continue;
            }
            (geom_word + 2, glen) // geometry blob start (words)
        };
        let md = Model::load(streamed_model_bytes_at(gw * 4, glen));
        let visible_bodies =
            model_visible_bodies(ty, nprops, ncarry, carry_variant, md.has_body_masks());
        let model_faces = md.render_face_count(visible_bodies);
        let model_runs = md.render_face_run_count(visible_bodies);
        let compact_body_textures = md.has_body_masks();
        let used_textures = if compact_body_textures {
            md.render_texture_mask(visible_bodies)
        } else {
            0
        };
        if compact_body_textures && used_textures.count_ones() as usize > POOL_TEX_SLOTS - tex_off {
            continue;
        }
        if face_off + model_faces > POOL_FACE_CAP || run_off + model_runs > POOL_FACE_RUN_CAP {
            continue; // face/run pool exhausted: drop the whole type (a pass-2
                      // statue by tier order) instead of baking it partially
        }
        let (nf, nr) = md.fill_render_faces_split_raw(
            core::ptr::addr_of_mut!(POOL_FACE_INDICES)
                .cast::<u32>()
                .add(face_off),
            core::ptr::addr_of_mut!(POOL_FACE_PAYLOADS)
                .cast::<ModelRenderFacePayload>()
                .add(face_off),
            core::ptr::addr_of_mut!(POOL_FACE_RUNS)
                .cast::<u32>()
                .add(run_off),
            POOL_FACE_CAP - face_off,
            visible_bodies,
        );
        // The pool draw reads topology from POOL_FACE_* (baked above) and only
        // verts/clips from the blob, so the TriRec tail is dead weight now.
        // Keep just the frame section; the NEXT type's chunk loads over the
        // dropped tail + the in-chunk texture once it's uploaded.
        let mut kept = md.frame_section_len().min(glen);
        if md.has_body_masks() {
            // MODEL_SCRATCH is dead during map streaming and provides a
            // zero-RAM old->compact vertex table. Removing unused scientist
            // heads here shrinks retained animation bytes and the hot draw's
            // projection count; the already-baked face stream is remapped once.
            let remap = core::ptr::addr_of_mut!(MODEL_SCRATCH).cast::<u16>();
            if let Some(compact_kept) = md.compact_visible_body_frames_raw(
                buf_ptr.add(gw).cast::<u8>(),
                glen,
                visible_bodies,
                remap,
                MAX_MODEL_VERTS,
            ) {
                kept = compact_kept;
                let indices = core::ptr::addr_of_mut!(POOL_FACE_INDICES)
                    .cast::<u32>()
                    .add(face_off);
                for face in 0..nf {
                    let packed = core::ptr::read(indices.add(face));
                    let a = core::ptr::read(
                        remap.add((packed & model::RENDER_FACE_INDEX_MASK) as usize),
                    );
                    let b = core::ptr::read(
                        remap.add(((packed >> 10) & model::RENDER_FACE_INDEX_MASK) as usize),
                    );
                    let c = core::ptr::read(
                        remap.add(((packed >> 20) & model::RENDER_FACE_INDEX_MASK) as usize),
                    );
                    debug_assert!(a != u16::MAX && b != u16::MAX && c != u16::MAX);
                    core::ptr::write(
                        indices.add(face),
                        a as u32 | ((b as u32) << 10) | ((c as u32) << 20),
                    );
                }
            }
        }
        *buf_ptr.add(gw + 2) = 0; // header u32 n_tris at byte offset 8
        let tex_bytes = if split_model {
            let stage_word = gw + kept.div_ceil(4);
            if stage_word >= model_capacity() {
                continue;
            }
            let dst = core::slice::from_raw_parts_mut(
                buf_ptr.add(stage_word),
                model_capacity() - stage_word,
            );
            let texture_chunk = if per_map_variant.is_some() {
                MODEL_TEX_CHUNK_BASE + ty as u32
            } else if let Some((_, texture)) = legacy_variant {
                texture
            } else {
                MODEL_TEX_CHUNK_BASE + ty as u32
            };
            let Some(load) = load_streamed_chunk(texture_chunk, dst) else {
                continue;
            };
            account_streamed_chunk(load, stream_chunks, stream_bytes, stream_sectors);
            let tlen = load.raw_len;
            if tlen < 8
                || stage_word + tlen.div_ceil(4) > model_capacity()
                || *buf_ptr.add(stage_word) != u32::from_le_bytes(*b"HLTX")
            {
                continue;
            }
            streamed_model_bytes_at(stage_word * 4, tlen)
        } else {
            streamed_model_bytes_at(gw * 4 + glen, clen - 8 - glen)
        };
        let mut texture_remap = [u8::MAX; 32];
        let ntex = if compact_body_textures {
            telemetry::stage_begin(telemetry::stage::VRAM_UPLOAD);
            let uploaded = vram::upload_tex_chunk_append_masked_raw(
                tex_bytes,
                core::ptr::addr_of_mut!(POOL_TEX)
                    .cast::<TexSlot>()
                    .add(tex_off),
                POOL_TEX_SLOTS - tex_off,
                used_textures,
                &mut texture_remap,
            );
            telemetry::stage_end(telemetry::stage::VRAM_UPLOAD);
            let Some((ntex, _tex_fail)) = uploaded else {
                continue;
            };
            // Face runs still contain the original texture ids. Retarget them
            // to the compact slots without touching the hot per-face stream.
            let runs = core::ptr::addr_of_mut!(POOL_FACE_RUNS).cast::<u32>();
            for r in 0..nr {
                let run = core::ptr::read(runs.add(run_off + r));
                let old_tex = ((run >> 16) & 0xff) as usize;
                if old_tex < texture_remap.len() {
                    let new_tex = texture_remap[old_tex];
                    core::ptr::write(
                        runs.add(run_off + r),
                        (run & 0xff00_ffff) | ((new_tex as u32) << 16),
                    );
                }
            }
            ntex
        } else {
            telemetry::stage_begin(telemetry::stage::VRAM_UPLOAD);
            let (ntex, _tex_fail) = vram::upload_tex_chunk_append_raw(
                tex_bytes,
                core::ptr::addr_of_mut!(POOL_TEX)
                    .cast::<TexSlot>()
                    .add(tex_off),
                POOL_TEX_SLOTS - tex_off,
            )
            .unwrap_or((0, 0));
            telemetry::stage_end(telemetry::stage::VRAM_UPLOAD);
            ntex
        };
        if ntex > POOL_TEX_SLOTS - tex_off {
            continue;
        }
        LOADED_MODELS[slot_idx] = LoadedModel {
            valid: true,
            type_id: ty as u8,
            run_start: run_off as u8,
            n_runs: nr as u8,
            geom_off: gw * 4,
            geom_len: kept,
            face_start: face_off,
            n_faces: nf,
            tex_start: tex_off,
            n_tex: ntex,
        };
        TYPE_TO_SLOT[ty] = slot_idx as u8;
        // Parse once (post-repack header) -- draws read the cached copy.
        LOADED_MODEL_CACHE[slot_idx] = Model::load(streamed_model_bytes_at(gw * 4, kept));
        geom_word = gw + kept.div_ceil(4);
        face_off += nf;
        run_off += nr;
        tex_off += ntex;
        slot_idx += 1;
    }
    MODEL_RESIDENT_WORDS = geom_word;
}

#[inline(always)]
fn scale12(x: i32, s: i32) -> i32 {
    (x * s) >> 12
}

#[inline]
fn scale12_vec(v: [i32; 3], s: i32) -> [i32; 3] {
    [scale12(v[0], s), scale12(v[1], s), scale12(v[2], s)]
}

#[inline]
fn vblank_reached(now: u32, target: u32) -> bool {
    now.wrapping_sub(target) < 0x8000_0000
}

#[inline]
fn wait_until_vblank(target: u32) {
    while !vblank_reached(interrupts::vblank_count(), target) {}
}

fn wait_vblank_edge() -> u32 {
    let entry = interrupts::vblank_count();
    loop {
        let now = interrupts::vblank_count();
        if now != entry {
            return now;
        }
    }
}

#[inline]
fn dist2_3(a: [i32; 3], b: [i32; 3]) -> i32 {
    let dx = a[0] - b[0];
    let dy = a[1] - b[1];
    let dz = a[2] - b[2];
    dx * dx + dy * dy + dz * dz
}

/// Length of a world-space segment.
#[inline]
fn seg_len(a: [i32; 3], b: [i32; 3]) -> i32 {
    isqrt_i32(dist2_3(a, b)).max(1)
}

#[inline]
fn tram_step_for_speed(speed: i32, remainder: &mut i32) -> i32 {
    if speed <= 0 {
        *remainder = 0;
        0
    } else {
        let scaled = remainder.saturating_add(speed);
        *remainder = scaled % 20;
        scaled / 20
    }
}

#[inline]
fn tram_path_pos(m: &Map, seg: usize, seg_dist: i32) -> [i32; 3] {
    if m.n_way == 0 {
        return [0, 0, 0];
    }
    if seg + 1 >= m.n_way {
        return m.waypoint(m.n_way - 1);
    }
    let a = m.waypoint(seg);
    let b = m.waypoint(seg + 1);
    let len = seg_len(a, b);
    let f = (seg_dist * 4096 / len).clamp(0, 4096);
    [
        a[0] + ((b[0] - a[0]) * f >> 12),
        a[1] + ((b[1] - a[1]) * f >> 12),
        a[2] + ((b[2] - a[2]) * f >> 12),
    ]
}

#[inline(always)]
fn tram_lerp_q8(a: [i32; 3], b: [i32; 3], dist: i32, len: i32) -> [i32; 3] {
    let f = (dist.max(0) << 12) / len.max(1);
    [
        (a[0] << 8) + ((b[0] - a[0]) * f >> 4),
        (a[1] << 8) + ((b[1] - a[1]) * f >> 4),
        (a[2] << 8) + ((b[2] - a[2]) * f >> 4),
    ]
}

/// Point `ahead` 3-D path units beyond `(seg,seg_dist)`, in Q8 world space.
/// CPathTrack::LookAhead crosses as many nodes as necessary and projects past
/// a terminal node along the final segment; clamping at the last point makes a
/// train turn too sharply immediately before a changelevel.
#[inline(never)]
fn tram_path_lookahead_q8(m: &Map, mut seg: usize, mut seg_dist: i32, mut ahead: i32) -> [i32; 3] {
    if m.n_way == 0 {
        return [0; 3];
    }
    if m.n_way == 1 {
        let p = m.waypoint(0);
        return [p[0] << 8, p[1] << 8, p[2] << 8];
    }
    seg = seg.min(m.n_way - 2);
    ahead = ahead.max(0);
    loop {
        let a = m.waypoint(seg);
        let b = m.waypoint(seg + 1);
        let len = seg_len(a, b).max(1);
        let left = (len - seg_dist).max(0);
        if ahead <= left {
            return tram_lerp_q8(a, b, seg_dist + ahead, len);
        }
        ahead -= left;
        if seg + 2 < m.n_way {
            seg += 1;
            seg_dist = 0;
            continue;
        }
        // Project along the terminal segment, matching CPathTrack::Project.
        let f = (ahead << 12) / len;
        return [
            (b[0] << 8) + ((b[0] - a[0]) * f >> 4),
            (b[1] << 8) + ((b[1] - a[1]) * f >> 4),
            (b[2] << 8) + ((b[2] - a[2]) * f >> 4),
        ];
    }
}

/// CPathTrack look-ahead including the synthetic cross-BSP approach leg.
#[inline(never)]
fn tram_lookahead_q8(
    m: &Map,
    seg: usize,
    seg_dist: i32,
    pre_from: [i32; 3],
    pre_total: i32,
    pre_left: i32,
    ahead: i32,
) -> [i32; 3] {
    if pre_left > 0 && m.n_way > 0 {
        let w = tram_reference_waypoint(m);
        if ahead <= pre_left {
            return tram_lerp_q8(pre_from, w, pre_total - pre_left + ahead, pre_total.max(1));
        }
        return tram_path_lookahead_q8(m, seg, seg_dist, ahead - pre_left);
    }
    tram_path_lookahead_q8(m, seg, seg_dist, ahead)
}

/// GoldSrc's absolute desired train yaw from a `wheels`-unit forward point.
/// A purely vertical synthetic trackchange leg has no horizontal heading, so
/// retain the previous target while the platform descends.
#[inline(never)]
fn tram_desired_yaw_q28(
    m: &Map,
    seg: usize,
    seg_dist: i32,
    pre_from: [i32; 3],
    pre_total: i32,
    pre_left: i32,
    fallback_q28: i32,
) -> i32 {
    let here = tram_pos_ext(m, seg, seg_dist, pre_from, pre_total, pre_left);
    let front = tram_lookahead_q8(
        m,
        seg,
        seg_dist,
        pre_from,
        pre_total,
        pre_left,
        m.tram_wheels().max(1),
    );
    let dx = front[0] - (here[0] << 8);
    let dz = front[2] - (here[2] << 8);
    if dx == 0 && dz == 0 {
        fallback_q28
    } else {
        tram_logic::atan2_q28(dz, dx)
    }
}

#[inline(always)]
fn tram_is_trackchange_segment(m: &Map, seg: usize) -> bool {
    if seg + 1 >= m.n_way {
        return false;
    }
    let a = m.waypoint(seg);
    let b = m.waypoint(seg + 1);
    a[0] == b[0] && a[2] == b[2] && a[1] != b[1]
}

/// A func_trackchange carries the train while translating/rotating its
/// platform; CFuncTrackTrain is stopped during that interval. The cooker
/// represents the translation as a vertical path segment. Return the signed
/// angular OFFSET contributed by that platform plus its full authored delta.
/// Applying offset(after)-offset(before) preserves the train's incoming
/// residual angle, matching CFuncTrackChange::UpdateTrain's copied avelocity.
#[inline(never)]
fn tram_trackchange_offset_q28(m: &Map, seg: usize, seg_dist: i32) -> Option<(i32, i32)> {
    if !tram_is_trackchange_segment(m, seg) {
        return None;
    }
    let a = m.waypoint(seg);
    let b = m.waypoint(seg + 1);
    let mut before = None;
    let mut i = seg;
    while i > 0 {
        i -= 1;
        let p = m.waypoint(i);
        let q = m.waypoint(i + 1);
        if p[0] != q[0] || p[2] != q[2] {
            before = Some(tram_seg_heading_q28(m, i));
            break;
        }
    }
    let mut after = None;
    i = seg + 1;
    while i + 1 < m.n_way {
        let p = m.waypoint(i);
        let q = m.waypoint(i + 1);
        if p[0] != q[0] || p[2] != q[2] {
            after = Some(tram_seg_heading_q28(m, i));
            break;
        }
        i += 1;
    }
    let (before, after) = (before?, after?);
    let delta = tram_logic::shortest_angle_delta_q28(before, after);
    let len = seg_len(a, b).max(1);
    Some((
        tram_logic::scale_angle_offset_q28(delta, seg_dist, len),
        delta,
    ))
}

#[inline(never)]
fn tram_integrate_yaw_q28(
    m: &Map,
    integrate: bool,
    seg_before: usize,
    dist_before: i32,
    seg_after: usize,
    dist_after: i32,
    actual: i32,
    target: i32,
) -> (i32, i32) {
    if !integrate {
        return (actual, 0);
    }
    let before_platform = tram_trackchange_offset_q28(m, seg_before, dist_before);
    let after_platform = tram_trackchange_offset_q28(m, seg_after, dist_after);
    let platform_step = if seg_before == seg_after {
        match (before_platform, after_platform) {
            (Some((before, _)), Some((after, _))) => Some(after - before),
            _ => None,
        }
    } else if let Some((after, _)) = after_platform {
        // Entering the platform at distance zero deliberately contributes
        // zero and suppresses the ordinary tracktrain controller for this
        // frame; Gold starts the platform pusher on the following frame.
        Some(after)
    } else {
        // On the platform's terminal frame Gold hands control back to the
        // tracktrain rather than snapping the final fractional unit to the
        // authored rail. Its half-error controller closes that tiny tail.
        None
    };
    let step = platform_step.unwrap_or_else(|| tram_logic::half_angle_step_q28(actual, target));
    let next = (actual + step) & (tram_logic::TRAM_YAW_Q28_TURN - 1);
    (next, tram_logic::shortest_angle_delta_q28(actual, next))
}

/// Heading of path segment `i` in Q28 turns (world X,Z).
fn tram_seg_heading_q28(m: &Map, i: usize) -> i32 {
    let a = m.waypoint(i);
    let b = m.waypoint(i + 1);
    tram_logic::atan2_q28(b[2] - a[2], b[0] - a[0])
}

#[inline(always)]
fn tram_reference_waypoint(m: &Map) -> [i32; 3] {
    if m.n_way > 0 {
        m.waypoint(m.tram_start)
    } else {
        [0, 0, 0]
    }
}

#[inline(always)]
fn tram_authored_heading_q28(m: &Map) -> i32 {
    if m.n_way < 2 {
        0
    } else {
        tram_seg_heading_q28(
            m,
            tram_logic::authored_heading_segment(m.tram_start, m.n_way),
        )
    }
}

/// Convert positive GoldSrc path yaw to the inverse PSX Y-up world rotation.
/// Camera yaw deliberately remains in positive travel space.
#[inline(always)]
fn tram_world_rotation(yaw_q12: u16) -> Mat3I16 {
    Mat3I16::rotate_y(tram_logic::world_rotation_angle_q8(yaw_q12))
}

/// Car position including the synthetic approach leg a ride transfer may
/// start on (`pre_left > 0`: between `pre_from` and the authored waypoint --
/// HL's transferred train drives toward its carried target track from wherever
/// the landmark put it).
fn tram_pos_ext(
    m: &Map,
    seg: usize,
    seg_dist: i32,
    pre_from: [i32; 3],
    pre_total: i32,
    pre_left: i32,
) -> [i32; 3] {
    if pre_left > 0 && m.n_way > 0 {
        let w = tram_reference_waypoint(m);
        let travelled = (pre_total - pre_left).clamp(0, pre_total);
        let total = pre_total.max(1);
        // Keep this as a direct integer lerp. The nested Q12 form
        // `(delta * (((travelled << 12) / total)) >> 12)` is mis-lowered by
        // the experimental MIPS-I backend: c0a0b advanced ~28K units per tick
        // and wrapped the rider through +/-524K during its transfer approach.
        // Intro approach legs keep delta*travelled safely inside i32.
        [
            pre_from[0] + (w[0] - pre_from[0]) * travelled / total,
            pre_from[1] + (w[1] - pre_from[1]) * travelled / total,
            pre_from[2] + (w[2] - pre_from[2]) * travelled / total,
        ]
    } else {
        tram_path_pos(m, seg, seg_dist)
    }
}

/// Nearest point on the tram path to `pos` as (segment, distance-into-segment).
/// Ride transfer seats the arriving map's car where the landmark put the
/// player. 16-sample projection per segment: no runtime i64 division (the
/// known PSX-target miscompile), plenty of accuracy for seating a train.
fn tram_seek_nearest(m: &Map, pos: [i32; 3]) -> (usize, i32) {
    let (mut best_seg, mut best_dist) = (0usize, 0i32);
    let mut best_d2 = i64::MAX;
    if m.n_way < 2 {
        return (0, 0);
    }
    for s in 0..m.n_way - 1 {
        let a = m.waypoint(s);
        let b = m.waypoint(s + 1);
        let len = seg_len(a, b);
        for k in 0..=16 {
            let t = len * k / 16;
            let p = [
                a[0] + (b[0] - a[0]) * k / 16,
                a[1] + (b[1] - a[1]) * k / 16,
                a[2] + (b[2] - a[2]) * k / 16,
            ];
            let (dx, dy, dz) = (
                (pos[0] - p[0]) as i64,
                (pos[1] - p[1]) as i64,
                (pos[2] - p[2]) as i64,
            );
            let d2 = dx * dx + dy * dy + dz * dz;
            if d2 < best_d2 {
                best_d2 = d2;
                best_seg = s;
                best_dist = t;
            }
        }
    }
    (best_seg, best_dist)
}

#[inline(never)]
fn tram_advance(
    m: &Map,
    seg: &mut usize,
    seg_dist: &mut i32,
    step: i32,
    speed: &mut i32,
) -> (bool, bool) {
    if step <= 0 || m.n_way < 2 {
        return (false, false);
    }
    let mut rem = step;
    let mut phase_boundary = false;
    while rem > 0 && *seg + 1 < m.n_way {
        let len = seg_len(m.waypoint(*seg), m.waypoint(*seg + 1));
        if *seg_dist + rem >= len {
            rem -= len - *seg_dist;
            let leaving_trackchange = tram_is_trackchange_segment(m, *seg);
            *seg += 1;
            *seg_dist = 0;
            // Passing a path_track with a "speed" key changes the train's
            // speed (CPathTrack, plats.cpp); 0 keeps the current one. c0a0
            // is authored 200..400 u/s in sections.
            let ws = m.way_speed(*seg);
            if ws > 0 {
                *speed = ws;
            }
            let entering_trackchange = tram_is_trackchange_segment(m, *seg);
            if leaving_trackchange != entering_trackchange {
                // A trackchange is a separate pusher phase. Gold fires the
                // boundary path_track while the car is still at the endpoint,
                // then begins the new mover on the next 50 ms frame; carrying
                // rail-distance remainder into it starts c0a0b/d 2-4 ticks
                // early and also skips their exact distance-zero state.
                rem = 0;
                phase_boundary = true;
            }
        } else {
            *seg_dist += rem;
            rem = 0;
        }
    }
    // Next() runs after this physical step and looks speed*0.1 units down the
    // track. Adopt the next path_track's speed as soon as that lookahead can
    // reach it; the already-computed `step` deliberately used the old speed.
    // Intro nodes are farther apart than the 40-unit maximum lookahead, so a
    // single adjacent-node check is equivalent to CPathTrack::LookAhead here.
    // c0a0a is the one uninterrupted variable-speed track in the opening
    // route. The later maps interleave path nodes with scripted stops and
    // trackchange phases whose fire-on-pass controller is still boundary
    // based in the compact cooker; anticipating only their speed would split
    // those two clocks and regress station timing.
    if m.n_way == 55 && *seg + 1 < m.n_way {
        let len = seg_len(m.waypoint(*seg), m.waypoint(*seg + 1));
        if len - *seg_dist <= (*speed).max(0) / 10 {
            let ws = m.way_speed(*seg + 1);
            if ws > 0 {
                *speed = ws;
            }
        }
    }
    (*seg + 1 < m.n_way, phase_boundary)
}

fn tram_apply_command(
    use_type: u8,
    requested_speed: i32,
    active: &mut bool,
    current_speed: &mut i32,
) -> bool {
    match use_type {
        map::USE_OFF => {
            *active = false;
            *current_speed = 0;
            false
        }
        map::USE_ON => {
            *active = requested_speed > 0;
            *current_speed = requested_speed.max(0);
            *active
        }
        _ => {
            if *active {
                *active = false;
                *current_speed = 0;
                false
            } else {
                *active = requested_speed > 0;
                *current_speed = requested_speed.max(0);
                *active
            }
        }
    }
}

#[inline]
fn train_hud_position(controlling: bool, speed: i32, maximum: i32) -> u8 {
    if !controlling {
        0
    } else if speed <= 0 || maximum <= 0 {
        1 // TRAIN_NEUTRAL
    } else if speed * 100 < maximum * 33 {
        2 // TRAIN_SLOW
    } else if speed * 100 < maximum * 66 {
        3 // TRAIN_MEDIUM
    } else {
        4 // TRAIN_FAST
    }
}

#[inline]
fn tram_should_carry_player(player_pos: [i32; 3], train_pos: [i32; 3]) -> bool {
    let dx = player_pos[0] - train_pos[0];
    let dz = player_pos[2] - train_pos[2];
    let dy = player_pos[1] - train_pos[1];
    dx * dx + dz * dz <= TRAM_CARRY_RADIUS2 && dy.abs() <= TRAM_CARRY_HEIGHT
}

/// Car-local rider position with no seat clamping applied.
#[inline(never)]
fn tram_seat_raw_local(player_pos: [i32; 3], train_pos: [i32; 3], yaw: u16) -> [i32; 3] {
    let r = tram_world_rotation(yaw);
    let xz = tram_logic::inverse_rotate_rider_xz(
        r.m[0][0] as i32,
        r.m[0][2] as i32,
        player_pos[0] - train_pos[0],
        player_pos[2] - train_pos[2],
    );
    [xz[0], player_pos[1] - train_pos[1], xz[1]]
}

#[inline(never)]
fn tram_seat_to_local(player_pos: [i32; 3], train_pos: [i32; 3], yaw: u16) -> [i32; 3] {
    let raw = tram_seat_raw_local(player_pos, train_pos, yaw);
    [
        raw[0].clamp(-130, 130),
        raw[1].clamp(30, 100),
        tram_logic::clamp_rider_local_z(raw[2]),
    ]
}

#[inline(never)]
fn tram_seat_to_world(train_pos: [i32; 3], local: [i32; 3], yaw: u16) -> [i32; 3] {
    let r = tram_world_rotation(yaw);
    let xz = tram_logic::rotate_rider_xz(r.m[0][0] as i32, r.m[0][2] as i32, local[0], local[2]);
    [
        train_pos[0] + xz[0],
        train_pos[1] + local[1],
        train_pos[2] + xz[1],
    ]
}

#[derive(Clone, Copy)]
struct LandmarkName {
    bytes: [u8; LANDMARK_NAME_MAX + 1],
    len: u8,
}

const NO_LANDMARK: LandmarkName = LandmarkName {
    bytes: [0; LANDMARK_NAME_MAX + 1],
    len: 0,
};

#[derive(Clone, Copy)]
struct RoomLaunch {
    room_id: u16,
    landmark: LandmarkName,
    landmark_offset: [i32; 3],
    yaw: u16,
    pitch: i16,
    health: u16,
    suit_equipped: bool,
    // Occupies the byte that was padding before armor; RoomLaunch remains 76 B.
    carry_count: u8,
    armor: u16,
    clip_ammo: u16,
    reserve_ammo: u16,
    preserve_view: bool,
    riding: bool,        // player was aboard a moving tracktrain at the transition
    ride_seat: [i32; 3], // rider offset from the car pivot at the transition
}
const _: [(); 76] = [(); core::mem::size_of::<RoomLaunch>()];

#[derive(Clone, Copy)]
enum PlayExit {
    BackToMenu,
    ChangeLevel(RoomLaunch),
    Restart(RoomLaunch),
    Chapter(RoomLaunch),
    Ending, // c5a1 outro finished: show the end card, then the menu
}

static mut CHANGE_REQUEST: RoomLaunch = RoomLaunch {
    room_id: 0,
    landmark: NO_LANDMARK,
    landmark_offset: [0; 3],
    yaw: 0,
    pitch: 0,
    health: PLAYER_START_HEALTH,
    suit_equipped: false,
    carry_count: 0,
    armor: 0,
    clip_ammo: GLOCK_MAX_CLIP,
    reserve_ammo: GLOCK_START_RESERVE,
    preserve_view: false,
    riding: false,
    ride_seat: [0; 3],
};
static mut CHANGE_REQUEST_ACTIVE: u8 = 0;
static mut LOGIC_TRAM_RIDING: u8 = 0;
static mut LOGIC_TRAM_SEAT: [i32; 3] = [0; 3]; // rider offset from the car pivot
#[derive(Clone, Copy)]
struct TramDynamicsCarry {
    // Absolute turn angles in Q28; remaining camera fraction is Q16 low bits.
    actual_yaw_q28: i32,
    desired_yaw_q28: i32,
    pending_push_q28: i32,
    meta: u32, // bits 0..3 camera fraction, bit4 primed, bit5 valid
}
const TRAM_DYNAMICS_ZERO: TramDynamicsCarry = TramDynamicsCarry {
    actual_yaw_q28: 0,
    desired_yaw_q28: 0,
    pending_push_q28: 0,
    meta: 0,
};
const _: [(); 16] = [(); core::mem::size_of::<TramDynamicsCarry>()];
static mut TRAM_DYNAMICS_CARRY: TramDynamicsCarry = TRAM_DYNAMICS_ZERO;
// env_shake: camera rattle. amplitude (world units) * remaining/duration decays.
static mut SHAKE_TICKS: u16 = 0;
static mut SHAKE_DUR: u16 = 1;
static mut SHAKE_AMP: u16 = 0;
// ---- Shared game-feel foundation: view punch + bob + pain compass ----
// View punch: a decaying camera kick (pitch/yaw, 12-bit view units) reused by
// weapon recoil, hard landings, taking damage, and enemy hits. HL's punchangle.
static mut PUNCH_PITCH: i32 = 0;
static mut PUNCH_YAW: i32 = 0;
// Walk view-bob phase (advances with movement each sim tick) -> a vertical head
// bob + a subtle strafe roll are derived from it in the render view setup.
static mut BOB_PHASE: u32 = 0;
// GoldSrc pain-compass edges packed as front/right/rear/left bits. This
// replaces the port-specific full-screen red wash with the original
// directional feedback without adding a resident array.
static mut DAMAGE_DIRECTION: u8 = 0;
static mut DAMAGE_TICKS: u8 = 0;
// HEV suit voice: 0 = fine, 1 = health critical, 2 = near death (fire once per
// worsening threshold crossing). Geiger cooldown throttles the radiation click.
static mut HEV_HEALTH_STATE: u8 = 0;
static mut GEIGER_COOLDOWN: u8 = 0;

/// Kick the view (decaying) -- HL's punchangle. `pitch` up is negative here to
/// match the view pitch convention; `yaw` is a small left/right jolt.
#[inline]
unsafe fn add_view_punch(pitch: i32, yaw: i32) {
    PUNCH_PITCH = (PUNCH_PITCH + pitch).clamp(-400, 400);
    PUNCH_YAW = (PUNCH_YAW + yaw).clamp(-400, 400);
}

/// Rotation a shot is actually aimed along. Every GoldSrc attack builds its
/// vectors from `v_angle + punchangle`, so accumulated recoil steers the
/// bullets, not just the camera: an MP5 burst climbs and its later rounds go
/// high. Firing off the un-punched look direction made recoil pure decoration.
#[inline]
unsafe fn aim_rotation(yaw: u16, pitch: i16) -> Mat3I16 {
    view_rotation(
        ((yaw as i32 + PUNCH_YAW) & 0xFFF) as u16,
        (pitch as i32 + PUNCH_PITCH).clamp(-(PITCH_MAX as i32), PITCH_MAX as i32) as i16,
    )
}
// ---- func_tank: the mountable gun the player is currently operating ----
static mut MOUNTED_TANK: i32 = -1; // logic index of the mounted tank, or -1
static mut TANK_FIRE_CD: u16 = 0; // ticks until the tank can fire again
                                  // ---- Screen titles (env_message / chapter cards) + screen fades (env_fade) ----
static mut TITLE_TEXT_ID: u16 = 0; // logic-names id of the text; 0 = none
static mut TITLE_T: u16 = 0;
static mut TITLE_HOLD: u16 = 0;
static mut TITLE_FADE: u16 = 20;
static mut TITLE_EFFECT: u8 = 0; // 0 fade, 1 flicker credits, 2 typewriter
static mut TITLE_LEFT_ALIGNED: bool = false;
/// Authored GoldSrc top edge in 1/31-screen steps; zero means vertically centered.
static mut TITLE_Y_Q5: u8 = 0;
static mut CHAPTER_TITLE_ID: u16 = 0; // worldspawn chaptertitle, shown after load
static mut CHAPTER_TITLE_HOLD: u16 = 0;
static mut GAMETITLE_TICKS: u16 = 0; // worldspawn gametitle: HALF-LIFE card countdown
static mut FADE_ACTIVE: bool = false;
static mut FADE_IN: bool = false; // ramp 255 -> clear (else clear -> full + hold)
static mut FADE_WHITE: bool = false;
static mut FADE_T: u16 = 0;
static mut FADE_DUR: u16 = 40;
static mut FADE_HOLD: u16 = 0;
static mut FADE_STARTDARK: bool = false; // worldspawn startdark: black until a fade fires
                                         // ---- CD music (CDDA tracks appended to the disc; HL track numbers pass through) ----
static mut CD_TRACK_WANT: i16 = 0; // >0 play, -1 stop, 0 none
static mut CD_TRACK_CUR: i16 = 0;
// Absolute BCD MSF captured by GetLocP when a stream suspends a live cue, so
// the cue RESUMES at its position (GoldSrc keeps the CD playing through weapon
// switches and changelevels) instead of restarting from the top.
static mut CD_RESUME_TRACK: i16 = 0;
static mut CD_RESUME_MSF: [u8; 3] = [0; 3];

/// Start/stop CDDA to match the wanted track. Only call when the drive is idle
/// (post-stream / mid-gameplay): any WORLD.PAK read preempts playback.
unsafe fn music_apply() {
    if CD_TRACK_WANT == CD_TRACK_CUR {
        return;
    }
    // An open weapon-switch pump session owns the drive (READN in flight
    // across ticks); issuing Play/Pause now would kill the stream. The wanted
    // track applies on the first tick after the session closes.
    if cdstream::stream_active() {
        return;
    }
    if CD_TRACK_WANT > 0 {
        // Keep the physical CD input closed until the controller is back in
        // CDDA mode and Play has acknowledged. Opening the SPU route while a
        // WORLD.PAK ReadN/data sector is still latched produces an audible
        // buzz on real hardware even though idealized emulators emit silence.
        psx_spu::enable_cd_audio(false);
        psx_spu::set_cd_volume(psx_spu::CdVolume::SILENCE, psx_spu::CdVolume::SILENCE);
        // AUTO_PAUSE: a Half-Life cue plays once and ends; without it the
        // drive rolls straight into the next CDDA track on the disc.
        let mode_ok = psx_io::cdrom::try_set_mode(
            psx_io::cdrom::MODE_DOUBLE_SPEED
                | psx_io::cdrom::MODE_CDDA
                | psx_io::cdrom::MODE_AUTO_PAUSE,
            2_000_000,
        )
        .is_some();
        // Resume a suspended cue at the position GetLocP captured (SetLoc +
        // parameterless Play); anything else starts its track from the top.
        let play_ok = mode_ok
            && if CD_TRACK_WANT == CD_RESUME_TRACK && CD_RESUME_MSF != [0; 3] {
                psx_io::cdrom::try_command(0x02, &CD_RESUME_MSF, 2_000_000).is_some()
                    && psx_io::cdrom::try_command(0x03, &[], 2_000_000).is_some()
            } else {
                psx_io::cdrom::try_play_track(CD_TRACK_WANT as u8, 2_000_000).is_some()
            };
        let ready = play_ok && psx_io::cdrom::try_demute(2_000_000).is_some();
        CD_RESUME_TRACK = 0;
        CD_RESUME_MSF = [0; 3];
        if ready {
            let v = settings::music_cd_volume();
            psx_spu::set_cd_volume(v, v);
            psx_spu::enable_cd_audio(true);
            CD_TRACK_CUR = CD_TRACK_WANT;
        } else {
            // Leave WANT intact so the next gameplay tick retries, but never
            // claim the route is live after a timed-out hardware command.
            CD_TRACK_CUR = 0;
        }
    } else {
        // Silence the SPU route before waiting for the asynchronous Pause
        // response. A slow or failed drive command must never leave several
        // seconds of the previous CD sector audible during the transition.
        psx_spu::enable_cd_audio(false);
        psx_spu::set_cd_volume(psx_spu::CdVolume::SILENCE, psx_spu::CdVolume::SILENCE);
        let _ = psx_io::cdrom::try_mute(2_000_000);
        let _ = psx_io::cdrom::try_pause(2_000_000);
        CD_TRACK_CUR = CD_TRACK_WANT;
    }
}

/// Close the physical CD audio path before a runtime WORLD.PAK data read.
/// Keep the requested track so [`music_apply`] can restart it after streaming.
unsafe fn music_suspend_for_stream() {
    psx_spu::enable_cd_audio(false);
    psx_spu::set_cd_volume(psx_spu::CdVolume::SILENCE, psx_spu::CdVolume::SILENCE);
    if CD_TRACK_CUR > 0 {
        // Only resurrect a cue the drive was still actually playing. A
        // Half-Life track plays once; after AUTO_PAUSE ends it, a later data
        // stream must not re-Play the finished song from the top.
        //
        // Seeking (0x40) counts as playing. Play is a seek followed by
        // playback and the two bits are mutually exclusive, so a track whose
        // Play was accepted moments ago reports neither. Reading that as
        // "finished" abandons a song that had not started yet.
        const PLAYING_OR_SEEKING: u8 = 0x80 | 0x40;
        let still_playing = psx_io::cdrom::try_get_stat(2_000_000)
            .map(|r| {
                r.bytes()
                    .first()
                    .is_some_and(|s| s & PLAYING_OR_SEEKING != 0)
            })
            .unwrap_or(false);
        CD_TRACK_WANT = if still_playing { CD_TRACK_CUR } else { 0 };
        if still_playing {
            // GetLocP: track,index,mm,ss,ff,amm,ass,aff (BCD). Bytes 5..8 are
            // the absolute position the resume path feeds back to SetLoc.
            if let Some(r) = psx_io::cdrom::try_get_loc_p(2_000_000) {
                let b = r.bytes();
                if b.len() >= 8 {
                    CD_RESUME_TRACK = CD_TRACK_CUR;
                    CD_RESUME_MSF = [b[5], b[6], b[7]];
                }
            }
        }
        // Controller-level mute is deliberately issued only for a known-live
        // CDDA stream. Cold boot/menu data reads need no extra command, while
        // a playing drive must stop feeding samples before Setmode/ReadN.
        let _ = psx_io::cdrom::try_mute(2_000_000);
        CD_TRACK_CUR = 0;
    }
}

/// Leave gameplay with both the drive and SPU CD input in a known-silent
/// state. Only send Pause while the cache says the drive is actively playing:
/// issuing it after a timed-out data stream can consume/mask the stream's late
/// CD IRQ and deadlock the menu's next asset read.
#[inline(never)]
unsafe fn music_stop_for_menu() {
    // A dialogue voice whose SPU-RAM sample was replaced can loop forever;
    // the frontend boundary must silence every game-owned voice, not CDDA only.
    sfx::stop_all();
    // Mute first: `try_pause` can wait for a delayed hardware response, while
    // the menu should become silent immediately and unconditionally.
    psx_spu::enable_cd_audio(false);
    psx_spu::set_cd_volume(psx_spu::CdVolume::SILENCE, psx_spu::CdVolume::SILENCE);
    if CD_TRACK_CUR > 0 {
        let _ = psx_io::cdrom::try_mute(2_000_000);
        let _ = psx_io::cdrom::try_pause(2_000_000);
    }
    CD_TRACK_WANT = 0;
    CD_TRACK_CUR = 0;
    CD_RESUME_TRACK = 0;
    CD_RESUME_MSF = [0; 3];
}
// Arsenal carried across changelevel (menu launches reset it): owned mask,
// per-weapon clips, ammo pools, selected weapon.
// Live checkpoint, refreshed once per simulation tick so the pause menu can
// write a save without threading the whole player state through the input path.
// Restoring sets PENDING_RESTORE: play() computes its normal spawn first and
// this overrides it, which keeps the save out of RoomLaunch's fixed 76 bytes.
static mut LIVE_CHECKPOINT: save::Checkpoint = save::Checkpoint::EMPTY;
static mut PENDING_RESTORE: save::Checkpoint = save::Checkpoint::EMPTY;
static mut PENDING_RESTORE_ACTIVE: bool = false;

/// Save staging borrows the head of the per-frame projection scratch. A save
/// only runs from the pause menu with no render in flight, and the next world
/// frame takes a fresh projection token, so stale contents are unreadable.
/// Read the card and arm a restore, returning the room to launch. The menu
/// calls this before it streams anything, so a failed read costs nothing.
pub fn load_saved_room() -> Option<usize> {
    unsafe {
        let cp = save::read_latest(save_staging()).ok()?;
        let room = cp.room_id as usize;
        if room >= menu::MAPS.len() {
            return None;
        }
        PENDING_RESTORE = cp;
        PENDING_RESTORE_ACTIVE = true;
        Some(room)
    }
}

unsafe fn save_staging() -> &'static mut [u8] {
    core::slice::from_raw_parts_mut(core::ptr::addr_of_mut!(SCRATCH_XY).cast::<u8>(), 1024)
}

static mut CARRY_VALID: bool = false;
static mut CARRY_OWNED: u16 = 0;
static mut CARRY_CLIPS: [u16; N_WEAPONS] = [0; N_WEAPONS];
static mut CARRY_AMMO: [u16; N_AMMO] = [0; N_AMMO];
static mut CARRY_CURRENT: u8 = 0;

// Persistent global state (env_global / multisource globalstate), keyed by the
// cook's global-name hash. Carried across changelevels like the arsenal (reset
// only on a fresh menu launch) so cross-map gates work (Blast Pit c1a4fpower).
static mut GLOBAL_HASH: [u16; 32] = [0; 32];
static mut GLOBAL_ON: [bool; 32] = [false; 32];
static mut GLOBAL_COUNT: usize = 0;

unsafe fn set_global(hash: u16, on: bool) {
    if hash == 0 {
        return;
    }
    for i in 0..GLOBAL_COUNT {
        if GLOBAL_HASH[i] == hash {
            GLOBAL_ON[i] = on;
            return;
        }
    }
    if GLOBAL_COUNT < GLOBAL_HASH.len() {
        GLOBAL_HASH[GLOBAL_COUNT] = hash;
        GLOBAL_ON[GLOBAL_COUNT] = on;
        GLOBAL_COUNT += 1;
    }
}

unsafe fn global_is_on(hash: u16) -> bool {
    if hash == 0 {
        return false;
    }
    (0..GLOBAL_COUNT).any(|i| GLOBAL_HASH[i] == hash && GLOBAL_ON[i])
}

// MAPLIST index of c1a0d, the map that holds the one HEV suit pickup. Rooms
// AFTER it assume you already have the suit; this map and earlier expose the
// item_suit. Keep in sync with the Makefile MAPLIST / menu::MAPS.
const HEV_SUIT_ROOM: usize = 10; // c1a0d

#[inline]
const fn standalone_room_starts_with_hev(room_id: usize) -> bool {
    // Standalone/menu launches to a map PAST the suit start with it, so
    // batteries/enemy damage are testable. c1a0d itself and earlier expose the
    // pickup. Hazard Course is also an authored progression: its menu entry
    // must begin suitless and weaponless, then award both through its pickups.
    // NB this must NOT apply to changelevel arrivals -- a real playthrough
    // carries the suit state and picks it up in c1a0d.
    room_id < menu::CAMPAIGN_MAP_COUNT && room_id > HEV_SUIT_ROOM
}

const _: () = {
    assert!(!standalone_room_starts_with_hev(menu::TRAINING_START_ROOM));
    assert!(!standalone_room_starts_with_hev(HEV_SUIT_ROOM));
    assert!(standalone_room_starts_with_hev(HEV_SUIT_ROOM + 1));
};

fn menu_launch(room_id: usize) -> RoomLaunch {
    RoomLaunch {
        room_id: room_id.min(u16::MAX as usize) as u16,
        landmark: NO_LANDMARK,
        landmark_offset: [0; 3],
        yaw: 0,
        pitch: 0,
        health: PLAYER_START_HEALTH,
        suit_equipped: standalone_room_starts_with_hev(room_id),
        carry_count: 0,
        armor: 0,
        clip_ammo: GLOCK_MAX_CLIP,
        reserve_ammo: GLOCK_START_RESERVE,
        preserve_view: false,
        riding: false,
        ride_seat: [0; 3],
    }
}

#[cfg(feature = "debug-regression-viewpoints")]
fn regression_viewpoint(
    room_id: usize,
    saved_view: bool,
    ladder_view: bool,
    momentary_view: bool,
    pushable_view: bool,
    entry_view: bool,
    panel_view: bool,
    train_view: bool,
    guntarget_view: bool,
) -> Option<([i32; 3], u16, i16)> {
    if guntarget_view && room_id == 96 {
        // Front-on Walter close-up: glasses, eyes and coat share coarse OT bins.
        return Some(([2120, 56, 1292], 3072, 0));
    }
    if saved_view && room_id == 97 {
        // Close view along the ramp railing, exposing layered brush faces.
        return Some(([150, 172, 550], 300, -125));
    }
    if momentary_view && room_id == 102 {
        // t0a0d's radiation trigger is a very long, thin floor brush beneath
        // the training train. Its GoldSrc Geiger distance is measured from
        // the brush centre, so pin this observer there to make both the
        // 0.25-second click probability and 0.5-second hurt pulse
        // deterministic enough for a headless audio/visual regression.
        return Some(([6, -104, -1890], 2048, 0));
    }
    if ladder_view && room_id == 102 {
        // t0a0d's real training train begins at path_track train1. Put a live
        // player on its 216x108-unit car (model *23), not on the duplicate
        // six-face control brush, so +use/notch inputs prove that the visible
        // mesh, collision and train HUD all follow one selected entity.
        return Some(([184, 10, -1076], 2048, 0));
    }
    if pushable_view && room_id == 102 {
        // Stand inside GoldSrc's 64-unit PlayerUse radius, facing the authored
        // Hazard Course Barney `bob`. This remains a live actor interaction:
        // two separated +use pulses must play BA_HAZ_OK then BA_HAZ_WAIT.
        return Some(([-990, 8, -1408], 3072, 0));
    }
    if guntarget_view && room_id == 98 {
        // Exact PSoXide save-slot 13 pose in t0a0b. Target 1 is at its
        // raised first path_track here: its authored lower leaf is outside
        // this camera PVS, so a cook-time-only brush membership drops it.
        return Some(([-2116, -152, 673], 2860, 0));
    }
    if train_view && room_id == 97 {
        // Fixed observer outside t0a0a's vertical lift. The diagnostic
        // bootstrap starts the real func_train after twenty simulation ticks,
        // making a stale cached mesh immediately visible against the shaft.
        return Some(([-96, -80, -1400], 2048, 0));
    }
    if panel_view && room_id == 96 {
        // Face the three jump-completion indicator panels from their authored
        // traversal lane. This is a live deterministic view: held Use in the
        // regression route turns the three cooked lightstyles on through the
        // same LogicEnt use path exercised by their trigger_once targets.
        return Some(([492, 64, 1810], 0, 0));
    }
    if entry_view && room_id == 96 {
        // Real public Hazard Course route: fifty vblanks walking straight out
        // of the opening elevator toward the hologram. The foreground floor
        // crosses the near/guard boundary here and exposes camera-edge affine
        // wedges that a standalone t0a0 spawn cannot reproduce.
        return Some(([-1380, -28, -1682], 0, 0));
    }
    if pushable_view && room_id == 6 {
        // c1a0 model *64: begin touching a real 44x44 office crate's near
        // face, looking directly at it. This remains a live player view so
        // held Use+Back must pull the box through the continuous-use radius
        // while the camera retreats.
        return Some(([-1042, -215, -840], 0, 0));
    }
    if momentary_view && room_id == 97 {
        // t0a0a model *65: stand within +use range of the near valve and
        // keep the complete wheel/door linkage visible for the headless
        // momentary mechanism regression.
        return Some(([1027, -140, -2156], 782, -170));
    }
    if ladder_view && room_id == 96 {
        // t0a0 model *149: begin flush with the lower ladder face, looking up
        // it. Unlike visual subject cameras this pose remains live so the
        // headless ladder route proves real attachment and vertical travel.
        return Some(([-692, -348, 764], 0, 512));
    }
    if saved_view && room_id == 95 {
        // c5a1 mirrors c0a0e's angled tram-door brush. Observe it from inside
        // the final tram so a rotated-vs-unrotated func_train centre produces
        // a visible jamb gap in the deterministic regression capture.
        return Some(([-1214, -205, -700], 0, 0));
    }
    if saved_view && room_id == 6 {
        // Captured from PSoXide save slot 1 at the straight c1a0 corridor
        // stress view. Keep this as a pose rather than a save-state fixture:
        // restoring the full machine would also restore the old executable,
        // while this camera remains valid across renderer rebuilds.
        return Some(([-367, -204, 824], 3074, 0));
    }
    if saved_view && room_id == 11 {
        // c1a0e's tiny translucent motor-button cover, viewed from the top
        // landing at eye height. Restoring the original emulator savestate
        // would also restore its stale executable; this pose exercises the
        // newly cooked brush transform against the current build instead.
        return Some(([1892, 98, 200], 0, 0));
    }
    if saved_view && room_id == 101 {
        // Exact PSoXide save-slot 15 pose below t0a0c's second swim-basin
        // exit. Keep this as a live pose rather than restoring the savestate's
        // old executable: look-up + forward + jump must combine GoldSrc's
        // paddle and water acceleration strongly enough to clear the hatch.
        // Slot 15 is south of model *5's authored 192x152-unit aperture.
        // Aim through its centre and reproduce the continuous look-up
        // manoeuvre from the player's captured position.
        return Some(([-1661, -404, -1140], 3816, 850));
    }
    if saved_view && room_id == 96 {
        // Captured from PSoXide save slot 3 at the t0a0 floor-grid failure.
        // The steep grazing view exposes both binary-alpha grate sampling loss
        // and any gap opened by independently projected affine children.
        return Some(([553, 16, 1202], 3995, -436));
    }
    if room_id == 96 {
        // Exact save-slot 14 observation-room pose. The scientists behind
        // model *93 must remain visible through its rendermode-4 cutouts; its
        // opaque BSP volume is not a valid whole-actor occluder.
        return Some(([2353, -8, 1045], 3642, 66));
    }
    let index = match room_id {
        64 => 0,
        23 => 1,
        18 => 2,
        94 => 3,
        6 => 4,
        9 => 5,
        11 => 6,
        97 => 7,
        _ => return None,
    };
    Some(room_budget::REGRESSION_VIEWPOINTS[index])
}

fn landmark_from_str(name: &str) -> LandmarkName {
    let mut out = NO_LANDMARK;
    let src = name.as_bytes();
    let n = src.len().min(LANDMARK_NAME_MAX);
    let mut i = 0usize;
    while i < n {
        out.bytes[i] = src[i];
        i += 1;
    }
    out.len = n as u8;
    out
}

fn landmark_matches(name: LandmarkName, other: &str) -> bool {
    let n = name.len as usize;
    other.as_bytes().len() == n && &name.bytes[..n] == other.as_bytes()
}

