/// Screen position of the drawn viewmodel's muzzle, refreshed by
/// `draw_viewmodel` while the GTE still holds the viewmodel transform.
static mut VM_MUZZLE_SCREEN: (i16, i16) = (168, 132);

/// Weapon slot whose muzzle `draw_viewmodel` should project. Set beside the
/// viewmodel selection so the draw stays free of weapon state.
static mut WEAPON_MUZZLE_SLOT: usize = W_GLOCK;

const MUZZLE_FLASH_WEAPONS: [bool; 14] = [
    false, // crowbar
    true,  // glock
    true,  // 357
    true,  // mp5
    true,  // shotgun
    false, // crossbow
    true,  // rpg
    true,  // gauss
    true,  // egon
    false, // hornet gun
    false, // grenade
    false, // snark
    false, // tripmine
    false, // satchel
];

/// GoldSrc-style additive muzzle star over the viewmodel barrel: a warm core
/// quad + four spikes, size jittered per frame. Immediate draws (post-OT),
/// Add blend so it brightens whatever is behind it.
fn draw_muzzle_flash(phase: u32) {
    use psx_gpu::material::BlendMode;
    // Barrel tip in screen space, projected from the model's own muzzle
    // attachment by `draw_viewmodel` (see VM_MUZZLE_MODEL).
    let (cx, cy) = unsafe { VM_MUZZLE_SCREEN };
    let r: i16 = if phase & 1 == 0 { 13 } else { 10 };
    let core = r - 4;
    let spikes = [
        [(cx, cy - r), (cx + 3, cy), (cx - 3, cy)],
        [(cx, cy + r), (cx - 3, cy), (cx + 3, cy)],
        [(cx - r, cy), (cx, cy - 3), (cx, cy + 3)],
        [(cx + r, cy), (cx, cy + 3), (cx, cy - 3)],
    ];
    for sp in spikes {
        fx_tri_flat_blended(sp, 255, 150, 40, BlendMode::Add);
    }
    fx_tri_flat_blended(
        [
            (cx - core, cy - core),
            (cx + core, cy - core),
            (cx, cy + core),
        ],
        255,
        236,
        170,
        BlendMode::Add,
    );
}

