const fn wdef(
    name: &'static str,
    ammo: usize,
    clip: u16,
    reserve_max: u16,
    damage: u8,
    range: i32,
    pellets: u8,
    spread: i32,
    cooldown: u8,
    reload: u8,
    fire: u8,
    proj: u8,
    wm: u8,
) -> WeaponDef {
    WeaponDef {
        name,
        ammo,
        clip,
        reserve_max,
        damage,
        range,
        pellets,
        spread,
        cooldown,
        reload,
        fire,
        proj,
        wm,
    }
}

