// SDK DEFAULT_GIVE per weapon (weapons.h:144-158): the total rounds a weapon
// pickup grants. A fresh pickup loads its clip from this (rest to the pool);
// a duplicate adds it to the pool. Clipless weapons arrive usable (grenade 5,
// snark 5, satchel 1, tripmine 1, hivehand 8, gauss/egon 20).
const WEAPON_DEFAULT_GIVE: [u16; N_WEAPONS] = [0, 17, 6, 25, 12, 5, 1, 20, 20, 8, 5, 5, 1, 1];
const HORNET_REGEN_TICKS: u8 = 10; // 1 hornet / 0.5 s (hornetgun.cpp:33)
const CROWBAR_HIT_COOLDOWN_TICKS: u8 = 5; // CCrowbar::Swing hit: 0.25 s
const CROWBAR_MISS_COOLDOWN_TICKS: u8 = 10; // CCrowbar::Swing miss: 0.5 s
const CROWBAR_FULL_DAMAGE_IDLE_TICKS: u8 = 20; // full damage again after one idle second

#[inline]
fn wdef_of(id: usize) -> &'static WeaponDef {
    &WEAPON_DEFS[id.min(N_WEAPONS - 1)]
}

#[inline(always)]
fn weapon_viewmodel(id: usize, satchel_mode: u8) -> usize {
    if id == W_SATCHEL && satchel_mode >= SATCHEL_RADIO {
        12 // v_satchel_radio
    } else {
        wdef_of(id).wm as usize
    }
}

/// The player's whole arsenal: owned set, per-weapon magazines, per-type reserve,
/// and the live firing/reload/switch timers for the selected weapon.
struct Arsenal {
    owned: u16, // bit i set => weapon i owned
    current: usize,
    clip: [u16; N_WEAPONS],
    ammo: [u16; N_AMMO],
    cooldown: u8,
    reload_ticks: u8,
    dry_ticks: u8,
    switch_ticks: u8, // brief lockout after a weapon change
    hornet_regen: u8, // ticks toward the next self-recharged hornet
    // 0 = idle; otherwise secondary-charge age in 20 Hz ticks. This occupies
    // the Arsenal tail padding on PS1, so faithful Gauss charging costs no
    // additional aligned player-state RAM.
    gauss_charge: u8,
}

impl Arsenal {
    fn new() -> Self {
        let mut a = Arsenal {
            owned: 0,
            current: W_GLOCK,
            clip: [0; N_WEAPONS],
            ammo: [0; N_AMMO],
            cooldown: 0,
            reload_ticks: 0,
            dry_ticks: 0,
            switch_ticks: 0,
            hornet_regen: 0,
            gauss_charge: 0,
        };
        // Faithful start: empty hands. The crowbar and glock are world pickups
        // (c1a1 onwards); chapter-select launches grant them in play() so
        // mid-campaign jumps stay playable.
        a
    }

    /// Grant the arsenal you'd have earned by `room_id` (chapter select): every
    /// weapon whose first-appearance map index is <= the selected room, each with
    /// a full clip and ~3 magazines of reserve so the loadout is immediately
    /// usable (and testable). A late chapter thus hands you every weapon.
    fn give_chapter_loadout(&mut self, room_id: usize) {
        for w in 0..N_WEAPONS {
            if WEAPON_FIRST_MAP[w] > room_id {
                continue;
            }
            self.give_weapon(w);
            let d = &WEAPON_DEFS[w];
            self.clip[w] = d.clip;
            if d.ammo != AMMO_NONE {
                // ~3 clips (or a stack of 15 for clip-less thrown/energy weapons),
                // capped at the pool's reserve max; never lower an existing stock.
                let give = ((d.clip.max(5) as u32) * 3).min(d.reserve_max as u32) as u16;
                if self.ammo[d.ammo] < give {
                    self.ammo[d.ammo] = give;
                }
            }
        }
        // A testable launcher out of chapter select (M203 rounds are otherwise
        // pickup-only; the pool is separate from hand grenades).
        if self.owns(W_MP5) {
            self.give_ammo(AMMO_ARGREN, 4);
        }
        // Select the glock if owned (the standard sidearm), else the crowbar,
        // else whatever the earliest owned weapon is.
        self.current = if self.owns(W_GLOCK) {
            W_GLOCK
        } else if self.owns(W_CROWBAR) {
            W_CROWBAR
        } else {
            (0..N_WEAPONS).find(|&w| self.owns(w)).unwrap_or(W_CROWBAR)
        };
    }

    /// Top every magazine and reserve pool up. God mode holds the player here
    /// each tick, so the ammo counter parking at full is also the readout that
    /// says the cheat is live.
    fn refill_ammo(&mut self) {
        let mut w = 0usize;
        while w < N_WEAPONS {
            self.clip[w] = WEAPON_DEFS[w].clip;
            w += 1;
        }
        let mut a = 0usize;
        while a < N_AMMO {
            self.ammo[a] = max_reserve_for(a);
            a += 1;
        }
    }

    /// Everything, loaded (DEBUG_ALL_WEAPONS test arsenal).
    fn give_all_debug(&mut self) {
        let mut w = 0usize;
        while w < N_WEAPONS {
            self.give_weapon(w);
            self.clip[w] = WEAPON_DEFS[w].clip;
            w += 1;
        }
        let mut a = 0usize;
        while a < N_AMMO {
            self.ammo[a] = 250;
            a += 1;
        }
        self.current = W_GLOCK;
    }

    /// True when the player holds any weapon at all (drives fire + viewmodel
    /// + the ammo HUD; empty hands before the first pickup).
    fn any_weapon(&self) -> bool {
        self.owned != 0
    }

    #[inline]
    fn def(&self) -> &'static WeaponDef {
        wdef_of(self.current)
    }

    fn owns(&self, id: usize) -> bool {
        id < N_WEAPONS && (self.owned & (1 << id)) != 0
    }

    fn give_weapon(&mut self, id: usize) {
        if id < N_WEAPONS {
            let fresh = !self.owns(id);
            self.owned |= 1 << id;
            // First pickup of a magazine weapon arrives loaded.
            if fresh && WEAPON_DEFS[id].clip > 0 && self.clip[id] == 0 {
                self.clip[id] = WEAPON_DEFS[id].clip;
            }
        }
    }

    fn give_ammo(&mut self, ammo: usize, n: u16) {
        if ammo < N_AMMO && ammo != AMMO_NONE {
            let cap = max_reserve_for(ammo);
            self.ammo[ammo] = self.ammo[ammo].saturating_add(n).min(cap);
        }
    }

    /// Apply a fresh weapon pickup's DEFAULT_GIVE: the clip fills first, the
    /// remainder lands in the pool (net rounds match the SDK's give-then-
    /// autoreload). Clipless weapons get the whole give as pool ammo.
    fn set_pickup_rounds(&mut self, id: usize) {
        let d = &WEAPON_DEFS[id];
        if d.ammo == AMMO_NONE {
            return;
        }
        let give = WEAPON_DEFAULT_GIVE[id];
        let to_clip = give.min(d.clip);
        self.clip[id] = to_clip;
        self.give_ammo(d.ammo, give - to_clip);
    }

    /// Live magazine count of the selected weapon (0 for no-magazine weapons).
    fn clip_display(&self) -> u16 {
        self.clip[self.current]
    }

    /// Reserve count of the selected weapon's ammo type.
    fn reserve_display(&self) -> u16 {
        self.ammo[self.def().ammo]
    }

    /// HUD ammo display mode: 0 = melee (none), 1 = reserve only, 2 = reserve|clip.
    fn ammo_mode(&self) -> u8 {
        let d = self.def();
        if d.ammo == AMMO_NONE {
            0
        } else if d.clip == 0 {
            1
        } else {
            2
        }
    }

    /// Advance weapon timers. A returned animation is a staged shotgun reload
    /// transition that must begin on this same simulation tick.
    fn tick(&mut self) -> Option<u8> {
        // The hornetgun self-recharges once owned (HL's infinite-ammo weapon);
        // without this it is 8 lifetime shots.
        if self.owns(W_HORNET) && self.ammo[AMMO_HORNET] < WEAPON_DEFS[W_HORNET].reserve_max {
            self.hornet_regen += 1;
            if self.hornet_regen >= HORNET_REGEN_TICKS {
                self.hornet_regen = 0;
                self.ammo[AMMO_HORNET] += 1;
            }
        } else {
            self.hornet_regen = 0;
        }
        if self.cooldown > 0 {
            self.cooldown -= 1;
        }
        if self.dry_ticks > 0 {
            self.dry_ticks -= 1;
        }
        if self.switch_ticks > 0 {
            self.switch_ticks -= 1;
        }
        if self.current == W_SHOTGUN
            && self.reload_ticks & (SHOTGUN_RELOAD_START_TAG | SHOTGUN_RELOAD_INSERT_TAG) != 0
        {
            let tag = self.reload_ticks & !SHOTGUN_RELOAD_COUNT_MASK;
            let left = self.reload_ticks & SHOTGUN_RELOAD_COUNT_MASK;
            if left > 1 {
                self.reload_ticks = tag | (left - 1);
            } else if tag == SHOTGUN_RELOAD_START_TAG {
                // The gun is now at the side. Begin the first shell exactly as
                // CShotgun::Reload advances m_fInSpecialReload 1 -> 2.
                self.reload_ticks = SHOTGUN_RELOAD_INSERT_TAG | SHOTGUN_INSERT_TICKS;
                unsafe {
                    sfx::play(if self.clip[W_SHOTGUN] & 1 == 0 {
                        sfx::RELOAD
                    } else {
                        sfx::RELOAD_SHOTGUN_ALT
                    })
                };
                return Some(VM_ANIM_RELOAD);
            } else {
                // One shell becomes usable at the end of each insert clip.
                self.clip[W_SHOTGUN] = self.clip[W_SHOTGUN].saturating_add(1);
                self.ammo[AMMO_BUCK] = self.ammo[AMMO_BUCK].saturating_sub(1);
                if self.clip[W_SHOTGUN] < WEAPON_DEFS[W_SHOTGUN].clip && self.ammo[AMMO_BUCK] != 0 {
                    self.reload_ticks = SHOTGUN_RELOAD_INSERT_TAG | SHOTGUN_INSERT_TICKS;
                    unsafe {
                        sfx::play(if self.clip[W_SHOTGUN] & 1 == 0 {
                            sfx::RELOAD
                        } else {
                            sfx::RELOAD_SHOTGUN_ALT
                        })
                    };
                    return Some(VM_ANIM_RELOAD);
                }
                self.reload_ticks = 0;
                unsafe { sfx::play(sfx::SHOTGUN_PUMP) };
                return Some(VM_ANIM_RELOAD_PUMP);
            }
        } else if self.reload_ticks > 0 {
            self.reload_ticks -= 1;
            if self.reload_ticks == 0 {
                self.finish_reload();
            }
        }
        None
    }

    fn start_reload(&mut self) -> bool {
        let d = self.def();
        if d.reload == 0 || d.clip == 0 || self.reload_ticks != 0 {
            return false;
        }
        if self.clip[self.current] >= d.clip || self.ammo[d.ammo] == 0 {
            return false;
        }
        if self.current == W_SHOTGUN {
            self.reload_ticks = SHOTGUN_RELOAD_START_TAG | SHOTGUN_START_RELOAD_TICKS;
            // GoldSrc blocks attack for one second while the gun first moves
            // aside, but subsequent shells may be interrupted once available.
            self.cooldown = self.cooldown.max(20);
        } else {
            self.reload_ticks = d.reload;
            self.cooldown = self.cooldown.max(d.reload);
            let sample = match self.current {
                W_GLOCK => Some(sfx::RELOAD_GLOCK),
                W_357 => Some(sfx::RELOAD_357),
                W_MP5 => Some(sfx::MP5_CLIP_RELEASE),
                W_CROSSBOW => Some(sfx::RELOAD_XBOW),
                _ => None,
            };
            if let Some(sample) = sample {
                unsafe { sfx::play(sample) };
            }
        }
        true
    }

    #[inline]
    fn reload_anim(&self) -> u8 {
        if self.current == W_SHOTGUN && self.reload_ticks & SHOTGUN_RELOAD_START_TAG != 0 {
            VM_ANIM_RELOAD_START
        } else {
            VM_ANIM_RELOAD
        }
    }

    fn finish_reload(&mut self) {
        let d = self.def();
        let need = d.clip.saturating_sub(self.clip[self.current]);
        let take = need.min(self.ammo[d.ammo]);
        self.clip[self.current] = self.clip[self.current].saturating_add(take);
        self.ammo[d.ammo] = self.ammo[d.ammo].saturating_sub(take);
        if self.current == W_MP5 {
            unsafe { sfx::play(sfx::MP5_CLIP_INSERT) };
        }
    }

    /// Consume ammo for one shot. Returns true if the shot goes off (the caller
    /// then runs the archetype). Handles dry-click + auto-reload.
    fn try_fire(&mut self) -> bool {
        if !self.owns(self.current) {
            return false; // empty hands (pre-pickup)
        }
        let d = self.def();
        if self.cooldown != 0 || self.switch_ticks != 0 {
            return false;
        }
        if self.reload_ticks != 0 {
            // Retail lets a loaded shotgun interrupt the per-shell loop after
            // its initial one-second attack lockout. An empty tube still has
            // to finish inserting the first shell.
            if self.current == W_SHOTGUN
                && self.reload_ticks & SHOTGUN_RELOAD_INSERT_TAG != 0
                && self.clip[W_SHOTGUN] != 0
            {
                self.reload_ticks = 0;
            } else {
                return false;
            }
        }
        if d.ammo == AMMO_NONE {
            self.cooldown = d.cooldown; // melee: never out of ammo
            return true;
        }
        if d.clip > 0 {
            if self.clip[self.current] == 0 {
                self.cooldown = GLOCK_EMPTY_COOLDOWN_TICKS;
                self.dry_ticks = GLOCK_EMPTY_COOLDOWN_TICKS;
                unsafe { sfx::play(sfx::DRY) };
                let _ = self.start_reload();
                return false;
            }
            self.clip[self.current] -= 1;
        } else {
            // The Tau Cannon's primary shot consumes two uranium cells in the
            // SDK; every other clipless weapon consumes one per attack pulse.
            let cost = if self.current == W_GAUSS { 2 } else { 1 };
            if self.ammo[d.ammo] < cost {
                self.cooldown = GLOCK_EMPTY_COOLDOWN_TICKS;
                self.dry_ticks = GLOCK_EMPTY_COOLDOWN_TICKS;
                unsafe { sfx::play(sfx::DRY) };
                return false;
            }
            self.ammo[d.ammo] -= cost;
        }
        // Both hivehand modes add the 0.5 s recharge interval when the shot
        // empties the internal eight-hornet store.
        self.cooldown = d.cooldown
            + if self.current == W_HORNET && self.ammo[d.ammo] == 0 {
                HORNET_REGEN_TICKS
            } else {
                0
            };
        true
    }

    /// Cycle to the next/prev owned weapon. Returns true if the selection changed
    /// (the caller then streams the new viewmodel).
    fn cycle(&mut self, forward: bool) -> bool {
        if self.owned == 0 {
            return false;
        }
        let mut i = self.current;
        for _ in 0..N_WEAPONS {
            i = if forward {
                (i + 1) % N_WEAPONS
            } else {
                (i + N_WEAPONS - 1) % N_WEAPONS
            };
            if self.owns(i) {
                if i != self.current {
                    self.select(i);
                    return true;
                }
                break;
            }
        }
        false
    }

    fn select(&mut self, id: usize) {
        self.current = id;
        self.reload_ticks = 0;
        self.cooldown = 0;
        self.dry_ticks = 0;
        self.switch_ticks = 10; // DefaultDeploy: m_flNextAttack = time + 0.5
        self.gauss_charge = 0;
    }

    /// Grant the full arsenal + ammo. NB this is a demake simplification: HL1
    /// starts with crowbar+glock and you pick the rest up. Faithful weapon_* /
    /// ammo_* pickups (with w_* world models) are the next step; for now the whole
    /// system is given at spawn so every weapon is reachable.
    fn give_full_arsenal(&mut self) {
        self.owned = (1u16 << N_WEAPONS) - 1;
        let mut i = 0;
        while i < N_WEAPONS {
            if WEAPON_DEFS[i].clip > 0 {
                self.clip[i] = WEAPON_DEFS[i].clip;
            }
            i += 1;
        }
        let mut a = 0;
        while a < N_AMMO {
            self.ammo[a] = max_reserve_for(a);
            a += 1;
        }
    }
}

#[inline]
fn max_reserve_for(ammo: usize) -> u16 {
    // The reserve cap is the largest reserve_max among weapons using this ammo.
    if ammo == AMMO_ARGREN {
        return ARGREN_MAX_CARRY; // no weapon def carries this pool (MP5 alt fire)
    }
    let mut cap = 0u16;
    let mut i = 0;
    while i < N_WEAPONS {
        if WEAPON_DEFS[i].ammo == ammo && WEAPON_DEFS[i].reserve_max > cap {
            cap = WEAPON_DEFS[i].reserve_max;
        }
        i += 1;
    }
    cap
}

#[inline]
fn project_world_point(p: [i32; 3], rot: &Mat3I16, base_t: [i32; 3]) -> Option<(i16, i16, i32)> {
    let vz = dot12(rot.m[2], p) + base_t[2];
    if !(render::NEAR_Z..=FAR_VIEW).contains(&vz) {
        return None;
    }
    let vx = dot12(rot.m[0], p) + base_t[0];
    let vy = dot12(rot.m[1], p) + base_t[1];
    let h = render::projection_h();
    let sx = 160 + (vx * h) / vz;
    let sy = 120 + (vy * h) / vz;
    if sx < -16 || sx > 336 || sy < -16 || sy > 256 {
        return None;
    }
    Some((sx as i16, sy as i16, vz))
}

#[optimize(size)]
unsafe fn clear_combat_fx() {
    clear_projectiles();
    PENDING_PLAYER_DAMAGE = 0;
    PENDING_GAUSS_SHOVE = [0; 3];
    IMPACT_PARTICLES.clear();
    let mut i = 0usize;
    while i < MAX_IMPACT_MARKS {
        IMPACT_MARKS[i] = EMPTY_IMPACT_MARK;
        i += 1;
    }
    IMPACT_MARK_CURSOR = 0;
    let mut t = 0usize;
    while t < MAX_TRACERS {
        TRACERS[t].2 = 0;
        t += 1;
    }
    TRACER_CURSOR = 0;
    clear_debris();
    clear_explosions();
}

unsafe fn decay_combat_fx() {
    // Particle bursts are transient; bullet/blood MARKS now persist (like HL
    // decals) -- they stay at full colour until the fixed-size ring buffer
    // recycles the oldest, so a wall you shot keeps its holes.
    IMPACT_PARTICLES.update(1);
    let mut i = 0usize;
    while i < MAX_TRACERS {
        if TRACERS[i].2 > 0 {
            TRACERS[i].2 -= 1;
        }
        i += 1;
    }
    tick_debris();
    tick_explosions();
}

unsafe fn spawn_impact_mark(pos: [i32; 3], kind: u8) {
    let i = IMPACT_MARK_CURSOR % MAX_IMPACT_MARKS;
    IMPACT_MARKS[i] = ImpactMark {
        pos,
        ttl: IMPACT_MARK_TICKS,
        kind,
    };
    IMPACT_MARK_CURSOR = (IMPACT_MARK_CURSOR + 1) % MAX_IMPACT_MARKS;
}

/// Queue a bullet tracer (muzzle -> impact) for a couple of sim ticks. Ring
/// buffer: an eighth in flight at once just overwrites the oldest.
unsafe fn push_tracer(start: [i32; 3], end: [i32; 3]) {
    let i = TRACER_CURSOR % MAX_TRACERS;
    TRACERS[i] = (start, end, 2);
    TRACER_CURSOR = (TRACER_CURSOR + 1) % MAX_TRACERS;
}

unsafe fn spawn_impact_particles(screen: (i16, i16), kind: u8) {
    let (color, count, spread, ttl) = if kind == IMPACT_KIND_BLOOD {
        ((130, 14, 8), 5, 28, 12)
    } else {
        ((232, 186, 82), 7, 44, 10)
    };
    IMPACT_PARTICLES.spawn_burst(&mut IMPACT_RNG, screen, color, count, spread, ttl);
}

unsafe fn spawn_impact_fx(pos: [i32; 3], kind: u8, rot: &Mat3I16, base_t: [i32; 3]) {
    spawn_impact_mark(pos, kind);
    if let Some((sx, sy, _)) = project_world_point(pos, rot, base_t) {
        spawn_impact_particles((sx, sy), kind);
    }
}

/// Self-contained blended flat quad, same GP0(E1)-prefix trick as `BeamTri`:
/// the draw-mode word makes the blend deterministic wherever the packet lands
/// in an ordering table. `RectFlat` (GP0 0x60) carries no draw-mode word, so a
/// decal built from one can only ever be opaque.
#[repr(C, align(4))]
struct DecalQuad {
    tag: u32,
    draw_mode: u32,
    color_cmd: u32,
    v0: u32,
    v1: u32,
    v2: u32,
    v3: u32,
}

impl DecalQuad {
    const WORDS: u8 = 6;
    const EMPTY: Self = Self {
        tag: 0,
        draw_mode: 0,
        color_cmd: 0,
        v0: 0,
        v1: 0,
        v2: 0,
        v3: 0,
    };

    fn new(cx: i16, cy: i16, half: i16, color: (u8, u8, u8), blend: BlendMode) -> Self {
        let (x0, y0) = (cx - half, cy - half);
        let (x1, y1) = (cx + half, cy + half);
        Self {
            tag: 0,
            draw_mode: TextureMaterial::blended(0, 0, color, blend).draw_mode_word(),
            // GP0(2Ah): flat, four-point, untextured, semi-transparent.
            color_cmd: 0x2A00_0000 | gp0_color(color.0, color.1, color.2),
            // Z order (TL, TR, BL, BR) -- perimeter order draws a bowtie.
            v0: gp0_vertex(x0, y0),
            v1: gp0_vertex(x1, y0),
            v2: gp0_vertex(x0, y1),
            v3: gp0_vertex(x1, y1),
        }
    }
}

unsafe fn render_impact_marks<const N: usize>(
    ot: &mut OrderingTable<N>,
    rects: &mut [DecalQuad; MAX_IMPACT_MARKS],
    rot: &Mat3I16,
    base_t: [i32; 3],
) -> usize {
    let mut written = 0usize;
    let mut i = 0usize;
    while i < MAX_IMPACT_MARKS {
        let mark = IMPACT_MARKS[i];
        if mark.ttl != 0 {
            if let Some((sx, sy, vz)) = project_world_point(mark.pos, rot, base_t) {
                // Perspective size: a fixed world radius through the same
                // projection the geometry uses, so a mark shrinks with range
                // instead of staying a constant screen blob.
                let half = ((DECAL_WORLD_HALF * render::projection_h()) / vz).clamp(1, 12) as i16;
                // Average blend (B/2 + F/2): the mark mixes HALF the lit wall
                // underneath it with a soot or blood tone, so it keeps the
                // surface's texture and lighting instead of replacing them.
                // Subtract was the other candidate and is wrong here -- N marks
                // in one spot subtract N times and go pure black, whereas
                // averaging converges on the decal colour however many land,
                // which is how GoldSrc's overlapping decals behave.
                let color = if mark.kind == IMPACT_KIND_BLOOD {
                    (86, 14, 10)
                } else {
                    (46, 44, 40)
                };
                rects[written] = DecalQuad::new(sx, sy, half, color, BlendMode::Average);
                ot.add(0, &mut rects[written], DecalQuad::WORDS);
                written += 1;
                if written >= MAX_IMPACT_MARKS {
                    break;
                }
            }
        }
        i += 1;
    }
    written
}

const MELEE_AIM_PIX: i32 = 70; // crowbar swing: wide forgiving cone

#[inline(always)]
fn inverse_rotate_scaled(
    point: [i32; 3],
    origin: [i32; 3],
    rotation: &Mat3I16,
    scale: i32,
) -> [i32; 3] {
    let d = [
        point[0] - origin[0],
        point[1] - origin[1],
        point[2] - origin[2],
    ];
    [
        ((rotation.m[0][0] as i32 * d[0]
            + rotation.m[1][0] as i32 * d[1]
            + rotation.m[2][0] as i32 * d[2])
            >> 12)
            * scale,
        ((rotation.m[0][1] as i32 * d[0]
            + rotation.m[1][1] as i32 * d[1]
            + rotation.m[2][1] as i32 * d[2])
            >> 12)
            * scale,
        ((rotation.m[0][2] as i32 * d[0]
            + rotation.m[1][2] as i32 * d[1]
            + rotation.m[2][2] as i32 * d[2])
            >> 12)
            * scale,
    ]
}

#[inline(always)]
fn inverse_bone_point(point: [i32; 3], bone: model::BoneTransform) -> [i32; 3] {
    let d = [
        point[0] - bone.translation.x as i32,
        point[1] - bone.translation.y as i32,
        point[2] - bone.translation.z as i32,
    ];
    [
        (bone.rotation.m[0][0] as i32 * d[0]
            + bone.rotation.m[1][0] as i32 * d[1]
            + bone.rotation.m[2][0] as i32 * d[2])
            >> 12,
        (bone.rotation.m[0][1] as i32 * d[0]
            + bone.rotation.m[1][1] as i32 * d[1]
            + bone.rotation.m[2][1] as i32 * d[2])
            >> 12,
        (bone.rotation.m[0][2] as i32 * d[0]
            + bone.rotation.m[1][2] as i32 * d[1]
            + bone.rotation.m[2][2] as i32 * d[2])
            >> 12,
    ]
}

/// GoldSrc's TraceLine reaches the studio collision path, which inverse-
/// transforms the ray by each animated hitbox bone before testing its local
/// AABB. HMD8 retains the same boxes and compact bone palettes.
#[inline(never)]
unsafe fn prop_studio_hit_fraction(
    m: &Map,
    pi: usize,
    start: [i32; 3],
    end: [i32; 3],
) -> Option<i32> {
    let ty = PROP_KIND[pi] as usize;
    if ty >= N_MODEL_TYPES {
        return None;
    }
    let slot = TYPE_TO_SLOT[ty];
    if slot == MODEL_SLOT_NONE {
        return None;
    }
    let md = loaded_model(slot as usize);
    if md.n_hitboxes == 0 {
        return None;
    }
    let (frame, frame2, frac16) = prop_anim_frame(
        m,
        &md,
        PROP_STATE[pi],
        PROP_HIT_FLASH[pi],
        SIM_NOW as u32,
        pi,
    );
    let pose = md.frame(frame).interpolate(md.frame(frame2), frac16);
    let yaw = prop_yaw_value(PROP_YAW[pi]);
    let model_rotation = prop_model_rotation(yaw, prop_authored_tilt(m, pi));
    let scale = model_local_scale(md.local_to_world_q12());
    let model_start = inverse_rotate_scaled(start, PROP_POS[pi], &model_rotation, scale);
    let model_end = inverse_rotate_scaled(end, PROP_POS[pi], &model_rotation, scale);
    let mut best = None;
    for hi in 0..md.n_hitboxes {
        let hitbox = md.hitbox(hi);
        let bone = pose.bone(hitbox.bone, false, 0);
        let local_start = inverse_bone_point(model_start, bone);
        let local_end = inverse_bone_point(model_end, bone);
        let mins = [
            hitbox.bbmin.x as i32,
            hitbox.bbmin.y as i32,
            hitbox.bbmin.z as i32,
        ];
        let maxs = [
            hitbox.bbmax.x as i32,
            hitbox.bbmax.y as i32,
            hitbox.bbmax.z as i32,
        ];
        if let Some(frac) = hitbox_logic::ray_aabb_fraction_q12(local_start, local_end, mins, maxs)
        {
            best = Some(best.map_or(frac, |old: i32| old.min(frac)));
        }
    }
    best
}

/// One hitscan trace. `damage`/`range` from the weapon; (`aim_x`,`aim_y`) is the
/// half-cone in screen px; (`cx_px`,`cy_px`) offsets the cone centre (shotgun
/// pellets). Returns `Some` for either an actor or world hit, applying damage
/// and impact effects; `None` means the trace missed everything.
#[allow(clippy::too_many_arguments)]
unsafe fn fire_hitscan(
    m: &Map,
    movers: &[phys::Mover],
    eye: [i32; 3],
    rot: &Mat3I16,
    base_t: [i32; 3],
    damage: u8,
    club_damage: bool,
    range: i32,
    aim_x: i32,
    aim_y: i32,
    cx_px: i32,
    cy_px: i32,
) -> Option<usize> {
    // Spread offsets select the actual trace direction; the old implementation
    // only shifted an acceptance rectangle while decals still followed the
    // centre ray, which could report hits outside the body.
    let shot_component = |axis: usize| -> i32 {
        let q12 = rot.m[2][axis] as i64 * H_PROJ as i64
            + rot.m[0][axis] as i64 * cx_px as i64
            + rot.m[1][axis] as i64 * cy_px as i64;
        ((q12 * range as i64) / (H_PROJ as i64 * 4096)) as i32
    };
    let end = [
        eye[0] + shot_component(0),
        eye[1] + shot_component(1),
        eye[2] + shot_component(2),
    ];
    let world_hit = phys::trace_line(m, movers, eye, end);
    #[cfg(feature = "deep-reference-trace")]
    reference_trace::hitscan(SIM_NOW as u32, eye, end, world_hit);
    let world_limit_frac = world_hit.map_or(4097, |hit| hit.frac);
    let mut best = usize::MAX;
    let mut best_frac = 4097i32;
    let mut pi = 0usize;
    let nprops = PROP_COUNT.min(CARRY_MAILBOX_FIRST);
    while pi < nprops {
        let ty = PROP_KIND[pi];
        if PROP_ACTIVE[pi] == 0
            || ty == PROP_TYPE_HOLO
            || prop_start_health(ty) == 0
            || PROP_HEALTH[pi] == 0
        {
            pi += 1;
            continue;
        }

        let slot = TYPE_TO_SLOT[(ty as usize).min(N_MODEL_TYPES - 1)];
        let has_studio_boxes =
            slot != MODEL_SLOT_NONE && loaded_model(slot as usize).n_hitboxes != 0;
        let hit_frac = if has_studio_boxes && !club_damage {
            prop_studio_hit_fraction(m, pi, eye, end)
        } else {
            // Crowbar traces use a swept hull in GoldSrc. Keep the broad
            // screen-space fallback for melee and legacy chunks only.
            let target = prop_target(ty, PROP_POS[pi]);
            let vz = dot12(rot.m[2], target) + base_t[2];
            if !(render::NEAR_Z..=range).contains(&vz) {
                None
            } else {
                let vx = dot12(rot.m[0], target) + base_t[0];
                let vy = dot12(rot.m[1], target) + base_t[1];
                let dx = vx * H_PROJ as i32 - cx_px * vz;
                let dy = vy * H_PROJ as i32 - cy_px * vz;
                let (hit_r, hit_hh) = prop_hit_extent(ty);
                let lim_x = (hit_r * H_PROJ as i32).max(vz * aim_x);
                let lim_y = (hit_hh * H_PROJ as i32).max(vz * aim_y);
                (dx.abs() <= lim_x && dy.abs() <= lim_y)
                    .then_some(((vz as i64 * 4096) / range.max(1) as i64) as i32)
            }
        };
        let Some(hit_frac) = hit_frac else {
            pi += 1;
            continue;
        };
        if hit_frac > world_limit_frac {
            pi += 1;
            continue;
        }
        if hit_frac < best_frac {
            best = pi;
            best_frac = hit_frac;
        }
        pi += 1;
    }

    // Muzzle a little below/right of the eye so the tracer streaks from the gun,
    // not the crosshair. Only bullets (long range) leave a tracer, never a swing.
    let muzzle = [
        eye[0]
            + ((rot.m[2][0] as i32 * 20 + rot.m[0][0] as i32 * 7 + rot.m[1][0] as i32 * 7) >> 12),
        eye[1]
            + ((rot.m[2][1] as i32 * 20 + rot.m[0][1] as i32 * 7 + rot.m[1][1] as i32 * 7) >> 12),
        eye[2]
            + ((rot.m[2][2] as i32 * 20 + rot.m[0][2] as i32 * 7 + rot.m[1][2] as i32 * 7) >> 12),
    ];
    if best == usize::MAX {
        let tracer_end = if let Some(hit) = world_hit {
            let decal_pos = [
                hit.pos[0] + ((hit.normal[0] * 2) >> 12),
                hit.pos[1] + ((hit.normal[1] * 2) >> 12),
                hit.pos[2] + ((hit.normal[2] * 2) >> 12),
            ];
            spawn_impact_fx(decal_pos, IMPACT_KIND_WORLD, rot, base_t);
            if club_damage {
                let material = if hit.mover >= 0 {
                    let mut found = map::MATERIAL_CONCRETE;
                    if let Some(mv) = movers.iter().find(|mv| mv.id == hit.mover) {
                        let (local_pos, local_normal) =
                            phys::mover_local_impact(mv, hit.pos, hit.normal);
                        let ent = m.entity(hit.mover as usize);
                        found = m.submodel_impact_material(ent.submodel, local_pos, local_normal);
                    }
                    found
                } else {
                    let sample = [
                        hit.pos[0] + ((hit.normal[0] * 2) >> 12),
                        hit.pos[1] + ((hit.normal[1] * 2) >> 12),
                        hit.pos[2] + ((hit.normal[2] * 2) >> 12),
                    ];
                    m.world_impact_material(hit.pos, hit.normal, camera_leaf(m, sample))
                };
                CROWBAR_HIT_VOLUME_DEN = match material {
                    map::MATERIAL_CONCRETE => {
                        // next_mixed, not next: bit 0 of the LCG strictly alternates, so this
                        // was ticking STEP1, STEP2, STEP1 rather than choosing.
                        let sample = if IMPACT_RNG.next_mixed() & 1 == 0 {
                            sfx::STEP1
                        } else {
                            sfx::STEP2
                        };
                        sfx::play_world(sample, decal_pos);
                        2
                    }
                    map::MATERIAL_WOOD => {
                        sfx::play_world(sfx::WOOD_IMPACT, decal_pos);
                        5
                    }
                    map::MATERIAL_DIRT => {
                        sfx::play_world(sfx::STEP1, decal_pos);
                        10
                    }
                    map::MATERIAL_TILE => {
                        sfx::play_world(sfx::STEP2, decal_pos);
                        5
                    }
                    map::MATERIAL_SLOSH => 0,
                    _ => {
                        sfx::play_world(sfx::RIC, decal_pos);
                        if material == map::MATERIAL_GRATE {
                            2
                        } else {
                            3
                        }
                    }
                };
            } else {
                sfx::play_world(sfx::RIC, decal_pos);
            }
            if hit.mover >= 0 {
                damage_brush_ent(
                    m,
                    m.n_logic,
                    m.n_ents,
                    hit.mover as usize,
                    damage,
                    club_damage,
                    SIM_NOW,
                );
            }
            hit.pos
        } else {
            end // shot into the void: streak to the far range point
        };
        if range > 1000 {
            push_tracer(muzzle, tracer_end);
        }
        world_hit.map(|_| usize::MAX)
    } else {
        let ty = PROP_KIND[best];
        let target = [
            eye[0] + (((end[0] - eye[0]) as i64 * best_frac as i64) >> 12) as i32,
            eye[1] + (((end[1] - eye[1]) as i64 * best_frac as i64) >> 12) as i32,
            eye[2] + (((end[2] - eye[2]) as i64 * best_frac as i64) >> 12) as i32,
        ];
        damage_prop(best, damage, true);
        // TEXTURETYPE_PlaySound: bullets on flesh thud (bullet_hit1/2); metal
        // turrets keep the ricochet. CCrowbar::Swing plays cbar_hitbod on any
        // target that is not CLASS_NONE/CLASS_MACHINE -- the caller's cbar_hit
        // dong is for the world only, so suppress it here.
        if model_def(ty).ai == AI_TURRET {
            sfx::play_world(sfx::RIC, target);
        } else if club_damage {
            sfx::play_world(sfx::CBAR_HITBOD, target);
            CROWBAR_HIT_VOLUME_DEN = 0;
        } else {
            let thud = if IMPACT_RNG.next_mixed() & 1 == 0 {
                sfx::BULLET_HIT1
            } else {
                sfx::BULLET_HIT2
            };
            sfx::play_world(thud, target);
        }
        spawn_impact_fx(target, IMPACT_KIND_BLOOD, rot, base_t);
        if range > 1000 {
            push_tracer(muzzle, target);
        }
        PROP_AI_TARGET[best] = PROP_TARGET_PLAYER;
        if prop_is_scientist(ty) {
            PROP_AI_TIMER[best] = SCIENTIST_FEAR_TICKS;
        }
        Some(best)
    }
}

/// Fixed spread pattern for shotgun pellets (no RNG in the render path); pellet
/// `i` lands `spread` px off-centre in a small fixed rosette.
#[inline]
fn pellet_offset(i: u8, spread: i32) -> (i32, i32) {
    const PAT: [(i32, i32); 6] = [(0, 0), (2, -1), (-2, 1), (1, 2), (-1, -2), (2, 2)];
    let (px, py) = PAT[(i as usize) % PAT.len()];
    (px * spread / 2, py * spread / 2)
}

/// Run a weapon's fire archetype for one shot already paid for by try_fire.
/// Returns true when a hitscan connected with an enemy (drives the crowbar
/// hit-vs-miss sound).
unsafe fn fire_weapon(
    d: &WeaponDef,
    damage: u8,
    m: &Map,
    movers: &[phys::Mover],
    eye: [i32; 3],
    rot: &Mat3I16,
    base_t: [i32; 3],
    inacc: i32,
) -> bool {
    // Random screen-space aim jitter of magnitude +-mag px. `inacc` grows with
    // player speed / being airborne (HL cone-of-fire); the shotgun adds its own
    // scatter so the pellet pattern isn't a fixed rosette.
    let jit = |mag: i32| {
        if mag <= 0 {
            0
        } else {
            (IMPACT_RNG.below((2 * mag + 1) as u32) as i32) - mag
        }
    };
    match d.fire {
        FIRE_MELEE => fire_hitscan(
            m,
            movers,
            eye,
            rot,
            base_t,
            damage,
            true,
            d.range,
            MELEE_AIM_PIX,
            MELEE_AIM_PIX,
            0,
            0,
        )
        .is_some(),
        FIRE_SPREAD => {
            let n = d.pellets.max(1);
            let scatter = inacc + (d.spread as i32 / 4).max(1);
            let mut i = 0u8;
            let mut hit = false;
            while i < n {
                let (cx, cy) = pellet_offset(i, d.spread);
                hit |= fire_hitscan(
                    m,
                    movers,
                    eye,
                    rot,
                    base_t,
                    damage,
                    false,
                    d.range,
                    GLOCK_AIM_PIX_X,
                    GLOCK_AIM_PIX_Y,
                    cx + jit(scatter),
                    cy + jit(scatter),
                )
                .is_some();
                i += 1;
            }
            hit
        }
        FIRE_PROJ => {
            spawn_projectile(d.proj, d.damage, eye, rot);
            false
        }
        _ => {
            // FIRE_SEMI / FIRE_AUTO: one hitscan inside the weapon's own cone,
            // widened by movement inaccuracy. `d.spread` used to be read only by
            // the shotgun's pellet rosette, so every single-bullet gun fired
            // pixel-perfect from a standstill -- an MP5 that never walks its
            // burst, and a glock as precise as the .357.
            let cone = inacc + d.spread;
            fire_hitscan(
                m,
                movers,
                eye,
                rot,
                base_t,
                damage,
                false,
                d.range,
                GLOCK_AIM_PIX_X,
                GLOCK_AIM_PIX_Y,
                jit(cone),
                jit(cone),
            )
            .is_some()
        }
    }
}

/// Repeating secondary shots (L2). Toggle/charge/radio modes live at the input
/// site because they need edge/release state; this function owns only attacks
/// that may repeat while L2 remains held.
#[inline(never)]
unsafe fn fire_secondary(
    w: &mut Arsenal,
    m: &Map,
    movers: &[phys::Mover],
    eye: [i32; 3],
    rot: &Mat3I16,
    base_t: [i32; 3],
    eye_under: bool,
) -> bool {
    if w.cooldown != 0 || w.switch_ticks != 0 {
        return false;
    }
    if w.reload_ticks != 0 {
        if w.current == W_SHOTGUN
            && w.reload_ticks & SHOTGUN_RELOAD_INSERT_TAG != 0
            && w.clip[W_SHOTGUN] >= 2
        {
            w.reload_ticks = 0;
        } else {
            return false;
        }
    }
    if eye_under && matches!(w.current, W_MP5 | W_SHOTGUN) {
        w.cooldown = 3; // SDK: 0.15 s deny cadence
        sfx::play(sfx::DRY);
        return false;
    }
    match w.current {
        W_GLOCK => {
            // Glock secondary: faster, deliberately less accurate fire. It
            // shares the source shoot clip but not the primary's accuracy.
            if w.clip[W_GLOCK] == 0 {
                w.start_reload();
                sfx::play(sfx::DRY);
                return false;
            }
            w.clip[W_GLOCK] -= 1;
            w.cooldown = 4;
            let d = w.def();
            // fire_weapon adds the weapon's own cone, so pass the difference up
            // to the SDK's wider no-autoaim secondary spread.
            let extra = GLOCK_ALT_SPREAD_PX - d.spread;
            fire_weapon(d, d.damage, m, movers, eye, rot, base_t, extra);
            sfx::play(sfx::GLOCK);
            true
        }
        W_MP5 => {
            // Grenade launcher: lobs a contact grenade, one M203 round per shot
            // (its own pool -- ammo_ARgrenades pickups feed it, not hand grenades).
            if w.ammo[AMMO_ARGREN] == 0 {
                w.cooldown = 3;
                sfx::play(sfx::DRY);
                return false;
            }
            w.ammo[AMMO_ARGREN] -= 1;
            w.cooldown = 20; // SDK: one second for both attack modes
            spawn_projectile(PROJ_M203, 100, eye, rot);
            sfx::play(sfx::M203);
            true
        }
        W_SHOTGUN => {
            // Double-barrel: two shells, twelve SP pellets, 1.5 s recovery.
            if w.clip[W_SHOTGUN] < 2 {
                sfx::play(sfx::DRY);
                let _ = w.start_reload();
                return false;
            }
            w.clip[W_SHOTGUN] -= 2;
            w.cooldown = 30;
            let d = w.def();
            fire_weapon(d, d.damage, m, movers, eye, rot, base_t, 4);
            fire_weapon(d, d.damage, m, movers, eye, rot, base_t, 6);
            sfx::play(sfx::SHOTGUN_DOUBLE);
            true
        }
        W_HORNET => {
            // Fast mode is a straight 1200 u/s dart, not the primary's slow
            // target-seeking hornet.
            if w.ammo[AMMO_HORNET] == 0 {
                return false;
            }
            w.ammo[AMMO_HORNET] -= 1;
            w.cooldown = 2 + if w.ammo[AMMO_HORNET] == 0 {
                HORNET_REGEN_TICKS
            } else {
                0
            };
            spawn_projectile(PROJ_HORNET_FAST, w.def().damage, eye, rot);
            sfx::play(sfx::ELECTRO);
            true
        }
        _ => false,
    }
}

const GAUSS_FULL_CHARGE_TICKS: u8 = 80; // GetFullChargeTime(): 4.0 s in SP
const GAUSS_SPINUP_TICKS: u8 = 10; // gauss.cpp switches SPINUP -> SPIN at 0.5 s
const GAUSS_AMMO_BURN_TICKS: u8 = 6; // one uranium cell every 0.3 s in SP
const GAUSS_OVERCHARGE_TICKS: u8 = 200; // ten seconds, then self-zap
const GAUSS_EVENT_NONE: u8 = 0;
const GAUSS_EVENT_START: u8 = 1;
const GAUSS_EVENT_SPIN: u8 = 2;
const GAUSS_EVENT_FIRE: u8 = 3;
const GAUSS_EVENT_OVERCHARGE: u8 = 4;

#[inline(never)]
unsafe fn fire_gauss_charge(
    w: &mut Arsenal,
    age: u8,
    m: &Map,
    movers: &[phys::Mover],
    eye: [i32; 3],
    rot: &Mat3I16,
    base_t: [i32; 3],
) -> u8 {
    let damage = (200u16 * age.min(GAUSS_FULL_CHARGE_TICKS) as u16 / GAUSS_FULL_CHARGE_TICKS as u16)
        .max(1) as u8;
    fire_hitscan(
        m,
        movers,
        eye,
        rot,
        base_t,
        damage,
        false,
        w.def().range,
        GLOCK_AIM_PIX_X,
        GLOCK_AIM_PIX_Y,
        0,
        0,
    );
    // v_forward * damage * 5 units/second, at 20 Hz, with Z dropped (single
    // player never gets the deathmatch pop-up).
    let shove = -(damage as i32) * 5 / 20;
    PENDING_GAUSS_SHOVE = [
        (rot.m[2][0] as i32 * shove) >> 12,
        0,
        (rot.m[2][2] as i32 * shove) >> 12,
    ];
    w.gauss_charge = 0;
    w.cooldown = 20;
    sfx::play(sfx::GAUSS);
    GAUSS_EVENT_FIRE
}

/// Advance the Tau Cannon's hold-to-charge secondary attack. Damage and ammo
/// cadence follow gauss.cpp; the one-byte age is the complete persistent state.
#[inline(never)]
unsafe fn tick_gauss_secondary(
    w: &mut Arsenal,
    held: bool,
    eye_under: bool,
    m: &Map,
    movers: &[phys::Mover],
    eye: [i32; 3],
    rot: &Mat3I16,
    base_t: [i32; 3],
) -> u8 {
    if w.current != W_GAUSS {
        w.gauss_charge = 0;
        return GAUSS_EVENT_NONE;
    }
    if eye_under && (held || w.gauss_charge != 0) {
        w.gauss_charge = 0;
        w.cooldown = 10;
        sfx::play(sfx::ELECTRO);
        return GAUSS_EVENT_OVERCHARGE;
    }
    if held {
        if w.gauss_charge == 0 {
            if w.cooldown != 0 || w.switch_ticks != 0 || w.reload_ticks != 0 {
                return GAUSS_EVENT_NONE;
            }
            if w.ammo[AMMO_URANIUM] == 0 {
                w.cooldown = GLOCK_EMPTY_COOLDOWN_TICKS;
                sfx::play(sfx::DRY);
                return GAUSS_EVENT_NONE;
            }
            // The SDK spends one cell as soon as the coils begin spinning.
            w.ammo[AMMO_URANIUM] -= 1;
            w.gauss_charge = 1;
            sfx::play(sfx::GAUSS_CHARGE);
            return GAUSS_EVENT_START;
        }

        w.gauss_charge = w.gauss_charge.saturating_add(1);
        let age = w.gauss_charge;
        if age < GAUSS_FULL_CHARGE_TICKS && age % GAUSS_AMMO_BURN_TICKS == 0 {
            if w.ammo[AMMO_URANIUM] == 0 {
                // Falling out of ammo fires the charge immediately, just like
                // SecondaryAttack's forced StartFire path.
                return fire_gauss_charge(w, age, m, movers, eye, rot, base_t);
            }
            w.ammo[AMMO_URANIUM] -= 1;
            if w.ammo[AMMO_URANIUM] == 0 {
                return fire_gauss_charge(w, age, m, movers, eye, rot, base_t);
            }
        }
        if age >= GAUSS_OVERCHARGE_TICKS {
            w.gauss_charge = 0;
            w.cooldown = 20;
            PENDING_PLAYER_DAMAGE = PENDING_PLAYER_DAMAGE.saturating_add(50);
            note_damage_direction(LOGIC_PLAYER_POS);
            sfx::play(sfx::ELECTRO);
            return GAUSS_EVENT_OVERCHARGE;
        }
        return if age == GAUSS_SPINUP_TICKS {
            GAUSS_EVENT_SPIN
        } else {
            GAUSS_EVENT_NONE
        };
    }

    if w.gauss_charge != 0 {
        return fire_gauss_charge(w, w.gauss_charge, m, movers, eye, rot, base_t);
    }
    GAUSS_EVENT_NONE
}

/// The fire sound for a weapon id; melee picks hit vs miss.
fn weapon_fire_sfx(id: usize, hit: bool) -> u8 {
    match id {
        W_CROWBAR => {
            if hit {
                sfx::CBAR_HIT
            } else {
                sfx::CBAR_MISS
            }
        }
        W_GLOCK => sfx::GLOCK,
        W_357 => sfx::PYTHON,
        W_MP5 => sfx::MP5,
        W_SHOTGUN => sfx::SHOTGUN,
        W_CROSSBOW => sfx::XBOW,
        W_RPG => sfx::RPG,
        W_GAUSS | W_EGON => sfx::GAUSS,
        W_HORNET => sfx::ELECTRO,
        _ => sfx::CBAR_MISS, // thrown/placed: a swing whoosh
    }
}

// ---- Projectiles: rockets, bolts, grenades, hornets, lobbed explosives -------
const MAX_PROJECTILES: usize = 12;
const PROJ_GRAVITY: i32 = 12; // world units/tick^2 for arced kinds
                              // CGrenade::ShootContact uses velocity 800 u/s and gravity 0.5. At the game's
                              // 20 Hz fixed step, Half-Life's default 800 u/s^2 gravity becomes exactly one
                              // world unit/tick^2 for the M203 contact grenade.
const M203_GRAVITY: i32 = 1;
const PROJ_HIT_RADIUS: i32 = 56; // projectile-vs-enemy contact radius

#[derive(Clone, Copy)]
struct Projectile {
    active: bool,
    pos: [i32; 3],
    vel: [i32; 3],
    kind: u8,
    damage: u8,
    life: u8,
    from_enemy: bool, // enemy shots hit the player; player shots hit props
}

impl Projectile {
    const ZERO: Projectile = Projectile {
        active: false,
        pos: [0; 3],
        vel: [0; 3],
        kind: 0,
        damage: 0,
        life: 0,
        from_enemy: false,
    };
}

static mut PROJECTILES: [Projectile; MAX_PROJECTILES] = [Projectile::ZERO; MAX_PROJECTILES];
static mut PROJ_RECTS: [RectFlat; MAX_PROJECTILES] =
    [const { RectFlat::new(0, 0, 0, 0, 0, 0, 0) }; MAX_PROJECTILES];
// The RPG designator is map-local like GoldSrc's CLaserSpot. Keeping one
// position instead of an entity saves a projectile slot; active rockets steer
// toward it and the render path emits one depth-sorted red marker.
static mut RPG_SPOT_ACTIVE: bool = false;
static mut RPG_SPOT_POS: [i32; 3] = [0; 3];
// Enemy AoE / projectiles / hazards deal damage here; the sim loop drains it into
// health/armor once per tick (keeps explode() off the &mut health thread).
static mut PENDING_PLAYER_DAMAGE: u16 = 0;
/// Horizontal shove owed to the player from a charged Tau shot, in world units
/// per tick. CGauss::StartFire subtracts `v_forward * flDamage * 5` from the
/// player's velocity on a secondary shot and then restores the Z component in
/// single player, so the kick is a pure horizontal shove -- the recoil that
/// makes a full-charge shot feel like a cannon instead of a rifle.
static mut PENDING_GAUSS_SHOVE: [i32; 3] = [0; 3];

// (speed, life ticks, gravity?, AoE radius (0 = direct hit only), colour, size px)
fn proj_params(kind: u8) -> (i32, u8, bool, i32, (u8, u8, u8), u16) {
    match kind {
        PROJ_ROCKET => (90, 50, false, 220, (250, 150, 50), 6),
        PROJ_BOLT => (100, 40, false, 0, (210, 210, 170), 3),
        PROJ_BOLT_WATER => (50, 80, false, 0, (210, 210, 170), 3),
        PROJ_GRENADE => (64, 60, true, 200, (120, 150, 90), 5),
        // Retail hivehand: primary is a 300 u/s tracking hornet; secondary is
        // a straight 1200 u/s dart. At 20 Hz those are 15 and 60 units/tick.
        PROJ_HORNET => (15, 160, false, 0, (250, 230, 70), 3),
        PROJ_HORNET_FAST => (60, 70, false, 0, (255, 244, 90), 3),
        PROJ_SNARK => (48, 80, true, 110, (190, 170, 50), 5),
        PROJ_SPIT => (75, 55, true, 0, (150, 220, 80), 4), // bullsquid acid glob
        PROJ_SATCHEL => (40, u8::MAX, true, 200, (170, 70, 50), 5),
        // ShootContact has no fuse: it travels until its first collision. The
        // source blast radius defaults to damage * 2.5 (100 * 2.5 = 250).
        PROJ_M203 => (40, u8::MAX, true, 250, (120, 150, 90), 5),
        _ => (40, 100, true, 200, (170, 70, 50), 5), // PROJ_TRIPMINE
    }
}

/// Unit-ish (q12) direction from a to b. Zero-length falls back to +Z forward.
fn dir_q12(a: [i32; 3], b: [i32; 3]) -> [i32; 3] {
    let d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    let len = isqrt_i32(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).max(1);
    [(d[0] << 12) / len, (d[1] << 12) / len, (d[2] << 12) / len]
}

unsafe fn clear_projectiles() {
    let mut i = 0;
    while i < MAX_PROJECTILES {
        PROJECTILES[i] = Projectile::ZERO;
        i += 1;
    }
    RPG_SPOT_ACTIVE = false;
}

/// Trace the RPG's designator to the aimed world surface. GoldSrc creates a
/// CLaserSpot entity; one point is enough for the PS1 renderer and guidance.
#[inline(never)]
unsafe fn update_rpg_spot(
    m: &Map,
    movers: &[phys::Mover],
    eye: [i32; 3],
    rot: &Mat3I16,
    enabled: bool,
) {
    RPG_SPOT_ACTIVE = enabled;
    if !enabled {
        return;
    }
    let end = [
        eye[0] + ((rot.m[2][0] as i32 * 8192) >> 12),
        eye[1] + ((rot.m[2][1] as i32 * 8192) >> 12),
        eye[2] + ((rot.m[2][2] as i32 * 8192) >> 12),
    ];
    RPG_SPOT_POS = phys::trace_line(m, movers, eye, end)
        .map(|hit| hit.pos)
        .unwrap_or(end);
}

#[inline]
unsafe fn guide_projectile(index: usize, target: [i32; 3], old_weight: i32) {
    let p = PROJECTILES[index];
    let speed = proj_params(p.kind).0;
    let dir = dir_q12(p.pos, target);
    let desired = [
        (dir[0] * speed) >> 12,
        (dir[1] * speed) >> 12,
        (dir[2] * speed) >> 12,
    ];
    let blended = [
        p.vel[0] * old_weight + desired[0],
        p.vel[1] * old_weight + desired[1],
        p.vel[2] * old_weight + desired[2],
    ];
    let len =
        isqrt_i32(blended[0] * blended[0] + blended[1] * blended[1] + blended[2] * blended[2])
            .max(1);
    PROJECTILES[index].vel = [
        blended[0] * speed / len,
        blended[1] * speed / len,
        blended[2] * speed / len,
    ];
}

/// Player weapon projectile: fires forward along the view.
unsafe fn spawn_projectile(kind: u8, damage: u8, eye: [i32; 3], rot: &Mat3I16) -> usize {
    let fwd = [rot.m[2][0] as i32, rot.m[2][1] as i32, rot.m[2][2] as i32];
    spawn_projectile_dir(kind, damage, eye, fwd, false)
}

/// Spawn a projectile from `origin` along the q12 direction `dir`. `from_enemy`
/// routes its damage at the player instead of props.
unsafe fn spawn_projectile_dir(
    kind: u8,
    damage: u8,
    origin: [i32; 3],
    dir: [i32; 3],
    from_enemy: bool,
) -> usize {
    let (speed, life, gravity, ..) = proj_params(kind);
    let mut slot = usize::MAX;
    let mut i = 0;
    while i < MAX_PROJECTILES {
        if !PROJECTILES[i].active {
            slot = i;
            break;
        }
        i += 1;
    }
    if slot == usize::MAX {
        slot = 0; // pool full: recycle slot 0
    }
    let mut vel = [
        (dir[0] * speed) >> 12,
        (dir[1] * speed) >> 12,
        (dir[2] * speed) >> 12,
    ];
    if gravity && kind != PROJ_M203 {
        vel[1] += speed / 3; // toss it up a little for an arc
    }
    let muzzle_forward = if kind == PROJ_M203 { 16 } else { 24 };
    PROJECTILES[slot] = Projectile {
        active: true,
        pos: [
            origin[0] + ((dir[0] * muzzle_forward) >> 12),
            origin[1] + ((dir[1] * muzzle_forward) >> 12),
            origin[2] + ((dir[2] * muzzle_forward) >> 12),
        ],
        vel,
        kind,
        damage,
        life,
        from_enemy,
    };
    slot
}

/// Detonate every charge thrown by the selected satchel weapon. Tripmines use
/// a distinct projectile kind and are intentionally unaffected by the radio.
unsafe fn detonate_satchels(m: &Map) -> bool {
    let mut detonated = false;
    let mut i = 0usize;
    while i < MAX_PROJECTILES {
        if PROJECTILES[i].active && PROJECTILES[i].kind == PROJ_SATCHEL {
            let p = PROJECTILES[i];
            PROJECTILES[i].active = false;
            explode(m, p.pos, p.damage, proj_params(PROJ_SATCHEL).3, true);
            detonated = true;
        }
        i += 1;
    }
    detonated
}

unsafe fn explode(m: &Map, pos: [i32; 3], damage: u8, radius: i32, player_inflicted: bool) {
    if radius <= 0 {
        return;
    }
    sfx::play_world(sfx::EXPLODE, pos);
    queue_explosion_fx(pos, (radius / 3).clamp(20, 255) as u8);
    // Flying sparks + debris chunks thrown outward, over the particle flash.
    let mut s = 0;
    while s < 7 {
        let vx = (IMPACT_RNG.below(25) as i32) - 12;
        let vy = 5 + (IMPACT_RNG.below(14) as i32);
        let vz = (IMPACT_RNG.below(25) as i32) - 12;
        spawn_debris(pos, [vx, vy, vz], DEBRIS_SPARK, 14);
        s += 1;
    }
    // GoldSrc RadiusDamage reaches every damageable brush, including the
    // Hazard Course's moving func_guntarget. A point trace to the live brush
    // centre keeps walls/glass authoritative while accepting a hit on the
    // target brush itself.
    let nents = m.n_ents;
    let r2 = radius * radius;
    let mut ei = 0usize;
    while ei < nents {
        if ENT_ACTIVE[ei] != 0 && ENT_BRUSH_LOGIC[ei] != u16::MAX {
            let li = ENT_BRUSH_LOGIC[ei] as usize;
            let kind = if li < m.n_logic { LOGIC_KIND[li] } else { 0 };
            if kind != map::LOGIC_FUNC_BREAKABLE && kind != map::LOGIC_FUNC_GUNTARGET {
                ei += 1;
                continue;
            }
            let e = ENT_CACHE[ei];
            let c = if e.kind == ENT_KIND_PUSHABLE {
                pushable_world_center(e, e.origin)
            } else {
                let off = ent_draw_offset(ei);
                [
                    e.center[0] + off[0],
                    e.center[1] + off[1],
                    e.center[2] + off[2],
                ]
            };
            let d2 = dist2_3(c, pos);
            if d2 < r2 {
                let line_clear =
                    match phys::trace_line(m, &MOVERS[..MOVER_COUNT.min(MAX_ENTS + 1)], pos, c) {
                        None => true,
                        Some(hit) => hit.mover == ei as i32,
                    };
                if line_clear {
                    let dmg = logic_state::radius_damage_at_distance(damage, radius, isqrt_i32(d2));
                    if dmg != 0 {
                        damage_brush_ent(m, m.n_logic, nents, ei, dmg, false, SIM_NOW);
                    }
                }
            }
        }
        ei += 1;
    }
    let mut pi = 0;
    let nprops = PROP_COUNT.min(CARRY_MAILBOX_FIRST);
    while pi < nprops {
        if PROP_ACTIVE[pi] != 0 && prop_start_health(PROP_KIND[pi]) != 0 && PROP_HEALTH[pi] != 0 {
            let t = prop_target(PROP_KIND[pi], PROP_POS[pi]);
            let d2 = dist2_3(t, pos);
            if d2 < r2 {
                let dmg = logic_state::radius_damage_at_distance(damage, radius, isqrt_i32(d2));
                damage_prop(pi, dmg, player_inflicted);
                if player_inflicted {
                    PROP_AI_TARGET[pi] = PROP_TARGET_PLAYER;
                }
            }
        }
        pi += 1;
    }
    // The blast also catches the player (own rockets self-hurt too -- faithful).
    let pd2 = dist2_3(
        [
            LOGIC_PLAYER_POS[0],
            LOGIC_PLAYER_POS[1] + 18,
            LOGIC_PLAYER_POS[2],
        ],
        pos,
    );
    if pd2 < r2 {
        let dmg = logic_state::radius_damage_at_distance(damage, radius, isqrt_i32(pd2));
        PENDING_PLAYER_DAMAGE = PENDING_PLAYER_DAMAGE.saturating_add(dmg as u16);
        note_damage_direction(pos);
    }
}

/// Houndeye sonic shockwave: radius damage centred on the animal, player only
/// (HL's houndeye pulse). Falls off with distance. Visual is the HE_BLAST sound
/// plus the caller's particle burst.
unsafe fn houndeye_blast(center: [i32; 3], radius: i32, dmg: u8) {
    let d2 = dist2_3(
        [
            LOGIC_PLAYER_POS[0],
            LOGIC_PLAYER_POS[1] + 18,
            LOGIC_PLAYER_POS[2],
        ],
        center,
    );
    if d2 < radius * radius {
        let scaled = logic_state::radius_damage_at_distance(dmg, radius, isqrt_i32(d2));
        PENDING_PLAYER_DAMAGE = PENDING_PLAYER_DAMAGE.saturating_add(scaled as u16);
        note_damage_direction(center);
    }
    queue_explosion_fx(center, 40); // pale burst stand-in (a proper ring lands with the FX pool)
}

#[inline(never)]
unsafe fn tick_projectiles(m: &Map, movers: &[phys::Mover]) {
    let mut i = 0;
    while i < MAX_PROJECTILES {
        if !PROJECTILES[i].active {
            i += 1;
            continue;
        }
        let kind = PROJECTILES[i].kind;
        let (_, _, gravity, aoe, _, _) = proj_params(kind);
        // Landed satchels and grenades remain stationary. Satchels wait for the
        // radio; hand grenades continue only their fuse countdown.
        if kind == PROJ_SATCHEL && PROJECTILES[i].vel == [0; 3] {
            i += 1;
            continue;
        }
        if kind == PROJ_GRENADE && PROJECTILES[i].vel == [0; 3] {
            PROJECTILES[i].life = PROJECTILES[i].life.saturating_sub(1);
            if PROJECTILES[i].life == 0 {
                let p = PROJECTILES[i];
                PROJECTILES[i].active = false;
                explode(m, p.pos, p.damage, aoe, true);
            }
            i += 1;
            continue;
        }
        // A placed tripmine stores its wall normal in `vel` (far larger than a
        // thrown velocity). Its 2.5 s arming countdown reaches zero and the
        // render path then exposes the laser beam.
        if kind == PROJ_TRIPMINE
            && PROJECTILES[i].vel[0]
                .abs()
                .max(PROJECTILES[i].vel[1].abs())
                .max(PROJECTILES[i].vel[2].abs())
                > 512
        {
            PROJECTILES[i].life = PROJECTILES[i].life.saturating_sub(1);
            i += 1;
            continue;
        }
        if kind == PROJ_ROCKET && !PROJECTILES[i].from_enemy && RPG_SPOT_ACTIVE {
            // The source rocket continuously homes on the active LTD spot. A
            // 3:1 velocity blend retains the authored sweeping turn instead
            // of snapping the missile directly onto the crosshair.
            guide_projectile(i, RPG_SPOT_POS, 3);
        } else if kind == PROJ_HORNET && !PROJECTILES[i].from_enemy {
            // Tracking-mode hornets seek the nearest visible living target;
            // the fast secondary kind deliberately skips this branch.
            let origin = PROJECTILES[i].pos;
            let mut best = usize::MAX;
            let mut best_d2 = 1024 * 1024;
            let mut pi = 0usize;
            let nprops = PROP_COUNT.min(CARRY_MAILBOX_FIRST);
            while pi < nprops {
                if PROP_ACTIVE[pi] != 0
                    && prop_start_health(PROP_KIND[pi]) != 0
                    && PROP_HEALTH[pi] != 0
                {
                    let target = prop_target(PROP_KIND[pi], PROP_POS[pi]);
                    let d2 = dist2_3(origin, target);
                    if d2 < best_d2 {
                        best_d2 = d2;
                        best = pi;
                    }
                }
                pi += 1;
            }
            if best != usize::MAX {
                let target = prop_target(PROP_KIND[best], PROP_POS[best]);
                if phys::line_clear_world(m, origin, target)
                    && phys::line_clear_movers(m, movers, origin, target)
                {
                    guide_projectile(i, target, 2);
                }
            }
        }
        let old = PROJECTILES[i].pos;
        if gravity {
            PROJECTILES[i].vel[1] -= if kind == PROJ_M203 {
                M203_GRAVITY
            } else {
                PROJ_GRAVITY
            };
        }
        let v = PROJECTILES[i].vel;
        let new = [old[0] + v[0], old[1] + v[1], old[2] + v[2]];
        let mut hit = false;
        let mut hit_pos = new;
        let mut hit_normal = [0i32; 3];
        if let Some(h) = phys::trace_line(m, movers, old, new) {
            hit = true;
            hit_pos = h.pos;
            hit_normal = h.normal;
        }
        let from_enemy = PROJECTILES[i].from_enemy;
        // Contact: enemy shots home on the player, player shots on the nearest
        // living prop (both within PROJ_HIT_RADIUS of the new pos).
        let mut best = usize::MAX;
        let mut player_hit = false;
        if from_enemy {
            let ppos = [
                LOGIC_PLAYER_POS[0],
                LOGIC_PLAYER_POS[1] + 18,
                LOGIC_PLAYER_POS[2],
            ];
            if dist2_3(ppos, new) < PROJ_HIT_RADIUS * PROJ_HIT_RADIUS {
                player_hit = true;
                hit = true;
                hit_pos = new;
            }
        } else {
            let mut best_d2 = PROJ_HIT_RADIUS * PROJ_HIT_RADIUS;
            let mut pi = 0;
            let nprops = PROP_COUNT.min(CARRY_MAILBOX_FIRST);
            while pi < nprops {
                if PROP_ACTIVE[pi] != 0
                    && prop_start_health(PROP_KIND[pi]) != 0
                    && PROP_HEALTH[pi] != 0
                {
                    let d2 = dist2_3(prop_target(PROP_KIND[pi], PROP_POS[pi]), new);
                    if d2 < best_d2 {
                        best_d2 = d2;
                        best = pi;
                    }
                }
                pi += 1;
            }
            if best != usize::MAX {
                hit = true;
                hit_pos = prop_target(PROP_KIND[best], PROP_POS[best]);
            }
        }
        PROJECTILES[i].pos = new;
        if kind != PROJ_SATCHEL && kind != PROJ_M203 && PROJECTILES[i].life > 0 {
            PROJECTILES[i].life -= 1;
        }
        if kind == PROJ_SATCHEL && hit {
            PROJECTILES[i].pos = hit_pos;
            PROJECTILES[i].vel = [0; 3];
            i += 1;
            continue;
        }
        if kind == PROJ_GRENADE && hit {
            let v = PROJECTILES[i].vel;
            let reflected = if hit_normal == [0; 3] {
                [-v[0] / 2, -v[1] / 2, -v[2] / 2]
            } else {
                let along =
                    (v[0] * hit_normal[0] + v[1] * hit_normal[1] + v[2] * hit_normal[2]) >> 12;
                [
                    (v[0] - ((hit_normal[0] * along * 2) >> 12)) / 2,
                    (v[1] - ((hit_normal[1] * along * 2) >> 12)) / 2,
                    (v[2] - ((hit_normal[2] * along * 2) >> 12)) / 2,
                ]
            };
            PROJECTILES[i].pos = [
                hit_pos[0] + (hit_normal[0] >> 11),
                hit_pos[1] + (hit_normal[1] >> 11),
                hit_pos[2] + (hit_normal[2] >> 11),
            ];
            PROJECTILES[i].vel =
                if reflected[0].abs() + reflected[1].abs() + reflected[2].abs() < 12 {
                    [0; 3]
                } else {
                    reflected
                };
            if PROJECTILES[i].life == 0 {
                let p = PROJECTILES[i];
                PROJECTILES[i].active = false;
                explode(m, p.pos, p.damage, aoe, true);
            }
            i += 1;
            continue;
        }
        if kind == PROJ_TRIPMINE && hit && hit_normal != [0; 3] {
            PROJECTILES[i].pos = [
                hit_pos[0] + (hit_normal[0] >> 11),
                hit_pos[1] + (hit_normal[1] >> 11),
                hit_pos[2] + (hit_normal[2] >> 11),
            ];
            PROJECTILES[i].vel = hit_normal;
            PROJECTILES[i].life = 50;
            i += 1;
            continue;
        }
        if hit || PROJECTILES[i].life == 0 {
            if aoe > 0 {
                explode(m, hit_pos, PROJECTILES[i].damage, aoe, !from_enemy);
            } else if best != usize::MAX {
                damage_prop(best, PROJECTILES[i].damage, true);
                PROP_AI_TARGET[best] = PROP_TARGET_PLAYER;
            } else if player_hit {
                PENDING_PLAYER_DAMAGE =
                    PENDING_PLAYER_DAMAGE.saturating_add(PROJECTILES[i].damage as u16);
                note_damage_direction(hit_pos);
            }
            PROJECTILES[i].active = false;
        }
        i += 1;
    }
}

unsafe fn render_projectiles<const N: usize>(
    ot: &mut OrderingTable<N>,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    let mut i = 0;
    while i < MAX_PROJECTILES {
        if PROJECTILES[i].active {
            let (_, _, _, _, (r, g, b), size) = proj_params(PROJECTILES[i].kind);
            if let Some((sx, sy, _)) = project_world_point(PROJECTILES[i].pos, rot, base_t) {
                let half = (size / 2) as i16;
                PROJ_RECTS[i] = RectFlat::new(sx - half, sy - half, size, size, r, g, b);
                ot.add(0, &mut PROJ_RECTS[i], RectFlat::WORDS);
            }
        }
        i += 1;
    }
}

/// Emit the RPG laser-designator dot into the world OT. Unlike transient FX,
/// this must sort at the traced wall depth so intervening geometry hides it.
unsafe fn queue_rpg_spot(
    packets: &mut PrimitivePacketArena<'_>,
    ot: &mut OrderingTable<OT_LEN>,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    if !RPG_SPOT_ACTIVE {
        return;
    }
    if let Some((sx, sy, vz)) = project_world_point(RPG_SPOT_POS, rot, base_t) {
        let size = if vz < 640 { 5 } else { 3 };
        let half = size as i16 / 2;
        if let Some(packet) =
            packets.push(RectFlat::new(sx - half, sy - half, size, size, 255, 24, 16))
        {
            ot.add(
                clamp_otz((vz.saturating_sub(4) as usize) >> OT_SHIFT),
                packet,
                RectFlat::WORDS,
            );
        } else {
            note_render_packet_drop(false);
        }
    }
}

// ---- Transient world debris: shell casings, gibs, sparks -------------------
// A small world-space pool: each entry falls under gravity, expires by ttl, and
// draws as one small coloured rect. Shell casings, death gibs, and env_spark
// showers all ride it (each just picks a kind + initial velocity).
const MAX_DEBRIS: usize = 48;
const DEBRIS_CASING: u8 = 0;
const DEBRIS_GIB: u8 = 1;
const DEBRIS_SPARK: u8 = 2;
const DEBRIS_BREAK_BASE: u8 = 3; // + GoldSrc Materials enum (0..6)

#[derive(Clone, Copy)]
struct Debris {
    pos: [i32; 3],
    vel: [i32; 3],
    ttl: u8,
    kind: u8,
}
impl Debris {
    const ZERO: Debris = Debris {
        pos: [0; 3],
        vel: [0; 3],
        ttl: 0,
        kind: 0,
    };
}
static mut DEBRIS: [Debris; MAX_DEBRIS] = [Debris::ZERO; MAX_DEBRIS];
static mut DEBRIS_CURSOR: usize = 0;
static mut DEBRIS_RECTS: [RectFlat; MAX_DEBRIS] =
    [const { RectFlat::new(0, 0, 0, 0, 0, 0, 0) }; MAX_DEBRIS];

unsafe fn spawn_debris(pos: [i32; 3], vel: [i32; 3], kind: u8, ttl: u8) {
    let i = DEBRIS_CURSOR % MAX_DEBRIS;
    DEBRIS[i] = Debris {
        pos,
        vel,
        ttl,
        kind,
    };
    DEBRIS_CURSOR = (DEBRIS_CURSOR + 1) % MAX_DEBRIS;
}

/// GoldSrc CBreakable::Die emits TE_BREAKMODEL with NUM_SHARDS=6 and a
/// 2.5-second lifetime. Reuse the resident world-debris pool: material lives in
/// the existing kind byte, so crates gain visible shards without any new RAM.
unsafe fn spawn_breakable_shards(rec: map::LogicEnt, live_center: [i32; 3]) {
    let material = rec.arg1.min(6) as u8;
    let authored_center = [
        (rec.mins[0] + rec.maxs[0]) / 2,
        (rec.mins[1] + rec.maxs[1]) / 2,
        (rec.mins[2] + rec.maxs[2]) / 2,
    ];
    let live_offset = [
        live_center[0] - authored_center[0],
        live_center[1] - authored_center[1],
        live_center[2] - authored_center[2],
    ];
    let mut shard = 0;
    while shard < 6 {
        let sample_axis = |lo: i32, hi: i32| -> i32 {
            let span = (hi - lo + 1).max(1);
            lo + (IMPACT_RNG.next() as i32).rem_euclid(span)
        };
        let p = [
            sample_axis(rec.mins[0], rec.maxs[0]) + live_offset[0],
            sample_axis(rec.mins[1], rec.maxs[1]) + live_offset[1],
            sample_axis(rec.mins[2], rec.maxs[2]) + live_offset[2],
        ];
        // TE_BREAKMODEL randomization=10 around a zero base velocity. Bias Y
        // upward just enough for the six fragments to read as a burst.
        let vel = [
            (IMPACT_RNG.below(21) as i32) - 10,
            6 + (IMPACT_RNG.below(9) as i32),
            (IMPACT_RNG.below(21) as i32) - 10,
        ];
        spawn_debris(p, vel, DEBRIS_BREAK_BASE + material, 50);
        shard += 1;
    }
}

unsafe fn clear_debris() {
    let mut i = 0;
    while i < MAX_DEBRIS {
        DEBRIS[i].ttl = 0;
        i += 1;
    }
    DEBRIS_CURSOR = 0;
}

/// Advance debris one sim tick: gravity + integrate, sparks fly straighter.
unsafe fn tick_debris() {
    let mut i = 0;
    while i < MAX_DEBRIS {
        if DEBRIS[i].ttl > 0 {
            DEBRIS[i].ttl -= 1;
            let g = if DEBRIS[i].kind == DEBRIS_SPARK {
                6
            } else if DEBRIS[i].kind >= DEBRIS_BREAK_BASE {
                2 // sv_gravity 800 at the 20 Hz simulation rate
            } else {
                12
            };
            DEBRIS[i].vel[1] -= g;
            DEBRIS[i].pos[0] += DEBRIS[i].vel[0];
            DEBRIS[i].pos[1] += DEBRIS[i].vel[1];
            DEBRIS[i].pos[2] += DEBRIS[i].vel[2];
        }
        i += 1;
    }
}

unsafe fn render_debris<const N: usize>(
    ot: &mut OrderingTable<N>,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    let mut i = 0;
    while i < MAX_DEBRIS {
        if DEBRIS[i].ttl > 0 {
            let (r, g, b, size) = match DEBRIS[i].kind {
                DEBRIS_CASING => (200u8, 170u8, 80u8, 2i16),
                DEBRIS_GIB => (150, 20, 15, 3),
                DEBRIS_SPARK => (255, 240, 150, 2),
                3 => (150, 205, 215, 2), // glass
                4 => (125, 75, 35, 3),   // wood
                5 => (150, 155, 160, 3), // metal
                6 => (145, 25, 20, 3),   // flesh
                7 => (115, 115, 105, 3), // cinder block
                8 => (185, 175, 145, 3), // ceiling tile
                _ => (75, 105, 70, 3),   // computer
            };
            if let Some((sx, sy, _)) = project_world_point(DEBRIS[i].pos, rot, base_t) {
                DEBRIS_RECTS[i] = RectFlat::new(
                    sx - size / 2,
                    sy - size / 2,
                    size as u16,
                    size as u16,
                    r,
                    g,
                    b,
                );
                ot.add(0, &mut DEBRIS_RECTS[i], RectFlat::WORDS);
            }
        }
        i += 1;
    }
}

// Animated explosion fireball: the resident s_explod.spr billboard. explode()
// and env_explosion spawn one here (via queue_explosion_fx); it plays its frames
// over ~10 sim ticks then expires. Layers over the spark debris + particle spray.
const MAX_EXPLOSIONS: usize = 8;
const EXPL_TICKS_PER_FRAME: u8 = 2; // 20 Hz sim -> ~5 frames over ~0.5 s
#[derive(Clone, Copy)]
struct ExplosionFx {
    pos: [i32; 3],
    age: u8,   // sim ticks since spawn (selects the frame)
    ttl: u8,   // ticks remaining (0 = free slot)
    half: i16, // world half-size
}
static mut EXPLOSIONS: [ExplosionFx; MAX_EXPLOSIONS] = [ExplosionFx {
    pos: [0; 3],
    age: 0,
    ttl: 0,
    half: 0,
}; MAX_EXPLOSIONS];
static mut EXPL_CURSOR: usize = 0;

unsafe fn spawn_explosion_fx(pos: [i32; 3], half: i16) {
    let nf = sprite::expl_def().n_frames;
    if nf == 0 {
        return; // resident sprite missing -> nothing to play (particles still fire)
    }
    let i = EXPL_CURSOR % MAX_EXPLOSIONS;
    EXPLOSIONS[i] = ExplosionFx {
        pos,
        age: 0,
        ttl: nf.saturating_mul(EXPL_TICKS_PER_FRAME).max(1),
        half,
    };
    EXPL_CURSOR = (EXPL_CURSOR + 1) % MAX_EXPLOSIONS;
}

unsafe fn clear_explosions() {
    let mut i = 0;
    while i < MAX_EXPLOSIONS {
        EXPLOSIONS[i].ttl = 0;
        i += 1;
    }
    EXPL_CURSOR = 0;
}

/// Advance every live fireball one sim tick (frame = age / ticks-per-frame).
unsafe fn tick_explosions() {
    let mut i = 0;
    while i < MAX_EXPLOSIONS {
        if EXPLOSIONS[i].ttl > 0 {
            EXPLOSIONS[i].ttl -= 1;
            EXPLOSIONS[i].age = EXPLOSIONS[i].age.saturating_add(1);
        }
        i += 1;
    }
}

/// Draw each live fireball as a camera-facing additive billboard of its frame.
unsafe fn render_explosions(
    packets: &mut PrimitivePacketArena<'_>,
    np: &mut usize,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    let d = sprite::expl_def();
    if d.n_frames == 0 {
        return;
    }
    let mut i = 0;
    while i < MAX_EXPLOSIONS {
        let e = EXPLOSIONS[i];
        if e.ttl > 0 {
            let frame = (e.age / EXPL_TICKS_PER_FRAME).min(d.n_frames - 1) as usize;
            emit_billboard(
                packets,
                np,
                e.pos,
                e.half as i32,
                e.half as i32,
                sprite::expl_slot(frame),
                d.crush_w,
                d.crush_h,
                rot,
                base_t,
            );
        }
        i += 1;
    }
}

/// Eject a brass casing near the muzzle: up + to the right, tumbling away.
unsafe fn eject_casing(eye: [i32; 3], rot: &Mat3I16) {
    let jitter = (IMPACT_RNG.below(5) as i32) - 2;
    // Right + up + a little forward from the eye (view axes in world coords).
    let pos = [
        eye[0] + ((rot.m[0][0] as i32 * 6 + rot.m[2][0] as i32 * 12) >> 12),
        eye[1] + ((rot.m[0][1] as i32 * 6 + rot.m[2][1] as i32 * 12) >> 12) - 4,
        eye[2] + ((rot.m[0][2] as i32 * 6 + rot.m[2][2] as i32 * 12) >> 12),
    ];
    let vel = [
        (rot.m[0][0] as i32 * (7 + jitter)) >> 12,
        6,
        (rot.m[0][2] as i32 * (7 + jitter)) >> 12,
    ];
    spawn_debris(pos, vel, DEBRIS_CASING, 40);
}

/// Burst of gore chunks from a killed enemy.
unsafe fn spawn_gibs(pos: [i32; 3], n: u8) {
    let mut k = 0;
    while k < n {
        let vx = (IMPACT_RNG.below(15) as i32) - 7;
        let vz = (IMPACT_RNG.below(15) as i32) - 7;
        let vy = 8 + (IMPACT_RNG.below(8) as i32);
        spawn_debris([pos[0], pos[1] + 20, pos[2]], [vx, vy, vz], DEBRIS_GIB, 70);
        k += 1;
    }
}

/// env_spark: each spark emitter throws a small shower now and then when the
/// player is nearby (cheap -- a 1/64 per-tick chance, distance-gated).
#[inline(never)]
#[optimize(size)]
unsafe fn tick_env_sparks(m: &Map, nlogic: usize) {
    let indexed = LOGIC_SPARK_COUNT != LOGIC_HOT_FALLBACK;
    let scan_count = if indexed {
        LOGIC_SPARK_COUNT as usize
    } else {
        nlogic
    };
    let mut scan = 0usize;
    while scan < scan_count {
        let li = if indexed {
            LOGIC_BREAK_HP[LOGIC_STORAGE_WORDS - 1 - scan] as usize
        } else {
            scan
        };
        // Full maps can exhaust the hotlist tail. Their cached kinds still
        // let us skip unrelated records without decoding 64 bytes each.
        if LOGIC_KIND[li] != map::LOGIC_ENV_SPARK {
            scan += 1;
            continue;
        }
        let rec = m.logic(li);
        if dist2_3(rec.origin, LOGIC_PLAYER_POS) < 1200 * 1200
            && (IMPACT_RNG.next_mixed() & 0x3F) == 0
        {
            let o = rec.origin;
            let mut s = 0;
            while s < 4 {
                let vx = (IMPACT_RNG.below(11) as i32) - 5;
                let vy = 3 + (IMPACT_RNG.below(8) as i32);
                let vz = (IMPACT_RNG.below(11) as i32) - 5;
                spawn_debris(o, [vx, vy, vz], DEBRIS_SPARK, 10);
                s += 1;
            }
            if rec.sound0 != u8::MAX {
                sfx::play_map_world(rec.sound0, o);
            } else {
                sfx::play_world(sfx::RIC, o);
            }
        }
        scan += 1;
    }
}

/// Sim-side beam timers. Transient beams (`life` > 0, the cascade's debris and
/// probe strikes) turn themselves back off when the strike expires; random-area
/// beams (no authored endpoint -- wacky_beams, the c1a0c arcs) re-strike a
/// freshly traced endpoint around their origin every period while toggled on.
#[inline(never)]
unsafe fn tick_beams(m: &Map, nlogic: usize) {
    let indexed = LOGIC_BEAM_COUNT != LOGIC_HOT_FALLBACK;
    let scan_count = if indexed {
        LOGIC_BEAM_COUNT as usize
    } else {
        nlogic
    };
    let mut scan = 0usize;
    let mut bk = 0usize;
    while scan < scan_count {
        let li = if indexed {
            LOGIC_BREAK_HP[LOGIC_STORAGE_WORDS - 1 - LOGIC_SPARK_COUNT as usize - scan] as usize
        } else {
            scan
        };
        if indexed || LOGIC_KIND[li] == map::LOGIC_BEAM {
            let rec = m.logic(li);
            if bk >= MAX_BEAM_STATES {
                return;
            }
            if LOGIC_STATE[li] != LOGIC_STATE_TOP {
                BEAM_LIFE[bk] = 0;
                BEAM_STRIKE[bk] = 0;
            } else {
                let fa = rec.first_aux as usize;
                let life = (m.logic_aux(fa + 1).delay_ticks & 0xFF) as u8;
                if rec.arg0 & 0x10 != 0 {
                    if BEAM_LIFE[bk] > 0 {
                        BEAM_LIFE[bk] -= 1;
                    }
                    if BEAM_STRIKE[bk] > 0 {
                        BEAM_STRIKE[bk] -= 1;
                    } else {
                        let rw = m.logic_aux(fa + 3).delay_ticks;
                        let radius = (rw & 0x0FFF) as i32;
                        let a0 = m.logic_aux(fa);
                        let a1 = m.logic_aux(fa + 1);
                        let start = [
                            a0.target as i16 as i32,
                            a0.delay_ticks as i16 as i32,
                            a1.target as i16 as i32,
                        ];
                        let d = [
                            (BEAM_RNG.below((2 * radius + 1) as u32) as i32) - radius,
                            (BEAM_RNG.below((radius + 1) as u32) as i32) - radius / 2,
                            (BEAM_RNG.below((2 * radius + 1) as u32) as i32) - radius,
                        ];
                        let goal = [start[0] + d[0], start[1] + d[1], start[2] + d[2]];
                        let hit = phys::trace_line(m, &[], start, goal)
                            .map(|h| h.pos)
                            .unwrap_or(goal);
                        let mut e = [0i16; 3];
                        let mut c = 0;
                        while c < 3 {
                            e[c] = hit[c].clamp(-32768, 32767) as i16;
                            c += 1;
                        }
                        BEAM_RAND_END[bk] = e;
                        // Even life-0 authored strikes need a visible flash.
                        BEAM_LIFE[bk] = life.max(6);
                        BEAM_STRIKE[bk] = ((rw >> 12) * 4).max(4);
                    }
                } else if life > 0 {
                    // Striking beam: lit for `life`, dark for the authored
                    // re-strike period, repeating while toggled on (GoldSrc
                    // StrikeThink at life + StrikeTime). A huge period (the
                    // debris beams' StrikeTime 9999) is effectively a single
                    // strike per fire.
                    if BEAM_LIFE[bk] > 0 {
                        BEAM_LIFE[bk] -= 1;
                        if BEAM_LIFE[bk] == 0 {
                            BEAM_STRIKE[bk] = m.logic_aux(fa + 3).delay_ticks.max(1);
                        }
                    } else if BEAM_STRIKE[bk] > 1 {
                        BEAM_STRIKE[bk] -= 1;
                    } else {
                        // First light after a toggle, or the period elapsed.
                        BEAM_LIFE[bk] = life;
                        BEAM_STRIKE[bk] = 0;
                    }
                }
            }
            bk += 1;
        }
        scan += 1;
    }
}

#[inline(always)]
unsafe fn world_order_key(depths: ordering::PrimitiveDepths, texture_backdrop: bool) -> usize {
    let policy = EMIT_POLICY;
    ordering::world_order_key(
        depths,
        ordering::SurfaceOrder {
            local_depth: policy.local_depth(),
            cutout_backed: policy.cutout(),
            coplanar_backdrop: policy.coplanar_backdrop(),
            texture_backdrop,
        },
    )
}

/// Non-world render domains (models, beams, sprites) retain their authored
/// depth rules but share the physical bounds of the hardware ordering table.
#[inline(always)]
fn clamp_otz(z: usize) -> usize {
    z.clamp(1, OT_LEN - 1)
}

fn camera_leaf(m: &Map, eye: [i32; 3]) -> i32 {
    if m.n_nodes == 0 {
        return 0;
    }
    let mut idx = 0i32;
    let mut guard = 0;
    loop {
        if idx < 0 || idx as usize >= m.n_nodes || guard > 256 {
            return 0;
        }
        guard += 1;
        let nd = m.node(idx as usize);
        let side = dot12_q5(nd.n, eye) - nd.dist_q5;
        let next = if side >= 0 { nd.c0 } else { nd.c1 };
        if next < 0 {
            return -next - 1;
        }
        idx = next;
    }
}

#[inline]
fn valid_pvs_leaf(m: &Map, leaf: i32) -> bool {
    leaf > 0 && (leaf as usize) <= m.n_visleaves
}

// This cache is touched from both the simulation and the very large render
// loop. LLVM's MIPS-I backend has repeatedly made an ordinary static access
// layout-sensitive as play() crosses code-alignment boundaries, causing the
// render side to observe -1 forever and rebuild the complete PVS every frame.
// Keep the shared invalidation channel as an explicit memory transaction; the
// render loop also owns a local leaf below so this global is not its hot cache.
#[inline]
unsafe fn pvs_cam_leaf_load() -> i32 {
    core::ptr::read_volatile(core::ptr::addr_of!(PVS_CAM_LEAF))
}

#[inline]
unsafe fn pvs_cam_leaf_store(leaf: i32) {
    core::ptr::write_volatile(core::ptr::addr_of_mut!(PVS_CAM_LEAF), leaf);
}

fn recover_camera_leaf(m: &Map, eye: [i32; 3], player_pos: [i32; 3], train_hint: [i32; 3]) -> i32 {
    let leaf = camera_leaf(m, eye);
    if valid_pvs_leaf(m, leaf) {
        return leaf;
    }

    const CANDIDATE_OFFSETS: [[i32; 3]; 10] = [
        [0, -VIEW_HEIGHT + 8, 0],
        [0, -32, 0],
        [0, 32, 0],
        [48, 0, 0],
        [-48, 0, 0],
        [0, 0, 48],
        [0, 0, -48],
        [96, -16, 0],
        [-96, -16, 0],
        [0, -16, 96],
    ];
    let mut i = 0usize;
    while i < CANDIDATE_OFFSETS.len() {
        let o = CANDIDATE_OFFSETS[i];
        let cand = [eye[0] + o[0], eye[1] + o[1], eye[2] + o[2]];
        let cand_leaf = camera_leaf(m, cand);
        if valid_pvs_leaf(m, cand_leaf) {
            return cand_leaf;
        }
        i += 1;
    }

    let player_leaf = camera_leaf(m, [player_pos[0], player_pos[1] + 8, player_pos[2]]);
    if valid_pvs_leaf(m, player_leaf) {
        return player_leaf;
    }

    let train_leaf = camera_leaf(
        m,
        [train_hint[0], train_hint[1] + VIEW_HEIGHT, train_hint[2]],
    );
    if valid_pvs_leaf(m, train_leaf) {
        return train_leaf;
    }

    leaf
}

fn decompress_vis(m: &Map, visofs: i32, out: &mut [u8]) {
    // GoldSrc rows are model[0].visleafs bits wide. The BSP leaf lump also
    // contains submodel-only leaves; decoding to that larger count consumes
    // bytes from the next compressed row and produces unstable visibility.
    let row = (m.n_visleaves + 7) / 8;
    let row = row.min(out.len());
    for b in out[..row].iter_mut() {
        *b = 0;
    }
    if visofs < 0 {
        for b in out[..row].iter_mut() {
            *b = 0xFF;
        }
        return;
    }
    let vis = m.vis();
    let mut v = visofs as usize;
    let mut c = 0usize;
    while c < row {
        if v >= vis.len() {
            break;
        }
        if vis[v] != 0 {
            out[c] = vis[v];
            v += 1;
            c += 1;
        } else {
            v += 1;
            if v >= vis.len() {
                break;
            }
            let mut cnt = vis[v];
            v += 1;
            while cnt > 0 && c < row {
                out[c] = 0;
                c += 1;
                cnt -= 1;
            }
        }
    }
}

/// Merge one GoldSrc PVS row into an already decoded row without allocating a
/// second MAX_LEAVES buffer. Underwater cameras use this for the first dry leaf
/// above the eye, matching the visibility on both sides of a transparent
/// boundary instead of presenting an otherwise-correct water polygon over
/// black.
fn merge_vis(m: &Map, visofs: i32, out: &mut [u8]) {
    let row = ((m.n_visleaves + 7) / 8).min(out.len());
    if visofs < 0 {
        out[..row].fill(0xff);
        return;
    }
    let vis = m.vis();
    let mut v = visofs as usize;
    let mut c = 0usize;
    while c < row && v < vis.len() {
        let byte = vis[v];
        v += 1;
        if byte != 0 {
            out[c] |= byte;
            c += 1;
        } else {
            if v >= vis.len() {
                break;
            }
            c = c.saturating_add(vis[v] as usize).min(row);
            v += 1;
        }
    }
}

fn dry_leaf_above(m: &Map, eye: [i32; 3]) -> Option<usize> {
    // BSP liquid boundaries are horizontal in the authored Hazard Course.
    // Short steps avoid jumping through a shallow dry pocket; the 512-unit
    // ceiling covers its deepest shafts without adding per-frame work (this
    // runs only on cold PVS rebuilds).
    let mut dy = 8;
    while dy <= 512 {
        let leaf = camera_leaf(m, [eye[0], eye[1] + dy, eye[2]]);
        if valid_pvs_leaf(m, leaf) && m.leaf_liquid(leaf as usize) == 0 {
            return Some(leaf as usize);
        }
        dy += 16;
    }
    None
}

#[inline(always)]
fn build_pvs_face_rec(m: &Map, face: usize) -> PvsFaceRec {
    let (first, cnt) = m.face_tris(face);
    let liquid = m.face_liquid(face);
    let cutout = m.face_cutout_backed(face);
    let coplanar_backdrop = m.face_coplanar_backdrop(face);
    let (bc, radius) = m.face_bounds(face);
    PvsFaceRec {
        first: first as u16,
        count: cnt as u16
            | if face_needs_generic_emit(m, face) {
                PVS_FACE_SPECIAL
            } else {
                0
            }
            | if cutout { PVS_FACE_CUTOUT } else { 0 },
        center: [bc[0] as i16, bc[1] as i16, bc[2] as i16],
        radius: radius as u16,
        tex: m.face_tex(face) as u8,
        meta: (if m.face_is_loop(face) {
            PVS_FACE_LOOP
        } else {
            0
        }) | (if m.face_is_patch(face) {
            PVS_FACE_PATCH
        } else {
            0
        }) | (if liquid { PVS_FACE_TRANSLUCENT } else { 0 })
            | (if m.face_refined_topology(face) {
                PVS_FACE_REFINED_TOPOLOGY
            } else {
                0
            })
            | (if coplanar_backdrop {
                PVS_FACE_COPLANAR_BACKDROP
            } else {
                0
            }),
    }
}

// PVS rebuilds run only when the camera crosses a BSP leaf. Keep the cold
// active-scene compiler compact so it cannot evict RAM or shift the
// frame-rate-critical renderer merely because its two-pass plan is verbose.
#[optimize(size)]
unsafe fn rebuild_pvs_cache(m: &Map, cam_leaf: i32, nents: usize, eye: [i32; 3], eye_under: bool) {
    // The packet payload borrows the old PVS arrays' unused suffix. Invalidate
    // before the new live prefix can overwrite any part of it.
    invalidate_world_packet_cache();
    let (visofs, _, _) = m.leaf(cam_leaf as usize);
    decompress_vis(m, visofs, &mut VIS_BITS);
    if eye_under {
        if let Some(dry_leaf) = dry_leaf_above(m, eye) {
            let (dry_visofs, _, _) = m.leaf(dry_leaf);
            merge_vis(m, dry_visofs, &mut VIS_BITS);
        }
    }
    let mut old_group = 0usize;
    while old_group < PVS_GROUP_COUNT {
        PVS_GROUP_FACE[PVS_GROUP_ACTIVE[old_group] as usize] = PVS_LINK_END;
        old_group += 1;
    }
    PVS_LEAF_COUNT = 0;
    PVS_FACE_COUNT = 0;

    PVS_GROUP_COUNT = 0;
    PVS_HAS_TRANSLUCENT = false;
    PVS_HAS_TEXANIM = false;
    PVS_TEX_ANIM_MASK = [0; map::TEX_ANIM_MAX / 32];
    PVS_TEX_ANIM_GEN = 0;
    PVS_TRI_REF_COUNT = 0;
    PVS_ENT_COUNT = 0;
    // A 1-bit duplicate marker recovers 7.4 KiB over the old byte-per-face
    // token array. PVS rebuilds already walk the visible marks; clearing 272
    // words here is cold compared with retaining that RAM every frame.
    PVS_FACE_MARK.fill(0);

    for i in 0..m.n_visleaves.min(MAX_LEAVES) {
        if VIS_BITS[i >> 3] & (1u8 << (i & 7)) == 0 {
            continue;
        }
        let leaf = i + 1;
        PVS_LEAF_COUNT += 1;

        let (_, m0, mc) = m.leaf(leaf);
        for mj in m0..m0 + mc {
            if mj >= m.n_marks {
                break;
            }
            let face = m.mark(mj);
            if face >= MAX_FACES {
                continue;
            }
            let mark_word = face >> 5;
            let mark_bit = 1u32 << (face & 31);
            if PVS_FACE_MARK[mark_word] & mark_bit != 0 {
                continue;
            }
            PVS_FACE_MARK[mark_word] |= mark_bit;
            let (first, cnt) = m.face_tris(face);
            if cnt == 0 || first > u16::MAX as usize || cnt > PVS_FACE_COUNT_MASK as usize {
                continue;
            }

            if PVS_FACE_COUNT >= MAX_FACES {
                continue;
            }

            let group = m.face_group(face);
            if group >= MAX_FACE_GROUPS {
                continue;
            }
            if PVS_GROUP_FACE[group] == PVS_LINK_END {
                if PVS_GROUP_COUNT >= MAX_FACE_GROUPS {
                    break;
                }
                PVS_GROUP_FIRST[group] = PVS_LINK_END;
                PVS_GROUP_FACE[group] = face as u16 & PVS_GROUP_FACE_MASK;
                PVS_GROUP_ACTIVE[PVS_GROUP_COUNT] = group as u16;
                PVS_GROUP_COUNT += 1;
            }
            if m.face_liquid(face) {
                PVS_GROUP_FACE[group] |= PVS_GROUP_LIQUID;
            }

            let entry = PVS_FACE_COUNT;
            PVS_FACE_INDEX.0[entry] = face as u16;
            let liquid = m.face_liquid(face);
            let face_tex = m.face_tex(face);
            let animated = tex_is_animated(face_tex);
            PVS_HAS_TRANSLUCENT |= liquid;
            PVS_HAS_TEXANIM |= animated;
            if animated {
                let tex = face_tex & (map::TEX_ANIM_MAX - 1);
                PVS_TEX_ANIM_MASK[tex >> 5] |= 1u32 << (tex & 31);
            }
            if entry < MAX_PVS_FACE_RECS {
                PVS_FACE_REC.0[entry] = build_pvs_face_rec(m, face);
            }
            PVS_TRI_REF_COUNT += cnt;
            PVS_FACE_NEXT.0[entry] = PVS_GROUP_FIRST[group];
            PVS_GROUP_FIRST[group] = entry as u16;
            PVS_FACE_COUNT += 1;
        }
    }

    let mut ei = 0usize;
    while ei < nents {
        let e = ENT_CACHE[ei];
        // kind 4 = invisible ladder volume: physics only, never drawn.
        if e.kind != 4
            && ENT_ACTIVE[ei] != 0
            // Moving brushes remain in the candidate list even when their
            // current box is outside this PVS. Their live verdict is refreshed
            // every visual; otherwise a stationary camera could never observe
            // a target/train/door crossing into a visible leaf.
            && visibility_logic::pvs_candidate(
                entity_uses_live_pvs(ei, e),
                entity_touches_pvs(m, &e),
            )
            && PVS_ENT_COUNT < MAX_ENTS
        {
            PVS_ENTS[PVS_ENT_COUNT] = ei as u16;
            PVS_ENT_COUNT += 1;
        }
        ei += 1;
    }
    pvs_cam_leaf_store(cam_leaf);
}

#[inline]
fn pvs_leaf_visible(m: &Map, leaf: usize) -> bool {
    if leaf == 0 || leaf > m.n_visleaves {
        return false;
    }
    let bit = leaf - 1;
    if bit >= m.n_visleaves || bit >= MAX_LEAVES {
        return false;
    }
    unsafe { (VIS_BITS[bit >> 3] & (1u8 << (bit & 7))) != 0 }
}

#[inline]
fn entity_touches_pvs(m: &Map, e: &map::Ent) -> bool {
    if e.leaf_count == 0 {
        return true;
    }
    let end = e.leaf_start.saturating_add(e.leaf_count);
    let mut i = e.leaf_start;
    while i < end {
        if pvs_leaf_visible(m, m.ent_leaf(i)) {
            return true;
        }
        i += 1;
    }
    false
}

/// Translated brushes whose current BSP membership is runtime state. Rotating
/// brushes retain their conservative cooked sweep: rotation cannot carry them
/// outside it, while these entities can cross portals with the camera still.
#[inline(always)]
unsafe fn entity_uses_live_pvs(ei: usize, e: map::Ent) -> bool {
    if e.kind == ENT_KIND_PUSHABLE {
        return true;
    }
    let train = ENT_TRAIN_SLOT[ei] as usize;
    if train < TRAIN_COUNT {
        return true;
    }
    (e.kind == 1 || e.kind == 3) && (ENT_BRUSH_LOGIC[ei] as usize) < MAX_LOGIC
}

/// Current world-space visibility bounds from the same transform state used by
/// rendering and collision. None means the entity is static/cook-spatialized.
#[inline(never)]
unsafe fn live_entity_pvs_bounds(m: &Map, ei: usize, e: map::Ent) -> Option<([i32; 3], [i32; 3])> {
    if e.kind == ENT_KIND_PUSHABLE {
        let center = pushable_world_center(e, e.origin);
        let half = pushable_half_extents(e);
        return Some(visibility_logic::translated_padded_bounds(
            [-half[0], -half[1], -half[2]],
            half,
            center,
        ));
    }

    let train = ENT_TRAIN_SLOT[ei] as usize;
    if train < TRAIN_COUNT {
        let li = train_logic_index(TRAIN_LI[train]);
        if li < m.n_logic {
            let rec = m.logic(li);
            // Logic bounds are already world-space at the entity's authored
            // transform. ent_draw_offset is absolute for origin brushes, so
            // only its displacement from that authored transform belongs here.
            // Adding the absolute offset double-translated Hazard Course's
            // local-model gun targets by their entire map position.
            let delta = visibility_logic::mover_bounds_delta(ent_draw_offset(ei), e.origin);
            return Some(visibility_logic::translated_padded_bounds(
                rec.mins, rec.maxs, delta,
            ));
        }
        return None;
    }

    if e.kind == 1 || e.kind == 3 {
        let li = ENT_BRUSH_LOGIC[ei] as usize;
        if li < m.n_logic {
            let rec = m.logic(li);
            // Door/button model bounds already include the authored origin;
            // only their bottom->top displacement is a live translation.
            let delta = scale12_vec(e.mv, ENT_PHASE[ei]);
            return Some(visibility_logic::translated_padded_bounds(
                rec.mins, rec.maxs, delta,
            ));
        }
    }
    None
}

#[inline(always)]
unsafe fn live_entity_pvs_visible(ei: usize) -> bool {
    PVS_LIVE_ENT_BITS[ei >> 5] & (1u32 << (ei & 31)) != 0
}

#[inline(always)]
unsafe fn live_entity_pvs_mark_dirty(ei: usize) {
    if ei < MAX_ENTS {
        PVS_LIVE_DIRTY_BITS[ei >> 5] |= 1u32 << (ei & 31);
    }
}

/// GoldSrc relinks movers after physics. We need only its visibility result,
/// not a resident 48-leaf edict array: query the current AABB directly against
/// the already-decompressed camera PVS and retain one bit until the next visual.
#[inline(never)]
unsafe fn refresh_live_entity_pvs(m: &Map, pvs_changed: bool) {
    if pvs_changed {
        PVS_LIVE_ENT_BITS.fill(0);
    }
    let mut bi = 0usize;
    while bi < PVS_ENT_COUNT {
        let ei = PVS_ENTS[bi] as usize;
        let e = ENT_CACHE[ei];
        let mask = 1u32 << (ei & 31);
        let dirty = PVS_LIVE_DIRTY_BITS[ei >> 5] & mask != 0;
        // Sliding doors/buttons expose their transform generation through the
        // existing render-phase snapshot. Trains and carts publish the same
        // transition through the compact dirty bitset when their offset moves.
        let phase_changed = (e.kind == 1 || e.kind == 3) && ENT_PHASE[ei] != ENT_RENDER_PHASE[ei];
        if !pvs_changed && !dirty && !phase_changed {
            bi += 1;
            continue;
        }
        PVS_LIVE_ENT_BITS[ei >> 5] &= !mask;
        if let Some((mins, maxs)) = live_entity_pvs_bounds(m, ei, e) {
            if m.n_nodes == 0 || box_touches_pvs_node(m, 0, mins, maxs, 0) {
                PVS_LIVE_ENT_BITS[ei >> 5] |= mask;
            }
        } else {
            // A malformed mover-to-logic mapping must degrade to a false
            // positive, never make the brush disappear. This matches the
            // conservative behavior of malformed BSP/PVS traversal below.
            PVS_LIVE_ENT_BITS[ei >> 5] |= mask;
        }
        bi += 1;
    }
    PVS_LIVE_DIRTY_BITS.fill(0);
}

/// The GTE's perspective quotient H/SZ3 saturates at ~2.0 (UNR result caps at
/// 0x1FFFF). Any vertex closer than H/2 = 80 units projects SHRUNKEN toward
/// the screen centre -- silently wrong screen coords for the whole 16..80
/// depth band (the black-wedge-at-your-feet / wall-vanishes-up-close bug).
/// Verts in that band get their sx/sy recomputed with a software reciprocal
/// under the SAME transform (mirrored in FIX_ROT/FIX_T at every GTE load
/// site), saturated to the GTE's +-1023 so `clamped()` routing is unchanged.
static mut FIX_ROT: Mat3I16 = Mat3I16 {
    m: [[4096, 0, 0], [0, 4096, 0], [0, 0, 4096]],
};
static mut FIX_T: [i32; 3] = [0; 3];

#[inline]
unsafe fn set_view_fix(rot: &Mat3I16, t: [i32; 3]) {
    FIX_ROT = *rot;
    FIX_T = t;
}

#[inline]
unsafe fn fix_projected_vertex(v: Vec3I16, mut p: Projected) -> Projected {
    let z = p.sz as i32;
    if z >= NEAR as i32 && z < render::projection_h() / 2 {
        let wv = [v.x as i32, v.y as i32, v.z as i32];
        let vx = dot12(FIX_ROT.m[0], wv) + FIX_T[0];
        let vy = dot12(FIX_ROT.m[1], wv) + FIX_T[1];
        let h = render::projection_h();
        let (sx, sy) = if h == render::SOFT_H && z >= render::CLOSE_LUT_Z0 {
            let inv = render::close_inv_q12(z); // exact 16..80 normal-FOV LUT band
            (
                render::OFX + ((vx * inv) >> 12),
                render::OFY + ((vy * inv) >> 12),
            )
        } else {
            // The 8..15 normal-FOV band and zoom quotient would overflow the
            // compact vx*Q12(H/z) path; vx*H/z is identical and remains i32.
            (render::OFX + vx * h / z, render::OFY + vy * h / z)
        };
        p.sx = sx.clamp(-1023, 1023) as i16;
        p.sy = sy.clamp(-1023, 1023) as i16;
    }
    p
}

#[inline(never)]
unsafe fn project_vert_fixed(m: &Map, i: usize) -> Projected {
    let v = m.vert(i);
    fix_projected_vertex(v, project_vertex_scheduled(v))
}

#[inline(never)]
unsafe fn cache_projected_vert(i: usize, frame: u16, v: Vec3I16, projected: Projected) {
    scratch_set(i, fix_projected_vertex(v, projected));
    VERT_FRAME[i] = frame as u8;
    ROOM_PROJECTED_COUNT = ROOM_PROJECTED_COUNT.saturating_add(1);
}

/// Project vertex `i` into the cache once per frame (base view matrix).
#[inline(always)]
unsafe fn proj_vert(m: &Map, i: usize, frame: u16) {
    if VERT_FRAME[i] != frame as u8 {
        let v = m.vert(i);
        cache_projected_vert(i, frame, v, project_vertex_scheduled(v));
    }
}

/// Fill the per-frame projection cache for four logical-quad corners.
///
/// Native GoldSrc patches overwhelmingly introduce three or four previously
/// unseen vertices together. RTPT projects three vertices in one GTE command
/// while producing the same SXY/SZ values as three RTPS calls. Preserve the
/// lazy cache and close-camera software correction exactly; only the GTE
/// command schedule changes.
#[inline(always)]
unsafe fn proj_quad_verts(m: &Map, indices: [usize; 4], frame: u16) {
    let mut missing = [0usize; 4];
    let mut count = 0usize;
    let mut corner = 0usize;
    while corner < 4 {
        let index = indices[corner];
        if VERT_FRAME[index] != frame as u8 {
            let mut duplicate = false;
            let mut seen = 0usize;
            while seen < count {
                if missing[seen] == index {
                    duplicate = true;
                    break;
                }
                seen += 1;
            }
            if !duplicate {
                missing[count] = index;
                count += 1;
            }
        }
        corner += 1;
    }

    if count == 0 {
        return;
    }
    let i0 = missing[0];
    let v0 = m.vert(i0);
    if count == 1 {
        cache_projected_vert(i0, frame, v0, project_vertex_scheduled(v0));
        return;
    }

    // Feed the second vertex twice for a two-corner miss. The first two RTPT
    // results remain the same as two RTPS operations, and keeping one shared
    // RTPT call avoids cloning its register schedule in the executable.
    let (i1, v1) = (missing[1], m.vert(missing[1]));
    let (i2, v2) = if count >= 3 {
        (missing[2], m.vert(missing[2]))
    } else {
        (i1, v1)
    };
    let projected = project_triangle_scheduled(v0, v1, v2);
    cache_projected_vert(i0, frame, v0, projected[0]);
    cache_projected_vert(i1, frame, v1, projected[1]);
    if count >= 3 {
        cache_projected_vert(i2, frame, v2, projected[2]);
    }
    if count == 4 {
        let i3 = missing[3];
        let v3 = m.vert(i3);
        cache_projected_vert(i3, frame, v3, project_vertex_scheduled(v3));
    }
}

unsafe fn next_proj_token() -> u16 {
    // Marks are one byte wide, so the token space is 1..=255.
    let next = PROJ_TOKEN.wrapping_add(1);
    if next == 0 || next > u8::MAX as u16 {
        for mark in VERT_FRAME.iter_mut() {
            *mark = 0;
        }
        PROJ_TOKEN = 1;
        WORLD_PROJECTION_TOKEN = 0;
    } else {
        PROJ_TOKEN = next;
    }
    PROJ_TOKEN
}

#[inline]
unsafe fn world_projection_token(
    room_id: u16,
    projection_h: u16,
    rot: &Mat3I16,
    base_t: [i32; 3],
) -> u16 {
    let key = WorldProjectionKey {
        room_id,
        projection_h,
        rot: rot.m,
        base_t,
    };
    if WORLD_PROJECTION_TOKEN != 0 && WORLD_PROJECTION_KEY == key {
        return WORLD_PROJECTION_TOKEN;
    }
    let token = next_proj_token();
    WORLD_PROJECTION_KEY = key;
    WORLD_PROJECTION_TOKEN = token;
    token
}

#[inline]
unsafe fn proj_submodel_vert(m: &Map, i: usize, token: u16) {
    if VERT_FRAME[i] != token as u8 {
        scratch_set(i, project_vert_fixed(m, i));
        VERT_FRAME[i] = token as u8;
    }
}

#[inline]
const fn uv_word(uv: (u8, u8)) -> u16 {
    (uv.0 as u16) | ((uv.1 as u16) << 8)
}

#[inline]
const fn uv_word_pair_i32(word: u16) -> (i32, i32) {
    ((word & 0xff) as i32, ((word >> 8) & 0xff) as i32)
}

#[inline]
unsafe fn cached_world_uv_words(m: &Map, tri_index: usize) -> [u16; 3] {
    m.tri_uv_words(tri_index)
}

#[inline]
unsafe fn push_tri(
    packets: &mut PrimitivePacketArena<'_>,
    np: &mut usize,
    screen: [(i16, i16); 3],
    uv: [(u8, u8); 3],
    rgb: [(u8, u8, u8); 3],
    mat: TexturedGouraudPacketMaterial,
    otz: usize,
) {
    push_tri_uv_words(
        packets,
        np,
        screen,
        [uv_word(uv[0]), uv_word(uv[1]), uv_word(uv[2])],
        rgb,
        mat,
        otz,
    );
}

/// Seam-census diagnostic: the active mechanism tint for world emission.
/// Zero keeps natural lightmap colours. Set per world-face path, cleared
/// before the entity phase; colours only, never geometry, so the uncovered
/// pinhole set is identical to a normal build.
#[cfg(feature = "seam-census")]
static mut SEAM_CENSUS_TINT: u32 = 0;
#[cfg(feature = "seam-census")]
const SEAM_CENSUS_PATCH_QUAD: u32 = pack_rgb_word((255, 0, 0));
#[cfg(feature = "seam-census")]
const SEAM_CENSUS_PATCH_TRI: u32 = pack_rgb_word((0, 255, 0));
#[cfg(feature = "seam-census")]
const SEAM_CENSUS_PATCH_FALLBACK: u32 = pack_rgb_word((255, 128, 0));
#[cfg(feature = "seam-census")]
const SEAM_CENSUS_REFINED: u32 = pack_rgb_word((255, 255, 0));
#[cfg(feature = "seam-census")]
const SEAM_CENSUS_LOOP_FACE: u32 = pack_rgb_word((0, 64, 255));
#[cfg(feature = "seam-census")]
const SEAM_CENSUS_RAW_TRI: u32 = pack_rgb_word((255, 0, 255));

#[inline]
unsafe fn push_tri_uv_words(
    packets: &mut PrimitivePacketArena<'_>,
    np: &mut usize,
    screen: [(i16, i16); 3],
    uv_words: [u16; 3],
    rgb: [(u8, u8, u8); 3],
    mat: TexturedGouraudPacketMaterial,
    otz: usize,
) {
    push_tri_uv_words_packed(
        packets,
        np,
        screen,
        uv_words,
        [
            pack_rgb_word(rgb[0]),
            pack_rgb_word(rgb[1]),
            pack_rgb_word(rgb[2]),
        ],
        mat,
        otz,
    );
}

#[inline(always)]
unsafe fn push_tri_uv_words_packed(
    packets: &mut PrimitivePacketArena<'_>,
    np: &mut usize,
    screen: [(i16, i16); 3],
    uv_words: [u16; 3],
    rgb: [u32; 3],
    mat: TexturedGouraudPacketMaterial,
    otz: usize,
) {
    #[cfg(feature = "seam-census")]
    let rgb = if SEAM_CENSUS_TINT != 0 {
        [SEAM_CENSUS_TINT; 3]
    } else {
        rgb
    };
    let prim = TriTexturedGouraud {
        tag: 0,
        tex_window: mat.tex_window_word,
        color0_cmd: mat.color0_command_word | rgb[0],
        v0: pack_vertex_word(screen[0].0, screen[0].1),
        uv0_clut: uv_words[0] as u32 | mat.clut_high_word,
        color1: rgb[1],
        v1: pack_vertex_word(screen[1].0, screen[1].1),
        uv1_tpage: uv_words[1] as u32 | mat.tpage_high_word,
        color2: rgb[2],
        v2: pack_vertex_word(screen[2].0, screen[2].1),
        uv2: uv_words[2] as u32,
    };
    let Some(packet) = packets.push(prim) else {
        note_render_packet_drop(false);
        WORLD_BAND_STATE |= WORLD_BAND_OVERFLOW;
        if TRAM_CACHE_BUILDING {
            TRAM_CACHE_OVERFLOW = true;
        }
        return;
    };
    world_cache_capture_packet(packet as *const TriTexturedGouraud, otz, false);
    tram_cache_capture_tri(packet as *const TriTexturedGouraud, otz);
    OT.add(otz, packet, TriTexturedGouraud::WORDS);
    *np += 1;
}

/// Copy one tram GT3 before OT insertion overwrites its tag.
#[inline(always)]
unsafe fn tram_cache_capture_tri(packet: *const TriTexturedGouraud, otz: usize) {
    if !TRAM_CACHE_BUILDING {
        return;
    }
    let i = TRAM_TRI_COUNT;
    if i >= MAX_TRAM_CACHE_TRIS {
        TRAM_CACHE_OVERFLOW = true;
        return;
    }
    core::ptr::copy_nonoverlapping(
        packet,
        core::ptr::addr_of_mut!(TRAM_TRI_CACHE)
            .cast::<TriTexturedGouraud>()
            .add(i),
        1,
    );
    TRAM_TRI_OTZ[i] = render::cache_otz_u16(otz);
    TRAM_TRI_COUNT = i + 1;
}

/// Copy one targeted floor GT4 and remember where it occurred in the
/// surrounding triangle stream.
#[inline(always)]
unsafe fn tram_cache_capture_quad(packet: *const QuadTexturedGouraud, otz: usize) {
    if !TRAM_CACHE_BUILDING {
        return;
    }
    let i = TRAM_QUAD_COUNT;
    if i >= MAX_TRAM_CACHE_QUADS || TRAM_TRI_COUNT > u16::MAX as usize {
        TRAM_CACHE_OVERFLOW = true;
        return;
    }
    core::ptr::copy_nonoverlapping(
        packet,
        core::ptr::addr_of_mut!(TRAM_QUAD_CACHE)
            .cast::<QuadTexturedGouraud>()
            .add(i),
        1,
    );
    TRAM_QUAD_OTZ[i] = render::cache_otz_u16(otz);
    TRAM_QUAD_AFTER_TRIS[i] = TRAM_TRI_COUNT as u16;
    TRAM_QUAD_COUNT = i + 1;
}

/// Emit triangle `t` from its three projected screen verts `p`. Fully visible
/// triangles use the cached GTE result; near straddlers use software clipping.
unsafe fn emit_projected(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tri: map::RenderTri,
    p: [Projected; 3],
    affine_level: u8,
    np: &mut usize,
) {
    let (a, b, c) = (
        tri.idx[0] as usize,
        tri.idx[1] as usize,
        tri.idx[2] as usize,
    );
    let (pa, pb, pc) = (p[0], p[1], p[2]);
    if pa.sz == 0 && pb.sz == 0 && pc.sz == 0 {
        return; // entirely behind the camera
    }
    if tri.tex >= m.n_texs || tri.tex >= MAX_TEX_SLOTS {
        return;
    }
    let slot = &*tex_slot_ptr(tri.tex);
    if !slot.valid {
        return;
    }
    let mut rgb = fog_world_rgb(
        tri.rgb,
        [pa.sz as i32, pb.sz as i32, pc.sz as i32],
        slot.backdrop,
    );
    if FLASHLIGHT_ON && !slot.backdrop {
        shade_world_rgb(&mut rgb, &p);
    }

    // View-space path (near-plane straddlers): rebuild, near-clip, emit.
    let cvv = |idx: usize, k: usize| {
        let v = scene::transform_vertex_scheduled(m.vert(idx));
        let c = unpack_rgb_word(rgb[k]);
        render::CVert {
            v: [v.x, v.y, v.z],
            rgb: (c.0 as i32, c.1 as i32, c.2 as i32),
            uv: uv_word_pair_i32(tri.uv_words[k]),
        }
    };
    let cv = [cvv(a, 0), cvv(b, 1), cvv(c, 2)];
    let guard_clamped =
        |q: &Projected| q.sx <= -1023 || q.sx >= 1023 || q.sy <= -1023 || q.sy >= 1023;
    let hit_guard = guard_clamped(&pa) || guard_clamped(&pb) || guard_clamped(&pc);
    let cache_of = |q: &Projected| {
        if q.sz as i32 >= NEAR as i32 && !guard_clamped(q) {
            Some((q.sx, q.sy))
        } else {
            None
        }
    };
    SOFT_CACHED_SCREEN = [cache_of(&pa), cache_of(&pb), cache_of(&pc)];
    SOFT_CACHED_CV = [cv[0].v, cv[1].v, cv[2].v];

    // The only fully-in-front triangles reaching this point were rejected by
    // the fast/GT4 path (most importantly because a vertex hit the GTE guard
    // clamp). Preserve the face selector here: otherwise the unclamped
    // software projection turns a selected close floor patch back into one
    // enormous affine triangle precisely at the edge of the camera.
    if pa.sz >= NEAR && pb.sz >= NEAR && pc.sz >= NEAR {
        if WORLD_AFFINE_NEAR_SUBDIVISION
            && (affine_level != 0 || hit_guard)
            && !slot.backdrop
            && EMIT_POLICY.blend() == 0
            && !EMIT_POLICY.wave()
        {
            emit_cv_split_route(
                packets,
                [&cv[0], &cv[1], &cv[2]],
                emit_packet_of(slot, tri.tex),
                slot.backdrop,
                np,
            );
        } else {
            emit_cv(
                packets,
                &cv,
                emit_packet_of(slot, tri.tex),
                slot.backdrop,
                np,
            );
        }
        return;
    }

    if WORLD_AFFINE_NEAR_SUBDIVISION
        && !slot.backdrop
        && EMIT_POLICY.blend() == 0
        && !EMIT_POLICY.wave()
    {
        emit_cv_split_route(
            packets,
            [&cv[0], &cv[1], &cv[2]],
            emit_packet_of(slot, tri.tex),
            slot.backdrop,
            np,
        );
        return;
    }

    let n = render::near_clip(&cv, &mut CLIP_CV);
    if n < 3 {
        return;
    }
    for k in 1..n - 1 {
        emit_cv(
            packets,
            &[CLIP_CV[0], CLIP_CV[k], CLIP_CV[k + 1]],
            emit_packet_of(slot, tri.tex),
            slot.backdrop,
            np,
        );
    }
}

#[inline(never)]
unsafe fn emit_screen_triangle(
    packets: &mut PrimitivePacketArena<'_>,
    p: [render::SVert; 3],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    np: &mut usize,
) {
    let (pa, pb, pc) = (p[0], p[1], p[2]);
    // The clipped parent fan triangle is culled once before subdivision. Do
    // not repeat that test on integer-rounded children: a very thin child can
    // quantize across zero area and disappear even though its parent is front.
    // Every CVert colour originates in an unpacked u8 and reaches SVert only
    // through convex Q12 interpolation or midpoint averaging. UVs already use
    // this same invariant below; avoid nine redundant release-mode clamps.
    let cl = |x: i32| {
        debug_assert!((0..=255).contains(&x));
        x as u8
    };
    // Common case: fully on-screen -> draw directly, no guard-clip buffer.
    if render::in_band(&pa) && render::in_band(&pb) && render::in_band(&pc) {
        push_tri(
            packets,
            np,
            [
                (pa.x as i16, pa.y as i16),
                (pb.x as i16, pb.y as i16),
                (pc.x as i16, pc.y as i16),
            ],
            [
                (pa.uv.0 as u8, pa.uv.1 as u8),
                (pb.uv.0 as u8, pb.uv.1 as u8),
                (pc.uv.0 as u8, pc.uv.1 as u8),
            ],
            [
                (cl(pa.rgb.0), cl(pa.rgb.1), cl(pa.rgb.2)),
                (cl(pb.rgb.0), cl(pb.rgb.1), cl(pb.rgb.2)),
                (cl(pc.rgb.0), cl(pc.rgb.1), cl(pc.rgb.2)),
            ],
            mat,
            world_order_key(
                ordering::PrimitiveDepths::tri(pa.z, pb.z, pc.z),
                texture_backdrop,
            ),
        );
        return;
    }
    // Off-screen span: guard-clip (rare). Static scratch: a stack local here
    // memset 256 B in the (inlined) caller's PROLOGUE, taxing every soft-path
    // call even when the in-band fast path returned early. Safe: emit_cv's
    // recursion happens before this point and g is consumed within the block.
    let g = &mut *core::ptr::addr_of_mut!(CLIP_SV);
    let gn = render::guard_clip(&[pa, pb, pc], 3, g);
    if gn < 3 {
        return;
    }
    for j in 1..gn - 1 {
        let (s0, s1, s2) = (g[0], g[j], g[j + 1]);
        push_tri(
            packets,
            np,
            [
                (s0.x as i16, s0.y as i16),
                (s1.x as i16, s1.y as i16),
                (s2.x as i16, s2.y as i16),
            ],
            [
                (s0.uv.0 as u8, s0.uv.1 as u8),
                (s1.uv.0 as u8, s1.uv.1 as u8),
                (s2.uv.0 as u8, s2.uv.1 as u8),
            ],
            [
                (cl(s0.rgb.0), cl(s0.rgb.1), cl(s0.rgb.2)),
                (cl(s1.rgb.0), cl(s1.rgb.1), cl(s1.rgb.2)),
                (cl(s2.rgb.0), cl(s2.rgb.1), cl(s2.rgb.2)),
            ],
            mat,
            world_order_key(
                ordering::PrimitiveDepths::tri(s0.z, s1.z, s2.z),
                texture_backdrop,
            ),
        );
    }
}

#[inline(always)]
fn affine_cv_midpoint(a: render::CVert, b: render::CVert) -> render::CVert {
    render::projected_midpoint_cv(a, b)
}

#[inline(always)]
fn affine_cv_edge_error(
    a: &render::CVert,
    pa: &render::SVert,
    b: &render::CVert,
    pb: &render::SVert,
) -> (u32, u32) {
    let screen_span = (pa.x - pb.x).abs().max((pa.y - pb.y).abs());
    if screen_span < WORLD_AFFINE_MIN_EDGE_PIXELS {
        return (0, 1);
    }
    let uv_span = (a.uv.0 - b.uv.0).abs().max((a.uv.1 - b.uv.1).abs()) as u32;
    (
        uv_span.saturating_mul((a.v[2] - b.v[2]).unsigned_abs()),
        2u32.saturating_mul((a.v[2] + b.v[2]).max(1) as u32),
    )
}

#[cold]
#[inline(never)]
#[link_section = ".hlpsx_cold.affine"]
unsafe fn emit_cv_subdivided(
    packets: &mut PrimitivePacketArena<'_>,
    cv: [render::CVert; 3],
    projected: [render::SVert; 3],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    depth: u8,
    np: &mut usize,
) {
    let edges = [(0usize, 1usize), (1, 2), (2, 0)];
    let mut still_warped = false;
    let mut i = 0usize;
    while i < edges.len() {
        let (a, b) = edges[i];
        let (num, den) = affine_cv_edge_error(&cv[a], &projected[a], &cv[b], &projected[b]);
        #[cfg(feature = "performance-telemetry")]
        if depth == 0 && affine_heatmap_active() {
            affine_record_error(num, den);
        }
        let threshold = if depth == 0 {
            WORLD_AFFINE_NEAR_ENTER_ERROR_TEXELS
        } else {
            WORLD_AFFINE_LEAVE_ERROR_TEXELS as u32
        };
        if num > den.saturating_mul(threshold) {
            still_warped = true;
        }
        i += 1;
    }
    if WORLD_AFFINE_NEAR_SUBDIVISION
        && !texture_backdrop
        && EMIT_POLICY.blend() == 0
        && !EMIT_POLICY.wave()
        && still_warped
        && depth < WORLD_AFFINE_NEAR_MAX_DEPTH
    {
        let cost = 3u16;
        WORLD_AFFINE_SPLIT_CANDIDATES = WORLD_AFFINE_SPLIT_CANDIDATES.saturating_add(1);
        WORLD_AFFINE_EXTRA_REQUESTED = WORLD_AFFINE_EXTRA_REQUESTED.saturating_add(cost as u32);
        if WORLD_AFFINE_EXTRA_BUDGET_LEFT >= cost
            && packets.remaining() >= WORLD_AFFINE_PACKET_RESERVE + cost as usize + 1
        {
            WORLD_AFFINE_EXTRA_BUDGET_LEFT -= cost;
            WORLD_AFFINE_LEVEL2_SPLITS = WORLD_AFFINE_LEVEL2_SPLITS.saturating_add(1);
            let ab = affine_cv_midpoint(cv[0], cv[1]);
            let bc = affine_cv_midpoint(cv[1], cv[2]);
            let ca = affine_cv_midpoint(cv[2], cv[0]);
            let pab = render::project_soft(&ab);
            let pbc = render::project_soft(&bc);
            let pca = render::project_soft(&ca);
            emit_cv_subdivided(
                packets,
                [cv[0], ab, ca],
                [projected[0], pab, pca],
                mat,
                false,
                depth + 1,
                np,
            );
            emit_cv_subdivided(
                packets,
                [ab, cv[1], bc],
                [pab, projected[1], pbc],
                mat,
                false,
                depth + 1,
                np,
            );
            emit_cv_subdivided(
                packets,
                [ca, bc, cv[2]],
                [pca, pbc, projected[2]],
                mat,
                false,
                depth + 1,
                np,
            );
            emit_cv_subdivided(
                packets,
                [ab, bc, ca],
                [pab, pbc, pca],
                mat,
                false,
                depth + 1,
                np,
            );
            return;
        }
    }
    #[cfg(feature = "performance-telemetry")]
    if affine_heatmap_active() || EMIT_POLICY.tram_grid() {
        i = 0;
        while i < edges.len() {
            let (a, b) = edges[i];
            let (num, den) = affine_cv_edge_error(&cv[a], &projected[a], &cv[b], &projected[b]);
            affine_record_remaining_error(num, den);
            i += 1;
        }
    }
    #[cfg(feature = "performance-telemetry")]
    if affine_heatmap_active() {
        let p = [
            Projected {
                sx: projected[0].x as i16,
                sy: projected[0].y as i16,
                sz: projected[0].z.clamp(0, u16::MAX as i32) as u16,
            },
            Projected {
                sx: projected[1].x as i16,
                sy: projected[1].y as i16,
                sz: projected[1].z.clamp(0, u16::MAX as i32) as u16,
            },
            Projected {
                sx: projected[2].x as i16,
                sy: projected[2].y as i16,
                sz: projected[2].z.clamp(0, u16::MAX as i32) as u16,
            },
        ];
        push_affine_heatmap_tri(
            packets,
            [&p[0], &p[1], &p[2]],
            [
                uv_word((cv[0].uv.0 as u8, cv[0].uv.1 as u8)),
                uv_word((cv[1].uv.0 as u8, cv[1].uv.1 as u8)),
                uv_word((cv[2].uv.0 as u8, cv[2].uv.1 as u8)),
            ],
            world_order_key(
                ordering::PrimitiveDepths::tri(projected[0].z, projected[1].z, projected[2].z),
                texture_backdrop,
            ),
            np,
        );
        return;
    }
    emit_screen_triangle(packets, projected, mat, texture_backdrop, np);
}

unsafe fn emit_cv(
    packets: &mut PrimitivePacketArena<'_>,
    cv: &[render::CVert; 3],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    np: &mut usize,
) {
    let projected = [
        render::project_soft(&cv[0]),
        render::project_soft(&cv[1]),
        render::project_soft(&cv[2]),
    ];
    if CULL
        && culled_soft(
            (projected[0].x, projected[0].y),
            (projected[1].x, projected[1].y),
            (projected[2].x, projected[2].y),
        )
    {
        return;
    }
    emit_screen_triangle(packets, projected, mat, texture_backdrop, np);
}

/// A cooked quad whose projection crosses the near plane or leaves the GPU
/// guard band cannot be one GT4. The old fallback threw the quad away and
/// pushed its two source triangles into the recursive view-space splitter,
/// which fanned one surface into up to sixteen triangles per triangle and
/// stopped whenever the shared packet budget ran out -- so a close floor or
/// wall visibly re-tessellated as the camera moved, with a diagonal fan
/// crawling across it.
///
/// Preserve the quad parameterisation through an adaptive cell tree, then
/// clip terminal triangles. The geometric span, depth ceiling, and packet
/// reserve bound refinement. `fixed_grid` selects the dedicated tram lattice.
/// Returns false when the caller should keep its own two-triangle fallback.
// Hot-section since the perspective-split reroute: tunnel floors take this
// path every ride frame, so the old cold placement thrashed the 4 KiB icache.
// Size-optimized: this is the per-quad SETUP (14 calls/frame); the recursion
// and leaves below stay at full speed.
#[inline(never)]
#[optimize(size)]
unsafe fn emit_soft_quad_split(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tex: usize,
    corners: [map::PackedLoopVert; 4],
    frame: u16,
    np: &mut usize,
    fixed_grid: bool,
    target_span: i32,
) -> bool {
    let slot = &*tex_slot_ptr(tex);
    // Backdrop/liquid/blended surfaces keep the proven path: sky must not be
    // fogged or split, and swaying UVs are generated per source vertex.
    if !slot.valid || slot.backdrop || EMIT_POLICY.blend() != 0 || EMIT_POLICY.wave() {
        return false;
    }
    // Require initial headroom; the recursive tree repeats its reserve check
    // before every subdivision. Preserve the actor/effect packet reserve.
    if packets.remaining() < WORLD_AFFINE_PACKET_RESERVE + 16 {
        return false;
    }
    // Quad order matches the GT4 the fast path would have emitted: (b, a, c, d)
    // is (q00, q10, q01, q11), the same parameterisation `affine_quad_children`
    // splits, so a refined child here tiles exactly like a refined child there.
    let order = [1usize, 0, 2, 3];
    let idx = [
        corners[order[0]].idx as usize,
        corners[order[1]].idx as usize,
        corners[order[2]].idx as usize,
        corners[order[3]].idx as usize,
    ];
    proj_quad_verts(m, idx, frame);
    let p = [
        scratch_get(idx[0]),
        scratch_get(idx[1]),
        scratch_get(idx[2]),
        scratch_get(idx[3]),
    ];
    let mut words = [
        fog_rgb_word_no_flash(corners[order[0]].rgb, p[0].sz as i32),
        fog_rgb_word_no_flash(corners[order[1]].rgb, p[1].sz as i32),
        fog_rgb_word_no_flash(corners[order[2]].rgb, p[2].sz as i32),
        fog_rgb_word_no_flash(corners[order[3]].rgb, p[3].sz as i32),
    ];
    if FLASHLIGHT_ON {
        shade_world_rgb(&mut words, &p);
    }
    if fixed_grid {
        let vertex = |k: usize| AffineVertex {
            position: m.vert(idx[k]),
            projected: p[k],
            uv: corners[order[k]].uv,
            rgb: words[k],
        };
        let q = [vertex(0), vertex(1), vertex(2), vertex(3)];
        emit_affine_quad_children(packets, q, emit_packet_of(slot, tex), np);
        return true;
    }
    let corner_cv = |k: usize| -> render::CVert {
        let v = scene::transform_vertex_scheduled(m.vert(idx[k]));
        let c = unpack_rgb_word(words[k]);
        render::CVert {
            v: [v.x, v.y, v.z],
            rgb: (c.0 as i32, c.1 as i32, c.2 as i32),
            uv: uv_word_pair_i32(corners[order[k]].uv),
        }
    };
    let q = [corner_cv(0), corner_cv(1), corner_cv(2), corner_cv(3)];
    // Sum-then-halve, so an edge shared with a neighbouring patch generates the
    // identical midpoint whichever side visits it first.
    let mid = |a: &render::CVert, b: &render::CVert| render::CVert {
        v: [
            (a.v[0] + b.v[0]) / 2,
            (a.v[1] + b.v[1]) / 2,
            (a.v[2] + b.v[2]) / 2,
        ],
        rgb: (
            (a.rgb.0 + b.rgb.0) / 2,
            (a.rgb.1 + b.rgb.1) / 2,
            (a.rgb.2 + b.rgb.2) / 2,
        ),
        uv: ((a.uv.0 + b.uv.0) / 2, (a.uv.1 + b.uv.1) / 2),
    };
    let _ = mid;
    let mat = emit_packet_of(slot, tex);
    // Screen-space LOD tree over the quad: leaves approach a uniform on-screen
    // cell size, so the level count rises directly with proximity.
    emit_soft_cell(
        packets,
        [&q[0], &q[1], &q[2], &q[3]],
        mat,
        0,
        np,
        target_span,
    );
    // Crack backstop: neighbouring cells at different levels leave
    // T-junctions whose rounding pinholes otherwise expose the clear colour.
    // Re-emit the whole quad behind its own refinement -- its conservative
    // far-depth key orders it earlier than every nearer child, and within an
    // equal bucket the LAST insert draws FIRST (OT insertion prepends).
    emit_cv_flat(packets, [&q[0], &q[1], &q[2]], mat, np);
    emit_cv_flat(packets, [&q[1], &q[3], &q[2]], mat, np);
    true
}

/// Midpoint of a soft-cell edge. Sum-then-halve, so a shared edge produces
/// the identical vertex whichever neighbouring cell computes it.
#[inline(always)]
fn soft_cell_mid(a: &render::CVert, b: &render::CVert) -> render::CVert {
    render::CVert {
        v: [
            (a.v[0] + b.v[0]) / 2,
            (a.v[1] + b.v[1]) / 2,
            (a.v[2] + b.v[2]) / 2,
        ],
        rgb: (
            (a.rgb.0 + b.rgb.0) / 2,
            (a.rgb.1 + b.rgb.1) / 2,
            (a.rgb.2 + b.rgb.2) / 2,
        ),
        uv: ((a.uv.0 + b.uv.0) / 2, (a.uv.1 + b.uv.1) / 2),
    }
}

/// One cell of the near-quad refinement tree: screen-space LOD. A cell
/// splits while an axis still projects wider than the target pixel span, so
/// the leaf mesh approaches uniform screen-size cells and the level count
/// rises directly with proximity. Skewed cells split their LONG axis only:
/// a duct wall seen down its length halves into two long cells instead of
/// fanning into ever-thinner slivers (the black-streak coverage cracks).
#[inline(never)]
unsafe fn emit_soft_cell(
    packets: &mut PrimitivePacketArena<'_>,
    c: [&render::CVert; 4],
    mat: TexturedGouraudPacketMaterial,
    depth: usize,
    np: &mut usize,
    target_span: i32,
) {
    // Prune whole subtrees the clipper would otherwise discard leaf by leaf:
    // a near-plane-crossing quad recursed into every child regardless of
    // visibility, and with most of the underfoot quad behind the camera that
    // was thousands of wasted midpoint/recursion nodes per frame -- the
    // measured 3 fps route collapse. All-out on ONE half-space is an exact
    // cull; the 45-degree lateral planes are conservative for the real FOV.
    // Near uses the clip plane itself (a cell wholly closer than NEAR_Z is
    // clipped to nothing anyway); vertical uses the exact display planes --
    // both prune strictly more than the old conservative forms while staying
    // pixel-identical.
    let nz = render::NEAR_Z;
    if c.iter().all(|v| v.v[2] < nz)
        || c.iter().all(|v| v.v[0] > v.v[2])
        || c.iter().all(|v| -v.v[0] > v.v[2])
        || render::quad_outside_vertical(&c)
    {
        return;
    }
    // At maximum depth the span cannot affect tessellation. Keep the same
    // clipped leaves without computing edge lengths and projected LOD first.
    if depth >= SOFT_SPLIT_MAX_DEPTH {
        emit_soft_leaf(packets, c, mat, np);
        return;
    }
    let cheb = |a: &render::CVert, b: &render::CVert| -> i32 {
        (a.v[0] - b.v[0])
            .abs()
            .max((a.v[1] - b.v[1]).abs())
            .max((a.v[2] - b.v[2]).abs())
    };
    // World extent of each parameter axis (the longer of its two edges, so a
    // trapezoid cannot under-report).
    let du = cheb(c[0], c[1]).max(cheb(c[2], c[3]));
    let dv = cheb(c[0], c[2]).max(cheb(c[1], c[3]));
    // NB: the span floor stays at the renderer NEAR (not NEAR_Z) -- raising it
    // would coarsen split decisions for cells partly inside 8 units and change
    // the emitted tessellation.
    let near_z = c[0].v[2]
        .min(c[1].v[2])
        .min(c[2].v[2])
        .min(c[3].v[2])
        .max(NEAR as i32);
    // span_px ~ extent * H / z. An axis is oversize while it would project
    // wider than SOFT_SPLIT_TARGET_SPAN_PX at the cell's nearest depth.
    let over = |extent: i32| -> bool {
        extent.saturating_mul(render::SOFT_H) > near_z.saturating_mul(target_span)
    };
    let split_u = over(du);
    let split_v = over(dv);

    if (split_u || split_v) && packets.remaining() >= WORLD_AFFINE_PACKET_RESERVE + 16 {
        // Anisotropic: when one axis is oversize (or twice the other), halve
        // it alone. Only near-square oversize cells pay the full 2x2.
        if split_u && (!split_v || du >= dv.saturating_mul(2)) {
            let top = soft_cell_mid(c[0], c[1]);
            let bottom = soft_cell_mid(c[2], c[3]);
            emit_soft_cell(
                packets,
                [c[0], &top, c[2], &bottom],
                mat,
                depth + 1,
                np,
                target_span,
            );
            emit_soft_cell(
                packets,
                [&top, c[1], &bottom, c[3]],
                mat,
                depth + 1,
                np,
                target_span,
            );
            return;
        }
        if split_v && (!split_u || dv >= du.saturating_mul(2)) {
            let left = soft_cell_mid(c[0], c[2]);
            let right = soft_cell_mid(c[1], c[3]);
            emit_soft_cell(
                packets,
                [c[0], c[1], &left, &right],
                mat,
                depth + 1,
                np,
                target_span,
            );
            emit_soft_cell(
                packets,
                [&left, &right, c[2], c[3]],
                mat,
                depth + 1,
                np,
                target_span,
            );
            return;
        }
        let top = soft_cell_mid(c[0], c[1]);
        let left = soft_cell_mid(c[0], c[2]);
        let right = soft_cell_mid(c[1], c[3]);
        let bottom = soft_cell_mid(c[2], c[3]);
        let center = soft_cell_mid(&top, &bottom);
        emit_soft_cell(
            packets,
            [c[0], &top, &left, &center],
            mat,
            depth + 1,
            np,
            target_span,
        );
        emit_soft_cell(
            packets,
            [&top, c[1], &center, &right],
            mat,
            depth + 1,
            np,
            target_span,
        );
        emit_soft_cell(
            packets,
            [&left, &center, c[2], &bottom],
            mat,
            depth + 1,
            np,
            target_span,
        );
        emit_soft_cell(
            packets,
            [&center, &right, &bottom, c[3]],
            mat,
            depth + 1,
            np,
            target_span,
        );
        return;
    }
    // The two hardware triangles of a GT4 (v0,v1,v2) and (v1,v3,v2).
    emit_soft_leaf(packets, c, mat, np);
}

/// Project the four unique corners once while retaining the two independent
/// triangles and their original ordering keys. Clipped/cached-corner cases
/// still use the original per-triangle path.
#[inline(never)]
unsafe fn emit_soft_leaf(
    packets: &mut PrimitivePacketArena<'_>,
    c: [&render::CVert; 4],
    mat: TexturedGouraudPacketMaterial,
    np: &mut usize,
) {
    if SOFT_CACHED_SCREEN.iter().all(Option::is_none) && c.iter().all(|v| v.v[2] >= render::NEAR_Z)
    {
        let p = [
            render::project_soft(c[0]),
            render::project_soft(c[1]),
            render::project_soft(c[2]),
            render::project_soft(c[3]),
        ];
        if p.iter().all(render::in_band) {
            let before = *np;
            for t in [[0usize, 1, 2], [1, 3, 2]] {
                let (a, b, c) = (p[t[0]], p[t[1]], p[t[2]]);
                let cr = (b.x - a.x) as i64 * (c.y - a.y) as i64
                    - (c.x - a.x) as i64 * (b.y - a.y) as i64;
                if !CULL || cr < 0 {
                    emit_screen_triangle(packets, [a, b, c], mat, false, np);
                }
            }
            WORLD_AFFINE_SPLIT_TRIS =
                WORLD_AFFINE_SPLIT_TRIS.saturating_add(np.saturating_sub(before) as u32);
            return;
        }
    }
    emit_cv_flat(packets, [c[0], c[1], c[2]], mat, np);
    emit_cv_flat(packets, [c[1], c[3], c[2]], mat, np);
}

/// Clip to the visible frustum before subdivision. This is the key close-floor
/// fix: the previous uniform splits spent most children hundreds of pixels
/// outside the display, leaving one enormous near child in the actual image.
/// Hot clone of the subdividing soft route: the cold-section legacy path
/// was correct when near-clip fans were rare, but the perspective-split
/// reroute made this the tunnel walls' every-frame path.
#[inline(never)]
unsafe fn emit_cv_split_route(
    packets: &mut PrimitivePacketArena<'_>,
    cv: [&render::CVert; 3],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    np: &mut usize,
) {
    // Near-clip only, in view space (unavoidable), then push the fan
    // through the SAME screen-space splitter every fast-path triangle
    // uses. No screen-plane clipping means no synthesized boundary
    // vertices: both sides of a shared edge rasterize the identical
    // straight cached-GTE segment, which closes the diagonal cracks the
    // old view-space screen clip opened (its re-projected cut vertices
    // landed off the true edge line). The splitter bounds primitive
    // sizes for the GPU and perspective-corrects the interiors.
    let cached_scr = SOFT_CACHED_SCREEN;
    let cached_cv = SOFT_CACHED_CV;
    SOFT_CACHED_SCREEN = [None; 3];
    let nc = render::near_clip(&[*cv[0], *cv[1], *cv[2]], &mut CLIP_CV);
    if nc < 3 {
        return;
    }
    let mut proj: [render::SVert; 4] = [render::SVert {
        x: 0,
        y: 0,
        z: 0,
        rgb: (0, 0, 0),
        uv: (0, 0),
    }; 4];
    let mut i = 0usize;
    while i < nc {
        proj[i] = render::project_soft(&CLIP_CV[i]);
        let mut q = 0usize;
        while q < 3 {
            if let Some((sx, sy)) = cached_scr[q] {
                // Component compares: `[i32; 3] ==` lowers to a memcmp call
                // (measured ~34k cycles/frame across the two scan sites).
                let (a, b) = (&CLIP_CV[i].v, &cached_cv[q]);
                if a[0] == b[0] && a[1] == b[1] && a[2] == b[2] {
                    proj[i].x = sx as i32;
                    proj[i].y = sy as i32;
                }
            }
            q += 1;
        }
        i += 1;
    }
    if CULL
        && culled_soft(
            (proj[0].x, proj[0].y),
            (proj[1].x, proj[1].y),
            (proj[2].x, proj[2].y),
        )
    {
        return;
    }
    let cl255 = |v: i32| v.clamp(0, 255) as u32;
    let mut k = 1usize;
    while k + 1 < nc {
        let tri = [0usize, k, k + 1];
        {
            // Fan triangle wholly outside the 320x240 draw area: skip the
            // conversion and splitter work entirely (pixel-identical; the
            // splitter would prune it anyway).
            let (a, b, c) = (&proj[0], &proj[k], &proj[k + 1]);
            if (a.x < 0 && b.x < 0 && c.x < 0)
                || (a.x >= 320 && b.x >= 320 && c.x >= 320)
                || (a.y < 0 && b.y < 0 && c.y < 0)
                || (a.y >= 240 && b.y >= 240 && c.y >= 240)
            {
                k += 1;
                continue;
            }
        }
        // A fan triangle whose projection leaves the guard band must not be
        // clamped: clamping folds its far vertices onto one corner, the
        // triangle collapses to a line and the screen it should have covered
        // stays black (the tram ride's black wedges: a grazing wall beside
        // the camera whose near-plane points project to (4580, 4740) and
        // both clamp to (1023, 1023)). Clip it to the display frustum in
        // view space instead, which is exact and bounded.
        {
            let over =
                |q: &render::SVert| q.x <= -1023 || q.x >= 1023 || q.y <= -1023 || q.y >= 1023;
            if over(&proj[tri[0]]) || over(&proj[tri[1]]) || over(&proj[tri[2]]) {
                let (v0, v1, v2) = (CLIP_CV[tri[0]], CLIP_CV[tri[1]], CLIP_CV[tri[2]]);
                SOFT_CACHED_SCREEN = [None; 3];
                emit_cv_clipped(
                    packets,
                    [&v0, &v1, &v2],
                    mat,
                    texture_backdrop,
                    np,
                    ClipRefinement::Guard,
                );
                k += 1;
                continue;
            }
        }
        let mut screen = [(0i16, 0i16); 3];
        let mut uvw = [0u16; 3];
        let mut rgbw = [0u32; 3];
        let mut szs = [0i32; 3];
        let mut j = 0usize;
        while j < 3 {
            let pv = &proj[tri[j]];
            screen[j] = (
                pv.x.clamp(-1023, 1023) as i16,
                pv.y.clamp(-1023, 1023) as i16,
            );
            uvw[j] = (pv.uv.0.clamp(0, 255) as u16) | ((pv.uv.1.clamp(0, 255) as u16) << 8);
            rgbw[j] = cl255(pv.rgb.0) | (cl255(pv.rgb.1) << 8) | (cl255(pv.rgb.2) << 16);
            szs[j] = pv.z.max(1);
            j += 1;
        }
        // Most fan triangles need no split: push directly with the same
        // ordering key the splitter leaf would compute, skipping the call
        // and its re-evaluation (identical output by construction).
        let span = |a: usize, b: usize| -> i32 {
            let dx = (screen[a].0 as i32 - screen[b].0 as i32).abs();
            let dy = (screen[a].1 as i32 - screen[b].1 as i32).abs();
            dx.max(dy)
        };
        let esplit = |sp: i32, za: i32, zb: i32| -> bool {
            if sp > 250 {
                return true;
            }
            if sp <= 96 {
                return false;
            }
            let (zmin, zmax) = if za < zb { (za, zb) } else { (zb, za) };
            zmax > zmin * 2
        };
        if !esplit(span(0, 1), szs[0], szs[1])
            && !esplit(span(1, 2), szs[1], szs[2])
            && !esplit(span(2, 0), szs[2], szs[0])
        {
            let otz = world_order_key(
                ordering::PrimitiveDepths::tri(szs[0], szs[1], szs[2]),
                texture_backdrop,
            );
            push_tri_uv_words_packed(packets, np, screen, uvw, rgbw, mat, otz);
            k += 1;
            continue;
        }
        push_tri_gpu_split(
            packets,
            np,
            screen,
            uvw,
            rgbw,
            szs,
            texture_backdrop,
            mat,
            0,
        );
        k += 1;
    }
}

#[cold]
#[inline(never)]
#[link_section = ".hlpsx_cold.affine"]
unsafe fn emit_cv_near(
    packets: &mut PrimitivePacketArena<'_>,
    cv: &[render::CVert; 3],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    np: &mut usize,
) {
    emit_cv_clipped(
        packets,
        [&cv[0], &cv[1], &cv[2]],
        mat,
        texture_backdrop,
        np,
        ClipRefinement::Adaptive,
    )
}

/// As `emit_cv_near`, but the caller has already fixed the topology, so a
/// clipped child must not decide to become four more children.
unsafe fn emit_cv_flat(
    packets: &mut PrimitivePacketArena<'_>,
    cv: [&render::CVert; 3],
    mat: TexturedGouraudPacketMaterial,
    np: &mut usize,
) {
    // Terminal leaves need no display clipping: the GPU scissors raster to
    // the draw area (the standard guard-band technique; scissored pixels are
    // free in the emulator's area-clipped pixel-cost model too). The display
    // clip only ever existed to stop SUBDIVISION wasting children off-screen;
    // a leaf that stays in front of the near plane and inside the guard band
    // pushes the identical projected triangle the clipped path would fan.
    if SOFT_CACHED_SCREEN.iter().all(Option::is_none)
        && cv[0].v[2] >= render::NEAR_Z
        && cv[1].v[2] >= render::NEAR_Z
        && cv[2].v[2] >= render::NEAR_Z
    {
        let p = [
            render::project_soft(cv[0]),
            render::project_soft(cv[1]),
            render::project_soft(cv[2]),
        ];
        if render::in_band(&p[0]) && render::in_band(&p[1]) && render::in_band(&p[2]) {
            if CULL {
                let cr = (p[1].x - p[0].x) as i64 * (p[2].y - p[0].y) as i64
                    - (p[2].x - p[0].x) as i64 * (p[1].y - p[0].y) as i64;
                if cr >= 0 {
                    return; // same verdict the clipped path's fan cull reaches
                }
            }
            let before = *np;
            emit_screen_triangle(packets, p, mat, false, np);
            WORLD_AFFINE_SPLIT_TRIS =
                WORLD_AFFINE_SPLIT_TRIS.saturating_add(np.saturating_sub(before) as u32);
            return;
        }
    }
    emit_cv_clipped(packets, cv, mat, false, np, ClipRefinement::Flat)
}

/// Guard fallback may correct its newly exposed fan; fixed tree leaves and
/// crack backstops must remain flat to keep their existing topology bound.
#[derive(Clone, Copy)]
enum ClipRefinement {
    Flat,
    Adaptive,
    Guard,
}

#[inline(never)]
unsafe fn emit_cv_clipped(
    packets: &mut PrimitivePacketArena<'_>,
    cv: [&render::CVert; 3],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    np: &mut usize,
    refinement: ClipRefinement,
) {
    if matches!(refinement, ClipRefinement::Adaptive) {
        emit_cv_split_route(packets, cv, mat, texture_backdrop, np);
        return;
    }
    let (clipped, n) = render::visible_clip(cv);
    let cached_scr = SOFT_CACHED_SCREEN;
    let cached_cv = SOFT_CACHED_CV;
    SOFT_CACHED_SCREEN = [None; 3];
    if n < 3 {
        return;
    }
    let before = *np;
    for k in 1..n - 1 {
        let v0 = *clipped;
        let v1 = *clipped.add(k);
        let v2 = *clipped.add(k + 1);
        let tri = [
            render::CVert {
                v: [v0.x, v0.y, v0.z],
                rgb: v0.rgb,
                uv: v0.uv,
            },
            render::CVert {
                v: [v1.x, v1.y, v1.z],
                rgb: v1.rgb,
                uv: v1.uv,
            },
            render::CVert {
                v: [v2.x, v2.y, v2.z],
                rgb: v2.rgb,
                uv: v2.uv,
            },
        ];
        let mut projected = [
            render::project_soft(&tri[0]),
            render::project_soft(&tri[1]),
            render::project_soft(&tri[2]),
        ];
        // Pre-substitution copies feed the winding verdict below: the verdict
        // historically re-projected these exact vertices, so reusing them is
        // bit-identical while saving three software divides per polygon.
        let raw = projected;
        {
            // One vertex, one projection: original corners surviving the clip
            // reuse the exact GTE screen coordinate the fast path pushes.
            let mut j = 0usize;
            while j < 3 {
                let mut q = 0usize;
                while q < 3 {
                    if let Some((sx, sy)) = cached_scr[q] {
                        let (a, b) = (&tri[j].v, &cached_cv[q]);
                        if a[0] == b[0] && a[1] == b[1] && a[2] == b[2] {
                            projected[j].x = sx as i32;
                            projected[j].y = sy as i32;
                        }
                    }
                    q += 1;
                }
                j += 1;
            }
        }
        if k == 1 && CULL {
            // Winding verdict for the whole convex fan -- but a clipped
            // polygon often starts with three near-collinear vertices along
            // the clip boundary. cross == 0 there says nothing about facing;
            // treating it as back-facing abandoned the entire polygon (large
            // grazing floor fans vanished as hard-edged black holes). Walk
            // forward to the first fan triangle with real signed area and let
            // THAT decide.
            let mut verdict = 0i64;
            let mut kk = 1usize;
            while kk < n - 1 {
                let (q0, q1, q2) = if kk == 1 {
                    (raw[0], raw[1], raw[2])
                } else {
                    let (v0, v1, v2) = (*clipped, *clipped.add(kk), *clipped.add(kk + 1));
                    (
                        render::project_soft(&render::CVert {
                            v: [v0.x, v0.y, v0.z],
                            rgb: v0.rgb,
                            uv: v0.uv,
                        }),
                        render::project_soft(&render::CVert {
                            v: [v1.x, v1.y, v1.z],
                            rgb: v1.rgb,
                            uv: v1.uv,
                        }),
                        render::project_soft(&render::CVert {
                            v: [v2.x, v2.y, v2.z],
                            rgb: v2.rgb,
                            uv: v2.uv,
                        }),
                    )
                };
                let cr = (q1.x - q0.x) as i64 * (q2.y - q0.y) as i64
                    - (q2.x - q0.x) as i64 * (q1.y - q0.y) as i64;
                if cr != 0 {
                    verdict = cr;
                    break;
                }
                kk += 1;
            }
            if verdict >= 0 {
                return; // back-facing (or fully degenerate: nothing to draw)
            }
        }
        if matches!(refinement, ClipRefinement::Guard)
            && try_emit_clipped_residue(packets, projected, mat, texture_backdrop, np)
        {
            continue;
        }
        emit_screen_triangle(packets, projected, mat, texture_backdrop, np);
    }
    let emitted = np.saturating_sub(before) as u32;
    WORLD_AFFINE_ACTUAL_EXTRA_EMITTED = WORLD_AFFINE_ACTUAL_EXTRA_EMITTED
        .saturating_add(emitted.saturating_sub(1).min(u16::MAX as u32) as u16);
    WORLD_AFFINE_SPLIT_TRIS = WORLD_AFFINE_SPLIT_TRIS.saturating_add(emitted);
    WORLD_AFFINE_EXTRA_EMITTED =
        WORLD_AFFINE_EXTRA_EMITTED.saturating_add(emitted.saturating_sub(1));
}

#[cold]
#[inline(never)]
unsafe fn emit_near_clipped_fan(
    packets: &mut PrimitivePacketArena<'_>,
    cv: &[render::CVert; 3],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    np: &mut usize,
) {
    emit_cv_near(packets, cv, mat, texture_backdrop, np);
}

unsafe fn try_emit_tri_pair_quad_values(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    t0: map::RenderTri,
    t1: map::RenderTri,
    frame: u16,
    affine_previous_level: u8,
    np: &mut usize,
    nq: &mut usize,
) -> bool {
    if t0.tex >= m.n_texs || t0.tex >= MAX_TEX_SLOTS {
        return false;
    }
    let Some(corners) = map::tri_pair_quad_corners(t0, t1) else {
        return false;
    };
    try_emit_quad_corners(
        packets,
        m,
        t0.tex,
        corners,
        frame,
        affine_previous_level,
        false,
        0,
        usize::MAX,
        np,
        nq,
    )
}

/// Quad-pair core on pre-decoded corners (a=shared fan base, b/c = the shared
/// diagonal pair's outer verts, d = the second tri's new vert). The world loop
/// walker feeds this directly so each loop vertex is decoded exactly once.
#[inline(never)]
unsafe fn try_emit_quad_corners(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tex: usize,
    corners: [map::PackedLoopVert; 4],
    frame: u16,
    affine_previous_level: u8,
    native_patch: bool,
    blocked_edges: u8,
    patch_state: usize,
    np: &mut usize,
    nq: &mut usize,
) -> bool {
    if tex >= m.n_texs || tex >= MAX_TEX_SLOTS {
        return false;
    }
    let (a, b, c, d) = (
        corners[0].idx as usize,
        corners[1].idx as usize,
        corners[2].idx as usize,
        corners[3].idx as usize,
    );
    let slot = &*tex_slot_ptr(tex);
    if !slot.valid {
        return true;
    }
    proj_quad_verts(m, [a, b, c, d], frame);
    let (pa, pb, pc, pd) = (
        scratch_get(a),
        scratch_get(b),
        scratch_get(c),
        scratch_get(d),
    );
    // `np` is consumed by telemetry and generic-triangle configurations. The
    // shipping native-patch path emits only GT4s, but keeping one signature
    // avoids duplicating this hot dispatch function.
    let _ = np;
    let clamped = |q: &Projected| q.sx <= -1023 || q.sx >= 1023 || q.sy <= -1023 || q.sy >= 1023;
    if pa.sz < NEAR
        || pb.sz < NEAR
        || pc.sz < NEAR
        || pd.sz < NEAR
        || clamped(&pa)
        || clamped(&pb)
        || clamped(&pc)
        || clamped(&pd)
    {
        // Tell the caller WHY. A cooked quad rejected here is geometrically
        // fine, it just needs clipping, so the native-patch walker can keep
        // the four corners and split the quad instead of surrendering to the
        // triangle fan. Every other rejection below is a real unsuitability
        // (bow-tie, depth-span) that splitting would not fix.
        WORLD_QUAD_NEEDS_SOFT_SPLIT = true;
        return false;
    }
    // GPU-oversized quads: signal the native-patch walker to SPLIT the cell
    // (keeping shared edges inside the patch machinery) rather than mixing
    // grid cells with the whole-face fallback fan, whose different tiling
    // opened dashed cracks along the boundary. The soft path now funnels
    // into the screen-space splitter, so the split route is cache-safe.
    // A shared fixed-box proof avoids exact per-triangle extrema for the
    // common case. Outliers retain both original tests and split decisions.
    let extent_code = psx_engine::projection::gpu_extent_box_code([pa.sx, pa.sy])
        | psx_engine::projection::gpu_extent_box_code([pb.sx, pb.sy])
        | psx_engine::projection::gpu_extent_box_code([pc.sx, pc.sy])
        | psx_engine::projection::gpu_extent_box_code([pd.sx, pd.sy]);
    if extent_code != 0
        && !render::quad_fits_gpu_xy(
            pack_vertex_word(pa.sx, pa.sy),
            pack_vertex_word(pb.sx, pb.sy),
            pack_vertex_word(pc.sx, pc.sy),
            pack_vertex_word(pd.sx, pd.sy),
        )
    {
        WORLD_QUAD_NEEDS_SOFT_SPLIT = true;
        return false;
    }
    // A GT4 has one OT link for both hardware triangles. For an explicitly
    // tagged refined cell, compare the keys the children would receive on
    // their own and split back to GT3s when one shared key would hide a real
    // depth transition. Four buckets = sixteen world units at OT_SHIFT=2;
    // larger spans can visibly interleave with nearby pipes, rails, and walls.
    let local_pair_otz = if EMIT_POLICY.local_depth() || EMIT_POLICY.cutout() {
        let first = world_order_key(
            ordering::PrimitiveDepths::tri(pb.sz as i32, pa.sz as i32, pc.sz as i32),
            slot.backdrop,
        );
        let second = world_order_key(
            ordering::PrimitiveDepths::tri(pa.sz as i32, pd.sz as i32, pc.sz as i32),
            slot.backdrop,
        );
        if !render::refined_pair_depth_compatible(first, second) {
            return false;
        }
        Some((first + second) / 2)
    } else {
        None
    };
    // The 0x3C quad splits on the a-c diagonal into tri(b,a,c) + tri(a,d,c).
    // That tiles a clean quad ONLY when b and d sit on opposite sides of a-c
    // (the two halves wind the same way). At grazing angles a fan-pair can
    // project so b and d land on the SAME side -- a bowtie whose halves overlap
    // and rasterize to garbage/black. View-dependent, so it pops in and out as
    // the camera moves. When that happens, defer to the single-tri path (each
    // half is convex on its own and draws fine).
    // Screen coords are clamped to +-1023 above, so the cross products fit i32
    // (2047 * 2047 max per term): no 64-bit multiply sequences on the R3000.
    let area = |p: &Projected, q: &Projected, r: &Projected| -> i32 {
        (q.sx as i32 - p.sx as i32) * (r.sy as i32 - p.sy as i32)
            - (q.sy as i32 - p.sy as i32) * (r.sx as i32 - p.sx as i32)
    };
    let w_bac = area(&pb, &pa, &pc);
    let w_adc = area(&pa, &pd, &pc);
    if w_bac == 0 || w_adc == 0 || (w_bac > 0) != (w_adc > 0) {
        return false;
    }
    // culled(pa, pc, pb) is the same signed area as w_bac under a cyclic
    // permutation. Reuse it instead of paying two more R3000 multiplies.
    if CULL && w_bac >= 0 {
        return true;
    }
    // Near-band distance tessellation: a quad fully in front of the camera
    // but inside the warp band refines through the same distance cascade as
    // the near-plane crossers, so mesh density scales continuously with
    // proximity instead of waiting on the ranked shortlist's global budget.
    // A false return (backdrop/blend/wave texture, or no packet headroom)
    // falls through to the ordinary emission below.
    let band_z = (pa.sz as i32)
        .min(pb.sz as i32)
        .min(pc.sz as i32)
        .min(pd.sz as i32);
    if band_z < SOFT_NEAR_BAND_Z
        && emit_soft_quad_split(
            packets,
            m,
            tex,
            corners,
            frame,
            np,
            false,
            SOFT_SPLIT_TARGET_SPAN_PX,
        )
    {
        return true;
    }
    let (rgb_a, rgb_b, rgb_c, rgb_d) = (
        corners[0].rgb,
        corners[1].rgb,
        corners[2].rgb,
        corners[3].rgb,
    );
    let mut qrgb = if slot.backdrop {
        [rgb_b, rgb_a, rgb_c, rgb_d]
    } else {
        [
            fog_rgb_word_no_flash(rgb_b, pb.sz as i32),
            fog_rgb_word_no_flash(rgb_a, pa.sz as i32),
            fog_rgb_word_no_flash(rgb_c, pc.sz as i32),
            fog_rgb_word_no_flash(rgb_d, pd.sz as i32),
        ]
    };
    if FLASHLIGHT_ON && !slot.backdrop {
        let p = [pb, pa, pc, pd];
        shade_world_rgb(&mut qrgb, &p);
    }
    let uv = if EMIT_POLICY.wave() {
        [
            sway_uv(corners[1].uv),
            sway_uv(corners[0].uv),
            sway_uv(corners[2].uv),
            sway_uv(corners[3].uv),
        ]
    } else {
        [corners[1].uv, corners[0].uv, corners[2].uv, corners[3].uv]
    };
    #[cfg(feature = "performance-telemetry")]
    if affine_heatmap_active() {
        let _ = affine_triangle_error([&pb, &pa, &pc], [uv[0], uv[1], uv[2]]);
        let _ = affine_triangle_error([&pa, &pd, &pc], [uv[1], uv[3], uv[2]]);
    }
    let mat = emit_packet_of(slot, tex);
    // Classic coverage extends the native corrected path beyond cooked
    // patches: loop and tri-kind quads take the same stateless decision
    // (patch_state is MAX for them, so no persistent bit is touched).
    if native_patch || WORLD_CLASSIC_AFFINE_SELECTION || affine_previous_level != 0 {
        let emitted = if native_patch || WORLD_CLASSIC_AFFINE_SELECTION {
            try_emit_native_affine_quad(
                packets,
                m,
                [b as u16, a as u16, c as u16, d as u16],
                [pb, pa, pc, pd],
                uv,
                qrgb,
                mat,
                slot.backdrop,
                affine_previous_level,
                blocked_edges,
                patch_state,
                nq,
            )
        } else {
            false
        };
        if emitted {
            return true;
        }
        // Second classic band: severe error routes to the recursive
        // screen-bounded quadtree on the original corners.
        if WORLD_CLASSIC_WANTS_SOFT {
            WORLD_CLASSIC_WANTS_SOFT = false;
            if emit_soft_quad_split(
                packets,
                m,
                tex,
                corners,
                frame,
                np,
                false,
                SOFT_SPLIT_TARGET_SPAN_PX,
            ) {
                return true;
            }
        }
    }
    if affine_heatmap_active() {
        affine_record_remaining_triangle([&pb, &pa, &pc], [uv[0], uv[1], uv[2]]);
        affine_record_remaining_triangle([&pa, &pd, &pc], [uv[1], uv[3], uv[2]]);
    }
    #[cfg(feature = "performance-telemetry")]
    if affine_heatmap_active() {
        let otz = local_pair_otz.unwrap_or_else(|| {
            world_order_key(
                ordering::PrimitiveDepths::quad(
                    pa.sz as i32,
                    pb.sz as i32,
                    pc.sz as i32,
                    pd.sz as i32,
                ),
                slot.backdrop,
            )
        });
        push_affine_heatmap_tri(packets, [&pb, &pa, &pc], [uv[0], uv[1], uv[2]], otz, nq);
        push_affine_heatmap_tri(packets, [&pa, &pd, &pc], [uv[1], uv[3], uv[2]], otz, nq);
        return true;
    }
    #[cfg(feature = "seam-census")]
    let qrgb = if SEAM_CENSUS_TINT != 0 {
        [SEAM_CENSUS_TINT; 4]
    } else {
        qrgb
    };
    let prim = QuadTexturedGouraud {
        tag: 0,
        tex_window: mat.tex_window_word,
        color0_cmd: (mat.color0_command_word | 0x0800_0000) | qrgb[0],
        v0: pack_vertex_word(pb.sx, pb.sy),
        uv0_clut: uv[0] as u32 | mat.clut_high_word,
        color1: qrgb[1],
        v1: pack_vertex_word(pa.sx, pa.sy),
        uv1_tpage: uv[1] as u32 | mat.tpage_high_word,
        color2: qrgb[2],
        v2: pack_vertex_word(pc.sx, pc.sy),
        uv2: uv[2] as u32,
        color3: qrgb[3],
        v3: pack_vertex_word(pd.sx, pd.sy),
        uv3: uv[3] as u32,
    };
    let Some(packet) = packets.push(prim) else {
        note_render_packet_drop(false);
        WORLD_BAND_STATE |= WORLD_BAND_OVERFLOW;
        if TRAM_CACHE_BUILDING {
            TRAM_CACHE_OVERFLOW = true;
        }
        return false;
    };
    let otz = local_pair_otz.unwrap_or_else(|| {
        world_order_key(
            ordering::PrimitiveDepths::quad(pa.sz as i32, pb.sz as i32, pc.sz as i32, pd.sz as i32),
            slot.backdrop,
        )
    });
    world_cache_capture_packet(packet as *const QuadTexturedGouraud, otz, true);
    OT.add(otz, packet, QuadTexturedGouraud::WORDS);
    *nq += 1;
    if native_patch {
        WORLD_AFFINE_NATIVE_GT4 = WORLD_AFFINE_NATIVE_GT4.saturating_add(1);
    }
    true
}

#[derive(Clone, Copy)]
struct WorldCounters {
    cells_considered: u32,
    cells_drawn: u32,
    cells_culled: u32,
    surfaces_considered: u32,
    emit_calls: u32,
}

impl WorldCounters {
    const fn new() -> WorldCounters {
        WorldCounters {
            cells_considered: 0,
            cells_drawn: 0,
            cells_culled: 0,
            surfaces_considered: 0,
            emit_calls: 0,
        }
    }
}

/// Recreate cached packets in the same arena slots and call OT.add in the same
/// emission order as the fresh renderer. Unlike direct links to persistent
/// storage, later brush/actor packets therefore retain their baseline addresses.
#[inline]
unsafe fn replay_world_packet_cache(
    packets: &mut PrimitivePacketArena<'_>,
    np: &mut usize,
    nq: &mut usize,
    counts: &mut WorldCounters,
    count: usize,
    cached_np: usize,
    cached_nq: usize,
) -> bool {
    if count > packets.remaining() || count > PVS_BAND_CAP || count > MAX_RENDER_PACKETS {
        invalidate_world_packet_cache();
        return false;
    }
    let mut i = 0usize;
    while i < count {
        let meta = PVS_BAND_ORDER[PVS_BAND_CAP - 1 - i];
        let otz = (meta & WORLD_CACHE_OTZ_MASK) as usize;
        if meta & WORLD_CACHE_SKIP_META != 0 {
            if packets.reuse_packet::<QuadTexturedGouraud>().is_none() {
                note_render_packet_drop(false);
                invalidate_world_packet_cache();
                WORLD_BAND_STATE |= WORLD_BAND_OVERFLOW;
                return false;
            }
        } else if meta & WORLD_CACHE_QUAD_META != 0 {
            let Some(packet) = packets.reuse_packet::<QuadTexturedGouraud>() else {
                note_render_packet_drop(false);
                invalidate_world_packet_cache();
                WORLD_BAND_STATE |= WORLD_BAND_OVERFLOW;
                return false;
            };
            OT.add(otz, packet, QuadTexturedGouraud::WORDS);
        } else {
            let Some(packet) = packets.reuse_packet::<TriTexturedGouraud>() else {
                note_render_packet_drop(false);
                invalidate_world_packet_cache();
                WORLD_BAND_STATE |= WORLD_BAND_OVERFLOW;
                return false;
            };
            OT.add(otz, packet, TriTexturedGouraud::WORDS);
        }
        i += 1;
    }
    *np += cached_np;
    *nq += cached_nq;
    counts.emit_calls = WORLD_CACHE_EMIT_CALLS;
    WORLD_AFFINE_SPLIT_TRIS = WORLD_CACHE_AFFINE_SPLIT_TRIS;
    WORLD_AFFINE_ERROR_MAX_Q8 = WORLD_CACHE_AFFINE_ERROR_MAX_Q8;
    WORLD_AFFINE_ERROR_P50_Q8 = WORLD_CACHE_AFFINE_ERROR_P50_Q8;
    WORLD_AFFINE_ERROR_P95_Q8 = WORLD_CACHE_AFFINE_ERROR_P95_Q8;
    WORLD_AFFINE_ERROR_P99_Q8 = WORLD_CACHE_AFFINE_ERROR_P99_Q8;
    WORLD_AFFINE_SPLIT_CANDIDATES = WORLD_CACHE_AFFINE_SPLIT_CANDIDATES;
    WORLD_AFFINE_EXTRA_REQUESTED = WORLD_CACHE_AFFINE_EXTRA_REQUESTED;
    WORLD_AFFINE_EXTRA_EMITTED = WORLD_CACHE_AFFINE_EXTRA_EMITTED;
    WORLD_AFFINE_NATIVE_GT4 = WORLD_CACHE_AFFINE_NATIVE_GT4;
    WORLD_AFFINE_SPLIT_PATCHES = WORLD_CACHE_AFFINE_SPLIT_PATCHES;
    WORLD_AFFINE_ADDED_GTE_TRANSFORMS = WORLD_CACHE_AFFINE_ADDED_GTE;
    WORLD_AFFINE_REMAINING_MAX_Q8 = WORLD_CACHE_AFFINE_REMAINING_MAX_Q8;
    WORLD_AFFINE_REMAINING_P50_Q8 = WORLD_CACHE_AFFINE_REMAINING_P50_Q8;
    WORLD_AFFINE_REMAINING_P95_Q8 = WORLD_CACHE_AFFINE_REMAINING_P95_Q8;
    WORLD_AFFINE_REMAINING_P99_Q8 = WORLD_CACHE_AFFINE_REMAINING_P99_Q8;
    WORLD_BAND_STATE = WORLD_CACHE_BAND_STATE;
    reset_emit_policy();
    true
}

/// Decode-after-cull fast path shared by the world and submodel triangle loops.
///
/// The caller has already projected the three verts (`pa`/`pb`/`pc`). Read only
/// the indices to get here; the heavier per-triangle data (tex, uv, per-vertex
/// rgb -- ~9 unaligned u16 reads + 3 rgb555 unpacks) is decoded only for
/// survivors, so the triangles that back-face/off-screen cull pay almost
/// nothing. Returns true when the triangle is fully handled (emitted or culled);
/// false means it straddles the near plane and the caller must run the full
/// decode + view-space clip path.
/// Distance-fog factor for a view depth, 256 = unfogged, 0 = full (black) at
/// FAR_VIEW. Compile-time reciprocal, so no runtime divide.
#[inline]
fn fog_factor(sz: i32) -> i32 {
    if sz <= FOG_START {
        256
    } else if sz >= FAR_VIEW {
        0
    } else {
        ((FAR_VIEW - sz) * FOG_INV) >> 12
    }
}

// GoldSrc traces the local player's lamp forward, then places an 80-unit white
// dynamic light at the hit. The PS1 renderer retains the 2000-unit occlusion
// trace and applies its cheaper analogue directly to world/model lighting.
const FLASH_RANGE: i32 = 2000;
const FLASH_OCCLUSION_SLOP: i32 = 48;
// The centre-ray trace exists to stop the lamp shining through a closed door,
// which is only meaningful at range. Taken literally it destroys the light in
// exactly the situations you switch it on: point at the floor while walking and
// the ray lands ~45 units ahead, so every vertex in the cone -- including the
// far corners of the very surface you are facing, which are always further away
// than the centre hit -- fails the depth test and the beam goes out completely.
// Measured on c1a2: 257 of 275 walking frames lit zero vertices. Never let the
// occlusion bound fall below the width of the cone it is bounding.
const FLASH_MIN_REACH: i32 = 512;
// Screen-space cone radii (px from centre) for the world-vertex lamp.
const FLASH_CONE_INNER: i32 = 64;
const FLASH_CONE_OUTER: i32 = 112;
const FLASH_DRAIN_TICKS: u8 = 24; // SDK FLASH_DRAIN_TIME: 1.2 s at 20 Hz
const FLASH_CHARGE_TICKS: u8 = 4; // SDK FLASH_CHARGE_TIME: 0.2 s at 20 Hz
static mut FLASHLIGHT_ON: bool = false;
static mut FLASHLIGHT_BATTERY: u8 = 99; // CBasePlayer::Spawn starts at 99
static mut FLASHLIGHT_TIMER: u8 = 1; // force the initial 99 -> 100 HUD update
static mut FLASHLIGHT_REACH: u16 = FLASH_RANGE as u16;

/// Advance GoldSrc's integer flashlight battery clock by one 20 Hz simulation
/// tick. The state is passed and returned by value: keeping the three byte-wide
/// fields out of adjacent mutable references avoids a bad MIPS-I codegen alias
/// on the experimental target. The final bool reports automatic shutoff.
#[inline(never)]
fn tick_flashlight_battery(on: bool, mut battery: u8, mut timer: u8) -> (bool, u8, u8, bool) {
    if timer > 0 {
        timer -= 1;
        if timer > 0 {
            return (on, battery, timer, false);
        }
    }
    if on {
        if battery > 0 {
            battery -= 1;
        }
        if battery == 0 {
            return (false, 0, FLASH_CHARGE_TICKS, true);
        }
        timer = FLASH_DRAIN_TICKS;
    } else if battery < 100 {
        battery += 1;
        timer = if battery < 100 { FLASH_CHARGE_TICKS } else { 0 };
    }
    (on, battery, timer, false)
}

/// Trace the beam centre once per visual frame. Static BSP and active brush
/// movers both stop it, so a closed door cannot light the room behind it.
#[inline(never)]
unsafe fn update_flashlight_reach(m: &Map, eye: [i32; 3], rot: &Mat3I16) {
    if !FLASHLIGHT_ON {
        FLASHLIGHT_REACH = FLASH_RANGE as u16;
        return;
    }
    let end = [
        eye[0] + ((rot.m[2][0] as i32 * FLASH_RANGE) >> 12),
        eye[1] + ((rot.m[2][1] as i32 * FLASH_RANGE) >> 12),
        eye[2] + ((rot.m[2][2] as i32 * FLASH_RANGE) >> 12),
    ];
    let movers = core::slice::from_raw_parts(
        core::ptr::addr_of!(MOVERS).cast::<phys::Mover>(),
        MOVER_COUNT.min(MAX_ENTS + 1),
    );
    if let Some(hit) = phys::trace_line(m, movers, eye, end) {
        FLASHLIGHT_REACH =
            ((FLASH_RANGE * hit.frac) >> 12).clamp(FLASH_MIN_REACH, FLASH_RANGE) as u16;
    } else {
        FLASHLIGHT_REACH = FLASH_RANGE as u16;
    }
}

#[inline(always)]
const fn pack_rgb_word(rgb: (u8, u8, u8)) -> u32 {
    rgb.0 as u32 | ((rgb.1 as u32) << 8) | ((rgb.2 as u32) << 16)
}

#[inline(always)]
const fn unpack_rgb_word(rgb: u32) -> (u8, u8, u8) {
    (rgb as u8, (rgb >> 8) as u8, (rgb >> 16) as u8)
}

#[inline(always)]
const fn pack_vertex_word(x: i16, y: i16) -> u32 {
    x as u16 as u32 | ((y as u16 as u32) << 16)
}

#[cfg(feature = "performance-telemetry")]
#[inline(always)]
fn affine_heatmap_color(error_q8: u32) -> (u8, u8, u8) {
    // Blue/green is below the leave threshold, yellow approaches the split
    // threshold, and red/magenta exposes severe residual error.
    if error_q8 <= 2 * 256 {
        (24, 96u8.saturating_add((error_q8 / 8) as u8), 255)
    } else if error_q8 <= 4 * 256 {
        let t = ((error_q8 - 2 * 256) >> 2).min(127) as u8;
        (t.saturating_mul(2), 255, 32)
    } else if error_q8 <= 8 * 256 {
        let t = ((error_q8 - 4 * 256) >> 4).min(255) as u8;
        (255, 255u8.saturating_sub(t), 16)
    } else {
        (255, 0, 160)
    }
}

#[cfg(feature = "performance-telemetry")]
#[inline(never)]
unsafe fn push_affine_heatmap_tri(
    packets: &mut PrimitivePacketArena<'_>,
    p: [&Projected; 3],
    uv: [u16; 3],
    otz: usize,
    count: &mut usize,
) -> bool {
    let error = affine_triangle_error_unrecorded(p, uv);
    let error_q8 = error.0.saturating_mul(256) / error.1.max(1);
    let color = affine_heatmap_color(error_q8);
    let prim = TriFlat::new(
        [(p[0].sx, p[0].sy), (p[1].sx, p[1].sy), (p[2].sx, p[2].sy)],
        color.0,
        color.1,
        color.2,
    );
    let Some(packet) = packets.push(prim) else {
        note_render_packet_drop(false);
        WORLD_BAND_STATE |= WORLD_BAND_OVERFLOW;
        return false;
    };
    OT.add(otz, packet, TriFlat::WORDS);
    *count += 1;
    true
}

/// Packed-colour fog for the dominant loop-quad path. The near case stays
/// entirely inline and avoids touching the color when no fade is required.
#[inline(always)]
fn fog_rgb_word_no_flash(rgb: u32, sz: i32) -> u32 {
    if sz <= FOG_START {
        return rgb;
    }
    if sz >= FAR_VIEW {
        return 0;
    }
    let f = (((FAR_VIEW - sz) * FOG_INV) >> 12) as u32;
    // R and B occupy independent 16-bit multiplication lanes: each 8-bit
    // component times f<=255 still fits below the neighbouring component.
    // This SWAR form is bit-exact to the three scalar products but removes one
    // variable R3000 MULT/MFLO pair for every fogged world vertex.
    let rb = ((rgb & 0x00ff_00ff).wrapping_mul(f) >> 8) & 0x00ff_00ff;
    let g = ((rgb & 0x0000_ff00).wrapping_mul(f) >> 8) & 0x0000_ff00;
    rb | g
}

/// PS1-cheap vertex analogue of GoldSrc's hit-centred flashlight light. The
/// traced hit clips the beam, while this contribution raises actual world
/// lighting inside the camera-facing cone.
/// Brightening toward white is saturation-free and preserves surface contrast.
#[inline(always)]
unsafe fn flashlight_rgb_word(rgb: u32, p: Projected) -> u32 {
    let z = p.sz as i32;
    if z < NEAR as i32 || z > FLASHLIGHT_REACH as i32 {
        return rgb;
    }
    let x = (p.sx as i32 - render::OFX).abs();
    let y = (p.sy as i32 - render::OFY).abs();
    // Graded radius rather than a hard box: the bright core keeps the beam the
    // shape it already had, and the outer ring at a quarter strength lets a big
    // near surface catch light on the corners that Gouraud then carries across
    // its middle. `max + min/2` is the octagonal length the model path uses.
    let radial = x.max(y) + (x.min(y) >> 1);
    if radial >= FLASH_CONE_OUTER {
        return rgb;
    }
    let near = z < FLASH_MIN_REACH;
    let shift = match (radial < FLASH_CONE_INNER, near) {
        (true, true) => 2,
        (true, false) => 3,
        (false, true) => 3,
        (false, false) => 4,
    };
    // R/B occupy independent 16-bit lanes. The post-shift masks discard lane
    // spill; every component moves 1/4 or 1/8 of the way toward 255.
    let rb = rgb & 0x00ff_00ff;
    let g = rgb & 0x0000_ff00;
    let rb = rb + (((0x00ff_00ff - rb) >> shift) & 0x00ff_00ff);
    let g = g + (((0x0000_ff00 - g) >> shift) & 0x0000_ff00);
    rb | g
}

#[inline(never)]
unsafe fn shade_world_rgb(rgb: &mut [u32], projected: &[Projected]) {
    debug_assert_eq!(rgb.len(), projected.len());
    let mut i = 0;
    while i < rgb.len() {
        rgb[i] = flashlight_rgb_word(rgb[i], projected[i]);
        i += 1;
    }
}

/// Fade a triangle's packed vertex colors toward black by per-vertex depth.
/// Backdrop/sky tris pass through so the horizon never darkens.
#[inline(always)]
fn fog_world_rgb(rgb: [u32; 3], sz: [i32; 3], backdrop: bool) -> [u32; 3] {
    if backdrop {
        return rgb;
    }
    [
        fog_rgb_word_no_flash(rgb[0], sz[0]),
        fog_rgb_word_no_flash(rgb[1], sz[1]),
        fog_rgb_word_no_flash(rgb[2], sz[2]),
    ]
}

#[cfg(feature = "performance-telemetry")]
#[inline(never)]
fn affine_ratio_cmp(an: u32, ad: u32, bn: u32, bd: u32) -> core::cmp::Ordering {
    (an as u64 * bd.max(1) as u64).cmp(&(bn as u64 * ad.max(1) as u64))
}

#[inline(always)]
fn affine_edge_error(a: &Projected, b: &Projected, uv_a: u16, uv_b: u16) -> (u32, u32) {
    let screen_span = (a.sx as i32 - b.sx as i32)
        .abs()
        .max((a.sy as i32 - b.sy as i32).abs());
    if screen_span < WORLD_AFFINE_MIN_EDGE_PIXELS || a.sz < NEAR || b.sz < NEAR {
        return (0, 1);
    }
    let uv_span = ((uv_a as u8 as i32) - (uv_b as u8 as i32))
        .abs()
        .max((((uv_a >> 8) as i32) - ((uv_b >> 8) as i32)).abs()) as u32;
    let z0 = a.sz as i32;
    let z1 = b.sz as i32;
    (
        uv_span.saturating_mul((z1 - z0).unsigned_abs()),
        2u32.saturating_mul((z0 + z1).max(1) as u32),
    )
}

#[inline(always)]
unsafe fn affine_candidates_ptr() -> *mut AffineFaceCandidate {
    core::ptr::addr_of_mut!(WORLD_AFFINE_CANDIDATES).cast::<AffineFaceCandidate>()
}

#[inline(always)]
unsafe fn affine_patch_candidates_ptr() -> *mut AffinePatchCandidate {
    core::ptr::addr_of_mut!(WORLD_AFFINE_PATCH_CANDIDATES).cast::<AffinePatchCandidate>()
}

#[cfg(feature = "performance-telemetry")]
#[inline(always)]
unsafe fn affine_histogram_ptr() -> *mut u16 {
    core::ptr::addr_of_mut!(WORLD_AFFINE_ERROR_HISTOGRAM).cast::<u16>()
}

#[cfg(feature = "performance-telemetry")]
#[inline(always)]
unsafe fn affine_remaining_histogram_ptr() -> *mut u16 {
    core::ptr::addr_of_mut!(WORLD_AFFINE_REMAINING_HISTOGRAM).cast::<u16>()
}

#[inline(always)]
unsafe fn affine_previous_level(face: usize) -> u8 {
    let mut lo = 0usize;
    let mut hi = WORLD_AFFINE_PREVIOUS_COUNT as usize;
    while lo < hi {
        let mid = (lo + hi) >> 1;
        let current = WORLD_AFFINE_PREVIOUS_FACES[mid] as usize;
        if current < face {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo < WORLD_AFFINE_PREVIOUS_COUNT as usize && WORLD_AFFINE_PREVIOUS_FACES[lo] as usize == face
    {
        WORLD_AFFINE_PREVIOUS_LEVELS[lo]
    } else {
        0
    }
}

#[inline(always)]
unsafe fn affine_previous_face_contains(face: usize) -> bool {
    let mut lo = 0usize;
    let mut hi = WORLD_AFFINE_PREVIOUS_COUNT as usize;
    while lo < hi {
        let mid = (lo + hi) >> 1;
        let current = WORLD_AFFINE_PREVIOUS_FACES[mid] as usize;
        if current < face {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo < WORLD_AFFINE_PREVIOUS_COUNT as usize && WORLD_AFFINE_PREVIOUS_FACES[lo] as usize == face
}

#[cfg(feature = "performance-telemetry")]
#[inline(never)]
unsafe fn affine_record_error(num: u32, den: u32) {
    // The exact distribution is a deliberately opt-in diagnostic. Keeping the
    // histogram out of ordinary performance runs is important: binary-search
    // binning every visible edge costs more than the correction itself on the
    // R3000. The dedicated heatmap launch still samples every emitted edge.
    if num == 0 {
        return;
    }
    WORLD_AFFINE_ERROR_EDGE_COUNT = WORLD_AFFINE_ERROR_EDGE_COUNT.saturating_add(1);
    if affine_ratio_cmp(
        num,
        den,
        WORLD_AFFINE_ERROR_MAX_NUM,
        WORLD_AFFINE_ERROR_MAX_DEN,
    )
    .is_gt()
    {
        WORLD_AFFINE_ERROR_MAX_NUM = num;
        WORLD_AFFINE_ERROR_MAX_DEN = den.max(1);
    }
    // One-texel histogram, assigned by cross multiplication. The final overflow
    // bucket represents >= 127 texels; no per-edge division occurs.
    let scaled_num = num;
    let mut lo = 0u32;
    let mut hi = (AFFINE_ERROR_BUCKETS - 1) as u32;
    while lo < hi {
        let mid = (lo + hi + 1) >> 1;
        if scaled_num >= den.saturating_mul(mid) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    let histogram = affine_histogram_ptr();
    let slot = histogram.add(lo as usize);
    slot.write(slot.read().saturating_add(1));

    WORLD_AFFINE_ERROR_MAX_Q8 =
        WORLD_AFFINE_ERROR_MAX_NUM.saturating_mul(256) / WORLD_AFFINE_ERROR_MAX_DEN.max(1);
    // Temporarily retain the sample count in P50; finalize overwrites it.
    WORLD_AFFINE_ERROR_P50_Q8 = WORLD_AFFINE_ERROR_EDGE_COUNT;
}

#[cfg(not(feature = "performance-telemetry"))]
#[inline(always)]
unsafe fn affine_record_error(_num: u32, _den: u32) {}

#[cfg(feature = "performance-telemetry")]
#[inline(never)]
unsafe fn affine_record_remaining_error(num: u32, den: u32) {
    if num == 0 {
        return;
    }
    WORLD_AFFINE_REMAINING_EDGE_COUNT = WORLD_AFFINE_REMAINING_EDGE_COUNT.saturating_add(1);
    if affine_ratio_cmp(
        num,
        den,
        WORLD_AFFINE_REMAINING_MAX_NUM,
        WORLD_AFFINE_REMAINING_MAX_DEN,
    )
    .is_gt()
    {
        WORLD_AFFINE_REMAINING_MAX_NUM = num;
        WORLD_AFFINE_REMAINING_MAX_DEN = den.max(1);
        WORLD_AFFINE_REMAINING_MAX_Q8 = num.saturating_mul(256) / den.max(1);
    }
    let scaled_num = num;
    let mut lo = 0u32;
    let mut hi = (AFFINE_ERROR_BUCKETS - 1) as u32;
    while lo < hi {
        let mid = (lo + hi + 1) >> 1;
        if scaled_num >= den.saturating_mul(mid) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    let histogram = affine_remaining_histogram_ptr();
    let slot = histogram.add(lo as usize);
    slot.write(slot.read().saturating_add(1));
}

#[cfg(not(feature = "performance-telemetry"))]
#[inline(always)]
unsafe fn affine_record_remaining_error(_num: u32, _den: u32) {}

#[cfg(feature = "performance-telemetry")]
#[inline(always)]
unsafe fn affine_record_remaining_triangle(p: [&Projected; 3], uv: [u16; 3]) {
    let edges = [(0usize, 1usize), (1, 2), (2, 0)];
    let mut i = 0usize;
    while i < edges.len() {
        let (a, b) = edges[i];
        let error = affine_edge_error(p[a], p[b], uv[a], uv[b]);
        affine_record_remaining_error(error.0, error.1);
        i += 1;
    }
}

#[cfg(not(feature = "performance-telemetry"))]
#[inline(always)]
unsafe fn affine_record_remaining_triangle(_p: [&Projected; 3], _uv: [u16; 3]) {}

#[cfg(feature = "performance-telemetry")]
#[inline(never)]
unsafe fn affine_triangle_error(p: [&Projected; 3], uv: [u16; 3]) -> (u32, u32) {
    let mut best = (0u32, 1u32);
    let edges = [(0usize, 1usize), (1, 2), (2, 0)];
    let mut i = 0usize;
    while i < 3 {
        let (a, b) = edges[i];
        let error = affine_edge_error(p[a], p[b], uv[a], uv[b]);
        affine_record_error(error.0, error.1);
        if affine_ratio_cmp(error.0, error.1, best.0, best.1).is_gt() {
            best = error;
        }
        i += 1;
    }
    best
}

#[cfg(feature = "performance-telemetry")]
#[inline(never)]
fn affine_triangle_error_unrecorded(p: [&Projected; 3], uv: [u16; 3]) -> (u32, u32) {
    let e0 = affine_edge_error(p[0], p[1], uv[0], uv[1]);
    let e1 = affine_edge_error(p[1], p[2], uv[1], uv[2]);
    let e2 = affine_edge_error(p[2], p[0], uv[2], uv[0]);
    let mut best = e0;
    if affine_ratio_cmp(e1.0, e1.1, best.0, best.1).is_gt() {
        best = e1;
    }
    if affine_ratio_cmp(e2.0, e2.1, best.0, best.1).is_gt() {
        best = e2;
    }
    best
}

#[inline(always)]
fn affine_triangle_threshold(previous_level: u8) -> i32 {
    if (previous_level & 3).saturating_sub(1) != 0 {
        WORLD_AFFINE_LEAVE_ERROR_TEXELS
    } else {
        WORLD_AFFINE_ENTER_ERROR_TEXELS
    }
}

#[inline(never)]
unsafe fn affine_insert_face_candidate(candidate: AffineFaceCandidate, count: &mut usize) {
    let candidates = affine_candidates_ptr();
    let active_cap = WORLD_AFFINE_ACTIVE_CAP as usize;
    let mut at = 0usize;
    while at < *count {
        let current = candidates.add(at).read();
        // Coarse candidates carry a common denominator. A plain u32 compare
        // avoids thousands of software u64 multiplies while walking a dense
        // PVS; exact rational ordering happens only after the 32-face cap.
        let order = candidate.score_q8.cmp(&current.score_q8);
        if order.is_gt() || (order.is_eq() && candidate.face < current.face) {
            break;
        }
        at += 1;
    }
    if at >= active_cap {
        return;
    }
    let new_count = (*count + 1).min(active_cap);
    let mut i = new_count - 1;
    while i > at {
        candidates.add(i).write(candidates.add(i - 1).read());
        i -= 1;
    }
    candidates.add(at).write(candidate);
    *count = new_count;
}

/// Cheap conservative shortlist score. A face sphere bounds both projected
/// size and possible depth variation; the cook's grid caps refined primitive
/// UV spans at roughly one cell. This pass touches no vertices; exact edge
/// error is evaluated only when a shortlisted primitive reaches emission.
#[inline(never)]
unsafe fn affine_coarse_face_candidate(m: &Map, face: usize) -> Option<AffineFaceCandidate> {
    if face >= m.n_faces || !m.face_is_patch(face) || m.face_liquid(face) {
        return None;
    }
    let tex = m.face_tex(face);
    if tex >= m.n_texs || tex >= MAX_TEX_SLOTS {
        return None;
    }
    let slot = &*tex_slot_ptr(tex);
    if !slot.valid || slot.backdrop {
        return None;
    }
    let (center, radius) = m.face_bounds(face);
    let depth = dot12(WORLD_AFFINE_VIEW_FORWARD, center) + WORLD_AFFINE_VIEW_Z_OFFSET;
    if depth + radius < NEAR as i32 || depth - radius > FAR_VIEW {
        return None;
    }
    let safe_depth = depth.max(NEAR as i32);
    // A sphere wholly beyond the leave range cannot contain a close patch.
    // Use the relaxed leave boundary here so the exact per-quad gate below
    // owns the visible enter/leave decision.
    if depth - radius > WORLD_AFFINE_CULL_MAX_DEPTH {
        return None;
    }
    // A projected sphere diameter below the enter threshold cannot contain a
    // qualifying quad. This remains conservative; exact screen bounds are
    // measured only after the four patch corners have been projected.
    if radius.saturating_mul(render::projection_h())
        < (WORLD_AFFINE_CULL_MIN_SPAN_PIXELS / 2).saturating_mul(safe_depth)
    {
        return None;
    }
    let uv_bound = 255u32;
    let (normal, _) = m.face_plane(face);
    // A front-on plane has little intra-polygon depth change even when its
    // authored bounds are enormous; a grazing plane has the opposite risk.
    // Weight the sphere bound by that tangent component so the shortlist does
    // not get monopolised by large, visually safe floors and walls.
    let alignment = dot12_plane(WORLD_AFFINE_VIEW_FORWARD, normal)
        .unsigned_abs()
        .min(4096);
    let slope_q8 = ((4096 - alignment) >> 4) + 16;
    let numerator = uv_bound
        .saturating_mul(radius.max(1) as u32)
        .saturating_mul(slope_q8);
    // This is a rank, not a measurement. Quantising depth to 64-unit
    // power-of-two bands replaces a software R3000 divide with one shift while
    // retaining the intended near-before-far ordering.
    let depth_shift = if safe_depth >= 2048 {
        5
    } else if safe_depth >= 1024 {
        4
    } else if safe_depth >= 512 {
        3
    } else if safe_depth >= 256 {
        2
    } else if safe_depth >= 128 {
        1
    } else {
        0
    };
    let score = numerator >> depth_shift;
    Some(AffineFaceCandidate {
        face: face.min(u16::MAX as usize) as u16,
        previous_level: affine_previous_level(face),
        selected_level: 0,
        score_q8: score,
    })
}

#[cfg(feature = "performance-telemetry")]
#[inline(never)]
unsafe fn affine_finalize_percentiles() {
    let total = WORLD_AFFINE_ERROR_P50_Q8;
    if total == 0 {
        WORLD_AFFINE_ERROR_P50_Q8 = 0;
        WORLD_AFFINE_ERROR_P95_Q8 = 0;
        WORLD_AFFINE_ERROR_P99_Q8 = 0;
        return;
    }
    let percentile = |numerator: u32, denominator: u32| -> u32 {
        let target = (total.saturating_mul(numerator) + denominator - 1) / denominator;
        let histogram = affine_histogram_ptr();
        let mut cumulative = 0u32;
        let mut i = 0usize;
        while i < AFFINE_ERROR_BUCKETS {
            cumulative = cumulative.saturating_add(histogram.add(i).read() as u32);
            if cumulative >= target {
                return (i as u32) * 256;
            }
            i += 1;
        }
        ((AFFINE_ERROR_BUCKETS - 1) as u32) * 256
    };
    WORLD_AFFINE_ERROR_P50_Q8 = percentile(50, 100);
    WORLD_AFFINE_ERROR_P95_Q8 = percentile(95, 100);
    WORLD_AFFINE_ERROR_P99_Q8 = percentile(99, 100);
}

#[cfg(not(feature = "performance-telemetry"))]
#[inline(always)]
unsafe fn affine_finalize_percentiles() {}

#[cfg(feature = "performance-telemetry")]
#[inline(never)]
unsafe fn affine_finalize_remaining_percentiles() {
    let total = WORLD_AFFINE_REMAINING_EDGE_COUNT;
    if total == 0 {
        return;
    }
    let percentile = |numerator: u32, denominator: u32| -> u32 {
        let target = (total.saturating_mul(numerator) + denominator - 1) / denominator;
        let histogram = affine_remaining_histogram_ptr();
        let mut cumulative = 0u32;
        let mut i = 0usize;
        while i < AFFINE_ERROR_BUCKETS {
            cumulative = cumulative.saturating_add(histogram.add(i).read() as u32);
            if cumulative >= target {
                return (i as u32) * 256;
            }
            i += 1;
        }
        ((AFFINE_ERROR_BUCKETS - 1) as u32) * 256
    };
    WORLD_AFFINE_REMAINING_P50_Q8 = percentile(50, 100);
    WORLD_AFFINE_REMAINING_P95_Q8 = percentile(95, 100);
    WORLD_AFFINE_REMAINING_P99_Q8 = percentile(99, 100);
}

#[cfg(not(feature = "performance-telemetry"))]
#[inline(always)]
unsafe fn affine_finalize_remaining_percentiles() {}

#[inline(never)]
unsafe fn prepare_world_affine_candidates(visibility: &CameraVisibility<'_>, frame: u16) {
    if !WORLD_NATIVE_PATCH_SUBDIVISION {
        WORLD_AFFINE_SELECTED_COUNT = 0;
        WORLD_AFFINE_PREVIOUS_COUNT = 0;
        return;
    }
    // Classic keeps the rank/hold cadence for its DECISION only: the 4-edge
    // error predicate measured 3.3% of the moving frame when re-derived every
    // frame; hold frames replay the persistent per-patch bit instead, a
    // one-frame decision lag that no static pose can see (splits land one
    // presented frame late during motion). Coverage itself stays total.
    WORLD_AFFINE_RANK_FRAME =
        !WORLD_AFFINE_POLICY_READY || WORLD_AFFINE_FORCE_RANK || frame & 1 == 0;
    WORLD_CLASSIC_SOFT_ROUTES_LEFT = WORLD_CLASSIC_SOFT_ROUTE_CAP;
    WORLD_AFFINE_FORCE_RANK = false;
    if !WORLD_AFFINE_RANK_FRAME {
        return;
    }
    // The correction budget is FIXED. It used to halve itself in "dense"
    // views, classified from the previous frame's deadline and emit count --
    // both of which the correction itself moves. Measured across ten maps
    // including the vista class, pinning it open costs 0.1-3.0% of frame rate
    // (worst: c4a1) while adding 15-60% more corrected quads, so the gate was
    // buying almost nothing and paying for it in visible instability: any
    // frame that overran re-tessellated the whole view for the next eight.
    WORLD_AFFINE_ACTIVE_CAP = AFFINE_CANDIDATE_CAP as u8;
    WORLD_AFFINE_SELECTED_COUNT = WORLD_AFFINE_PREVIOUS_COUNT.min(WORLD_AFFINE_ACTIVE_CAP);
    WORLD_AFFINE_COLLECTION_PHASE = if WORLD_AFFINE_PREVIOUS_COUNT == 0 {
        0xff
    } else {
        // Advance independently of the projection-cache token. Its low bits
        // are a camera hash, not a frame counter, so using them made discovery
        // jump unpredictably during motion and freeze on one bucket at rest.
        WORLD_AFFINE_COLLECTION_PHASE.wrapping_add(1) & 7
    };
    // Never accumulate scores from different camera poses. Re-score every
    // retained face with this frame's camera and inspect one eighth of the
    // remaining visible faces for replacements. The old implementation kept
    // NEXT across eight moving frames, which made the same nearby quad enter
    // and leave the shortlist according to stale viewpoints.
    WORLD_AFFINE_NEXT_COUNT = 0;
    WORLD_AFFINE_VIEW_FORWARD = visibility.rot.m[2];
    WORLD_AFFINE_VIEW_Z_OFFSET = visibility.base_t[2];
    WORLD_AFFINE_EDGE_NEXT_COUNT = 0;
    WORLD_AFFINE_NEXT_SPLIT_PATCHES = 0;
    WORLD_AFFINE_PATCH_CANDIDATE_COUNT = 0;
    WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY = 0;
    WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY = 0;
    WORLD_AFFINE_LOWEST_SELECTED_PRIORITY = 0;
    WORLD_AFFINE_NEXT_EDGE_BUDGET = WORLD_AFFINE_MAX_EXTRA_PACKETS;
    // Both candidate arrays are count-bounded transient workspaces. Every
    // active slot is overwritten by the sorted insertion paths below, so
    // clearing their inactive tails here only burns cached RAM bandwidth on
    // every visual frame.
    #[cfg(feature = "performance-telemetry")]
    if affine_heatmap_active() {
        let histogram = affine_histogram_ptr();
        let remaining = affine_remaining_histogram_ptr();
        let mut i = 0usize;
        while i < AFFINE_ERROR_BUCKETS {
            histogram.add(i).write(0);
            remaining.add(i).write(0);
            i += 1;
        }
    }
    WORLD_AFFINE_EXTRA_BUDGET_LEFT = if WORLD_CLASSIC_AFFINE_SELECTION {
        WORLD_CLASSIC_EXTRA_PACKETS
    } else {
        WORLD_AFFINE_MAX_EXTRA_PACKETS
    };
}

/// Rank a face only after the ordinary world traversal has already accepted
/// its plane and bounds. The resulting shortlist drives the following visual
/// frame, avoiding a second PVS/face walk while hysteresis hides the one-frame
/// handoff during motion.
#[inline(always)]
fn affine_edge_key(a: u16, b: u16) -> u32 {
    let lo = a.min(b) as u32;
    let hi = a.max(b) as u32;
    (lo << 14) | hi
}

#[inline(always)]
fn affine_quad_edge_keys(indices: [u16; 4]) -> [u32; 4] {
    [
        affine_edge_key(indices[0], indices[1]),
        affine_edge_key(indices[1], indices[3]),
        affine_edge_key(indices[3], indices[2]),
        affine_edge_key(indices[2], indices[0]),
    ]
}

#[inline(always)]
unsafe fn affine_current_edge_contains(key: u32) -> bool {
    let hash = (key ^ (key >> 7) ^ (key >> 15)) as usize & AFFINE_EDGE_BLOOM_MASK;
    if WORLD_AFFINE_EDGE_BLOOM[hash >> 5] & (1u32 << (hash & 31)) == 0 {
        return false;
    }
    let edges = core::ptr::addr_of!(WORLD_AFFINE_EDGE_CURRENT).cast::<u32>();
    let mut lo = 0usize;
    let mut hi = WORLD_AFFINE_EDGE_CURRENT_COUNT as usize;
    while lo < hi {
        let mid = (lo + hi) >> 1;
        let value = edges.add(mid).read();
        if value < key {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo < WORLD_AFFINE_EDGE_CURRENT_COUNT as usize && edges.add(lo).read() == key
}

#[inline(always)]
unsafe fn affine_current_edge_mask(keys: [u32; 4], blocked: u8) -> u8 {
    if WORLD_AFFINE_EDGE_CURRENT_COUNT == 0 {
        return 0;
    }
    let mut mask = 0u8;
    let mut edge = 0usize;
    while edge < 4 {
        if blocked & (1 << edge) == 0 && affine_current_edge_contains(keys[edge]) {
            mask |= 1 << edge;
        }
        edge += 1;
    }
    mask
}

/// Atomically record all four edges of a patch selected for the following
/// frame. A matching edge makes its neighbour use the same regular 2x2
/// topology, so conformity never requires an irregular triangle fan.
#[inline(never)]
unsafe fn affine_request_edges(keys: [u32; 4], cost: u16) -> bool {
    if WORLD_AFFINE_NEXT_SPLIT_PATCHES as usize >= AFFINE_CANDIDATE_CAP
        || WORLD_AFFINE_NEXT_EDGE_BUDGET < cost
    {
        return false;
    }
    let edges = core::ptr::addr_of_mut!(WORLD_AFFINE_EDGE_NEXT).cast::<u32>();
    let mut needed = 0usize;
    let mut missing = 0u8;
    let mut edge = 0usize;
    while edge < 4 {
        let key = keys[edge];
        let mut found = false;
        let mut i = 0usize;
        while i < WORLD_AFFINE_EDGE_NEXT_COUNT as usize {
            if edges.add(i).read() == key {
                found = true;
                break;
            }
            i += 1;
        }
        if !found {
            needed += 1;
            missing |= 1 << edge;
        }
        edge += 1;
    }
    if WORLD_AFFINE_EDGE_NEXT_COUNT as usize + needed > AFFINE_EDGE_CAP {
        return false;
    }
    edge = 0;
    while edge < 4 {
        if missing & (1 << edge) != 0 {
            let key = keys[edge];
            // Preserve the old second scan's duplicate behavior without
            // walking the complete accumulated list again. An earlier missing
            // copy is exactly the only way this key could have been appended
            // since the first pass.
            let mut duplicate = false;
            let mut earlier = 0usize;
            while earlier < edge {
                if missing & (1 << earlier) != 0 && keys[earlier] == key {
                    duplicate = true;
                    break;
                }
                earlier += 1;
            }
            if !duplicate {
                edges.add(WORLD_AFFINE_EDGE_NEXT_COUNT as usize).write(key);
                WORLD_AFFINE_EDGE_NEXT_COUNT += 1;
            }
        }
        edge += 1;
    }
    WORLD_AFFINE_NEXT_SPLIT_PATCHES += 1;
    WORLD_AFFINE_NEXT_EDGE_BUDGET -= cost;
    WORLD_AFFINE_EXTRA_REQUESTED = WORLD_AFFINE_EXTRA_REQUESTED.saturating_add(cost as u32);
    true
}

#[inline(always)]
unsafe fn affine_request_patch_edges(keys: [u32; 4], blocked: u8) -> bool {
    blocked == 0 && affine_request_edges(keys, WORLD_AFFINE_NATIVE_EDGE_RESERVATION)
}

#[inline(always)]
unsafe fn affine_request_seamed_pair_edges(keys: [u32; 4]) -> bool {
    affine_request_edges(keys, WORLD_AFFINE_SEAMED_EDGE_RESERVATION)
}

#[inline(always)]
fn affine_patch_candidate_precedes(a: AffinePatchCandidate, b: AffinePatchCandidate) -> bool {
    a.screen_span > b.screen_span
        || (a.screen_span == b.screen_span
            && (a.near_depth < b.near_depth
                || (a.near_depth == b.near_depth
                    && (a.was_split > b.was_split
                        || (a.was_split == b.was_split && a.key0 < b.key0)))))
}

/// Retain the largest projected patches independently of BSP/PVS traversal
/// order. Near depth, current ownership, and the canonical key break ties.
#[inline(never)]
unsafe fn affine_rank_patch_candidate(candidate: AffinePatchCandidate) {
    let cap = AFFINE_PATCH_CANDIDATE_CAP;
    let candidates = affine_patch_candidates_ptr();
    let count = WORLD_AFFINE_PATCH_CANDIDATE_COUNT as usize;
    // The table is kept in descending priority. Once full, the tail is the
    // exact admission threshold; most dense-view patches rank below it.
    // Reject those in O(1) instead of walking all sixteen entries merely to
    // arrive at `at == cap`. This preserves the same top-K and tie-breaking.
    if count == cap {
        let tail = candidates.add(cap - 1).read();
        if !affine_patch_candidate_precedes(candidate, tail) {
            WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY =
                WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY.max(candidate.screen_span);
            return;
        }
    }
    let mut at = 0usize;
    while at < count && !affine_patch_candidate_precedes(candidate, candidates.add(at).read()) {
        at += 1;
    }
    if at >= cap {
        WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY =
            WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY.max(candidate.screen_span);
        return;
    }
    let new_count = (count + 1).min(cap);
    if count == cap {
        WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY =
            WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY.max(candidates.add(cap - 1).read().screen_span);
    }
    let mut i = new_count - 1;
    while i > at {
        candidates.add(i).write(candidates.add(i - 1).read());
        i -= 1;
    }
    candidates.add(at).write(candidate);
    WORLD_AFFINE_PATCH_CANDIDATE_COUNT = new_count as u8;
}

#[inline(never)]
unsafe fn finish_world_affine_patch_candidates() {
    let candidates = affine_patch_candidates_ptr();
    let count = WORLD_AFFINE_PATCH_CANDIDATE_COUNT as usize;
    let mut selected = 0usize;
    let mut budget_exhausted = false;
    WORLD_AFFINE_LOWEST_SELECTED_PRIORITY = 0;
    WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY = 0;
    let mut i = 0usize;
    while i < count {
        let candidate = candidates.add(i).read();
        // Every candidate corner was projected into the frame cache before
        // ranking. Reload only the top-K survivors here rather than carrying
        // 24 bytes of projected coordinates through every sorted insertion.
        let projected = [
            scratch_get(candidate.indices[0] as usize),
            scratch_get(candidate.indices[1] as usize),
            scratch_get(candidate.indices[2] as usize),
            scratch_get(candidate.indices[3] as usize),
        ];
        let keys = affine_quad_edge_keys(candidate.indices);
        let needs_split = if candidate.kind == AFFINE_PATCH_KIND_SEAMED_PAIR {
            true
        } else if (candidate.near_depth as i32) < RANKED_NEAR_PRESENCE_Z
            && (candidate.screen_span as i32) > RANKED_NEAR_PRESENCE_SPAN_PX
        {
            // Near-presence candidates split regardless of measured error:
            // see `rank_affine_patch`.
            true
        } else {
            let first = affine_triangle_error_level(
                [&projected[0], &projected[1], &projected[2]],
                [candidate.uv[0], candidate.uv[1], candidate.uv[2]],
                if candidate.was_split != 0 { 2 } else { 1 },
            );
            let second = affine_triangle_error_level(
                [&projected[1], &projected[3], &projected[2]],
                [candidate.uv[1], candidate.uv[3], candidate.uv[2]],
                if candidate.was_split != 0 { 2 } else { 1 },
            );
            first.max(second) != 0
        };
        if needs_split {
            WORLD_AFFINE_SPLIT_CANDIDATES = WORLD_AFFINE_SPLIT_CANDIDATES.saturating_add(1);
            if !budget_exhausted && selected < AFFINE_PATCH_CANDIDATE_CAP {
                let admitted = if candidate.kind == AFFINE_PATCH_KIND_SEAMED_PAIR {
                    affine_request_seamed_pair_edges(keys)
                } else {
                    affine_request_patch_edges(keys, 0)
                };
                if admitted {
                    selected += 1;
                    WORLD_AFFINE_LOWEST_SELECTED_PRIORITY = candidate.screen_span;
                } else {
                    budget_exhausted = true;
                    WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY =
                        WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY.max(candidate.screen_span);
                    // Candidates are already in descending projected-edge
                    // order. Once the fixed packet budget rejects one, every
                    // later entry is lower priority; do not pay additional
                    // exact UV tests merely to rediscover that fact.
                    break;
                }
            } else {
                WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY =
                    WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY.max(candidate.screen_span);
                break;
            }
        }
        i += 1;
    }
    if WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY != 0 {
        if !budget_exhausted && selected < AFFINE_PATCH_CANDIDATE_CAP {
            // The exact-eligibility proof window was exhausted before the
            // packet budget filled. Encode an unmistakable inversion so the
            // headless regression fails instead of silently accepting a
            // potentially eligible omitted patch.
            WORLD_AFFINE_LOWEST_SELECTED_PRIORITY = 0;
        }
        WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY =
            WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY.max(WORLD_AFFINE_HIGHEST_DROPPED_PRIORITY);
    }
}

#[inline(never)]
unsafe fn sort_world_affine_next_edges() {
    let next = core::ptr::addr_of_mut!(WORLD_AFFINE_EDGE_NEXT).cast::<u32>();
    let count = WORLD_AFFINE_EDGE_NEXT_COUNT as usize;
    // Tiny deterministic insertion sort; lookup on every visible patch is then
    // a seven-comparison binary search instead of a 128-entry scan.
    let mut i = 1usize;
    while i < count {
        let value = next.add(i).read();
        let mut j = i;
        while j > 0 && next.add(j - 1).read() > value {
            next.add(j).write(next.add(j - 1).read());
            j -= 1;
        }
        next.add(j).write(value);
        i += 1;
    }
}

#[inline(never)]
unsafe fn install_world_affine_next_edges() {
    let next = core::ptr::addr_of_mut!(WORLD_AFFINE_EDGE_NEXT).cast::<u32>();
    let count = WORLD_AFFINE_EDGE_NEXT_COUNT as usize;
    let current = core::ptr::addr_of_mut!(WORLD_AFFINE_EDGE_CURRENT).cast::<u32>();
    WORLD_AFFINE_EDGE_BLOOM = [0; AFFINE_EDGE_BLOOM_WORDS];
    let mut changed = count != WORLD_AFFINE_EDGE_CURRENT_COUNT as usize;
    let mut i = 0usize;
    while i < count {
        let value = next.add(i).read();
        changed |= current.add(i).read() != value;
        current.add(i).write(value);
        let hash = (value ^ (value >> 7) ^ (value >> 15)) as usize & AFFINE_EDGE_BLOOM_MASK;
        WORLD_AFFINE_EDGE_BLOOM[hash >> 5] |= 1u32 << (hash & 31);
        i += 1;
    }
    WORLD_AFFINE_EDGE_CURRENT_COUNT = count as u8;
    if changed {
        WORLD_AFFINE_EDGE_GENERATION = WORLD_AFFINE_EDGE_GENERATION.wrapping_add(1);
    }
    WORLD_AFFINE_EDGES_PENDING = false;
}

#[inline(never)]
unsafe fn reset_world_affine_frame() {
    WORLD_AFFINE_SELECTED_COUNT = 0;
    WORLD_AFFINE_EXTRA_BUDGET_LEFT = if WORLD_CLASSIC_AFFINE_SELECTION {
        WORLD_CLASSIC_EXTRA_PACKETS
    } else {
        WORLD_AFFINE_MAX_EXTRA_PACKETS
    };
    WORLD_AFFINE_SPLIT_TRIS = 0;
    WORLD_AFFINE_ERROR_MAX_Q8 = 0;
    WORLD_AFFINE_ERROR_MAX_NUM = 0;
    WORLD_AFFINE_ERROR_MAX_DEN = 1;
    WORLD_AFFINE_ERROR_EDGE_COUNT = 0;
    WORLD_AFFINE_REMAINING_MAX_NUM = 0;
    WORLD_AFFINE_REMAINING_MAX_DEN = 1;
    WORLD_AFFINE_REMAINING_EDGE_COUNT = 0;
    WORLD_AFFINE_REMAINING_MAX_Q8 = 0;
    WORLD_AFFINE_REMAINING_P50_Q8 = 0;
    WORLD_AFFINE_REMAINING_P95_Q8 = 0;
    WORLD_AFFINE_REMAINING_P99_Q8 = 0;
    WORLD_AFFINE_ERROR_P50_Q8 = 0;
    WORLD_AFFINE_ERROR_P95_Q8 = 0;
    WORLD_AFFINE_ERROR_P99_Q8 = 0;
    WORLD_AFFINE_SPLIT_CANDIDATES = 0;
    WORLD_AFFINE_EXTRA_REQUESTED = 0;
    WORLD_AFFINE_EXTRA_EMITTED = 0;
    WORLD_AFFINE_LEVEL2_SPLITS = 0;
    WORLD_AFFINE_NATIVE_GT4 = 0;
    WORLD_AFFINE_SPLIT_PATCHES = 0;
    WORLD_AFFINE_SEAMED_SPLITS = 0;
    WORLD_AFFINE_NATIVE_TRI_SPLITS = 0;
    WORLD_AFFINE_ADDED_GTE_TRANSFORMS = 0;
    WORLD_AFFINE_ACTUAL_EXTRA_EMITTED = 0;
}

#[inline(always)]
unsafe fn finish_world_affine_candidates() {
    if !WORLD_AFFINE_RANK_FRAME {
        if WORLD_AFFINE_EDGES_PENDING {
            install_world_affine_next_edges();
        }
        return;
    }
    finish_world_affine_patch_candidates();
    sort_world_affine_next_edges();
    WORLD_AFFINE_PREVIOUS_COUNT = 0;
    if !WORLD_AFFINE_POLICY_READY {
        // Bootstrap immediately; later policies remain resident for the
        // following hold frame before their replacement is installed.
        install_world_affine_next_edges();
        WORLD_AFFINE_FORCE_RANK = true;
    } else if WORLD_CLASSIC_AFFINE_SELECTION {
        // Classic mode ranks every frame, so the hold-frame branch that
        // installs a pending edge set never runs; install immediately or the
        // seamed-pair edge set freezes at its bootstrap contents.
        install_world_affine_next_edges();
    } else {
        WORLD_AFFINE_EDGES_PENDING = true;
    }
    WORLD_AFFINE_POLICY_READY = true;
}

unsafe fn affine_selected_face_slow(face: usize) -> u8 {
    let mut lo = 0usize;
    let mut hi = WORLD_AFFINE_SELECTED_COUNT as usize;
    while lo < hi {
        let mid = (lo + hi) >> 1;
        let current = WORLD_AFFINE_PREVIOUS_FACES[mid] as usize;
        if current < face {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo < WORLD_AFFINE_SELECTED_COUNT as usize && WORLD_AFFINE_PREVIOUS_FACES[lo] as usize == face
    {
        let previous_level = WORLD_AFFINE_PREVIOUS_LEVELS[lo].min(2);
        WORLD_AFFINE_PREVIOUS_LEVELS[lo] = 0;
        return ((lo as u8) << 2) | (previous_level + 1);
    }
    0
}

#[inline(never)]
unsafe fn affine_note_split_level(selected: u8, level: u8) {
    if selected & 0x80 != 0 {
        return;
    }
    let slot = (selected >> 2) as usize;
    if slot < WORLD_AFFINE_SELECTED_COUNT as usize {
        WORLD_AFFINE_PREVIOUS_LEVELS[slot] = WORLD_AFFINE_PREVIOUS_LEVELS[slot].max(level);
    }
}

#[inline(never)]
fn affine_triangle_error_level(projected: [&Projected; 3], uv: [u16; 3], previous_level: u8) -> u8 {
    let split_threshold = affine_triangle_threshold(previous_level) as u32;
    let edges = [(0usize, 1usize), (1, 2), (2, 0)];
    let mut level = 0u8;
    let mut i = 0usize;
    while i < 3 {
        let (a, b) = edges[i];
        let (num, den) = affine_edge_error(projected[a], projected[b], uv[a], uv[b]);
        if num > den.saturating_mul(split_threshold) {
            level = 1;
        }
        i += 1;
    }
    level
}

#[inline(always)]
unsafe fn affine_triangle_eligible(projected: [&Projected; 3], texture_backdrop: bool) -> bool {
    !texture_backdrop
        && EMIT_POLICY.blend() == 0
        && !EMIT_POLICY.wave()
        && projected[0].sz >= NEAR
        && projected[1].sz >= NEAR
        && projected[2].sz >= NEAR
}

#[inline(always)]
unsafe fn affine_quad_split_level(
    packets: &PrimitivePacketArena<'_>,
    projected: [&Projected; 4],
    uv: [u16; 4],
    texture_backdrop: bool,
    previous_level: u8,
) -> u8 {
    if !affine_triangle_eligible([projected[0], projected[1], projected[2]], texture_backdrop)
        || !affine_triangle_eligible([projected[1], projected[3], projected[2]], texture_backdrop)
    {
        return 0;
    }
    if WORLD_AFFINE_EXTRA_BUDGET_LEFT < WORLD_AFFINE_NEAR_PACKET_RESERVE + 3
        || packets.remaining() < WORLD_AFFINE_PACKET_RESERVE + 4
    {
        return 0;
    }
    let first = affine_triangle_error_level(
        [projected[0], projected[1], projected[2]],
        [uv[0], uv[1], uv[2]],
        previous_level,
    );
    let second = affine_triangle_error_level(
        [projected[1], projected[3], projected[2]],
        [uv[1], uv[3], uv[2]],
        previous_level,
    );
    let level = first.max(second);
    if level == 0 {
        return 0;
    }
    let cost = 3u16;
    WORLD_AFFINE_SPLIT_CANDIDATES = WORLD_AFFINE_SPLIT_CANDIDATES.saturating_add(1);
    WORLD_AFFINE_EXTRA_REQUESTED = WORLD_AFFINE_EXTRA_REQUESTED.saturating_add(cost as u32);
    if WORLD_AFFINE_EXTRA_BUDGET_LEFT < WORLD_AFFINE_NEAR_PACKET_RESERVE + cost
        || packets.remaining() < WORLD_AFFINE_PACKET_RESERVE + cost as usize + 1
    {
        return 0;
    }
    WORLD_AFFINE_EXTRA_BUDGET_LEFT -= cost;
    level
}

#[derive(Clone, Copy)]
struct AffineVertex {
    position: Vec3I16,
    projected: Projected,
    uv: u16,
    rgb: u32,
}

const _: () = assert!(
    AFFINE_WORKSPACE_SCRATCH_OFFSET + 5 * core::mem::size_of::<AffineVertex>() <= scratchpad::SIZE
);

#[inline(always)]
const fn average_packed_bytes(a: u32, b: u32, lane_mask: u32) -> u32 {
    (a & b) + (((a ^ b) & lane_mask) >> 1)
}

#[inline(always)]
fn affine_midpoint_unprojected(va: AffineVertex, vb: AffineVertex) -> AffineVertex {
    // Sum-first averaging is symmetric when an odd edge is visited in the
    // opposite direction by its neighbouring triangle, preventing cracks.
    let avg = |x: i16, y: i16| ((x as i32 + y as i32) / 2) as i16;
    AffineVertex {
        position: Vec3I16::new(
            avg(va.position.x, vb.position.x),
            avg(va.position.y, vb.position.y),
            avg(va.position.z, vb.position.z),
        ),
        // Dense builds replace this value in groups of three before emission.
        projected: va.projected,
        uv: average_packed_bytes(va.uv as u32, vb.uv as u32, 0x0000_fefe) as u16,
        rgb: average_packed_bytes(va.rgb, vb.rgb, 0x00fe_fefe),
    }
}

#[inline(never)]
unsafe fn affine_midpoint(va: AffineVertex, vb: AffineVertex) -> AffineVertex {
    let mut vertex = affine_midpoint_unprojected(va, vb);
    ROOM_PROJECTED_COUNT = ROOM_PROJECTED_COUNT.saturating_add(1);
    WORLD_AFFINE_ADDED_GTE_TRANSFORMS = WORLD_AFFINE_ADDED_GTE_TRANSFORMS.saturating_add(1);
    vertex.projected =
        fix_projected_vertex(vertex.position, project_vertex_scheduled(vertex.position));
    vertex
}

#[cold]
#[inline(never)]
unsafe fn affine_tri_children(vertices: [AffineVertex; 3]) -> [[AffineVertex; 3]; 4] {
    let work = scratchpad::ptr_at::<AffineVertex>(AFFINE_WORKSPACE_SCRATCH_OFFSET);
    // The three source vertices already live in the by-value argument. Keep
    // only generated midpoints in scratch; duplicating the originals used six
    // unnecessary slots and made a valid 2848-plane-group recook overflow the
    // 1 KB CPU scratchpad.
    work.add(0).write(affine_midpoint(vertices[0], vertices[1]));
    work.add(1).write(affine_midpoint(vertices[1], vertices[2]));
    work.add(2).write(affine_midpoint(vertices[2], vertices[0]));
    let [a, b, c] = vertices;
    let ab = work.add(0).read();
    let bc = work.add(1).read();
    let ca = work.add(2).read();
    [[a, ab, ca], [ab, b, bc], [ca, bc, c], [ab, bc, ca]]
}

#[inline(never)]
unsafe fn push_affine_quad_gt4(
    packets: &mut PrimitivePacketArena<'_>,
    q: [&AffineVertex; 4],
    mat: TexturedGouraudPacketMaterial,
    otz: usize,
    nq: &mut usize,
) -> *mut QuadTexturedGouraud {
    // Refined children always take the refined tint: this function is only
    // reached through try_emit_native_affine_quad's subdivision path. The
    // feature-off arm keeps the original tokens exactly so a shipping build
    // stays byte-identical with the diagnostic compiled out.
    #[cfg(not(feature = "seam-census"))]
    let prim = QuadTexturedGouraud::with_packet_material_packed_uv_words(
        [
            (q[0].projected.sx, q[0].projected.sy),
            (q[1].projected.sx, q[1].projected.sy),
            (q[2].projected.sx, q[2].projected.sy),
            (q[3].projected.sx, q[3].projected.sy),
        ],
        [q[0].uv, q[1].uv, q[2].uv, q[3].uv],
        [
            unpack_rgb_word(q[0].rgb),
            unpack_rgb_word(q[1].rgb),
            unpack_rgb_word(q[2].rgb),
            unpack_rgb_word(q[3].rgb),
        ],
        mat,
    );
    #[cfg(feature = "seam-census")]
    let prim = {
        let census_rgb = |rgb: u32| {
            unpack_rgb_word(if SEAM_CENSUS_TINT != 0 {
                SEAM_CENSUS_REFINED
            } else {
                rgb
            })
        };
        QuadTexturedGouraud::with_packet_material_packed_uv_words(
            [
                (q[0].projected.sx, q[0].projected.sy),
                (q[1].projected.sx, q[1].projected.sy),
                (q[2].projected.sx, q[2].projected.sy),
                (q[3].projected.sx, q[3].projected.sy),
            ],
            [q[0].uv, q[1].uv, q[2].uv, q[3].uv],
            [
                census_rgb(q[0].rgb),
                census_rgb(q[1].rgb),
                census_rgb(q[2].rgb),
                census_rgb(q[3].rgb),
            ],
            mat,
        )
    };
    // Every caller enters through try_emit_native_affine_quad, which reserves
    // the complete build-selected child count before subdivision begins.
    let packet = packets.push_unchecked(prim);
    world_cache_capture_packet(packet as *const QuadTexturedGouraud, otz, true);
    tram_cache_capture_quad(packet as *const QuadTexturedGouraud, otz);
    *nq += 1;
    packet
}

#[inline(never)]
#[optimize(size)]
unsafe fn emit_affine_quad_child(
    packets: &mut PrimitivePacketArena<'_>,
    q: [&AffineVertex; 4],
    mat: TexturedGouraudPacketMaterial,
    nq: &mut usize,
) -> bool {
    if EMIT_POLICY.tram_grid() {
        let area = |a: &Projected, b: &Projected, c: &Projected| -> i32 {
            (b.sx as i32 - a.sx as i32) * (c.sy as i32 - a.sy as i32)
                - (b.sy as i32 - a.sy as i32) * (c.sx as i32 - a.sx as i32)
        };
        let w0 = area(&q[0].projected, &q[1].projected, &q[2].projected);
        let w1 = area(&q[1].projected, &q[3].projected, &q[2].projected);
        let safe = q.iter().all(|v| {
            v.projected.sz >= NEAR
                && render::in_band_xy(v.projected.sx as i32, v.projected.sy as i32)
        }) && w0 != 0
            && w1 != 0
            && (w0 > 0) == (w1 > 0);
        if !safe {
            let corner = |i: usize| {
                let v = scene::transform_vertex_scheduled(q[i].position);
                let rgb = unpack_rgb_word(q[i].rgb);
                render::CVert {
                    v: [v.x, v.y, v.z],
                    rgb: (rgb.0 as i32, rgb.1 as i32, rgb.2 as i32),
                    uv: uv_word_pair_i32(q[i].uv),
                }
            };
            let c = [corner(0), corner(1), corner(2), corner(3)];
            emit_cv_flat(packets, [&c[0], &c[1], &c[2]], mat, nq);
            emit_cv_flat(packets, [&c[1], &c[3], &c[2]], mat, nq);
            return true;
        }
        if CULL && w0 >= 0 {
            return true;
        }
    }
    #[cfg(feature = "performance-telemetry")]
    if affine_heatmap_active() {
        affine_record_remaining_triangle(
            [&q[0].projected, &q[1].projected, &q[2].projected],
            [q[0].uv, q[1].uv, q[2].uv],
        );
        affine_record_remaining_triangle(
            [&q[1].projected, &q[3].projected, &q[2].projected],
            [q[1].uv, q[3].uv, q[2].uv],
        );
    }
    #[cfg(feature = "performance-telemetry")]
    if affine_heatmap_active() {
        let otz = world_order_key(
            ordering::PrimitiveDepths::quad(
                q[0].projected.sz as i32,
                q[1].projected.sz as i32,
                q[2].projected.sz as i32,
                q[3].projected.sz as i32,
            ),
            false,
        );
        let first = push_affine_heatmap_tri(
            packets,
            [&q[0].projected, &q[1].projected, &q[2].projected],
            [q[0].uv, q[1].uv, q[2].uv],
            otz,
            nq,
        );
        let second = push_affine_heatmap_tri(
            packets,
            [&q[1].projected, &q[3].projected, &q[2].projected],
            [q[1].uv, q[3].uv, q[2].uv],
            otz,
            nq,
        );
        return first || second;
    }
    let otz = world_order_key(
        ordering::PrimitiveDepths::quad(
            q[0].projected.sz as i32,
            q[1].projected.sz as i32,
            q[2].projected.sz as i32,
            q[3].projected.sz as i32,
        ),
        false,
    );
    let packet = push_affine_quad_gt4(packets, q, mat, otz, nq);
    OT.add(otz, &mut *packet, QuadTexturedGouraud::WORDS);
    true
}

#[inline(never)]
unsafe fn emit_affine_quad_children(
    packets: &mut PrimitivePacketArena<'_>,
    vertices: [AffineVertex; 4],
    mat: TexturedGouraudPacketMaterial,
    nq: &mut usize,
) {
    let work = scratchpad::ptr_at::<AffineVertex>(AFFINE_WORKSPACE_SCRATCH_OFFSET);
    // Preserve only the five generated grid points. The four source corners
    // remain in `vertices` and cost no scratchpad duplication. All five
    // midpoints are known in 3D before any projection, so two RTPT batches
    // replace five separate scheduled RTPS calls (pixel-identical GTE math;
    // this function measured 1.6% of the moving frame as single RTPS).
    let mut top = affine_midpoint_unprojected(vertices[0], vertices[1]);
    let mut left = affine_midpoint_unprojected(vertices[0], vertices[2]);
    let mut right = affine_midpoint_unprojected(vertices[1], vertices[3]);
    let mut bottom = affine_midpoint_unprojected(vertices[2], vertices[3]);
    let mut center = affine_midpoint_unprojected(top, bottom);
    let p = project_triangle_scheduled(top.position, left.position, right.position);
    top.projected = fix_projected_vertex(top.position, p[0]);
    left.projected = fix_projected_vertex(left.position, p[1]);
    right.projected = fix_projected_vertex(right.position, p[2]);
    let p = project_triangle_scheduled(bottom.position, center.position, center.position);
    bottom.projected = fix_projected_vertex(bottom.position, p[0]);
    center.projected = fix_projected_vertex(center.position, p[1]);
    ROOM_PROJECTED_COUNT = ROOM_PROJECTED_COUNT.saturating_add(5);
    WORLD_AFFINE_ADDED_GTE_TRANSFORMS = WORLD_AFFINE_ADDED_GTE_TRANSFORMS.saturating_add(5);
    work.add(0).write(top);
    work.add(1).write(left);
    work.add(2).write(right);
    work.add(3).write(bottom);
    work.add(4).write(center);
    let top = &*work.add(0);
    let left = &*work.add(1);
    let right = &*work.add(2);
    let bottom = &*work.add(3);
    let center = &*work.add(4);
    let children = [
        [&vertices[0], top, left, center],
        [top, &vertices[1], center, right],
        [left, center, &vertices[2], bottom],
        [center, right, bottom, &vertices[3]],
    ];

    // Diagnostic heatmaps replace every GT4 with two GT3s, so retain their
    // existing per-child insertion path. The shipping path below emits the
    // same four GT4s in the same order.
    if affine_heatmap_active() || EMIT_POLICY.tram_grid() {
        let mut child = 0usize;
        while child < children.len() {
            emit_affine_quad_child(packets, children[child], mat, nq);
            child += 1;
        }
        return;
    }

    // The four children are one persistent source patch. Give the complete
    // patch one coarse depth key and prelink its resident packet run, avoiding
    // three redundant depth calculations and OT read/modify/write operations.
    let otz = world_order_key(
        ordering::PrimitiveDepths::quad(
            vertices[0].projected.sz as i32,
            vertices[1].projected.sz as i32,
            vertices[2].projected.sz as i32,
            vertices[3].projected.sz as i32,
        ),
        false,
    );
    let mut run = [core::ptr::null_mut::<QuadTexturedGouraud>(); 4];
    let mut child = 0usize;
    while child < children.len() {
        run[child] = push_affine_quad_gt4(packets, children[child], mat, otz, nq);
        child += 1;
    }

    // Match four sequential OT.add calls with one table-head update. Each
    // packet points at the previous packet in the run, preserving the original
    // child order when the GPU traverses the list.
    const OT_ADDR_MASK: u32 = 0x00ff_ffff;
    let slot = otz.min(OT_LEN - 1);
    let entries = core::ptr::addr_of_mut!(OT).cast::<u32>();
    let mut next = core::ptr::read_volatile(entries.add(slot)) & OT_ADDR_MASK;
    let mut packet = 0usize;
    while packet < run.len() {
        core::ptr::write_volatile(
            run[packet].cast::<u32>(),
            ((QuadTexturedGouraud::WORDS as u32) << 24) | next,
        );
        next = run[packet] as u32 & OT_ADDR_MASK;
        packet += 1;
    }
    core::ptr::write_volatile(entries.add(slot), next);
}

/// Classic stateless native decision, hoisted out of `rank_affine_patch` so
/// native patches skip the edge-key canonicalisation and bloom probes
/// entirely -- edge consensus is unused under classic (the underlay papers
/// T-junctions). Ordered cheapest-first: eligibility flags, the near-presence
/// span test, then the four rational edge errors with early exit.
#[inline(never)]
unsafe fn classic_native_patch_mask(
    projected: [Projected; 4],
    uv: [u16; 4],
    texture_backdrop: bool,
    blocked_edges: u8,
) -> u8 {
    if blocked_edges != 0 && !WORLD_CLASSIC_SPLIT_BLOCKED {
        return 0;
    }
    if !affine_triangle_eligible(
        [&projected[0], &projected[1], &projected[2]],
        texture_backdrop,
    ) || !affine_triangle_eligible(
        [&projected[1], &projected[3], &projected[2]],
        texture_backdrop,
    ) {
        return 0;
    }
    let near_depth = projected
        .iter()
        .map(|p| p.sz as i32)
        .min()
        .unwrap_or(i32::MAX);
    if near_depth < RANKED_NEAR_PRESENCE_Z {
        let edge_span = |a: &Projected, b: &Projected| {
            (a.sx as i32 - b.sx as i32)
                .abs()
                .max((a.sy as i32 - b.sy as i32).abs())
        };
        let screen_span = edge_span(&projected[0], &projected[1])
            .max(edge_span(&projected[1], &projected[3]))
            .max(edge_span(&projected[3], &projected[2]))
            .max(edge_span(&projected[2], &projected[0]));
        if screen_span > RANKED_NEAR_PRESENCE_SPAN_PX {
            return 0x0f;
        }
    }
    let edge_over = |a: usize, b: usize| {
        let (n, d) = affine_edge_error(&projected[a], &projected[b], uv[a], uv[b]);
        n as u64 >= WORLD_AFFINE_SPLIT_ERROR_TEXELS as u64 * d.max(1) as u64
    };
    if edge_over(0, 1) || edge_over(1, 3) || edge_over(3, 2) || edge_over(2, 0) {
        0x0f
    } else {
        0
    }
}

#[inline(never)]
unsafe fn rank_affine_patch(
    indices: [u16; 4],
    projected: [Projected; 4],
    uv: [u16; 4],
    texture_backdrop: bool,
    blocked_edges: u8,
    kind: u8,
) -> u8 {
    if WORLD_CLASSIC_AFFINE_SELECTION && kind == AFFINE_PATCH_KIND_NATIVE {
        return classic_native_patch_mask(projected, uv, texture_backdrop, blocked_edges);
    }
    let boundary_keys = affine_quad_edge_keys(indices);
    let current_mask = affine_current_edge_mask(boundary_keys, blocked_edges);
    let was_split = current_mask == 0x0f;
    // Blocked patches may conform to a selected neighbour through their
    // unblocked edges, but they can never enter the next-frame root shortlist.
    // Return that exact ownership mask before doing screen-span, depth, and
    // affine-error ranking work which the final eligibility gate would reject.
    // Classic coverage admits them (underlay papers the reopened T-junction).
    if blocked_edges != 0 && !(WORLD_CLASSIC_AFFINE_SELECTION && WORLD_CLASSIC_SPLIT_BLOCKED) {
        return current_mask;
    }
    if !WORLD_AFFINE_RANK_FRAME {
        return current_mask;
    }
    let edge_span = |a: &Projected, b: &Projected| {
        (a.sx as i32 - b.sx as i32)
            .abs()
            .max((a.sy as i32 - b.sy as i32).abs())
    };
    let screen_span = edge_span(&projected[0], &projected[1])
        .max(edge_span(&projected[1], &projected[3]))
        .max(edge_span(&projected[3], &projected[2]))
        .max(edge_span(&projected[2], &projected[0]));

    // Rank and gate by the nearest visible corner, not the arithmetic centre.
    // A large floor/wall patch can reach the camera while its centre remains
    // hundreds of units away; centre depth therefore let smaller, farther
    // patches consume the budget first even though ordering was deterministic.
    let near_depth = projected
        .iter()
        .map(|p| p.sz as i32)
        .min()
        .unwrap_or(i32::MAX);
    // One rule for the whole renderer: a patch is refined when its MEASURED
    // affine error exceeds a texel, never because it happens to be large on
    // screen. Screen span and depth are the inputs to that error, so gating on
    // them directly needed enter/leave hysteresis to stop a surface flipping
    // tessellation as the camera turned. The error is continuous, so it does
    // not.
    let over =
        |n: u32, d: u32| n as u64 >= WORLD_AFFINE_SPLIT_ERROR_TEXELS as u64 * d.max(1) as u64;
    let edge_over = |a: usize, b: usize| {
        let (n, d) = affine_edge_error(&projected[a], &projected[b], uv[a], uv[b]);
        over(n, d)
    };
    let near_presence =
        near_depth < RANKED_NEAR_PRESENCE_Z && screen_span > RANKED_NEAR_PRESENCE_SPAN_PX;
    let large_and_close =
        near_presence || edge_over(0, 1) || edge_over(1, 3) || edge_over(3, 2) || edge_over(2, 0);
    if large_and_close
        && affine_triangle_eligible(
            [&projected[0], &projected[1], &projected[2]],
            texture_backdrop,
        )
        && affine_triangle_eligible(
            [&projected[1], &projected[3], &projected[2]],
            texture_backdrop,
        )
    {
        affine_rank_patch_candidate(AffinePatchCandidate {
            indices,
            uv,
            key0: boundary_keys[0],
            near_depth: near_depth.clamp(0, u16::MAX as i32) as u16,
            screen_span: screen_span.clamp(0, u16::MAX as i32) as u16,
            was_split: was_split as u8,
            kind,
        });
    }
    current_mask
}

/// Underlay for a perspective-refined native patch: its unrefined corner quad
/// with straight screen edges, pushed AFTER the children so it draws first
/// within its depth bucket. A refined boundary chain bows off a neighbouring
/// face's straight chord (the cook refines one side of such shared edges);
/// the bow wedge otherwise rasterizes as a dashed black line.
#[inline(never)]
#[optimize(size)]
unsafe fn push_patch_underlay(
    packets: &mut PrimitivePacketArena<'_>,
    projected: [Projected; 4],
    uv: [u16; 4],
    rgb: [u32; 4],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    nq: &mut usize,
) {
    let (mut p0, mut p1, mut p2, mut p3) = (projected[0], projected[1], projected[2], projected[3]);
    let out = render::quad_underlay_corners(projected.map(|p| (p.sx, p.sy)));
    p0.sx = out[0].0;
    p0.sy = out[0].1;
    p1.sx = out[1].0;
    p1.sy = out[1].1;
    p2.sx = out[2].0;
    p2.sy = out[2].1;
    p3.sx = out[3].0;
    p3.sy = out[3].1;
    let prim = QuadTexturedGouraud {
        tag: 0,
        tex_window: mat.tex_window_word,
        color0_cmd: (mat.color0_command_word | 0x0800_0000) | rgb[0],
        v0: pack_vertex_word(p0.sx, p0.sy),
        uv0_clut: uv[0] as u32 | mat.clut_high_word,
        color1: rgb[1],
        v1: pack_vertex_word(p1.sx, p1.sy),
        uv1_tpage: uv[1] as u32 | mat.tpage_high_word,
        color2: rgb[2],
        v2: pack_vertex_word(p2.sx, p2.sy),
        uv2: uv[2] as u32,
        color3: rgb[3],
        v3: pack_vertex_word(p3.sx, p3.sy),
        uv3: uv[3] as u32,
    };
    let Some(packet) = packets.push(prim) else {
        note_render_packet_drop(false);
        return;
    };
    let otz = world_order_key(
        ordering::PrimitiveDepths::quad(p0.sz as i32, p1.sz as i32, p2.sz as i32, p3.sz as i32),
        texture_backdrop,
    );
    world_cache_capture_packet(packet as *const QuadTexturedGouraud, otz, true);
    OT.add(otz, packet, QuadTexturedGouraud::WORDS);
    *nq += 1;
}

/// Shipping variant: byte-for-byte the pre-split monolith, so the mask /
/// emission split above cannot shift the shipping renderer's code layout on
/// the 4 KiB direct-mapped I-cache (a relinked layout alone measured -8 flips
/// of pure alignment noise on the frozen tape).

#[inline(never)]
unsafe fn try_emit_native_affine_quad(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    indices: [u16; 4],
    projected: [Projected; 4],
    uv: [u16; 4],
    rgb: [u32; 4],
    mat: TexturedGouraudPacketMaterial,
    texture_backdrop: bool,
    _previous_level: u8,
    blocked_edges: u8,
    patch_state: usize,
    nq: &mut usize,
) -> bool {
    let current_mask = if !WORLD_AFFINE_RANK_FRAME && patch_state != usize::MAX {
        if m.patch_subdiv_active(patch_state) {
            1
        } else {
            0
        }
    } else {
        let mask = rank_affine_patch(
            indices,
            projected,
            uv,
            texture_backdrop,
            blocked_edges,
            AFFINE_PATCH_KIND_NATIVE,
        );
        if patch_state != usize::MAX {
            m.set_patch_subdiv_active(patch_state, mask != 0);
        }
        mask
    };
    // A runtime patch has exactly two valid topologies: the original logical
    // quad, or the build-selected regular grid. A complete mask is a selected
    // root; a partial mask is an edge-sharing neighbour that must use the same
    // grid. The old partial path ear-clipped those neighbours into long,
    // camera-dependent triangles.
    if current_mask == 0 {
        return false;
    }
    // Second classic band: a split-worthy patch still measuring severe error
    // after one 2x2 level would leave its children visibly warped; hand it to
    // the recursive screen-bounded quadtree via the caller's soft fallback.
    if WORLD_CLASSIC_AFFINE_SELECTION
        && (packets.remaining() < WORLD_CLASSIC_ARENA_FLOOR || WORLD_AFFINE_EXTRA_BUDGET_LEFT < 6)
    {
        return false;
    }
    // A fixed 4x4 lattice for the severe band was MEASURED WORSE than the
    // adaptive quadtree on both quality-per-budget and CPU (hallway saturated
    // pixels above baseline, p50 +11%): the tree spends packets only where
    // the error rule demands. Severe stays on the capped quadtree route.
    if WORLD_CLASSIC_AFFINE_SELECTION
        && WORLD_CLASSIC_SOFT_ROUTES_LEFT != 0
        && WORLD_AFFINE_EXTRA_BUDGET_LEFT >= WORLD_CLASSIC_SOFT_ROUTE_COST
    {
        let severe = |a: usize, b: usize| {
            let (n, d) = affine_edge_error(&projected[a], &projected[b], uv[a], uv[b]);
            n as u64 >= WORLD_CLASSIC_SEVERE_ERROR_TEXELS as u64 * d.max(1) as u64
        };
        if severe(0, 1) || severe(1, 3) || severe(3, 2) || severe(2, 0) {
            WORLD_CLASSIC_SOFT_ROUTES_LEFT -= 1;
            WORLD_AFFINE_EXTRA_BUDGET_LEFT -=
                WORLD_CLASSIC_SOFT_ROUTE_COST.min(WORLD_AFFINE_EXTRA_BUDGET_LEFT);
            WORLD_CLASSIC_WANTS_SOFT = true;
            return false;
        }
    }
    // Read the world positions only now. `rank_affine_patch` rejects the large
    // majority of patches, and four unaligned vertex fetches per rejected quad
    // is real traffic in the densest views.
    let positions = [
        m.vert(indices[0] as usize),
        m.vert(indices[1] as usize),
        m.vert(indices[2] as usize),
        m.vert(indices[3] as usize),
    ];
    let vertices = [
        AffineVertex {
            position: positions[0],
            projected: projected[0],
            uv: uv[0],
            rgb: rgb[0],
        },
        AffineVertex {
            position: positions[1],
            projected: projected[1],
            uv: uv[1],
            rgb: rgb[1],
        },
        AffineVertex {
            position: positions[2],
            projected: projected[2],
            uv: uv[2],
            rgb: rgb[2],
        },
        AffineVertex {
            position: positions[3],
            projected: projected[3],
            uv: uv[3],
            rgb: rgb[3],
        },
    ];
    if packets.remaining() < WORLD_AFFINE_PACKET_RESERVE + WORLD_AFFINE_NATIVE_EMIT_PACKETS {
        return false;
    }
    let before = *nq;
    emit_affine_quad_children(packets, vertices, mat, nq);
    let emitted = nq.saturating_sub(before) as u32;
    if emitted != 0 {
        // Skip the underlay skirt when every projected 2x2 edge midpoint
        // landed exactly on its parent chord: the children then rasterize the
        // parent's exact boundary, a crack is geometrically impossible, and
        // the skirt is one wasted packet per split.
        let skip_underlay = WORLD_CLASSIC_AFFINE_SELECTION && {
            let work = scratchpad::ptr_at::<AffineVertex>(AFFINE_WORKSPACE_SCRATCH_OFFSET);
            let collinear = |a: &Projected, b: &Projected, i: usize| {
                let m = (*work.add(i)).projected;
                (b.sx as i32 - a.sx as i32) * (m.sy as i32 - a.sy as i32)
                    == (b.sy as i32 - a.sy as i32) * (m.sx as i32 - a.sx as i32)
            };
            collinear(&projected[0], &projected[1], 0)
                && collinear(&projected[0], &projected[2], 1)
                && collinear(&projected[1], &projected[3], 2)
                && collinear(&projected[2], &projected[3], 3)
        };
        if !skip_underlay {
            push_patch_underlay(packets, projected, uv, rgb, mat, texture_backdrop, nq);
        }
    }
    if WORLD_CLASSIC_AFFINE_SELECTION {
        // Spend the counted classic budget: everything this split emitted
        // beyond the single quad the patch would have cost anyway.
        let extras = (nq.saturating_sub(before) as u16).saturating_sub(1);
        WORLD_AFFINE_EXTRA_BUDGET_LEFT -= extras.min(WORLD_AFFINE_EXTRA_BUDGET_LEFT);
    }
    WORLD_AFFINE_NATIVE_GT4 = WORLD_AFFINE_NATIVE_GT4.saturating_add(emitted);
    WORLD_AFFINE_SPLIT_PATCHES = WORLD_AFFINE_SPLIT_PATCHES.saturating_add(1);
    WORLD_AFFINE_SPLIT_TRIS = WORLD_AFFINE_SPLIT_TRIS.saturating_add(emitted.saturating_mul(2));
    WORLD_AFFINE_EXTRA_EMITTED =
        WORLD_AFFINE_EXTRA_EMITTED.saturating_add(emitted.saturating_sub(1));
    WORLD_AFFINE_ACTUAL_EXTRA_EMITTED = WORLD_AFFINE_ACTUAL_EXTRA_EMITTED
        .saturating_add(emitted.saturating_sub(1).min(u16::MAX as u32) as u16);
    emitted != 0
}

/// Studio models use one tint per draw, so test the actor centre once and
/// brighten the whole model in three angular/depth bands. This is deliberately
/// cheaper than touching every HMD8 face and shares the world beam's occlusion.
#[inline]
fn flashlight_model_shade(base: u8, center: [i32; 3], eye: [i32; 3], rot: &Mat3I16) -> u8 {
    if !unsafe { FLASHLIGHT_ON } {
        return base;
    }
    let rel = [center[0] - eye[0], center[1] - eye[1], center[2] - eye[2]];
    let z = dot12(rot.m[2], rel);
    if z <= 0 || z >= FLASH_RANGE || z > unsafe { FLASHLIGHT_REACH } as i32 + FLASH_OCCLUSION_SLOP {
        return base;
    }
    let x = dot12(rot.m[0], rel).abs();
    let y = dot12(rot.m[1], rel).abs();
    let radial = x.max(y) + (x.min(y) >> 1);
    if radial * 2 >= z {
        return base;
    }
    let angular = if radial * 8 <= z {
        70
    } else if radial * 4 <= z {
        48
    } else {
        28
    };
    let lift = if z < 256 {
        angular
    } else if z < 480 {
        angular * 3 / 4
    } else {
        angular / 2
    };
    base.saturating_add(lift as u8)
}

#[inline(always)]
unsafe fn emit_proj_fast(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tt: usize,
    pa: Projected,
    pb: Projected,
    pc: Projected,
    np: &mut usize,
    affine_previous_level: u8,
) -> bool {
    let clamped = |q: &Projected| q.sx <= -1023 || q.sx >= 1023 || q.sy <= -1023 || q.sy >= 1023;
    if pa.sz >= NEAR
        && pb.sz >= NEAR
        && pc.sz >= NEAR
        && render::tri_outside_band([(pa.sx, pa.sy), (pb.sx, pb.sy), (pc.sx, pc.sy)])
    {
        return true;
    }
    if pa.sz >= NEAR
        && pb.sz >= NEAR
        && pc.sz >= NEAR
        && !clamped(&pa)
        && !clamped(&pb)
        && !clamped(&pc)
    {
        let (sa, sb, sc) = (
            (pa.sx as i32, pa.sy as i32),
            (pb.sx as i32, pb.sy as i32),
            (pc.sx as i32, pc.sy as i32),
        );
        let tex = m.tri_tex(tt);
        if CULL && culled(sa, sb, sc) {
            return true;
        }
        if tex >= m.n_texs || tex >= MAX_TEX_SLOTS {
            return true;
        }
        let slot = &*tex_slot_ptr(tex);
        if !slot.valid {
            return true;
        }
        let otz = world_order_key(
            ordering::PrimitiveDepths::tri(pa.sz as i32, pb.sz as i32, pc.sz as i32),
            slot.backdrop,
        );
        let mut rgb = fog_world_rgb(
            m.tri_rgb_words(tt),
            [pa.sz as i32, pb.sz as i32, pc.sz as i32],
            slot.backdrop,
        );
        if FLASHLIGHT_ON && !slot.backdrop {
            let p = [pa, pb, pc];
            shade_world_rgb(&mut rgb, &p);
        }
        let uv = sway_uv3(m.tri_uv_words(tt));
        #[cfg(feature = "performance-telemetry")]
        if affine_heatmap_active() {
            let _ = affine_triangle_error([&pa, &pb, &pc], uv);
        }
        #[cfg(feature = "performance-telemetry")]
        if affine_heatmap_active() {
            affine_record_remaining_triangle([&pa, &pb, &pc], uv);
        }
        #[cfg(feature = "performance-telemetry")]
        if affine_heatmap_active() {
            push_affine_heatmap_tri(packets, [&pa, &pb, &pc], uv, otz, np);
            return true;
        }
        if !tri_fits_gpu(&pa, &pb, &pc) {
            push_tri_gpu_split(
                packets,
                np,
                [(pa.sx, pa.sy), (pb.sx, pb.sy), (pc.sx, pc.sy)],
                uv,
                rgb,
                [pa.sz as i32, pb.sz as i32, pc.sz as i32],
                slot.backdrop,
                emit_packet_of(slot, tex),
                0,
            );
            return true;
        }
        push_tri_uv_words_packed(
            packets,
            np,
            [(pa.sx, pa.sy), (pb.sx, pb.sy), (pc.sx, pc.sy)],
            uv,
            rgb,
            emit_packet_of(slot, tex),
            otz,
        );
        return true;
    }
    // All-behind-camera counts as handled (nothing to draw); otherwise straddler.
    pa.sz == 0 && pb.sz == 0 && pc.sz == 0
}

/// The GPU rejects primitives wider than 1023 px or taller than 511 px
/// outright (silicon, and PSoXide models it). Grazing floor views project
/// in-clamp-range triangles 700+ px tall; pushed raw they vanish wholesale
/// (the hardware "missing polygon" holes).
#[inline]
fn tri_fits_gpu(pa: &Projected, pb: &Projected, pc: &Projected) -> bool {
    let (min_x, max_x) = (
        (pa.sx).min(pb.sx).min(pc.sx) as i32,
        (pa.sx).max(pb.sx).max(pc.sx) as i32,
    );
    let (min_y, max_y) = (
        (pa.sy).min(pb.sy).min(pc.sy) as i32,
        (pa.sy).max(pb.sy).max(pc.sy) as i32,
    );
    max_x - min_x <= 1023 && max_y - min_y <= 511
}

/// Screen-space bisection for GPU-oversized triangles. Affine interpolation
/// is linear in screen space, so splitting the longest edge at its screen
/// midpoint with lerped UV/RGB rasterizes the same surface. Children remain
/// ordinary fast-path packets through push_tri_uv_words_packed -- identical
/// emission pattern, so the tram/world packet caches never notice (rerouting
/// these to the soft path is what corrupted the tram ride in the reverted
/// 0036c99). Each level halves the longest span: depth 4 covers +-1023.
#[allow(clippy::too_many_arguments)]
#[inline(never)]
unsafe fn push_tri_gpu_split(
    packets: &mut PrimitivePacketArena<'_>,
    np: &mut usize,
    screen: [(i16, i16); 3],
    uv: [u16; 3],
    rgb: [u32; 3],
    sz: [i32; 3],
    texture_backdrop: bool,
    mat: TexturedGouraudPacketMaterial,
    depth: u8,
) {
    // Wholly outside the 320x240 draw area: neither this triangle nor any
    // child can rasterize a pixel. The near-clip reroute keeps each source
    // triangle's full footprint (the old path screen-clipped first), so
    // grazing walls otherwise spawn large off-screen subtrees that cost
    // packets, OT links and DMA for nothing. Pruning here is pixel-identical
    // and prunes the entire subtree in one test.
    if (screen[0].0 < 0 && screen[1].0 < 0 && screen[2].0 < 0)
        || (screen[0].0 >= 320 && screen[1].0 >= 320 && screen[2].0 >= 320)
        || (screen[0].1 < 0 && screen[1].1 < 0 && screen[2].1 < 0)
        || (screen[0].1 >= 240 && screen[1].1 >= 240 && screen[2].1 >= 240)
    {
        return;
    }
    // A frame that needed GPU-size splitting must not be served from the
    // world packet cache: the standstill replay measurably loses the split
    // children. Strong invalidation: the overflow flag alone still let the
    // ROOM_ONLY salvage replay a prefix missing these children.
    if depth == 0 {
        WORLD_CACHE_OVERFLOW = true;
        invalidate_world_packet_cache();
    }
    // Edge-local split rule (crack-free): identical verdicts on both sides
    // of a shared edge, geometry-only. Midpoint XY stays the plain screen
    // midpoint (children tile the straight chord); depth is the harmonic
    // mean and UV/RGB the depth-swapped weighting -- perspective-correct at
    // that screen point.
    //
    // PERF: hottest render symbol on the tram ride as first written (21.7%
    // of CPU). No `%` indexing (modulo is a hardware divide on MIPS) and a
    // single 24-bit reciprocal replaces the three divides per midpoint;
    // outputs are bit-identical to the divide form for view-range depths.
    let span = |a: usize, b: usize| -> i32 {
        let dx = (screen[a].0 as i32 - screen[b].0 as i32).abs();
        let dy = (screen[a].1 as i32 - screen[b].1 as i32).abs();
        dx.max(dy)
    };
    let warp_ok = depth < 2;
    let edge_split = |sp: i32, za: i32, zb: i32| -> bool {
        if sp > 250 {
            return true;
        }
        if !warp_ok || sp <= 96 {
            return false;
        }
        let (zmin, zmax) = if za < zb { (za, zb) } else { (zb, za) };
        zmax > zmin * 2
    };
    let split = [
        edge_split(span(0, 1), sz[0], sz[1]),
        edge_split(span(1, 2), sz[1], sz[2]),
        edge_split(span(2, 0), sz[2], sz[0]),
    ];
    if depth >= 6 || (!split[0] && !split[1] && !split[2]) {
        let otz = world_order_key(
            ordering::PrimitiveDepths::tri(sz[0], sz[1], sz[2]),
            texture_backdrop,
        );
        push_tri_uv_words_packed(packets, np, screen, uv, rgb, mat, otz);
        return;
    }
    // Perimeter polygon (corners + split-edge midpoints, winding order),
    // fanned from the first midpoint. Wrap indices by subtract, never `%`.
    let mut pxy: [(i16, i16); 6] = [(0, 0); 6];
    let mut puv: [u16; 6] = [0; 6];
    let mut prgb: [u32; 6] = [0; 6];
    let mut pz: [i32; 6] = [0; 6];
    let mut anchor = usize::MAX;
    let mut pn = 0usize;
    let mut k = 0usize;
    while k < 3 {
        pxy[pn] = screen[k];
        puv[pn] = uv[k];
        prgb[pn] = rgb[k];
        pz[pn] = sz[k];
        pn += 1;
        if split[k] {
            let b = if k == 2 { 0 } else { k + 1 };
            let (za, zb) = (sz[k].max(1), sz[b].max(1));
            let d = za + zb;
            let z = ((2 * za * zb) / d).max(1);
            let (ua, va) = ((uv[k] & 0xff) as i32, (uv[k] >> 8) as i32);
            let (ub, vb) = ((uv[b] & 0xff) as i32, (uv[b] >> 8) as i32);
            let mu = ((ua * zb + ub * za + (d >> 1)) / d).clamp(0, 255) as u16;
            let mv = ((va * zb + vb * za + (d >> 1)) / d).clamp(0, 255) as u16;
            let (ra, rb) = (rgb[k], rgb[b]);
            pxy[pn] = (
                (((screen[k].0 as i32) + (screen[b].0 as i32)) >> 1) as i16,
                (((screen[k].1 as i32) + (screen[b].1 as i32)) >> 1) as i16,
            );
            puv[pn] = mu | (mv << 8);
            prgb[pn] = (((ra & 0xff) + (rb & 0xff) + 1) >> 1)
                | (((((ra >> 8) & 0xff) + ((rb >> 8) & 0xff) + 1) >> 1) << 8)
                | (((((ra >> 16) & 0xff) + ((rb >> 16) & 0xff) + 1) >> 1) << 16);
            pz[pn] = z;
            if anchor == usize::MAX {
                anchor = pn;
            }
            pn += 1;
        }
        k += 1;
    }
    let mut i1 = anchor + 1;
    if i1 >= pn {
        i1 -= pn;
    }
    let mut k = 1usize;
    while k + 1 < pn {
        let mut i2 = i1 + 1;
        if i2 >= pn {
            i2 -= pn;
        }
        push_tri_gpu_split(
            packets,
            np,
            [pxy[anchor], pxy[i1], pxy[i2]],
            [puv[anchor], puv[i1], puv[i2]],
            [prgb[anchor], prgb[i1], prgb[i2]],
            [pz[anchor], pz[i1], pz[i2]],
            texture_backdrop,
            mat,
            depth + 1,
        );
        i1 = i2;
        k += 1;
    }
}

// Inlined into its two loop callers on purpose: as an out-of-line call this
// streamed 3.2 KiB through the 4 KiB I-cache on every world triangle, which
// measured -1.0% on the tram-ride benchmark. Funded from BEAM_FX_TRIM.
#[inline(always)]
unsafe fn emit_proj_fast_tri(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tri: &map::RenderTri,
    pa: Projected,
    pb: Projected,
    pc: Projected,
    np: &mut usize,
    affine_previous_level: u8,
) -> bool {
    let clamped = |q: &Projected| q.sx <= -1023 || q.sx >= 1023 || q.sy <= -1023 || q.sy >= 1023;
    if pa.sz >= NEAR
        && pb.sz >= NEAR
        && pc.sz >= NEAR
        && render::tri_outside_band([(pa.sx, pa.sy), (pb.sx, pb.sy), (pc.sx, pc.sy)])
    {
        return true;
    }
    if pa.sz >= NEAR
        && pb.sz >= NEAR
        && pc.sz >= NEAR
        && !clamped(&pa)
        && !clamped(&pb)
        && !clamped(&pc)
    {
        let (sa, sb, sc) = (
            (pa.sx as i32, pa.sy as i32),
            (pb.sx as i32, pb.sy as i32),
            (pc.sx as i32, pc.sy as i32),
        );
        if CULL && culled(sa, sb, sc) {
            return true;
        }
        if tri.tex >= m.n_texs || tri.tex >= MAX_TEX_SLOTS {
            return true;
        }
        let slot = &*tex_slot_ptr(tri.tex);
        if !slot.valid {
            return true;
        }
        let otz = world_order_key(
            ordering::PrimitiveDepths::tri(pa.sz as i32, pb.sz as i32, pc.sz as i32),
            slot.backdrop,
        );
        let mut rgb = fog_world_rgb(
            tri.rgb,
            [pa.sz as i32, pb.sz as i32, pc.sz as i32],
            slot.backdrop,
        );
        if FLASHLIGHT_ON && !slot.backdrop {
            let p = [pa, pb, pc];
            shade_world_rgb(&mut rgb, &p);
        }
        let uv = sway_uv3(tri.uv_words);
        #[cfg(feature = "performance-telemetry")]
        if affine_heatmap_active() {
            let _ = affine_triangle_error([&pa, &pb, &pc], uv);
        }
        #[cfg(feature = "performance-telemetry")]
        if affine_heatmap_active() {
            affine_record_remaining_triangle([&pa, &pb, &pc], uv);
        }
        #[cfg(feature = "performance-telemetry")]
        if affine_heatmap_active() {
            push_affine_heatmap_tri(packets, [&pa, &pb, &pc], uv, otz, np);
            return true;
        }
        if !tri_fits_gpu(&pa, &pb, &pc) {
            push_tri_gpu_split(
                packets,
                np,
                [(pa.sx, pa.sy), (pb.sx, pb.sy), (pc.sx, pc.sy)],
                uv,
                rgb,
                [pa.sz as i32, pb.sz as i32, pc.sz as i32],
                slot.backdrop,
                emit_packet_of(slot, tri.tex),
                0,
            );
            return true;
        }
        push_tri_uv_words_packed(
            packets,
            np,
            [(pa.sx, pa.sy), (pb.sx, pb.sy), (pc.sx, pc.sy)],
            uv,
            rgb,
            emit_packet_of(slot, tri.tex),
            otz,
        );
        return true;
    }
    pa.sz == 0 && pb.sz == 0 && pc.sz == 0
}

/// Emit world triangle `tt` from the per-frame projected-vertex cache.
unsafe fn emit_world_tri(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tt: usize,
    frame: u16,
    np: &mut usize,
    counts: &mut WorldCounters,
    affine_previous_level: u8,
) {
    if tt >= m.n_tris {
        return;
    }
    let idx = m.tri_idx(tt);
    let (a, b, c) = (idx[0] as usize, idx[1] as usize, idx[2] as usize);
    proj_vert(m, a, frame);
    proj_vert(m, b, frame);
    proj_vert(m, c, frame);
    counts.emit_calls += 1;
    let (pa, pb, pc) = (scratch_get(a), scratch_get(b), scratch_get(c));
    xhair_consider(m, tt, pa, pb, pc); // pick covers fast + soft-clip paths
    if emit_proj_fast(packets, m, tt, pa, pb, pc, np, affine_previous_level) {
        return;
    }
    // Straddlers use the software near-clipping path.
    let tri = m.render_tri(tt, cached_world_uv_words(m, tt));
    emit_projected(packets, m, tri, [pa, pb, pc], affine_previous_level, np);
}

/// Emit submodel triangle `tt` (brush entity / tram), decode-after-cull, using
/// the submodel-token vertex cache (the GTE translation is the entity offset).
unsafe fn emit_submodel_tri(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tt: usize,
    token: u16,
    np: &mut usize,
) {
    if tt >= m.n_tris {
        return;
    }
    let idx = m.tri_idx(tt);
    let (a, b, c) = (idx[0] as usize, idx[1] as usize, idx[2] as usize);
    proj_submodel_vert(m, a, token);
    proj_submodel_vert(m, b, token);
    proj_submodel_vert(m, c, token);
    let (pa, pb, pc) = (scratch_get(a), scratch_get(b), scratch_get(c));
    xhair_consider(m, tt, pa, pb, pc); // pick covers fast + soft-clip paths
    if SUBMODEL_ACTOR_OVERLAP {
        let tri = m.render_tri(tt, cached_world_uv_words(m, tt));
        if emit_actor_occluding_face(packets, m, &tri, [pa, pb, pc], np) {
            return;
        }
    }
    if emit_proj_fast(packets, m, tt, pa, pb, pc, np, 0) {
        return;
    }
    let tri = m.render_tri(tt, cached_world_uv_words(m, tt));
    emit_projected(packets, m, tri, [pa, pb, pc], 0, np);
}

/// Submodel version of emit_world_loop_tri: uses the entity-token vertex cache.
unsafe fn emit_submodel_loop_tri(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tri: &map::RenderTri,
    token: u16,
    np: &mut usize,
) {
    let (a, b, c) = (
        tri.idx[0] as usize,
        tri.idx[1] as usize,
        tri.idx[2] as usize,
    );
    proj_submodel_vert(m, a, token);
    proj_submodel_vert(m, b, token);
    proj_submodel_vert(m, c, token);
    let (pa, pb, pc) = (scratch_get(a), scratch_get(b), scratch_get(c));
    emit_submodel_loop_tri_projected(packets, m, tri, pa, pb, pc, np);
}

#[inline(never)]
unsafe fn emit_submodel_loop_tri_projected(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tri: &map::RenderTri,
    pa: Projected,
    pb: Projected,
    pc: Projected,
    np: &mut usize,
) {
    if SUBMODEL_ACTOR_OVERLAP && emit_actor_occluding_face(packets, m, tri, [pa, pb, pc], np) {
        return;
    }
    if emit_proj_fast_tri(packets, m, tri, pa, pb, pc, np, 0) {
        return;
    }
    emit_projected(packets, m, *tri, [pa, pb, pc], 0, np);
}

/// Keep a moving face in front of nearby actors without moving its whole
/// ordering key forward. Sixteen small children replace one broad triangle;
/// the far-depth parent fills only rounding gaps between their boundaries.
#[inline(never)]
#[optimize(size)]
unsafe fn emit_actor_occluding_face(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tri: &map::RenderTri,
    p: [Projected; 3],
    np: &mut usize,
) -> bool {
    if SUBMODEL_OCCLUSION_EXTRAS < 20
        || packets.remaining() < WORLD_AFFINE_PACKET_RESERVE + 21
        || EMIT_POLICY.blend() != 0
        || EMIT_POLICY.wave()
        || EMIT_POLICY.cutout()
        || tri.tex >= MAX_TEX_SLOTS
        || tri.tex >= m.n_texs
        || p.iter()
            .any(|v| v.sz < NEAR || !render::in_band_xy(v.sx as i32, v.sy as i32))
        || !ordering::moving_face_needs_local_depth(p.map(|v| v.sz))
        || !tri_fits_gpu(&p[0], &p[1], &p[2])
    {
        return false;
    }
    let slot = &*tex_slot_ptr(tri.tex);
    if !slot.valid || slot.backdrop {
        return false;
    }
    if CULL
        && culled(
            (p[0].sx as i32, p[0].sy as i32),
            (p[1].sx as i32, p[1].sy as i32),
            (p[2].sx as i32, p[2].sy as i32),
        )
    {
        return true;
    }
    let mut rgb = fog_world_rgb(tri.rgb, p.map(|v| v.sz as i32), false);
    if FLASHLIGHT_ON {
        shade_world_rgb(&mut rgb, &p);
    }
    let vertex = |i: usize| {
        let c = unpack_rgb_word(rgb[i]);
        render::SVert {
            x: p[i].sx as i32,
            y: p[i].sy as i32,
            z: p[i].sz as i32,
            uv: uv_word_pair_i32(tri.uv_words[i]),
            rgb: (c.0 as i32, c.1 as i32, c.2 as i32),
        }
    };
    let vertices = [vertex(0), vertex(1), vertex(2)];
    let saved = EMIT_POLICY;
    EMIT_POLICY = saved.with_local_depth(true);
    emit_residue_children(
        packets,
        vertices,
        emit_packet_of(slot, tri.tex),
        np,
        RESIDUE_OWN_BUDGET | 2,
    );
    EMIT_POLICY = saved;
    SUBMODEL_OCCLUSION_EXTRAS -= 20;
    true
}

#[inline(never)]
unsafe fn brush_touches_actor(center: [i32; 3], radius: i32, eye: [i32; 3]) -> bool {
    if (0..3).any(|axis| (center[axis] - eye[axis]).abs() > 384 + radius) {
        return false;
    }
    let reach = radius + 64;
    for pi in 0..PROP_COUNT.min(CARRY_MAILBOX_FIRST) {
        if PROP_ACTIVE[pi] != 0
            && PROP_KIND[pi] < PROP_TYPE_WEAPON_FIRST
            && (0..3).all(|axis| (PROP_POS[pi][axis] - center[axis]).abs() <= reach)
        {
            return true;
        }
    }
    false
}

/// The two c0a0 tram floor panels that straddle the rider's near plane reach
/// runtime as raw GT3 pairs. Their exact local bounds make the selection
/// independent of cooked face/vertex numbering while keeping every other
/// moving brush on the measured two-triangle path.
#[inline]
fn is_intro_tram_floor_quad(m: &Map, corners: [map::PackedLoopVert; 4]) -> bool {
    let mut min = [i32::MAX; 3];
    let mut max = [i32::MIN; 3];
    for corner in corners {
        let v = m.vert(corner.idx as usize);
        let p = [v.x as i32, v.y as i32, v.z as i32];
        let mut axis = 0usize;
        while axis < 3 {
            min[axis] = min[axis].min(p[axis]);
            max[axis] = max[axis].max(p[axis]);
            axis += 1;
        }
    }
    (min == [-141, 7, -64] && max == [83, 7, 0]) || (min == [-62, 7, 0] && max == [141, 7, 64])
}

/// Draw one brush-entity/tram face: fan its loop, or iterate its raw tris.
unsafe fn emit_submodel_face(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    f: usize,
    first: usize,
    cnt: usize,
    token: u16,
    np: &mut usize,
) {
    // The caller establishes the complete policy atomically before entering
    // this shared submodel path.
    if m.face_is_loop(f) {
        // Chain-member textures resolve to their current animation frame
        // (raw-tri faces resolve inside tri_tex/render_tri instead).
        let tex = map::tex_anim_display(m.face_tex(f));
        if cnt == 4 {
            // A cooked four-corner face always expands to the exact fan
            // `(0,2,1) + (0,3,2)`. Decode its packed vertices once and project
            // the four unique positions once; the old generic loop decoded six
            // records and repeated two projection-cache probes every frame.
            let corners = m.loop_corners4(first);
            for corner in &corners {
                proj_submodel_vert(m, corner.idx as usize, token);
            }
            let projected = [
                scratch_get(corners[0].idx as usize),
                scratch_get(corners[1].idx as usize),
                scratch_get(corners[2].idx as usize),
                scratch_get(corners[3].idx as usize),
            ];
            if (projected[0].sz | projected[1].sz | projected[2].sz | projected[3].sz) == 0 {
                return;
            }
            // Close brush panels need the same perspective correction as
            // world walls. Keep their complete quad through clipping instead
            // of committing to the two broad fan triangles first.
            if SUBMODEL_OCCLUSION_EXTRAS >= 40
                && packets.remaining() >= WORLD_AFFINE_PACKET_RESERVE + 160
                && projected.iter().all(|p| p.sz >= NEAR)
                && projected.iter().any(|p| p.sz < 256)
                && (!CULL || {
                    let xy = |i: usize| (projected[i].sx as i32, projected[i].sy as i32);
                    !culled_soft(xy(0), xy(2), xy(1)) || !culled_soft(xy(0), xy(3), xy(2))
                })
                && (0..4).any(|i| {
                    let j = (i + 1) & 3;
                    let (n, d) = affine_edge_error(
                        &projected[i],
                        &projected[j],
                        corners[i].uv,
                        corners[j].uv,
                    );
                    n as u64 >= WORLD_CLASSIC_SEVERE_ERROR_TEXELS as u64 * d.max(1) as u64
                })
                && emit_soft_quad_split(packets, m, tex, corners, token, np, false, 48)
            {
                SUBMODEL_OCCLUSION_EXTRAS -= 40;
                return;
            }
            let first_tri = map::RenderTri {
                idx: [corners[0].idx, corners[2].idx, corners[1].idx],
                tex,
                uv_words: [corners[0].uv, corners[2].uv, corners[1].uv],
                rgb: [corners[0].rgb, corners[2].rgb, corners[1].rgb],
            };
            emit_submodel_loop_tri_projected(
                packets,
                m,
                &first_tri,
                projected[0],
                projected[2],
                projected[1],
                np,
            );
            let second_tri = map::RenderTri {
                idx: [corners[0].idx, corners[3].idx, corners[2].idx],
                tex,
                uv_words: [corners[0].uv, corners[3].uv, corners[2].uv],
                rgb: [corners[0].rgb, corners[3].rgb, corners[2].rgb],
            };
            emit_submodel_loop_tri_projected(
                packets,
                m,
                &second_tri,
                projected[0],
                projected[3],
                projected[2],
                np,
            );
            return;
        }
        let mut k = 1;
        while k + 1 < cnt {
            let tri = m.loop_render_tri(tex, first, first + k + 1, first + k);
            emit_submodel_loop_tri(packets, m, &tri, token, np);
            k += 1;
        }
    } else {
        let (center, radius) = m.face_bounds(f);
        let tram_floor_face = TRAM_CACHE_BUILDING
            && ((cnt == 9 && center == [-29, 7, -32] && radius == 122)
                || (cnt == 6 && center == [39, 7, 32] && radius == 112));
        let end = first + cnt;
        let mut tt = first;
        while tt < end {
            if tram_floor_face && tt + 1 < end && tt + 1 < m.n_tris {
                let t0 = m.render_tri(tt, m.tri_uv_words(tt));
                let t1 = m.render_tri(tt + 1, m.tri_uv_words(tt + 1));
                if let Some(corners) = map::tri_pair_quad_corners(t0, t1) {
                    if is_intro_tram_floor_quad(m, corners) {
                        let saved_policy = EMIT_POLICY;
                        EMIT_POLICY = saved_policy.with_local_depth(true).with_tram_grid();
                        let emitted = emit_soft_quad_split(
                            packets,
                            m,
                            t0.tex,
                            corners,
                            token,
                            np,
                            true,
                            SOFT_SPLIT_TARGET_SPAN_PX,
                        );
                        EMIT_POLICY = saved_policy;
                        if emitted {
                            tt += 2;
                            continue;
                        }
                    }
                }
            }
            emit_submodel_tri(packets, m, tt, token, np);
            tt += 1;
        }
    }
    // Preserve every later renderer symbol's accepted cache-set address while
    // the four-corner all-behind return removes 36 bytes from this function.
    // The targeted `cnt == 4` path returns above and never executes this pad.
    #[cfg(target_arch = "mips")]
    core::arch::asm!(
        "b 2f",
        "nop",
        ".rept 4",
        "nop",
        ".endr",
        "2:",
        options(nostack, preserves_flags)
    );
}

/// Draw an entity-local `func_platrot`. Keep this cold/out-of-line: the main
/// render loop is already near the MIPS PC16 branch span in diagnostic builds.
#[inline(never)]
unsafe fn emit_platrot_entity(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    visibility: &CameraVisibility<'_>,
    e: map::Ent,
    phase: i32,
    eye: [i32; 3],
    off: [i32; 3],
    rot: &Mat3I16,
    base_t: [i32; 3],
    np: &mut usize,
    model_culled_tris: &mut u32,
) {
    let local_rot = platrot_rotation(e, phase);
    let mr = rot.mul(&local_rot);
    let ome = [off[0] - eye[0], off[1] - eye[1], off[2] - eye[2]];
    let et = [
        dot12(rot.m[0], ome),
        dot12(rot.m[1], ome),
        dot12(rot.m[2], ome),
    ];
    scene::load_rotation(&mr);
    scene::load_translation(Vec3I32::new(et[0], et[1], et[2]));
    set_view_fix(&mr, et);
    let eye_local = platrot_world_to_local(eye, off, &local_rot);
    let submodel_token = next_proj_token();
    let (ff, nf) = m.submodel(e.submodel);
    for f in ff..ff + nf {
        let (fnrm, fd) = m.face_plane(f);
        if dot_plane(fnrm, eye_local) <= fd {
            let (_, cnt) = m.face_tris(f);
            *model_culled_tris = model_culled_tris.saturating_add(cnt as u32);
            continue;
        }
        let (bc, be) = m.face_bounds(f);
        if WORLD_BOUNDS_CULL {
            // This entity-local matrix is currently resident in the GTE. Feed
            // its transformed centre into the same camera-plane predicate used
            // by world faces and actors.
            let v = scene::transform_vertex_scheduled(Vec3I16::new(
                bc[0] as i16,
                bc[1] as i16,
                bc[2] as i16,
            ));
            if !visibility.view_sphere([v.x, v.y, v.z], be) {
                continue;
            }
        }
        let (first, cnt) = m.face_tris(f);
        set_emit_face(m, f, visibility_logic::brush_packet_blend(e.blend));
        emit_submodel_face(packets, m, f, first, cnt, submodel_token, np);
    }
    reset_emit_policy();
    scene::load_rotation(rot);
    scene::load_translation(Vec3I32::new(base_t[0], base_t[1], base_t[2]));
    set_view_fix(rot, base_t);
}

unsafe fn emit_world_face_tris(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    first: usize,
    cnt: usize,
    refined_topology: bool,
    _face: usize,
    frame: u16,
    np: &mut usize,
    nq: &mut usize,
    counts: &mut WorldCounters,
) {
    #[cfg(feature = "seam-census")]
    {
        SEAM_CENSUS_TINT = SEAM_CENSUS_RAW_TRI;
    }
    // Clean fans and refined raw faces both take this path. Pair only when the
    // two decoded triangles prove an identical packed shared diagonal; the GT4
    // core then rejects near-plane, clamped, degenerate, same-side/bow-tie, and
    // depth-spanning projections. Refined descendants receive local keys;
    // only explicitly tagged regular cells may share one.
    let end = first + cnt;
    let mut tt = first;
    let affine_face = 0;
    let saved_policy = EMIT_POLICY;
    EMIT_POLICY = saved_policy.with_local_depth(refined_topology);
    while tt < end {
        if WORLD_QUAD_PAIRING && tt + 1 < end && tt + 1 < m.n_tris {
            let paired = if refined_topology {
                if let Some(code) = m.tri_quad_pair_code(tt) {
                    let t0 = m.render_tri(tt, cached_world_uv_words(m, tt));
                    let t1 = m.render_tri(tt + 1, cached_world_uv_words(m, tt + 1));
                    try_emit_quad_corners(
                        packets,
                        m,
                        t0.tex,
                        map::encoded_pair_quad_corners(t0, t1, code),
                        frame,
                        affine_face,
                        false,
                        0,
                        usize::MAX,
                        np,
                        nq,
                    )
                } else {
                    false
                }
            } else {
                let t0 = m.render_tri(tt, cached_world_uv_words(m, tt));
                let t1 = m.render_tri(tt + 1, cached_world_uv_words(m, tt + 1));
                try_emit_tri_pair_quad_values(packets, m, t0, t1, frame, affine_face, np, nq)
            };
            if paired {
                counts.emit_calls += 2;
                tt += 2;
                continue;
            }
        }
        emit_world_tri(packets, m, tt, frame, np, counts, affine_face);
        tt += 1;
    }
    EMIT_POLICY = saved_policy;
}

unsafe fn emit_world_loop_tri(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tri: &map::RenderTri,
    frame: u16,
    np: &mut usize,
    counts: &mut WorldCounters,
    affine_previous_level: u8,
) {
    let (a, b, c) = (
        tri.idx[0] as usize,
        tri.idx[1] as usize,
        tri.idx[2] as usize,
    );
    proj_vert(m, a, frame);
    proj_vert(m, b, frame);
    proj_vert(m, c, frame);
    counts.emit_calls += 1;
    let (pa, pb, pc) = (scratch_get(a), scratch_get(b), scratch_get(c));
    if emit_proj_fast_tri(packets, m, tri, pa, pb, pc, np, affine_previous_level) {
        return;
    }
    emit_projected(packets, m, *tri, [pa, pb, pc], affine_previous_level, np);
}

/// Fan a loop face into triangles (tri k = anchor, loop[k+1], loop[k] -- the
/// cook's exact fan), pairing consecutive fan tris into a POLY_GT4 where they
/// form a convex on-screen quad. A 4-vertex face is one natural quad; pairs are
/// exact consecutive fan tris, so no false pairing (avoids the grazing bowtie).
unsafe fn emit_world_face_loop(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tex: usize,
    base: usize,
    count: usize,
    _face: usize,
    frame: u16,
    np: &mut usize,
    nq: &mut usize,
    counts: &mut WorldCounters,
) {
    if count < 3 {
        return;
    }
    #[cfg(feature = "seam-census")]
    {
        SEAM_CENSUS_TINT = SEAM_CENSUS_LOOP_FACE;
    }
    // Chain-member textures resolve to their current animation frame (world
    // faces + frame-0 ents show their own chain; the alternate row is selected
    // per entity via map::tex_anim_select before this call).
    let tex = map::tex_anim_display(tex);
    let affine_face = 0;
    // Rolling window over the fan: decode each loop vertex exactly once
    // (the old path rebuilt full RenderTris per pair, re-decoding shared
    // corners three to four times through the uncached blob).
    let va = m.loop_vert(base); // shared fan base
    let mut vk = m.loop_vert(base + 1);
    let mut k = 1;
    while k + 1 < count {
        let vk1 = m.loop_vert(base + k + 1);
        if WORLD_QUAD_PAIRING && k + 2 < count {
            let vk2 = m.loop_vert(base + k + 2);
            // Fan structure guarantees the shared edge; go straight to the core.
            WORLD_QUAD_NEEDS_SOFT_SPLIT = false;
            if try_emit_quad_corners(
                packets,
                m,
                tex,
                [va, vk, vk1, vk2],
                frame,
                affine_face,
                false,
                0,
                usize::MAX,
                np,
                nq,
            ) {
                counts.emit_calls += 2;
                vk = vk2;
                k += 2;
                continue;
            }
            // A loop quad that crosses the near plane or the guard band is
            // the nearest geometry in the frame. The raw clipped fan it fell
            // back to carries no affine correction, so keep it four-sided
            // through the same view-space quadtree the cooked-patch walker
            // uses, under the same per-frame route cap so a close wall
            // cannot drain the packet arena (the E3 regress overflow).
            if WORLD_QUAD_SOFT_SPLIT
                && WORLD_QUAD_NEEDS_SOFT_SPLIT
                && WORLD_CLASSIC_SOFT_ROUTES_LEFT
                    > WORLD_CLASSIC_SOFT_ROUTE_CAP - LOOP_SOFT_ROUTE_CAP
                && packets.remaining() >= LOOP_SOFT_ROUTE_ARENA_FLOOR
                && emit_soft_quad_split(
                    packets,
                    m,
                    tex,
                    [va, vk, vk1, vk2],
                    frame,
                    np,
                    false,
                    SOFT_SPLIT_TARGET_SPAN_PX,
                )
            {
                WORLD_CLASSIC_SOFT_ROUTES_LEFT -= 1;
                counts.emit_calls += 2;
                vk = vk2;
                k += 2;
                continue;
            }
        }
        let tri = map::RenderTri {
            idx: [va.idx, vk1.idx, vk.idx],
            tex,
            uv_words: [va.uv, vk1.uv, vk.uv],
            rgb: [va.rgb, vk1.rgb, vk.rgb],
        };
        emit_world_loop_tri(packets, m, &tri, frame, np, counts, affine_face);
        vk = vk1;
        k += 1;
    }
}

/// Score two GT3 records that retain a positional quad but disagree on their
/// diagonal attributes. The returned marker lets the cold seam path perform
/// one bounded 1-to-4 split without adding work to ordinary triangle draws.
#[inline(never)]
#[link_section = ".hlpsx_cold.seamed"]
unsafe fn collect_world_seamed_pair(
    m: &Map,
    first: map::RenderTri,
    second: map::RenderTri,
    frame: u16,
) -> u8 {
    // Cooker order is `(b,a,c) + (a,d,c)`, retaining the independent shared
    // UV/light values while exposing the four geometric boundary vertices.
    let indices = [first.idx[0], first.idx[1], first.idx[2], second.idx[1]];
    for &index in &indices {
        proj_vert(m, index as usize, frame);
    }
    let projected = [
        scratch_get(indices[0] as usize),
        scratch_get(indices[1] as usize),
        scratch_get(indices[2] as usize),
        scratch_get(indices[3] as usize),
    ];
    let min_x = projected[0]
        .sx
        .min(projected[1].sx)
        .min(projected[2].sx)
        .min(projected[3].sx) as i32;
    let max_x = projected[0]
        .sx
        .max(projected[1].sx)
        .max(projected[2].sx)
        .max(projected[3].sx) as i32;
    let min_y = projected[0]
        .sy
        .min(projected[1].sy)
        .min(projected[2].sy)
        .min(projected[3].sy) as i32;
    let max_y = projected[0]
        .sy
        .max(projected[1].sy)
        .max(projected[2].sy)
        .max(projected[3].sy) as i32;
    if max_x - min_x < WORLD_AFFINE_SEAMED_MIN_SPAN_PIXELS
        && max_y - min_y < WORLD_AFFINE_SEAMED_MIN_SPAN_PIXELS
    {
        return 0;
    }
    let clamped = |q: &Projected| q.sx <= -1023 || q.sx >= 1023 || q.sy <= -1023 || q.sy >= 1023;
    if projected.iter().any(|p| p.sz < NEAR || clamped(p))
        || first.tex >= m.n_texs
        || first.tex >= MAX_TEX_SLOTS
    {
        return 0;
    }
    let slot = &*tex_slot_ptr(first.tex);
    if !slot.valid {
        return 0;
    }
    let current = rank_affine_patch(
        indices,
        projected,
        [0; 4],
        slot.backdrop,
        0,
        AFFINE_PATCH_KIND_SEAMED_PAIR,
    );
    if current == 0x0f {
        1
    } else {
        0
    }
}

#[cold]
#[inline(never)]
#[link_section = ".hlpsx_cold.seamed"]
fn affine_triangle_may_need_split(a: &Projected, b: &Projected, c: &Projected) -> bool {
    let min_x = a.sx.min(b.sx).min(c.sx) as i32;
    let max_x = a.sx.max(b.sx).max(c.sx) as i32;
    let min_y = a.sy.min(b.sy).min(c.sy) as i32;
    let max_y = a.sy.max(b.sy).max(c.sy) as i32;
    if (max_x - min_x).max(max_y - min_y) < WORLD_AFFINE_MIN_EDGE_PIXELS {
        return false;
    }
    let min_z = a.sz.min(b.sz).min(c.sz) as i32;
    let max_z = a.sz.max(b.sz).max(c.sz) as i32;
    // A UV edge cannot span more than 255 texels. If even that theoretical
    // maximum stays below the error threshold, avoid the detailed UV test.
    255 * (max_z - min_z) > 4 * WORLD_AFFINE_LEAVE_ERROR_TEXELS * min_z
}

unsafe fn try_emit_world_seamed_tri(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tri: map::RenderTri,
    frame: u16,
    np: &mut usize,
    counts: &mut WorldCounters,
) -> bool {
    let indices = [
        tri.idx[0] as usize,
        tri.idx[1] as usize,
        tri.idx[2] as usize,
    ];
    proj_vert(m, indices[0], frame);
    proj_vert(m, indices[1], frame);
    proj_vert(m, indices[2], frame);
    let pa = scratch_get(indices[0]);
    let pb = scratch_get(indices[1]);
    let pc = scratch_get(indices[2]);
    let projected = [&pa, &pb, &pc];
    if !affine_triangle_may_need_split(&pa, &pb, &pc)
        || tri.tex >= m.n_texs
        || tri.tex >= MAX_TEX_SLOTS
    {
        return false;
    }
    let slot = &*tex_slot_ptr(tri.tex);
    if !slot.valid
        || !affine_triangle_eligible(projected, slot.backdrop)
        || packets.remaining() < WORLD_AFFINE_PACKET_RESERVE + 4
    {
        return false;
    }
    let uv = sway_uv3(tri.uv_words);
    let mut rgb = fog_world_rgb(
        tri.rgb,
        [pa.sz as i32, pb.sz as i32, pc.sz as i32],
        slot.backdrop,
    );
    if FLASHLIGHT_ON && !slot.backdrop {
        let p = [pa, pb, pc];
        shade_world_rgb(&mut rgb, &p);
    }
    counts.emit_calls += 1;
    macro_rules! make_cv {
        ($idx:expr, $corner:expr) => {{
            let v = scene::transform_vertex_scheduled(m.vert($idx));
            let c = unpack_rgb_word(rgb[$corner]);
            render::CVert {
                v: [v.x, v.y, v.z],
                rgb: (c.0 as i32, c.1 as i32, c.2 as i32),
                uv: uv_word_pair_i32(uv[$corner]),
            }
        }};
    }
    let cv = [
        make_cv!(indices[0], 0),
        make_cv!(indices[1], 1),
        make_cv!(indices[2], 2),
    ];
    let soft = [
        render::project_soft(&cv[0]),
        render::project_soft(&cv[1]),
        render::project_soft(&cv[2]),
    ];
    if CULL
        && culled_soft(
            (soft[0].x, soft[0].y),
            (soft[1].x, soft[1].y),
            (soft[2].x, soft[2].y),
        )
    {
        return true;
    }
    emit_cv_subdivided(
        packets,
        cv,
        soft,
        emit_packet_of(slot, tri.tex),
        slot.backdrop,
        0,
        np,
    );
    true
}

#[cold]
#[inline(never)]
#[link_section = ".hlpsx_cold.seamed"]
unsafe fn try_emit_world_seamed_pair(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tex: usize,
    base: usize,
    count: usize,
    patch: usize,
    first: map::RenderTri,
    frame: u16,
    np: &mut usize,
    counts: &mut WorldCounters,
) -> bool {
    if patch + 1 >= count || !m.patch_is_triangle(base, patch + 1) {
        return false;
    }
    let next = m.patch_corners(base, patch + 1);
    let second = map::RenderTri {
        idx: [next[0].idx, next[1].idx, next[2].idx],
        tex,
        uv_words: [next[0].uv, next[1].uv, next[2].uv],
        rgb: [next[0].rgb, next[1].rgb, next[2].rgb],
    };
    let selected =
        WORLD_AFFINE_SEAMED_SPLITS == 0 && collect_world_seamed_pair(m, first, second, frame) != 0;
    let before = *np;
    if !selected || !try_emit_world_seamed_tri(packets, m, first, frame, np, counts) {
        emit_world_loop_tri(packets, m, &first, frame, np, counts, 0);
    }
    if !selected || !try_emit_world_seamed_tri(packets, m, second, frame, np, counts) {
        emit_world_loop_tri(packets, m, &second, frame, np, counts, 0);
    }
    if selected && *np > before {
        WORLD_AFFINE_SPLIT_PATCHES = WORLD_AFFINE_SPLIT_PATCHES.saturating_add(1);
        WORLD_AFFINE_SEAMED_SPLITS = 1;
    }
    true
}

#[cold]
#[inline(never)]
#[link_section = ".hlpsx_cold.seamed"]
unsafe fn emit_world_seamed_prefix(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tex: usize,
    base: usize,
    count: usize,
    frame: u16,
    np: &mut usize,
    counts: &mut WorldCounters,
) -> usize {
    let mut patch = 0usize;
    while patch + 1 < count
        && m.patch_is_seamed_pair_start(base, patch)
        && m.patch_is_triangle(base, patch + 1)
    {
        let corners = m.patch_corners(base, patch);
        let first = map::RenderTri {
            idx: [corners[0].idx, corners[1].idx, corners[2].idx],
            tex,
            uv_words: [corners[0].uv, corners[1].uv, corners[2].uv],
            rgb: [corners[0].rgb, corners[1].rgb, corners[2].rgb],
        };
        if !try_emit_world_seamed_pair(
            packets, m, tex, base, count, patch, first, frame, np, counts,
        ) {
            break;
        }
        patch += 2;
    }
    patch
}

/// Correct a severe triangular residue without changing its boundary ownership.
/// Four children plus the original crack backstop cost four extra packets;
/// at most sixteen roots/frame share the existing affine budget and arena reserve.
#[inline(never)]
#[optimize(size)]
unsafe fn try_emit_native_residue(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tri: &map::RenderTri,
    frame: u16,
    np: &mut usize,
) -> bool {
    if WORLD_AFFINE_NATIVE_TRI_SPLITS >= WORLD_AFFINE_RESIDUE_ROOT_CAP
        || WORLD_AFFINE_EXTRA_BUDGET_LEFT < 4
        || packets.remaining() < WORLD_AFFINE_PACKET_RESERVE + 5
        || tri.tex >= MAX_TEX_SLOTS
        || tri.tex >= m.n_texs
    {
        return false;
    }
    let slot = &*tex_slot_ptr(tri.tex);
    if !slot.valid || EMIT_POLICY.cutout() {
        return false;
    }
    let mut p = [Projected {
        sx: 0,
        sy: 0,
        sz: 0,
    }; 3];
    for i in 0..3 {
        proj_vert(m, tri.idx[i] as usize, frame);
        p[i] = scratch_get(tri.idx[i] as usize);
    }
    if !affine_triangle_eligible([&p[0], &p[1], &p[2]], slot.backdrop)
        || !tri_fits_gpu(&p[0], &p[1], &p[2])
        || p.iter()
            .any(|v| !render::in_band_xy(v.sx as i32, v.sy as i32))
    {
        return false;
    }
    if !render::residue_screen_coverage(p.map(|v| (v.sx as i32, v.sy as i32))) {
        return false;
    }
    let over = |a: usize, b: usize| {
        let (n, d) = affine_edge_error(&p[a], &p[b], tri.uv_words[a], tri.uv_words[b]);
        n > WORLD_CLASSIC_SEVERE_ERROR_TEXELS * d.max(1)
    };
    if !(over(0, 1) || over(1, 2) || over(2, 0)) {
        return false;
    }
    let screen = [(p[0].sx, p[0].sy), (p[1].sx, p[1].sy), (p[2].sx, p[2].sy)];
    if CULL
        && culled_soft(
            (screen[0].0 as i32, screen[0].1 as i32),
            (screen[1].0 as i32, screen[1].1 as i32),
            (screen[2].0 as i32, screen[2].1 as i32),
        )
    {
        return true;
    }
    let mut rgb = fog_world_rgb(
        tri.rgb,
        [p[0].sz as i32, p[1].sz as i32, p[2].sz as i32],
        false,
    );
    if FLASHLIGHT_ON {
        shade_world_rgb(&mut rgb, &p);
    }
    let vertex = |i: usize| {
        let c = unpack_rgb_word(rgb[i]);
        render::SVert {
            x: p[i].sx as i32,
            y: p[i].sy as i32,
            z: p[i].sz as i32,
            uv: uv_word_pair_i32(tri.uv_words[i]),
            rgb: (c.0 as i32, c.1 as i32, c.2 as i32),
        }
    };
    let before = *np;
    emit_residue_children(
        packets,
        [vertex(0), vertex(1), vertex(2)],
        emit_packet_of(slot, tri.tex),
        np,
        1,
    );
    WORLD_AFFINE_SPLIT_TRIS += np.saturating_sub(before) as u32;
    true
}

/// The guard fallback already clipped and culled this fan. Share the native
/// residue limit, packet reserve, midpoint attributes and far-depth backstop.
#[inline(never)]
#[optimize(size)]
unsafe fn try_emit_clipped_residue(
    packets: &mut PrimitivePacketArena<'_>,
    p: [render::SVert; 3],
    mat: TexturedGouraudPacketMaterial,
    backdrop: bool,
    np: &mut usize,
) -> bool {
    if WORLD_AFFINE_NATIVE_TRI_SPLITS >= WORLD_AFFINE_RESIDUE_ROOT_CAP
        || WORLD_AFFINE_EXTRA_BUDGET_LEFT < 4
        || packets.remaining() < WORLD_AFFINE_PACKET_RESERVE + 5
        || backdrop
        || EMIT_POLICY.blend() != 0
        || EMIT_POLICY.wave()
        || EMIT_POLICY.cutout()
        || p.iter()
            .any(|v| !(render::NEAR_Z..=65535).contains(&v.z) || !render::in_band(v))
    {
        return false;
    }
    if !render::residue_screen_coverage(p.map(|v| (v.x, v.y))) {
        return false;
    }
    let over = |a: usize, b: usize| {
        render::affine_edge_needs_split(
            (p[a].x, p[a].y),
            p[a].z,
            p[a].uv,
            (p[b].x, p[b].y),
            p[b].z,
            p[b].uv,
            WORLD_CLASSIC_SEVERE_ERROR_TEXELS as i32,
            WORLD_AFFINE_MIN_EDGE_PIXELS,
        )
    };
    if !(over(0, 1) || over(1, 2) || over(2, 0)) {
        return false;
    }
    emit_residue_children(packets, p, mat, np, 1);
    true
}

#[inline(never)]
#[optimize(size)]
unsafe fn emit_residue_children(
    packets: &mut PrimitivePacketArena<'_>,
    vertices: [render::SVert; 3],
    mat: TexturedGouraudPacketMaterial,
    np: &mut usize,
    levels: u8,
) {
    let [a, b, c] = vertices;
    let ab = render::perspective_screen_midpoint(a, b);
    let bc = render::perspective_screen_midpoint(b, c);
    let ca = render::perspective_screen_midpoint(c, a);
    for child in [[a, ab, ca], [ab, b, bc], [ca, bc, c], [ab, bc, ca]] {
        if levels & !RESIDUE_OWN_BUDGET > 1 {
            emit_residue_children(packets, child, mat, np, levels - 1);
        } else {
            emit_screen_triangle(packets, child, mat, false, np);
        }
    }
    // A far-depth parent must draw before every child, including when the
    // cooked face uses local centroid ordering. Restore policy immediately.
    let saved_policy = EMIT_POLICY;
    EMIT_POLICY = saved_policy.with_local_depth(false);
    emit_screen_triangle(packets, [a, b, c], mat, false, np);
    EMIT_POLICY = saved_policy;
    if levels & RESIDUE_OWN_BUDGET == 0 {
        WORLD_AFFINE_EXTRA_BUDGET_LEFT -= 4;
        WORLD_AFFINE_NATIVE_TRI_SPLITS += 1;
    }
    WORLD_AFFINE_SPLIT_PATCHES += 1;
}

/// Draw fixed four-corner records cooked from logical GoldSrc quads. A record
/// normally maps to one GT4 and may become a bounded 2x2 GT4 grid; the marked
/// three-corner fallback keeps irregular seam fragments on the proven path.
unsafe fn emit_world_face_patches(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    tex: usize,
    base: usize,
    count: usize,
    refined_topology: bool,
    face: usize,
    frame: u16,
    np: &mut usize,
    nq: &mut usize,
    counts: &mut WorldCounters,
) {
    let tex = map::tex_anim_display(tex);
    let affine_face = 0u8;
    let saved_policy = EMIT_POLICY;
    EMIT_POLICY = saved_policy.with_local_depth(refined_topology);
    let mut patch = 0;
    while patch < count {
        let (corners, is_triangle, blocked_edges) = m.patch_corners_meta(base, patch);
        #[cfg(feature = "seam-census")]
        {
            SEAM_CENSUS_TINT = SEAM_CENSUS_PATCH_QUAD;
        }
        if is_triangle {
            #[cfg(feature = "seam-census")]
            {
                SEAM_CENSUS_TINT = SEAM_CENSUS_PATCH_TRI;
            }
            let tri = map::RenderTri {
                idx: [corners[0].idx, corners[1].idx, corners[2].idx],
                tex,
                uv_words: [corners[0].uv, corners[1].uv, corners[2].uv],
                rgb: [corners[0].rgb, corners[1].rgb, corners[2].rgb],
            };
            if try_emit_native_residue(packets, m, &tri, frame, np) {
                counts.emit_calls += 1;
            } else {
                emit_world_loop_tri(packets, m, &tri, frame, np, counts, 0);
            }
            patch += 1;
            continue;
        }
        WORLD_QUAD_NEEDS_SOFT_SPLIT = false;
        if try_emit_quad_corners(
            packets,
            m,
            tex,
            corners,
            frame,
            affine_face,
            true,
            blocked_edges,
            base + patch * 4,
            np,
            nq,
        ) {
            counts.emit_calls += 2;
            patch += 1;
            continue;
        }
        #[cfg(feature = "seam-census")]
        {
            SEAM_CENSUS_TINT = SEAM_CENSUS_PATCH_FALLBACK;
        }
        // Near plane or guard band only: keep the quad and split it once.
        if WORLD_QUAD_SOFT_SPLIT
            && WORLD_QUAD_NEEDS_SOFT_SPLIT
            && emit_soft_quad_split(
                packets,
                m,
                tex,
                corners,
                frame,
                np,
                false,
                SOFT_SPLIT_TARGET_SPAN_PX,
            )
        {
            counts.emit_calls += 2;
            patch += 1;
            continue;
        }
        // Bow-tie or local-depth rejection: preserve the exact two hardware
        // triangles represented by `[a,b,c,d]`.
        let first = map::RenderTri {
            idx: [corners[1].idx, corners[0].idx, corners[2].idx],
            tex,
            uv_words: [corners[1].uv, corners[0].uv, corners[2].uv],
            rgb: [corners[1].rgb, corners[0].rgb, corners[2].rgb],
        };
        let second = map::RenderTri {
            idx: [corners[0].idx, corners[3].idx, corners[2].idx],
            tex,
            uv_words: [corners[0].uv, corners[3].uv, corners[2].uv],
            rgb: [corners[0].rgb, corners[3].rgb, corners[2].rgb],
        };
        emit_world_loop_tri(packets, m, &first, frame, np, counts, affine_face);
        emit_world_loop_tri(packets, m, &second, frame, np, counts, affine_face);
        patch += 1;
    }
    EMIT_POLICY = saved_policy;
}

unsafe fn emit_world_face(
    packets: &mut PrimitivePacketArena<'_>,
    m: &Map,
    face: usize,
    frame: u16,
    eye: [i32; 3],
    visibility: &CameraVisibility<'_>,
    np: &mut usize,
    nq: &mut usize,
    counts: &mut WorldCounters,
) {
    if face >= m.n_faces || face >= MAX_FACES {
        return;
    }
    counts.surfaces_considered += 1;

    let (fnrm, fd) = m.face_plane(face);
    if dot_plane(fnrm, eye) <= fd && !(PLAYER_EYE_UNDER && m.face_liquid(face)) {
        return;
    }
    let (first, cnt) = m.face_tris(face);
    if cnt == 0 {
        return;
    }
    let (bc, be) = m.face_bounds(face);
    if WORLD_BOUNDS_CULL && !visibility.sphere(bc, be) {
        return;
    }
    // Face-level, from the cook: blend, sway, backed-cutout pull and coplanar
    // bias are installed together and can never leak independently.
    set_emit_face(m, face, 0);
    if m.face_is_patch(face) {
        emit_world_face_patches(
            packets,
            m,
            m.face_tex(face),
            first,
            cnt,
            m.face_refined_topology(face),
            face,
            frame,
            np,
            nq,
            counts,
        );
    } else if m.face_is_loop(face) {
        emit_world_face_loop(
            packets,
            m,
            m.face_tex(face),
            first,
            cnt,
            face,
            frame,
            np,
            nq,
            counts,
        );
    } else {
        emit_world_face_tris(
            packets,
            m,
            first,
            cnt,
            m.face_refined_topology(face),
            face,
            frame,
            np,
            nq,
            counts,
        );
    }
}

/// Compose one HMD8 model-space bone affine with the already-oriented camera
/// matrix. Four hazard-safe GTE MVMVA operations replace 27 slow R3000 scalar
/// multiplies and leave the GTE ready for the bone range's RTPT batches.
#[inline(never)]
fn compose_hmd7_bone_gte(
    view_model: &Mat3I16,
    view_origin: Vec3I32,
    bone: model::BoneTransform,
) -> (Mat3I16, Vec3I32) {
    scene::load_rotation(view_model);
    scene::load_translation(Vec3I32::ZERO);
    let c0 = scene::transform_vertex_scheduled(Vec3I16::new(
        bone.rotation.m[0][0],
        bone.rotation.m[1][0],
        bone.rotation.m[2][0],
    ));
    let c1 = scene::transform_vertex_scheduled(Vec3I16::new(
        bone.rotation.m[0][1],
        bone.rotation.m[1][1],
        bone.rotation.m[2][1],
    ));
    let c2 = scene::transform_vertex_scheduled(Vec3I16::new(
        bone.rotation.m[0][2],
        bone.rotation.m[1][2],
        bone.rotation.m[2][2],
    ));
    let bt = scene::transform_vertex_scheduled(bone.translation);
    let clamp = |value: i32| value.clamp(i16::MIN as i32, i16::MAX as i32) as i16;
    (
        Mat3I16 {
            m: [
                [clamp(c0.x), clamp(c1.x), clamp(c2.x)],
                [clamp(c0.y), clamp(c1.y), clamp(c2.y)],
                [clamp(c0.z), clamp(c1.z), clamp(c2.z)],
            ],
        },
        Vec3I32::new(
            view_origin.x.saturating_add(bt.x),
            view_origin.y.saturating_add(bt.y),
            view_origin.z.saturating_add(bt.z),
        ),
    )
}

/// Feed one already-packed HMD8 triple straight to V0/V1/V2.
///
/// `project_triangle_scheduled` is ideal for general `Vec3I16` callers,
/// but HMD8 vertices already live in the GTE's packed XY + sign-extended Z
/// layout. Keeping that representation removes the repeated halfword
/// shifts/ORs from every animated-model RTPT batch while preserving the
/// hardware-verified MTC2/RTPT/MFC2 schedule byte-for-byte.
#[inline(always)]
fn project_hmd7_triangle_words(
    v0: GteVertexWords,
    v1: GteVertexWords,
    v2: GteVertexWords,
) -> [Projected; 3] {
    #[cfg(target_arch = "mips")]
    {
        let sxy0: u32;
        let sxy1: u32;
        let sxy2: u32;
        let sz1: u32;
        let sz2: u32;
        let sz3: u32;
        unsafe {
            core::arch::asm!(
                ".word 0x48880000",
                ".word 0x48890800",
                ".word 0x488a1000",
                ".word 0x488b1800",
                ".word 0x488c2000",
                ".word 0x488d2800",
                ".word 0x4a080030",
                ".word 0x48086000",
                ".word 0x48096800",
                ".word 0x480a7000",
                ".word 0x480b8800",
                ".word 0x480c9000",
                ".word 0x480d9800",
                ".word 0",
                inlateout("$8") v0.xy => sxy0,
                inlateout("$9") v0.z => sxy1,
                inlateout("$10") v1.xy => sxy2,
                inlateout("$11") v1.z => sz1,
                inlateout("$12") v2.xy => sz2,
                inlateout("$13") v2.z => sz3,
                options(nostack, nomem, preserves_flags),
            );
        }
        return [
            Projected {
                sx: sxy0 as i16,
                sy: (sxy0 >> 16) as i16,
                sz: sz1 as u16,
            },
            Projected {
                sx: sxy1 as i16,
                sy: (sxy1 >> 16) as i16,
                sz: sz2 as u16,
            },
            Projected {
                sx: sxy2 as i16,
                sy: (sxy2 >> 16) as i16,
                sz: sz3 as u16,
            },
        ];
    }
    #[cfg(not(target_arch = "mips"))]
    {
        let unpack = |v: GteVertexWords| Vec3I16::new(v.xy as i16, (v.xy >> 16) as i16, v.z as i16);
        project_triangle_scheduled(unpack(v0), unpack(v1), unpack(v2))
    }
}

/// Project one interpolated HMD8 palette. Vertices are cooker-grouped into
/// contiguous bone/body ranges, so each range pays one matrix load and feeds
/// the static bone-local stream directly to RTPT.
unsafe fn project_hmd7_model_inner(
    md: &Model,
    frame: usize,
    frame2: usize,
    frac16: u32,
    body: u8,
    mouth: u8,
    view_model: &Mat3I16,
    view_origin: Vec3I32,
    projected_xy: *mut u32,
    projected_z: *mut u16,
) {
    let pose = md.frame(frame).interpolate(md.frame(frame2), frac16);
    let body_bit = 1u8 << body.min(7);
    let mut loaded_bone = usize::MAX;
    let mut loaded_mouth = false;
    let mut range_index = 0usize;
    while range_index < md.n_ranges {
        let range = md.range(range_index);
        range_index += 1;
        if md.has_body_masks() && range.body_mask & body_bit == 0 {
            continue;
        }
        if loaded_bone != range.bone || loaded_mouth != range.mouth {
            let bone = pose.bone(range.bone, range.mouth, mouth);
            let (rotation, translation) = compose_hmd7_bone_gte(view_model, view_origin, bone);
            scene::load_rotation(&rotation);
            scene::load_translation(translation);
            loaded_bone = range.bone;
            loaded_mouth = range.mouth;
        }
        let end = range
            .first
            .saturating_add(range.count)
            .min(md.n_verts)
            .min(MAX_MODEL_VERTS);
        let mut vertex = range.first.min(end);
        while vertex + 2 < end {
            let tri = project_hmd7_triangle_words(
                md.vert_gte_words(vertex),
                md.vert_gte_words(vertex + 1),
                md.vert_gte_words(vertex + 2),
            );
            projected_soa_set(projected_xy, projected_z, vertex, tri[0]);
            projected_soa_set(projected_xy, projected_z, vertex + 1, tri[1]);
            projected_soa_set(projected_xy, projected_z, vertex + 2, tri[2]);
            vertex += 3;
        }
        while vertex < end {
            projected_soa_set(
                projected_xy,
                projected_z,
                vertex,
                project_vertex_scheduled(md.vert(vertex)),
            );
            vertex += 1;
        }
    }
}

#[repr(C)]
struct ProjectionStackCall {
    md: *const Model,
    frame: usize,
    frame2: usize,
    frac16: u32,
    body: u8,
    mouth: u8,
    view_model: *const Mat3I16,
    view_origin: Vec3I32,
    projected_xy: *mut u32,
    projected_z: *mut u16,
}

// A guard failure disables future switches and leaves projection on the normal
// main stack. The canary sits inside the dead group-bit range, above the
// persistent viewmodel heads and the trampoline save record.
static mut PROJECTION_SCRATCH_STACK_OK: bool = true;

#[inline(never)]
unsafe extern "C" fn project_hmd7_model_stack_entry(context: *mut u8) {
    let call = unsafe { &*(context.cast::<ProjectionStackCall>()) };
    unsafe {
        project_hmd7_model_inner(
            &*call.md,
            call.frame,
            call.frame2,
            call.frac16,
            call.body,
            call.mouth,
            &*call.view_model,
            call.view_origin,
            call.projected_xy,
            call.projected_z,
        );
    }
}

/// Run the stack-heavy bone interpolation/composition path in the scratchpad
/// tail after group visibility's final tram consumer. Model vertices and final
/// projected arrays remain in main RAM; only the high-churn call stack moves.
unsafe fn project_hmd7_model(
    md: &Model,
    frame: usize,
    frame2: usize,
    frac16: u32,
    body: u8,
    mouth: u8,
    view_model: &Mat3I16,
    view_origin: Vec3I32,
    projected_xy: *mut u32,
    projected_z: *mut u16,
) {
    if !unsafe { PROJECTION_SCRATCH_STACK_OK } {
        unsafe {
            project_hmd7_model_inner(
                md,
                frame,
                frame2,
                frac16,
                body,
                mouth,
                view_model,
                view_origin,
                projected_xy,
                projected_z,
            );
        }
        return;
    }

    let mut call = ProjectionStackCall {
        md,
        frame,
        frame2,
        frac16,
        body,
        mouth,
        view_model,
        view_origin,
        projected_xy,
        projected_z,
    };
    let intact = unsafe {
        scratchpad::call_on_projection_stack(
            core::ptr::addr_of_mut!(call).cast::<u8>(),
            project_hmd7_model_stack_entry,
        )
    };
    if !intact {
        unsafe { PROJECTION_SCRATCH_STACK_OK = false };
    }
}

/// Tightly packed replacement view over the shared primitive arena tail used
/// by the complete actor-model pass.
struct ModelPacketWriter<'a> {
    words: &'a mut [u32],
    used_words: usize,
    packet_count: usize,
}

impl ModelPacketWriter<'_> {
    #[inline(always)]
    unsafe fn push(&mut self, prim: TriTextured) -> bool {
        let prim_words = core::mem::size_of::<TriTextured>() / core::mem::size_of::<u32>();
        if self.used_words + prim_words > self.words.len() {
            return false;
        }
        unsafe {
            self.words
                .as_mut_ptr()
                .add(self.used_words)
                .cast::<TriTextured>()
                .write(prim);
        }
        self.used_words += prim_words;
        self.packet_count += 1;
        true
    }
}

/// Draw a model at world `pos`, using its packed yaw plus authored pitch/roll.
/// Keep this walker compact: the fractional-depth sorter must fit beside the
/// unchanged campaign arenas, and this body shares the R3000 instruction cache.
#[optimize(size)]
unsafe fn draw_model(
    packets: &mut ModelPacketWriter<'_>,
    md: &Model,
    slots: &[TexSlot],
    face_indices: *const u32,
    face_payloads: *const ModelRenderFacePayload,
    face_runs: *const u32,
    run_count: usize,
    face_count: usize,
    pos: [i32; 3],
    yaw: u16,
    tilt: u16,
    body: u8,
    mouth: u8,
    frame: usize,
    frame2: usize,
    frac16: u32,
    blend: BlendMode,
    shade: u8,
    eye: [i32; 3],
    rot: &Mat3I16,
    np: &mut usize,
) -> u32 {
    if slots.is_empty() {
        return 0;
    }
    // Studio models carry one tint per draw, so the options screen's brightness
    // curve lands here rather than on any per-vertex or per-pixel path: one call
    // per model, and at the default level it returns immediately.
    let shade = settings::bright(shade);
    // OoT/Crash vertex-precision trick. Vertices are baked at `s`x (cook), so
    // keep the rotation matrix FULL precision and inflate the view-space
    // translation by `s` instead of folding the 1/s down-scale into the matrix.
    // The whole model is then `s`x in view space; the perspective divide
    // (screen = H·x/z) cancels the uniform `s`, but the vertices keep their
    // sub-unit resolution through the divide -> no coarse vertex grid. (Folding
    // 1/s into the matrix -- the old path -- cancels ×s against ÷s BEFORE the
    // GTE's >>12, collapsing right back to a 1-unit grid: no gain at any s.)
    // ponytail: ceiling ~16x -- inflated view-Z fills SZ3's u16 (clips past
    // ~16383 world units) and IR1/IR3's i16; fine for s=4 at model range.
    let (s, scale_shift) = model_local_scale_and_shift(md.local_to_world_q12());
    // Model bakes keep HL's +X local forward; rotate_y maps that to world
    // yaw - 1024, so add a quarter turn to line actors up with their authored
    // (and AI-updated) world yaw.
    let mr = rot.mul(&prop_model_rotation(yaw, tilt));
    let es = [eye[0] - pos[0], eye[1] - pos[1], eye[2] - pos[2]];
    // Translation uses the view rotation only (model yaw spins verts about the
    // origin, not the origin itself); scale it into the same `s`x view space.
    let et = [
        -dot12(rot.m[0], es) * s,
        -dot12(rot.m[1], es) * s,
        -dot12(rot.m[2], es) * s,
    ];
    let near_s = (NEAR as i32 * s) as u16;
    let nv = md.n_verts.min(MAX_MODEL_VERTS);
    telemetry::stage_begin(telemetry::stage::TEXTURED_MODEL_PROJECT);
    let (model_projected_xy, model_projected_z) = model_projected_ptrs();
    project_hmd7_model(
        md,
        frame,
        frame2,
        frac16,
        body,
        mouth,
        &mr,
        Vec3I32::new(et[0], et[1], et[2]),
        model_projected_xy,
        model_projected_z,
    );
    telemetry::stage_end(telemetry::stage::TEXTURED_MODEL_PROJECT);
    telemetry::stage_begin(telemetry::stage::TEXTURED_MODEL_FACES);
    // face_count/run_count come from the stream-time bake; the repack zeroes
    // the blob's n_tris afterwards (TriRec tail dropped), so these are the
    // authoritative bounds. Faces remain in authored order inside each run.
    let shade_word = (shade as u32) | ((shade as u32) << 8) | ((shade as u32) << 16);
    let mut run_first = 0usize;
    let mut r = 0usize;
    while r < run_count {
        let run = *face_runs.add(r);
        let run_end = ((run & 0xffff) as usize).min(face_count);
        if run_end <= run_first {
            r += 1;
            continue;
        }
        let body_mask = (run >> 24) as u8;
        if body_mask != 0 && body_mask & (1u8 << body.min(7)) == 0 {
            run_first = run_end;
            r += 1;
            continue;
        }
        let slot = slots[(((run >> 16) & 0xff) as usize).min(slots.len() - 1)];
        if !slot.valid {
            run_first = run_end;
            r += 1;
            continue;
        }
        // Studio models use one uniform tint per draw. Build the flat FT3
        // packet from the source material so the Hazard Course hologram can
        // retain the model texture while using the PS1 additive blend bit.
        let base_material =
            TexturedPacketMaterial::from_texture(slot.material.with_blend_mode(blend));
        let flat_material = TexturedPacketMaterial {
            tex_window_word: base_material.tex_window_word,
            color_command_word: (base_material.color_command_word & 0xff00_0000) | shade_word,
            clut_high_word: base_material.clut_high_word,
            tpage_high_word: base_material.tpage_high_word,
        };
        let mut t = run_first;
        while t < run_end {
            let packed = *face_indices.add(t);
            let (a, b, c) = (
                (packed & model::RENDER_FACE_INDEX_MASK) as usize,
                ((packed >> 10) & model::RENDER_FACE_INDEX_MASK) as usize,
                ((packed >> 20) & model::RENDER_FACE_INDEX_MASK) as usize,
            );
            let (pa_xy, pb_xy, pc_xy) = (
                model_projected_xy.add(a).read(),
                model_projected_xy.add(b).read(),
                model_projected_xy.add(c).read(),
            );
            let (pa_z, pb_z, pc_z) = (
                model_projected_z.add(a).read(),
                model_projected_z.add(b).read(),
                model_projected_z.add(c).read(),
            );
            if pa_z < near_s || pb_z < near_s || pc_z < near_s {
                t += 1;
                continue;
            }
            let (pa_sx, pa_sy) = (pa_xy as u16 as i16, (pa_xy >> 16) as u16 as i16);
            let (pb_sx, pb_sy) = (pb_xy as u16 as i16, (pb_xy >> 16) as u16 as i16);
            let (pc_sx, pc_sy) = (pc_xy as u16 as i16, (pc_xy >> 16) as u16 as i16);
            // The actor sphere is intentionally conservative, but studio face
            // submission previously sent every back-facing/offscreen child to
            // the packet arena. Reject only a common viewport half-space; the
            // GPU draw area already clips to this guard-banded rectangle, so
            // this removes no visible sample and changes no surviving packet.
            if triangle_outside_common_plane(
                [
                    [pa_sx as i32, pa_sy as i32],
                    [pb_sx as i32, pb_sy as i32],
                    [pc_sx as i32, pc_sy as i32],
                ],
                ScreenClipBounds::new(-1, 320, -1, 240),
            ) {
                t += 1;
                continue;
            }
            if MODEL_CULL
                && culled_gte(
                    (pa_sx as i32, pa_sy as i32),
                    (pb_sx as i32, pb_sy as i32),
                    (pc_sx as i32, pc_sy as i32),
                )
            {
                t += 1;
                continue;
            }
            // Studio meshes have close layered surfaces (face/teeth/tongue,
            // glasses, helmet, holster). Farthest-corner depth makes those
            // layers invert as an actor turns; centroid depth is the standard
            // PS1 choice for compact triangles and matches the viewmodel path.
            // Retain quarter-unit precision until the shared model pass sorts
            // ties inside each existing four-unit world bucket.
            let depth_key = ordering::model_depth_key(pa_z, pb_z, pc_z, scale_shift);
            let payload = *face_payloads.add(t);
            // XY is already in the GPU packet's packed word layout. Preserve
            // it directly instead of unpacking to i16 pairs only to repack it.
            let prim = TriTextured {
                tag: 0,
                tex_window: flat_material.tex_window_word,
                color_cmd: flat_material.color_command_word,
                v0: pa_xy,
                uv0_clut: payload.uv_words[0] as u32 | flat_material.clut_high_word,
                v1: pb_xy,
                uv1_tpage: payload.uv_words[1] as u32 | flat_material.tpage_high_word,
                v2: pc_xy,
                uv2: payload.uv_words[2] as u32 | ((depth_key as u32) << 16),
            };
            if unsafe { packets.push(prim) } {
                *np += 1;
            } else {
                note_render_packet_drop(true);
            }
            t += 1;
        }
        run_first = run_end;
        r += 1;
    }
    telemetry::stage_end(telemetry::stage::TEXTURED_MODEL_FACES);
    nv as u32
}

/// Resolve fractional model depth without adding hardware OT slots or packet
/// storage. Every packet restores UV2's reserved half before DMA can see it.
#[inline(never)]
#[optimize(size)]
unsafe fn insert_model_depth_stream(first: *mut u32, end: *mut u32) {
    const _: () = assert!(core::mem::size_of::<TriTextured>() == ordering::MODEL_PACKET_WORDS * 4);
    let words = core::slice::from_raw_parts_mut(first, end.offset_from(first) as usize);
    let bands = ordering::model_depth_bands(words);
    for mut offset in bands {
        while offset != ordering::MODEL_LINK_END {
            let packet = first.add(offset as usize).cast::<TriTextured>();
            let next = (*packet).tag;
            let key = (*packet).uv2 >> 16;
            (*packet).uv2 &= 0xffff;
            OT.add((key >> 4) as usize, &mut *packet, TriTextured::WORDS);
            offset = next;
        }
    }
}

/// Camera-facing sprite quad (env_sprite / env_glow / env_spark / env_explosion).
/// Projects the world center, sizes the quad by perspective (world extent x
/// active projection plane / depth), and emits an additive textured quad into the OT at the
/// center's depth so it sorts with the world. Screen-aligned (VP_PARALLEL);
/// upright/oriented sprite types collapse to this, which reads fine at PS1 scale.
unsafe fn draw_billboard(
    packets: &mut PrimitivePacketArena<'_>,
    np: &mut usize,
    center: [i32; 3],
    world_half_w: i32,
    world_half_h: i32,
    id: usize,
    frame: usize,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    let d = sprite::def(id);
    emit_billboard(
        packets,
        np,
        center,
        world_half_w,
        world_half_h,
        sprite::slot_for(id, frame),
        d.crush_w,
        d.crush_h,
        rot,
        base_t,
    );
}

/// Emit one camera-facing additive billboard for an explicit texture slot +
/// crushed UV dims. Shared by placed sprites (draw_billboard) and the resident
/// explosion pool, so both project + size + emit identically.
#[allow(clippy::too_many_arguments)]
unsafe fn emit_billboard(
    packets: &mut PrimitivePacketArena<'_>,
    np: &mut usize,
    center: [i32; 3],
    world_half_w: i32,
    world_half_h: i32,
    sl: TexSlot,
    crush_w: u16,
    crush_h: u16,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    if !sl.valid {
        return;
    }
    let Some((sx, sy, sz)) = project_world_point(center, rot, base_t) else {
        return;
    };
    // Perspective size follows the same focal length as the world GTE.
    let h = render::projection_h();
    let shw = ((world_half_w * h) / sz).clamp(1, 400);
    let shh = ((world_half_h * h) / sz).clamp(1, 400);
    let l = (sx as i32 - shw).clamp(-1023, 1023) as i16;
    let r = (sx as i32 + shw).clamp(-1023, 1023) as i16;
    let t = (sy as i32 - shh).clamp(-1023, 1023) as i16;
    let b = (sy as i32 + shh).clamp(-1023, 1023) as i16;
    let uw = crush_w.saturating_sub(1).min(255) as u8;
    let uh = crush_h.saturating_sub(1).min(255) as u8;
    // Sprites are additive (glows/explosions add light); the cook baked the dark
    // background to black so it contributes nothing under Add, and set the
    // per-texel semi-transparency bit so the GPU blends instead of drawing opaque.
    let mat = sl.material.with_blend_mode(BlendMode::Add);
    let packet = TexturedGouraudPacketMaterial::from_texture(mat);
    let otz = clamp_otz((sz >> OT_SHIFT) as usize);
    let (uv_tl, uv_tr, uv_bl, uv_br) = (
        uv_word((0, 0)),
        uv_word((uw, 0)),
        uv_word((0, uh)),
        uv_word((uw, uh)),
    );
    // Two triangles (the proven push_tri_uv_words path) rather than a quad, whose
    // vertex-order convention flipped the UVs inside-out.
    push_tri_uv_words(
        packets,
        np,
        [(l, t), (r, t), (l, b)],
        [uv_tl, uv_tr, uv_bl],
        [(255, 255, 255); 3],
        packet,
        otz,
    );
    push_tri_uv_words(
        packets,
        np,
        [(r, t), (r, b), (l, b)],
        [uv_tr, uv_br, uv_bl],
        [(255, 255, 255); 3],
        packet,
        otz,
    );
}

/// Self-contained additive flat triangle. The GP0(E1) prefix makes the blend
/// mode deterministic even when this packet is interleaved with textured world
/// packets in the same ordering table.
#[repr(C, align(4))]
struct BeamTri {
    tag: u32,
    draw_mode: u32,
    color_cmd: u32,
    v0: u32,
    v1: u32,
    v2: u32,
}

impl BeamTri {
    const WORDS: u8 = 5;

    fn new(verts: [(i16, i16); 3], color: (u8, u8, u8)) -> Self {
        let tri = TriFlat::new(verts, color.0, color.1, color.2);
        let draw_mode = TextureMaterial::blended(0, 0, color, BlendMode::Add).draw_mode_word();
        Self {
            tag: 0,
            draw_mode,
            // GP0 polygon bit 25 enables semi-transparency for an untextured
            // primitive; E1 above selects additive blending.
            color_cmd: tri.color_cmd | 0x0200_0000,
            v0: tri.v0,
            v1: tri.v1,
            v2: tri.v2,
        }
    }
}

/// A beam (env_beam / env_laser): a flat additive quad from world `start` to
/// `end`, widened perpendicular in screen space by the world half-width scaled
/// to the beam's average depth. Both halves enter the world ordering table, so
/// nearer BSP/model packets cover a laser instead of every laser being an
/// unconditional overlay. Culled if either endpoint is off-screen/behind.
fn draw_beam(
    packets: &mut PrimitivePacketArena<'_>,
    ot: &mut OrderingTable<OT_LEN>,
    start: [i32; 3],
    end: [i32; 3],
    half_world: i32,
    color: (u8, u8, u8),
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    let (Some((sx0, sy0, sz0)), Some((sx1, sy1, sz1))) = (
        project_world_point(start, rot, base_t),
        project_world_point(end, rot, base_t),
    ) else {
        return;
    };
    let (x0, y0, x1, y1) = (sx0 as i32, sy0 as i32, sx1 as i32, sy1 as i32);
    let (dx, dy) = (x1 - x0, y1 - y0);
    let len = isqrt_i32(dx * dx + dy * dy);
    if len < 3 {
        return; // edge-on / zero-length: the beam is invisible, skip
    }
    let avg = ((sz0 + sz1) / 2).max(render::NEAR_Z);
    // Beams read as thin bright lines; cap the half-width tightly (even a thick
    // bolt is only a few px) and keep it well under the length so short beams do
    // not become squares.
    let hw = ((half_world * render::projection_h()) / avg)
        .clamp(1, 4)
        .min((len / 4).max(1));
    // Screen-space perpendicular (-dy, dx), normalized to the half-width.
    let (px, py) = ((-dy * hw) / len, (dx * hw) / len);
    let a = ((x0 + px) as i16, (y0 + py) as i16);
    let b = ((x0 - px) as i16, (y0 - py) as i16);
    let d = ((x1 + px) as i16, (y1 + py) as i16);
    let e = ((x1 - px) as i16, (y1 - py) as i16);
    let otz = clamp_otz((avg as usize) >> OT_SHIFT);
    if let Some(packet) = packets.push(BeamTri::new([a, b, d], color)) {
        ot.add(otz, packet, BeamTri::WORDS);
    } else {
        unsafe { note_render_packet_drop(false) };
    }
    if let Some(packet) = packets.push(BeamTri::new([b, e, d], color)) {
        ot.add(otz, packet, BeamTri::WORDS);
    } else {
        unsafe { note_render_packet_drop(false) };
    }
}

/// Textured beam: the authored .spr (lgtning / plasma / laserbeam) drawn as a
/// jointed polyline of additive quads. V tiles one full sprite per segment and
/// scrolls by TextureScroll; interior joints sway by NoiseAmplitude (sine, per
/// beam phase-shifted); frames animate at ~5 Hz. Falls back to the flat quad
/// when the sprite frame is not resident (pack cap overflow).
#[allow(clippy::too_many_arguments)]
#[inline(never)]
unsafe fn draw_beam_textured(
    packets: &mut PrimitivePacketArena<'_>,
    ot: &mut OrderingTable<OT_LEN>,
    start: [i32; 3],
    end: [i32; 3],
    half_world: i32,
    color: (u8, u8, u8),
    sprite_id: usize,
    noise_world: i32,
    scroll: u8,
    seed: u16,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    let d = sprite::def(sprite_id);
    let frame = (BEAM_ANIM >> 2) as usize % d.n_frames.max(1) as usize;
    let sl = sprite::slot_for(sprite_id, frame);
    if d.n_frames == 0 || !sl.valid {
        draw_beam(packets, ot, start, end, half_world, color, rot, base_t);
        return;
    }
    let (Some((sx0, sy0, sz0)), Some((sx1, sy1, sz1))) = (
        project_world_point(start, rot, base_t),
        project_world_point(end, rot, base_t),
    ) else {
        return;
    };
    let (x0, y0, x1, y1) = (sx0 as i32, sy0 as i32, sx1 as i32, sy1 as i32);
    let (dx, dy) = (x1 - x0, y1 - y0);
    let len = isqrt_i32(dx * dx + dy * dy);
    if len < 3 {
        return;
    }
    let avg = ((sz0 + sz1) / 2).max(render::NEAR_Z);
    let h = render::projection_h();
    // The sprite's own falloff does the thinning, so textured beams keep their
    // authored width -- capped so a close-up bolt cannot fill the screen.
    let hw = ((half_world * h) / avg).clamp(1, 48).min(len);
    let (px, py) = ((-dy * hw) / len, (dx * hw) / len);
    let na = ((noise_world * h) / avg).clamp(0, 60);
    let segs = ((len / 28).max(1) as usize).min(7);
    let otz = clamp_otz((avg as usize) >> OT_SHIFT);
    let mat = sl.material.with_blend_mode(BlendMode::Add);
    let packet = TexturedGouraudPacketMaterial::from_texture(mat);
    let uw = d.crush_w.saturating_sub(1).min(255) as u8;
    let vspan = d.crush_h.clamp(1, 64) as i32;
    let v0 = ((BEAM_ANIM as i32 * scroll as i32) >> 3).rem_euclid(vspan) as u8;
    let v1 = v0 + (vspan - 1) as u8; // wraps inside the pow2 texture window
    let rgb = [color; 3];
    // Joint positions along the projected line, interior ones swayed.
    let mut jx = [0i32; 8];
    let mut jy = [0i32; 8];
    let mut i = 0usize;
    while i <= segs {
        let t = (i as i32) * 4096 / segs as i32;
        let mut x = x0 + ((dx * t) >> 12);
        let mut y = y0 + ((dy * t) >> 12);
        if i > 0 && i < segs && na > 0 {
            let ang =
                (((i as i32 * 1365) + (BEAM_ANIM as i32 * 220) + seed as i32) & 0x0fff) as u16;
            let off = (na * sincos::sin_q12(ang)) >> 12;
            x += (px * off) / hw;
            y += (py * off) / hw;
        }
        jx[i] = x;
        jy[i] = y;
        i += 1;
    }
    let cl = |v: i32| v.clamp(-1023, 1023) as i16;
    // Direct packet pushes: beams are dynamic overlays, so they must NOT run
    // through push_tri_uv_words (its world/tram cache capture would fold beam
    // packets into the cached world plan). Bit 25 forces semi-transparency so
    // the STP-set texels blend additively, exactly like BeamTri does.
    let mut emit =
        |packets: &mut PrimitivePacketArena<'_>, screen: [(i16, i16); 3], uv: [u16; 3]| {
            let prim = TriTexturedGouraud {
                tag: 0,
                tex_window: packet.tex_window_word,
                color0_cmd: (packet.color0_command_word | 0x0200_0000) | pack_rgb_word(rgb[0]),
                v0: pack_vertex_word(screen[0].0, screen[0].1),
                uv0_clut: uv[0] as u32 | packet.clut_high_word,
                color1: pack_rgb_word(rgb[1]),
                v1: pack_vertex_word(screen[1].0, screen[1].1),
                uv1_tpage: uv[1] as u32 | packet.tpage_high_word,
                color2: pack_rgb_word(rgb[2]),
                v2: pack_vertex_word(screen[2].0, screen[2].1),
                uv2: uv[2] as u32,
            };
            if let Some(pk) = packets.push(prim) {
                OT.add(otz, pk, TriTexturedGouraud::WORDS);
            } else {
                note_render_packet_drop(false);
            }
        };
    i = 0;
    while i < segs {
        let a = (cl(jx[i] + px), cl(jy[i] + py));
        let b = (cl(jx[i] - px), cl(jy[i] - py));
        let c = (cl(jx[i + 1] + px), cl(jy[i + 1] + py));
        let e = (cl(jx[i + 1] - px), cl(jy[i + 1] - py));
        emit(
            packets,
            [a, b, c],
            [uv_word((0, v0)), uv_word((uw, v0)), uv_word((0, v1))],
        );
        emit(
            packets,
            [b, e, c],
            [uv_word((uw, v0)), uv_word((uw, v1)), uv_word((0, v1))],
        );
        i += 1;
    }
}

/// Draw armed tripmine lasers from the wall normal retained in the projectile.
/// This costs two tiny OT triangles per live mine and no persistent RAM.
unsafe fn draw_tripmine_beams(
    packets: &mut PrimitivePacketArena<'_>,
    ot: &mut OrderingTable<OT_LEN>,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    let mut i = 0usize;
    while i < MAX_PROJECTILES {
        let p = PROJECTILES[i];
        let normal_sized = p.vel[0].abs().max(p.vel[1].abs()).max(p.vel[2].abs()) > 512;
        if p.active && p.kind == PROJ_TRIPMINE && p.life == 0 && normal_sized {
            let end = [
                p.pos[0] + ((p.vel[0] * 384) >> 12),
                p.pos[1] + ((p.vel[1] * 384) >> 12),
                p.pos[2] + ((p.vel[2] * 384) >> 12),
            ];
            draw_beam(packets, ot, p.pos, end, 1, (255, 30, 20), rot, base_t);
        }
        i += 1;
    }
}

/// Queue every world-space beam before the world OT is submitted. Static map
/// beams, bullet tracers, and armed tripmines share the same depth behavior.
unsafe fn queue_world_beams(
    packets: &mut PrimitivePacketArena<'_>,
    ot: &mut OrderingTable<OT_LEN>,
    m: &Map,
    nlogic: usize,
    rot: &Mat3I16,
    base_t: [i32; 3],
) {
    BEAM_ANIM = BEAM_ANIM.wrapping_add(1);
    let indexed = LOGIC_BEAM_COUNT != LOGIC_HOT_FALLBACK;
    let scan_count = if indexed {
        LOGIC_BEAM_COUNT as usize
    } else {
        nlogic
    };
    let mut scan = 0usize;
    let mut bk = 0usize;
    while scan < scan_count {
        let li = if indexed {
            LOGIC_BREAK_HP[LOGIC_STORAGE_WORDS - 1 - LOGIC_SPARK_COUNT as usize - scan] as usize
        } else {
            scan
        };
        if indexed || LOGIC_KIND[li] == map::LOGIC_BEAM {
            let rec = m.logic(li);
            let random = rec.arg0 & 0x10 != 0;
            let fa = rec.first_aux as usize;
            let (a0, a1, a2, a3) = (
                m.logic_aux(fa),
                m.logic_aux(fa + 1),
                m.logic_aux(fa + 2),
                m.logic_aux(fa + 3),
            );
            // Striking beams (random-area or life > 0) only draw during the
            // strike window tick_beams runs; steady beams draw whenever on.
            let strike_mode = random || (a1.delay_ticks & 0xFF) != 0;
            let visible = LOGIC_STATE[li] == LOGIC_STATE_TOP
                && (!strike_mode || (bk < MAX_BEAM_STATES && BEAM_LIFE[bk] > 0));
            if visible {
                let start = [
                    a0.target as i16 as i32,
                    a0.delay_ticks as i16 as i32,
                    a1.target as i16 as i32,
                ];
                let end = if random {
                    let e = BEAM_RAND_END[bk];
                    [e[0] as i32, e[1] as i32, e[2] as i32]
                } else {
                    [
                        a2.target as i16 as i32,
                        a2.delay_ticks as i16 as i32,
                        a3.target as i16 as i32,
                    ]
                };
                let c = rec.speed;
                let color = (
                    ((c & 0x1f) << 3) as u8,
                    (((c >> 5) & 0x1f) << 3) as u8,
                    (((c >> 10) & 0x1f) << 3) as u8,
                );
                let sprite_plus = (rec.arg0 & 0x0F) as usize;
                if sprite_plus > 0 {
                    let noise = ((rec.arg0 >> 5) & 0x7FF) as i32;
                    let scroll = (a1.delay_ticks >> 8) as u8;
                    draw_beam_textured(
                        packets,
                        ot,
                        start,
                        end,
                        rec.arg1 as i32,
                        color,
                        sprite_plus - 1,
                        noise,
                        scroll,
                        li as u16,
                        rot,
                        base_t,
                    );
                } else {
                    draw_beam(packets, ot, start, end, rec.arg1 as i32, color, rot, base_t);
                }
            }
            bk += 1;
        }
        scan += 1;
    }

    let mut ti = 0usize;
    while ti < MAX_TRACERS {
        let (start, end, ttl) = TRACERS[ti];
        if ttl > 0 {
            draw_beam(packets, ot, start, end, 3, (250, 220, 120), rot, base_t);
        }
        ti += 1;
    }
    draw_tripmine_beams(packets, ot, rot, base_t);
}

// First-person viewmodel transform. GoldSrc attaches the model to the camera:
// view.cpp copies the camera angles to the viewmodel and uses the predicted
// view origin, while the MDL vertices carry the actual first-person placement.
// Keep that authored placement here; only map HL's local axes into PSX view
// space and scale to this port's cooked-world/projection units.
const VM_BASE: Mat3I16 = Mat3I16 {
    m: [[0, 0, -4096], [0, -4096, 0], [4096, 0, 0]],
};
const VM_SCALE: i32 = 5;
const VM_VIEW_SHIFT: [i32; 3] = [30, 30, 40]; // PS1 viewport fit: right, down, deeper
const VM_CULL: bool = true;
const VM_OT_Z0: u32 = 48;
const VM_OT_STEP: u32 = 2;
const VM_CULL_POS: bool = true; // winding sign that is the backface
const VM_TWO_SIDED_TEX: usize = 0; // GLOVED_sleeve: avoid punched gaps in the orange arm
                                   // 2 px per VM unit approximates H/Z at the viewmodel's representative depth
                                   // (160 / 80) while keeping the projected cache invariant under procedural motion.
const VM_SCREEN_PX_PER_UNIT: i32 = 2;
const SHOW_VIEWMODEL: bool = true;

const VM_ANIM_IDLE: u8 = 0;
const VM_ANIM_FIRE: u8 = 1;
const VM_ANIM_ALT: u8 = 2;
const VM_ANIM_RELOAD: u8 = 3;
const VM_ANIM_DRAW: u8 = 4;
const VM_ANIM_RELOAD_PUMP: u8 = 5;
const VM_ANIM_RELOAD_START: u8 = 6;
const VM_ANIM_CHARGE_LOOP: u8 = 7;
const VM_ANIM_CHARGED_FIRE: u8 = 8;
const VM_ANIM_LAST: u8 = VM_ANIM_CHARGED_FIRE;
// Clip indices for [idle, primary, secondary/hit, reload, draw, pump,
// start-reload, charge-loop, charged-fire], keyed by the
// 16-entry WEAPON_MODELS order in host/hl-build. Duplicate states point at one
// source clip instead of retaining duplicate vertex streams.
const VM_ANIM_CLIPS: [[u8; 9]; 16] = [
    [0, 1, 1, 2, 3, 2, 2, 1, 1], // v_9mmhandgun
    [0, 1, 1, 2, 3, 2, 2, 1, 1], // v_357
    [0, 1, 2, 3, 4, 3, 3, 2, 2], // v_9mmar
    [0, 1, 1, 2, 3, 2, 2, 1, 1], // v_crossbow
    [0, 1, 2, 0, 3, 0, 0, 2, 1], // v_crowbar (miss / hit)
    [0, 1, 1, 0, 2, 0, 0, 1, 1], // v_chub
    [0, 1, 2, 0, 3, 0, 0, 2, 1], // v_egon
    [0, 3, 1, 0, 5, 0, 0, 2, 4], // v_gauss (spinup/spin/fire/fire2)
    [0, 1, 2, 0, 3, 0, 0, 2, 1], // v_grenade
    [0, 1, 1, 0, 2, 0, 0, 1, 1], // v_hgun
    [0, 1, 1, 2, 3, 2, 2, 1, 1], // v_rpg
    [0, 1, 1, 0, 2, 0, 0, 1, 1], // v_satchel
    [0, 1, 1, 0, 2, 0, 0, 1, 1], // v_satchel_radio
    [0, 1, 2, 3, 6, 4, 5, 2, 2], // v_shotgun
    [0, 1, 1, 0, 2, 0, 0, 1, 1], // v_squeak
    [0, 1, 2, 0, 3, 0, 0, 2, 1], // v_tripmine
];

#[inline]
fn viewmodel_anim_frame(
    md: &Model,
    wm: usize,
    kind: u8,
    started: u32,
    now: u32,
    hold_last: bool,
) -> (usize, usize, u32) {
    let clips = VM_ANIM_CLIPS[wm.min(VM_ANIM_CLIPS.len() - 1)];
    let kind = kind.min(VM_ANIM_LAST) as usize;
    let clip = clips[kind] as usize;
    let len = md.clip_len(clip).max(1);
    let duration = md.clip_hold_ticks(clip).max(1) as u32;
    let age = now.wrapping_sub(started);
    if kind == VM_ANIM_CHARGE_LOOP as usize {
        md.looped_clip_phase(clip, duration as usize, age as usize)
    } else if kind != VM_ANIM_IDLE as usize && age >= duration && hold_last {
        let frame = md.clip_frame(clip, len - 1);
        (frame, frame, 0)
    } else if kind == VM_ANIM_IDLE as usize || age >= duration {
        let idle = clips[VM_ANIM_IDLE as usize] as usize;
        let idle_duration = md.clip_hold_ticks(idle).max(1) as u32;
        md.looped_clip_phase(idle, idle_duration as usize, now as usize)
    } else {
        md.one_shot_clip_phase(clip, duration as usize, age as usize)
    }
}

#[inline]
fn viewmodel_anim_finished(md: &Model, wm: usize, kind: u8, started: u32, now: u32) -> bool {
    if kind == VM_ANIM_IDLE {
        return false;
    }
    let clips = VM_ANIM_CLIPS[wm.min(VM_ANIM_CLIPS.len() - 1)];
    let clip = clips[kind.min(VM_ANIM_LAST) as usize] as usize;
    now.wrapping_sub(started) >= md.clip_hold_ticks(clip).max(1) as u32
}

/// Build the viewmodel's GTE matrix: authored HL viewmodel axes plus the
/// first-person fit scale. The model-local precision scale is kept out of the
/// matrix and applied to translation/depth, matching the world-model path.
fn viewmodel_rot() -> Mat3I16 {
    let mut m = VM_BASE;
    let mut r = 0;
    while r < 3 {
        let mut c = 0;
        while c < 3 {
            m.m[r][c] =
                (m.m[r][c] as i32 * VM_SCALE).clamp(i16::MIN as i32, i16::MAX as i32) as i16;
            c += 1;
        }
        r += 1;
    }
    m
}

#[inline]
fn viewmodel_otz(avgz: u32) -> usize {
    let rel = avgz.saturating_sub(VM_OT_Z0) / VM_OT_STEP;
    1 + (rel as usize).min(VM_SORT_BUCKETS - 2)
}

fn draw_sky(m: &Map, yaw: u16, pitch: i16) {
    if m.sky_tex_base == SKY_TEX_NONE || m.sky_tex_base + SKY_FACE_COUNT > MAX_TEX_SLOTS {
        return;
    }
    // Cooker face order: ft, rt, bk, lf, up, dn.
    let sky_yaw = ((yaw as usize) + 512) & 0xFFF;
    let side = (sky_yaw >> 10) & 3;
    let face = if pitch > 760 {
        4
    } else if pitch < -760 {
        5
    } else {
        side
    };
    let slot = unsafe { TEX_SLOTS[m.sky_tex_base + face] };
    if !slot.valid {
        return;
    }
    let u0 = if face < 4 {
        (((sky_yaw & 1023) * SKY_TEX_SIZE) >> 10) as u8
    } else {
        0
    };
    let u1 = u0.wrapping_add((SKY_TEX_SIZE - 1) as u8);
    let v1 = (SKY_TEX_SIZE - 1) as u8;
    gpu::draw_quad_textured_material(
        [(0, 0), (319, 0), (0, 239), (319, 239)],
        [(u0, 0), (u1, 0), (u0, v1), (u1, v1)],
        slot.material,
    );
}

/// Small camera-space motion layered over the source animation. Reload/draw/fire
/// articulation now comes from the retail MDL; retaining only a quarter of the
/// old whole-model recoil avoids double-kicking while preserving impact.
fn viewmodel_offset(recoil: i32, phase: u32) -> [i32; 2] {
    let sin = |p: u32| Mat3I16::rotate_z((p as u16) & 0xFF).m[1][0] as i32; // q12 sine
    let bob_x = (sin(phase.wrapping_mul(4)) * 3) >> 12;
    let bob_y = (sin(phase.wrapping_mul(8)) * 2) >> 12;
    [bob_x, bob_y - recoil / 4]
}

/// Camera-space key light from packed cooked face normals. VM_BASE maps a
/// cooked normal (x,y,z) to view (-z,-y,x); the integer weights below are an
/// upper-left/front light without a per-face normalize or divide. A zero normal
/// denotes GoldSrc FLATSHADE and remains texture-neutral.
#[inline(always)]
fn vm_normal_shade(normal: [i8; 3]) -> u8 {
    let (x, y, z) = (normal[0] as i32, normal[1] as i32, normal[2] as i32);
    if (x | y | z) == 0 {
        return 128;
    }
    let dot = -(x << 2) + y * 3 + (z << 1);
    (104 + ((dot * 15) >> 8)).clamp(64, 144) as u8
}

/// Immediate GP0 equivalent of `TriTextured`. Viewmodels render after the
/// world's linked-list DMA, so a resident 44-byte OT packet per triangle buys
/// nothing; emitting eight words here recovers enough of the fixed reserve for
/// complete topology plus authored animation.
#[inline]
fn draw_vm_tri(
    packed_xy: [u32; 3],
    uv_words: [u16; 3],
    material: TexturedGouraudPacketMaterial,
    shade: u8,
    texture_window: &mut u32,
) {
    let rgb = shade as u32 | ((shade as u32) << 8) | ((shade as u32) << 16);
    psx_io::gpu::wait_cmd_ready();
    let next_window = material.tex_window_word;
    if next_window != *texture_window {
        psx_io::gpu::write_gp0(next_window);
        *texture_window = next_window;
    }
    psx_io::gpu::write_gp0((material.color0_command_word & !0x1000_0000) | rgb);
    psx_io::gpu::write_gp0(packed_xy[0]);
    psx_io::gpu::write_gp0(uv_words[0] as u32 | material.clut_high_word);
    psx_io::gpu::write_gp0(packed_xy[1]);
    psx_io::gpu::write_gp0(uv_words[1] as u32 | material.tpage_high_word);
    psx_io::gpu::write_gp0(packed_xy[2]);
    psx_io::gpu::write_gp0(uv_words[2] as u32);
}

/// Draw the complete held weapon after the world OT. Projected vertices cache
/// by authored interpolated pose; every visual performs only a compact u16 bucket sort and
/// immediate GP0 emission. Procedural motion remains a temporary draw offset,
/// so it does not invalidate projection data.
unsafe fn draw_viewmodel(
    md: &Model,
    slots: &[TexSlot],
    frame: usize,
    frame2: usize,
    frac16: u32,
    emit: bool,
) -> usize {
    if slots.is_empty() {
        return 0; // viewmodel texture failed to upload: skip rather than index empty
    }
    if md.n_tris > MAX_WEAPON_TRIS {
        // Never draw a partial weapon. The host asset audit keeps retail models
        // below this bound; a future asset must raise the compact u16 scratch.
        return 0;
    }
    let nv = md.n_verts.min(MAX_MODEL_VERTS);
    let local_to_world = md.local_to_world_q12();
    let (s, scale_shift) = model_local_scale_and_shift(local_to_world);
    let (projected_xy, projected_z) = weapon_projected_ptrs();
    let near_s = (NEAR as i32 * s) as u16;
    let pose_key = (frame as u32 & 0x3ff)
        | ((frame2 as u32 & 0x3ff) << 10)
        | ((frac16.min(15) & 0x0f) << 20)
        | (u32::from(render::projection_h() != H_PROJ as i32) << 24);
    let rebuild_cache = WEAPON_CACHE_POSE != pose_key
        || WEAPON_CACHE_VERTS != nv
        || WEAPON_CACHE_SCALE != local_to_world;
    if rebuild_cache {
        let r = viewmodel_rot();
        // Project the muzzle through the very transform the vertices use, so
        // the flash tracks the barrel for every weapon instead of sitting at a
        // fixed screen point tuned for one of them.
        let muzzle = VM_MUZZLE_MODEL[WEAPON_MUZZLE_SLOT.min(13)];
        if muzzle != [0, 0, 0] {
            scene::load_rotation(&r);
            scene::load_translation(Vec3I32::new(
                VM_VIEW_SHIFT[0] * s,
                VM_VIEW_SHIFT[1] * s,
                VM_VIEW_SHIFT[2] * s,
            ));
            let p = project_vertex_scheduled(Vec3I16::new(muzzle[0], muzzle[1], muzzle[2]));
            if p.sz as i32 > render::NEAR_Z {
                VM_MUZZLE_SCREEN = (p.sx, p.sy);
            }
        }
        project_hmd7_model(
            md,
            frame,
            frame2,
            frac16,
            0,
            0,
            &r,
            Vec3I32::new(
                VM_VIEW_SHIFT[0] * s,
                VM_VIEW_SHIFT[1] * s,
                VM_VIEW_SHIFT[2] * s,
            ),
            projected_xy,
            projected_z,
        );
        WEAPON_CACHE_POSE = pose_key;
        WEAPON_CACHE_VERTS = nv;
        WEAPON_CACHE_SCALE = local_to_world;
        // The held model is camera-locked. Its procedural bob/recoil is a GPU
        // draw offset, so a stable authored frame has stable cull/depth order.
        // Keep the bucket links beside the projected-vertex cache instead of
        // re-reading and sorting every retail triangle on every visual frame.
        let heads = weapon_tri_heads_ptr();
        let records = weapon_tri_records_ptr();
        let indices = weapon_tri_indices_ptr();
        for bucket in 0..VM_SORT_BUCKETS {
            heads.add(bucket).write(VM_SORT_NONE);
        }
        for t in 0..md.n_tris {
            let tri = md.tri(t);
            let tex_id = tri.tex;
            let slot = slots[tex_id.min(slots.len() - 1)];
            if !slot.valid {
                continue;
            }
            let (a, b, c) = (
                tri.idx[0] as usize,
                tri.idx[1] as usize,
                tri.idx[2] as usize,
            );
            let (pa, pb, pc) = (
                projected_soa_get(projected_xy, projected_z, a),
                projected_soa_get(projected_xy, projected_z, b),
                projected_soa_get(projected_xy, projected_z, c),
            );
            if pa.sz < near_s || pb.sz < near_s || pc.sz < near_s {
                continue;
            }
            if VM_CULL && tex_id != VM_TWO_SIDED_TEX {
                if culled_gte(
                    (pa.sx as i32, pa.sy as i32),
                    (pb.sx as i32, pb.sy as i32),
                    (pc.sx as i32, pc.sy as i32),
                ) == VM_CULL_POS
                {
                    continue;
                }
            }
            let avgz = model_unscale_depth(
                ((pa.sz as u32) + (pb.sz as u32) + (pc.sz as u32)) / 3,
                scale_shift,
            );
            let bucket = viewmodel_otz(avgz);
            let packed_indices = (tri.idx[0] as u32 & model::RENDER_FACE_INDEX_MASK)
                | ((tri.idx[1] as u32 & model::RENDER_FACE_INDEX_MASK) << 10)
                | ((tri.idx[2] as u32 & model::RENDER_FACE_INDEX_MASK) << 20);
            indices.add(t).write(packed_indices);
            records.add(t).write(
                *heads.add(bucket) as u32
                    | ((tex_id as u32 & 0xff) << VM_SORT_TEX_SHIFT)
                    | ((settings::bright(vm_normal_shade(tri.normal)) as u32)
                        << VM_SORT_SHADE_SHIFT),
            );
            heads.add(bucket).write(t as u16);
        }
    }

    // The world OT can DMA while the CPU projects and sorts the held model.
    // A prepare-only call stops here; a second call after the DMA wait sees the
    // same pose key and performs only the ordered GP0 emission.
    if !emit {
        return 0;
    }

    let heads = weapon_tri_heads_ptr();
    let records = weapon_tri_records_ptr();
    let indices = weapon_tri_indices_ptr();
    let mut submitted = 0usize;
    // E2 is global GPU state, not part of the polygon itself. Viewmodel tris
    // are emitted consecutively, so repeat it only when the authored material
    // window changes; the first triangle always establishes a known value.
    let mut texture_window = u32::MAX;
    for bucket in (0..VM_SORT_BUCKETS).rev() {
        let mut link = *heads.add(bucket);
        while link != VM_SORT_NONE {
            let t = link as usize;
            let record = records.add(t).read();
            let packed_indices = indices.add(t).read();
            let tex = ((record >> VM_SORT_TEX_SHIFT) & 0xff) as usize;
            let shade = ((record >> VM_SORT_SHADE_SHIFT) & 0xff) as u8;
            let slot = slots[tex.min(slots.len() - 1)];
            let a = (packed_indices & model::RENDER_FACE_INDEX_MASK) as usize;
            let b = ((packed_indices >> 10) & model::RENDER_FACE_INDEX_MASK) as usize;
            let c = ((packed_indices >> 20) & model::RENDER_FACE_INDEX_MASK) as usize;
            let packed_xy = [
                projected_xy.add(a).read(),
                projected_xy.add(b).read(),
                projected_xy.add(c).read(),
            ];
            let uv_words = md.tri_uv_words(t);
            draw_vm_tri(packed_xy, uv_words, slot.packet, shade, &mut texture_window);
            submitted += 1;
            link = (record & VM_SORT_LINK_MASK) as u16;
        }
    }
    submitted
}

/// Stack high-water probe (telemetry builds only): paint the free region
/// between the statics and the live stack at boot, then report the lowest
/// canary the stack ever clobbered. This measures the real stack need behind
/// the linker's fixed safety reserve.
#[cfg(feature = "emulator-telemetry")]
mod stackprobe {
    use psx_math::fmt::{i32_dec, I32_DEC_MAX};

    const CANARY: u32 = 0x5AC4_57AC;
    extern "C" {
        static __bss_end: u8;
    }

    fn region() -> (usize, usize) {
        let lo = (unsafe { core::ptr::addr_of!(__bss_end) } as usize + 3) & !3;
        // A local's address stands in for SP (inline asm is unstable on MIPS);
        // the guard below keeps us clear of the live frame either way.
        let marker = 0u32;
        let sp = core::ptr::addr_of!(marker) as usize;
        (lo, sp.saturating_sub(256) & !3)
    }

    pub fn paint() {
        let (lo, hi) = region();
        let mut p = lo;
        while p < hi {
            unsafe { (p as *mut u32).write_volatile(CANARY) };
            p += 4;
        }
    }

    /// Guest-debug-log one line: bytes never touched above the statics, and
    /// the peak stack depth measured from the 0x8020_0000 RAM top.
    pub fn report() {
        let (lo, _) = region();
        let mut p = lo;
        while unsafe { (p as *const u32).read_volatile() } == CANARY {
            p += 4;
        }
        let mut line = [0u8; 64];
        let mut n = 0;
        let mut push = |s: &[u8]| {
            for &b in s {
                if n < line.len() {
                    line[n] = b;
                    n += 1;
                }
            }
        };
        let mut buf = [0u8; I32_DEC_MAX];
        push(b"stackwm free=");
        push(i32_dec(&mut buf, (p - lo) as i32).as_bytes());
        push(b" peak=");
        push(i32_dec(&mut buf, (0x8020_0000 - p) as i32).as_bytes());
        crate::telemetry::debug_log(core::str::from_utf8(&line[..n]).unwrap_or("stackwm"));
    }
}

/// The retail BIOS and warm-boot environments do not guarantee that COP2 is
/// enabled when control reaches PSX.EXE. Enable the GTE explicitly before the
/// first scene setup command; relying on inherited COP0 Status.CU2 left the
/// game at a black screen in DuckStation's clean boot environment.
#[cfg(target_arch = "mips")]
#[inline(always)]
fn enable_cop2() {
    let mut status: u32;
    unsafe {
        core::arch::asm!("mfc0 $8, $12", lateout("$8") status);
        status |= 0x4000_0000;
        core::arch::asm!(
            "mtc0 $8, $12",
            "nop",
            "nop",
            "nop",
            in("$8") status,
            options(nostack, nomem, preserves_flags),
        );
    }
}

#[no_mangle]
#[optimize(size)]
fn main() {
    tty::println("hl-psx: booting renderer");
    enable_cop2();
    unsafe {
        init_pvs_link_sentinels();
        init_data_defaults();
    };
    // Hardware scratchpad sits outside BSS and has unspecified warm-boot
    // contents. Clear it before interrupts or a render cache can observe it.
    unsafe { scratchpad::clear() };
    #[cfg(feature = "emulator-telemetry")]
    stackprobe::paint();

    gpu::init(VideoMode::Ntsc, Resolution::R320X240);
    let mut fb = FrameBuffer::new(320, 240);
    gpu::set_draw_area(0, 0, 319, 239);
    gpu::set_draw_offset(0, 0);
    scene::set_screen_offset(160 << 16, 120 << 16);
    scene::set_projection_plane(H_PROJ);
    // Models are no longer loaded here: play() streams each map's model set into
    // the pool (stream_map_models) after the world loads.

    // SFX: stream the cooked SPU-ADPCM pack once and park it in SPU RAM (its
    // own 512 KB; no main-RAM cost). MAP_BUF is free until the first map loads,
    // so stage through it.
    let sfx_ready = {
        let len = cdstream::load_chunk_decompressed(sfx::CHUNK_ID, unsafe { map_buf() })
            .map(|load| load.raw_len)
            .unwrap_or(0);
        let bytes = unsafe { streamed_map_bytes(len) };
        if len > 0 {
            let ready = unsafe { sfx::init_from_pack(bytes) };
            if ready > 0 {
                unsafe { ACTIVE_SFX_CHUNK = sfx::CHUNK_ID };
            }
            ready
        } else {
            0
        }
    };
    if sfx_ready == 0 {
        tty::println("hl-psx: SFX pack missing/failed (silent boot)");
    }

    // Keep the branded presentation out of deterministic direct-map builds so
    // their route timing and performance counters begin at exactly the same
    // guest state. Shipping boots mirror the Celeste collection's PSoXide
    // splash before entering the original-style Half-Life menu.
    if !DBG_PAD_BOOT {
        menu::intro(&mut fb, unsafe { stream_menu_assets() });
    }

    // Boot flow: pick a map in the menu, stream + play it, return on Select.
    // (Analog is enabled inside play(); the menu runs on the digital pad.)
    loop {
        // Debug: the headless harness holds L1 with a map index in the pad's low
        // byte to boot any map directly (the menu only exposes 19 chapter starts),
        // for all-maps load verification. Released before gameplay.
        let mut dbg_sel = None;
        if DBG_PAD_BOOT {
            #[cfg(feature = "performance-telemetry")]
            unsafe {
                DEBUG_PERF_WALK_ROUTE = false;
                // `affine-heatmap` records the error distribution for a whole
                // run instead of only for launches that hold R1 with a matching
                // selector. Without it the `*_error_texels` columns stay zero
                // and a tessellation change cannot be judged at all.
                DEBUG_AFFINE_HEATMAP_ACTIVE = cfg!(feature = "affine-heatmap");
            }
            let mut i = 0;
            while i < 150 {
                interrupts::wait_vblank();
                fb.swap();
                let b = poll_port1().buttons;
                if b.is_held(button::L1) {
                    dbg_sel = Some((b.bits() & 0xFF) as usize);
                    let selector = ((b.bits() >> 12) & 0x0F) as usize;
                    #[cfg(feature = "performance-telemetry")]
                    unsafe {
                        DEBUG_AFFINE_HEATMAP_ACTIVE = cfg!(feature = "affine-heatmap")
                            || b.is_held(button::R1)
                                && (selector == DEBUG_REGRESSION_SELECTOR
                                    || selector == DEBUG_SAVED_VIEW_SELECTOR
                                    || selector == DEBUG_LADDER_VIEW_SELECTOR
                                    || selector == DEBUG_MOMENTARY_VIEW_SELECTOR
                                    || selector == DEBUG_PUSHABLE_VIEW_SELECTOR
                                    || selector == DEBUG_ENTRY_VIEW_SELECTOR
                                    || selector == DEBUG_PANEL_VIEW_SELECTOR
                                    || selector == 0);
                        DEBUG_PERF_WALK_ROUTE =
                            b.is_held(button::R1) && !DEBUG_AFFINE_HEATMAP_ACTIVE;
                    }
                    if DEBUG_ALL_WEAPONS {
                        // Selector 1..14 maps to weapon 0..13. This is sampled
                        // before the room load, so the face-button bits are
                        // released long before gameplay input begins.
                        unsafe {
                            DEBUG_GALLERY_WEAPON = if selector == 0
                                || (DEBUG_REGRESSION_VIEWPOINTS
                                    && (selector == DEBUG_REGRESSION_SELECTOR
                                        || selector == DEBUG_SAVED_VIEW_SELECTOR
                                        || selector == DEBUG_LADDER_VIEW_SELECTOR
                                        || selector == DEBUG_MOMENTARY_VIEW_SELECTOR
                                        || selector == DEBUG_PUSHABLE_VIEW_SELECTOR
                                        || selector == DEBUG_ENTRY_VIEW_SELECTOR
                                        || selector == DEBUG_PANEL_VIEW_SELECTOR
                                        || selector == DEBUG_TRAIN_VIEW_SELECTOR
                                        || selector == DEBUG_GUNTARGET_VIEW_SELECTOR))
                            {
                                W_GLOCK as u8
                            } else {
                                (selector - 1).min(N_WEAPONS - 1) as u8
                            };
                        }
                    }
                    break;
                }
                i += 1;
            }
        }
        // Instrumented direct-map discs never need the interactive menu. Making
        // the timeout fall back to map zero lets LTO discard menu-only code and
        // leaves enough executable RAM for profiler hooks; shipping still takes
        // the ordinary menu path because DBG_PAD_BOOT is a compile-time false.
        let sel = if DBG_PAD_BOOT {
            dbg_sel.unwrap_or(0)
        } else {
            menu::run(&mut fb, unsafe { stream_menu_assets() })
        };
        let mut launch = menu_launch(sel);
        if DEBUG_REGRESSION_VIEWPOINTS && dbg_sel.is_some() {
            let selector = ((poll_port1().buttons.bits() >> 12) & 0x0F) as usize;
            if selector == DEBUG_REGRESSION_SELECTOR {
                // Diagnostic-only sentinel consumed after the cooked map is
                // resident. Shipping launches always retain pitch zero here.
                launch.pitch = i16::MIN;
            } else if selector == DEBUG_SAVED_VIEW_SELECTOR {
                launch.pitch = DEBUG_SAVED_VIEW_PITCH_SENTINEL;
            } else if selector == DEBUG_LADDER_VIEW_SELECTOR {
                launch.pitch = DEBUG_LADDER_VIEW_PITCH_SENTINEL;
            } else if selector == DEBUG_MOMENTARY_VIEW_SELECTOR {
                launch.pitch = DEBUG_MOMENTARY_VIEW_PITCH_SENTINEL;
            } else if selector == DEBUG_PUSHABLE_VIEW_SELECTOR {
                launch.pitch = DEBUG_PUSHABLE_VIEW_PITCH_SENTINEL;
            } else if selector == DEBUG_ENTRY_VIEW_SELECTOR {
                launch.pitch = DEBUG_ENTRY_VIEW_PITCH_SENTINEL;
            } else if selector == DEBUG_PANEL_VIEW_SELECTOR {
                launch.pitch = DEBUG_PANEL_VIEW_PITCH_SENTINEL;
            } else if selector == DEBUG_TRAIN_VIEW_SELECTOR {
                launch.pitch = DEBUG_TRAIN_VIEW_PITCH_SENTINEL;
            } else if selector == DEBUG_GUNTARGET_VIEW_SELECTOR {
                launch.pitch = DEBUG_GUNTARGET_VIEW_PITCH_SENTINEL;
            }
        }
        #[cfg(feature = "semantic-input")]
        let mut semantic_player = {
            let tape = match semantic_input::Tape::parse(SEMANTIC_INPUT_BYTES) {
                Ok(tape) => tape,
                Err(_) => panic!("invalid HLINPUT1 route"),
            };
            let mut player = semantic_input::Player::new(tape);
            // Direct-map debug boots may begin in the middle of a full route.
            // Seek once here; later changelevels still consume the remaining
            // HLINPUT1 segments in strict order.
            if let Some(_) = dbg_sel {
                let Some(map_name) = menu::MAPS.get(sel) else {
                    panic!("debug map index outside campaign registry");
                };
                if player.seek_to_map(map_name).is_err() {
                    panic!("HLINPUT1 direct map missing from route");
                }
            }
            player
        };
        // Build-time reference checkpoints are consumed by the first loaded
        // map only. Natural changelevels must preserve the state produced by
        // gameplay instead of reapplying the direct-boot checkpoint.
        #[cfg(feature = "semantic-input")]
        let mut semantic_checkpoint_pending = true;
        #[cfg(feature = "route-follow")]
        let follow_route = match route_follow::Route::parse(ROUTE_WAYPOINT_BYTES) {
            Ok(route) => route,
            Err(_) => panic!("invalid HLWPTS1 route"),
        };
        #[cfg(feature = "route-follow")]
        let mut follower = route_follow::Follower::new();
        // First load comes from the menu (fresh -> full loading card). A
        // changelevel re-enters play() with the previous frame still on screen,
        // so keep it frozen and overlay only a tiny "Loading" strip.
        let mut keep_frame = false;
        loop {
            match play(
                &mut fb,
                launch,
                keep_frame,
                #[cfg(feature = "semantic-input")]
                &mut semantic_player,
                #[cfg(feature = "semantic-input")]
                &mut semantic_checkpoint_pending,
                #[cfg(feature = "route-follow")]
                follow_route,
                #[cfg(feature = "route-follow")]
                &mut follower,
            ) {
                exit @ (PlayExit::BackToMenu | PlayExit::Ending) => {
                    // Silence the physical drive and SPU route before the first
                    // menu frame. Keeping this out of the cold boot path also
                    // avoids issuing any CD command between the intro's two
                    // menu-asset streams.
                    unsafe { music_stop_for_menu() };
                    if matches!(exit, PlayExit::Ending) {
                        menu::ending(&mut fb, unsafe { stream_menu_assets() });
                    }
                    break;
                }
                PlayExit::ChangeLevel(next) => {
                    // Shut the CD input before the next play() starts its
                    // WORLD.PAK reads. Real hardware otherwise exposes the
                    // CDDA-to-data handoff as a persistent buzz.
                    unsafe { music_suspend_for_stream() };
                    launch = next;
                    keep_frame = true;
                }
                PlayExit::Restart(checkpoint) => {
                    // Death reloads the room from its immutable entry handoff.
                    // Keeping the final red frame avoids flashing stale room
                    // geometry while WORLD.PAK and the checkpoint assets stream.
                    unsafe { music_suspend_for_stream() };
                    launch = checkpoint;
                    keep_frame = true;
                }
                PlayExit::Chapter(next) => {
                    // A pause-menu chapter jump is a fresh campaign start, not
                    // a landmark transition. Reset through menu_launch and use
                    // the full loading card instead of preserving this scene.
                    unsafe { music_suspend_for_stream() };
                    launch = next;
                    keep_frame = false;
                }
            }
        }
    }
}

#[inline(always)]
fn room_world_chunk_id(room_id: u32) -> u32 {
    room_id.saturating_mul(ROOM_WORLD_CHUNK_MUL)
}

#[inline(always)]
fn room_texture_chunk_id(room_id: u32) -> u32 {
    room_world_chunk_id(room_id).saturating_add(ROOM_TEXTURE_CHUNK_ADD)
}

#[inline]
fn account_streamed_chunk(
    load: cdstream::ChunkLoad,
    chunks: &mut u32,
    bytes: &mut u32,
    sectors: &mut u32,
) {
    *chunks = chunks.saturating_add(1);
    *bytes = bytes.saturating_add(load.stored_len as u32);
    *sectors = sectors.saturating_add(((load.stored_len as u32) + 2047) / 2048);
}

#[inline]
fn load_streamed_chunk(chunk_id: u32, dst: &mut [u32]) -> Option<cdstream::ChunkLoad> {
    telemetry::stage_begin(telemetry::stage::CD_WORLD_PACK_STREAM);
    let loaded = cdstream::load_chunk_decompressed(chunk_id, dst);
    telemetry::stage_end(telemetry::stage::CD_WORLD_PACK_STREAM);
    loaded
}

#[inline]
unsafe fn load_accounted_map_chunk(
    chunk_id: u32,
    stream_chunks: &mut u32,
    stream_bytes: &mut u32,
    stream_sectors: &mut u32,
) -> Option<cdstream::ChunkLoad> {
    let load = load_streamed_chunk(chunk_id, map_buf())?;
    account_streamed_chunk(load, stream_chunks, stream_bytes, stream_sectors);
    Some(load)
}

fn stream_model_texture_chunk(
    chunk_id: u32,
    dst_word: usize,
    stage_end: usize,
    slots: *mut TexSlot,
    slot_len: usize,
    stream_chunks: &mut u32,
    stream_bytes: &mut u32,
    stream_sectors: &mut u32,
) -> Option<(usize, usize)> {
    // Stage the texture in the free tail above the geometry loaded so far, NOT
    // at offset 0 (offset 0 holds live geometry draw_model reads; a texture
    // there would clobber it and crash -- this was c1a2a). `stage_end` bounds
    // the scratch so it cannot spill into the NEXT region: a viewmodel streamed
    // mid-switch stages inside the pool (stage_end = VM_POOL_WORDS) and never
    // touches the resident enemies above it. load_chunk refuses a chunk larger
    // than its destination, so a tex that won't fit is skipped (untextured).
    let load = {
        let buf = unsafe { core::slice::from_raw_parts_mut(model_ptr(), model_capacity()) };
        let end = stage_end.min(buf.len());
        if dst_word >= end {
            return None;
        }
        load_streamed_chunk(chunk_id, &mut buf[dst_word..end])
    };
    let Some(load) = load else {
        return None;
    };
    let len = load.raw_len;
    account_streamed_chunk(load, stream_chunks, stream_bytes, stream_sectors);
    let bytes = unsafe { streamed_model_bytes_at(dst_word * 4, len) };
    telemetry::stage_begin(telemetry::stage::VRAM_UPLOAD);
    let uploaded = unsafe { vram::upload_tex_chunk_append_raw(bytes, slots, slot_len) };
    telemetry::stage_end(telemetry::stage::VRAM_UPLOAD);
    uploaded
}

/// Stream a room from WORLD.PAK, upload its textures, and run the renderer +
/// physics loop until Select returns to menu or a trigger_changelevel requests
/// the next room.
#[cfg(feature = "reference-trace")]
#[inline(never)]
unsafe fn trace_brush_entities(m: &Map, map_tick: u32) {
    let nents = m.n_ents.min(MAX_ENTS);
    let nlogic = m.n_logic.min(MAX_LOGIC);
    let mut ei = 0usize;
    while ei < nents {
        let e = ENT_CACHE[ei];
        let mut logic_match = None;
        let mut li = 0usize;
        while li < nlogic {
            let rec = m.logic(li);
            if rec.brush as usize == ei {
                logic_match = Some((li, rec));
                break;
            }
            li += 1;
        }

        let base_class = match e.kind {
            0 => Some("func_wall"),
            1 => Some("func_door"),
            // Non-moving props deliberately keep a zero
            // translation vector in the compact format. They remain usable;
            // omit them here because GoldSrc identifies them as
            // `func_rot_button`, outside the movable-brush parity set.
            3 if e.mv != [0; 3] => Some("func_button"),
            5 => Some("func_rotating"),
            7 => Some("func_door_rotating"),
            ENT_KIND_PLATROT => Some("func_platrot"),
            ENT_KIND_PUSHABLE => Some("func_pushable"),
            ENT_KIND_PENDULUM => Some("func_pendulum"),
            ENT_KIND_ROT_BUTTON => Some("func_rot_button"),
            _ => None,
        };
        let class = match logic_match.map(|(_, rec)| rec.kind) {
            Some(map::LOGIC_FUNC_TRAIN) => Some("func_train"),
            Some(map::LOGIC_FUNC_TRACKTRAIN) => Some("func_tracktrain"),
            Some(map::LOGIC_FUNC_BREAKABLE) if e.kind == ENT_KIND_PUSHABLE => Some("func_pushable"),
            Some(map::LOGIC_FUNC_BREAKABLE) => Some("func_breakable"),
            Some(map::LOGIC_WALL_TOGGLE) => Some("func_wall_toggle"),
            Some(map::LOGIC_FUNC_DOOR) if e.kind == 7 => Some("func_door_rotating"),
            Some(map::LOGIC_FUNC_DOOR) if e.kind == ENT_KIND_PLATROT => Some("func_platrot"),
            Some(map::LOGIC_FUNC_DOOR) => Some("func_door"),
            Some(map::LOGIC_HEALTH_CHARGER) => Some("func_healthcharger"),
            Some(map::LOGIC_HEV_CHARGER) => Some("func_recharge"),
            Some(map::LOGIC_FUNC_PENDULUM) => Some("func_pendulum"),
            Some(map::LOGIC_TANK) => Some("func_tank"),
            _ => base_class,
        };
        let Some(class) = class else {
            ei += 1;
            continue;
        };

        let (targetname, health, state, spawnflags) = if let Some((li, rec)) = logic_match {
            (
                m.logic_name(rec.targetname),
                if rec.kind == map::LOGIC_FUNC_BREAKABLE {
                    LOGIC_BREAK_HP[li]
                } else {
                    0
                },
                LOGIC_STATE[li],
                rec.spawnflags,
            )
        } else {
            // Untargeted fans intentionally have no LogicEnt, but their raw
            // SDK flags still matter to parity traces and the stateless phase.
            ("", 0, 0, if e.kind == 5 { e.mv[2] as u16 } else { 0 })
        };
        let off = ent_draw_offset(ei);
        let yaw_q12 = if e.kind == ENT_KIND_PLATROT {
            platrot_yaw(e, ENT_PHASE[ei]) as i32
        } else if e.kind == 5 {
            fan_angle_q12(ei, map_tick) as i32
        } else if e.kind == 7 || e.kind == ENT_KIND_ROT_BUTTON {
            let movement = (ENT_PHASE[ei].wrapping_mul(e.mv[0]) >> 12) & 0x0fff;
            movement + (((e.mv[2] as u32 >> 8) & 0xff) << 4) as i32
        } else if e.kind == ENT_KIND_PENDULUM {
            pendulum_angle_q12(ei) as i32
        } else {
            0
        };
        let center = if e.kind == ENT_KIND_PLATROT {
            platrot_local_to_world(e.center, off, &platrot_rotation(e, ENT_PHASE[ei]))
        } else if e.kind == 5 {
            let r = fan_rotation(e, yaw_q12 as u16);
            rotating_local_center(e, r)
        } else if e.kind == ENT_KIND_PENDULUM {
            rotating_local_center(e, pendulum_rotation(e, yaw_q12 as u16))
        } else if e.kind == 7 || e.kind == ENT_KIND_ROT_BUTTON {
            // yaw_q12 includes the packed base angle for the trace payload;
            // axial_brush_rotation adds that base itself, so feed it only the
            // live door movement here.
            let movement = ((ENT_PHASE[ei] * e.mv[0]) >> 12) as u16 & 0x0fff;
            let r = axial_brush_rotation(e, movement);
            [
                off[0] + dot12(r.m[0], e.center),
                off[1] + dot12(r.m[1], e.center),
                off[2] + dot12(r.m[2], e.center),
            ]
        } else {
            [
                e.center[0] + off[0],
                e.center[1] + off[1],
                e.center[2] + off[2],
            ]
        };
        reference_trace::entity(reference_trace::EntityState {
            map_tick,
            slot: ei as u16,
            class,
            targetname,
            brush: e.submodel as i32,
            pos: if e.kind == 7 && ENT_TRAIN_SLOT[ei] != 0xFF {
                off
            } else if e.kind == 5
                || e.kind == 7
                || e.kind == ENT_KIND_ROT_BUTTON
                || e.kind == ENT_KIND_PENDULUM
            {
                e.origin
            } else {
                off
            },
            center,
            vel: [0; 3],
            yaw_q12,
            health,
            active: ENT_ACTIVE[ei] != 0,
            state,
            phase: if e.kind == 5 {
                fan_angle_q12(ei, map_tick) as i32
            } else if e.kind == ENT_KIND_PENDULUM {
                pendulum_phase_q19(ei)
            } else {
                ENT_PHASE[ei]
            },
            spawnflags,
        });
        ei += 1;
    }
}

#[cfg(feature = "reference-trace")]
#[inline(never)]
unsafe fn trace_point_actors(m: &Map, map_tick: u32) {
    // A monstermaker is a live point entity, while its preallocated PropRec is
    // only dormant stock and does not exist in GoldSrc until MakeMonster. Emit
    // the former and suppress the latter so the trace describes game state,
    // not this port's allocation strategy.
    let nlogic = m.n_logic.min(MAX_LOGIC);
    let mut li = 0usize;
    while li < nlogic {
        let rec = m.logic(li);
        if rec.kind == map::LOGIC_MONSTERMAKER && LOGIC_STATE[li] != LOGIC_STATE_REMOVED {
            reference_trace::entity(reference_trace::EntityState {
                map_tick,
                slot: 0x4000 | li as u16,
                class: "monstermaker",
                targetname: m.logic_name(rec.targetname),
                brush: -1,
                pos: rec.origin,
                center: rec.origin,
                vel: [0; 3],
                yaw_q12: 0,
                health: 0,
                active: true,
                state: LOGIC_STATE[li],
                phase: LOGIC_COUNTER[li] as i32,
                spawnflags: rec.spawnflags,
            });
        }
        li += 1;
    }

    let nprops = PROP_COUNT.min(CARRY_MAILBOX_FIRST);
    let mut pi = 0usize;
    while pi < nprops {
        if PROP_DORMANT[pi] & PROP_RUNTIME_DORMANT_STOCK != 0 {
            pi += 1;
            continue;
        }
        let passive_generic = PROP_DORMANT[pi] & PROP_RUNTIME_PRISONER != 0
            && matches!(PROP_KIND[pi], PROP_TYPE_SCIENTIST | PROP_TYPE_BARNEY);
        let class = match PROP_KIND[pi] {
            PROP_TYPE_SCIENTIST if passive_generic => Some("monster_generic"),
            PROP_TYPE_BARNEY if passive_generic => Some("monster_generic"),
            PROP_TYPE_SCIENTIST => Some("monster_scientist"),
            PROP_TYPE_BARNEY => Some("monster_barney"),
            PROP_TYPE_HEADCRAB => Some("monster_headcrab"),
            5 => Some("monster_zombie"),
            PROP_TYPE_HOUNDEYE => Some("monster_houndeye"),
            PROP_TYPE_BULLSQUID => Some("monster_bullchicken"),
            8 => Some("monster_human_grunt"),
            9 => Some("monster_alien_slave"),
            10 => Some("monster_alien_grunt"),
            PROP_TYPE_CONTROLLER => Some("monster_alien_controller"),
            12 => Some("monster_barnacle"),
            13 => Some("monster_leech"),
            14 => Some("monster_cockroach"),
            15 => Some("monster_gman"),
            16 => Some("monster_gargantua"),
            17 => Some("monster_nihilanth"),
            18 => Some("monster_bigmomma"),
            19 => Some("monster_ichthyosaur"),
            20 => Some("monster_sentry"),
            21 => Some("monster_turret"),
            22 => Some("monster_miniturret"),
            23 => Some("monster_apache"),
            24 => Some("monster_flyer_flock"),
            PROP_TYPE_SITTING_SCI => Some("monster_sitting_scientist"),
            50 => Some("monster_tentacle"),
            51 => Some("monster_human_assassin"),
            57 => Some("monster_tripmine"),
            58 => Some("monster_snark"),
            59 => Some("monster_babycrab"),
            60 => Some("monster_rat"),
            61 => Some("monster_osprey"),
            PROP_TYPE_LOADER => Some("monster_generic"),
            PROP_TYPE_FORKLIFT => Some("monster_generic"),
            PROP_TYPE_SCRIPTED_SITTING_SCI => Some("monster_scientist"),
            PROP_TYPE_VENT_ZOMBIE => Some("monster_zombie"),
            _ => None,
        };
        if let Some(class) = class {
            let pos = PROP_POS[pi];
            reference_trace::entity(reference_trace::EntityState {
                map_tick,
                slot: 0x8000 | pi as u16,
                class,
                targetname: m.logic_name(PROP_NAME[pi]),
                brush: -1,
                pos,
                center: [
                    pos[0],
                    pos[1] + model_def(PROP_KIND[pi]).target_h / 2,
                    pos[2],
                ],
                vel: [0; 3],
                yaw_q12: prop_yaw_value(PROP_YAW[pi]) as i32,
                health: PROP_HEALTH[pi] as u16,
                active: PROP_ACTIVE[pi] != 0,
                state: PROP_STATE[pi],
                phase: PROP_SCRIPT_MODE[pi] as i32,
                spawnflags: 0,
            });
        }
        pi += 1;
    }
}

#[cfg(feature = "reference-trace")]
#[inline(never)]
unsafe fn trace_sim_tick(m: &Map, state: reference_trace::TickState) {
    let map_tick = state.map_tick;
    // Named/set-piece actors are checkpointed once per simulated second. Keep
    // this loop out of play(): the reference feature otherwise pushes MIPS-I's
    // largest function beyond a PC16 branch span.
    if map_tick % 20 == 0 {
        trace_brush_entities(m, map_tick);
        trace_point_actors(m, map_tick);
        let player_leaf = camera_leaf(
            m,
            [
                state.player_pos[0],
                state.player_pos[1] + VIEW_HEIGHT,
                state.player_pos[2],
            ],
        );
        let cached_pvs_leaf = pvs_cam_leaf_load();
        let pvs_current = valid_pvs_leaf(m, cached_pvs_leaf) && player_leaf == cached_pvs_leaf;
        let mut pi = 0usize;
        while pi < PROP_COUNT.min(CARRY_MAILBOX_FIRST) {
            let prop_pos = PROP_POS[pi];
            let prop_top = [prop_pos[0], prop_pos[1] + PROP_GROUND_PROBE_UP, prop_pos[2]];
            let prop_bottom = [
                prop_pos[0],
                prop_pos[1] - PROP_GROUND_PROBE_DOWN,
                prop_pos[2],
            ];
            reference_trace::prop(reference_trace::PropState {
                map_tick,
                index: pi as u16,
                name: m.logic_name(PROP_NAME[pi]),
                kind: PROP_KIND[pi],
                active: PROP_ACTIVE[pi] != 0,
                pos: PROP_POS[pi],
                yaw: prop_yaw_value(PROP_YAW[pi]),
                state: PROP_STATE[pi],
                health: PROP_HEALTH[pi],
                ai_target: PROP_AI_TARGET[pi],
                player_leaf,
                cached_pvs_leaf,
                pvs_current,
                in_player_pvs: if !pvs_current {
                    false
                } else if PROP_LEAF[pi] > 0 {
                    pvs_leaf_visible(m, PROP_LEAF[pi] as usize)
                } else {
                    true
                },
                script_mode: PROP_SCRIPT_MODE[pi],
                script_goal: PROP_SCRIPT_GOAL[pi],
                nav_src: prop_nav_cache_get(pi, PROP_NAV_SRC_SLOT),
                nav_dst: prop_nav_cache_get(pi, PROP_NAV_DST_SLOT),
                nav_next: prop_nav_cache_get(pi, PROP_NAV_NEXT_SLOT),
                move_cooldown: PROP_MOVE_COOLDOWN[pi],
                world_floor: phys::trace_line(m, &[], prop_top, prop_bottom)
                    .map(|hit| hit.pos[1])
                    .unwrap_or(i32::MIN),
                top_leaf: camera_leaf(m, prop_top),
                top_ent_solid: point_in_ent_solid(m, prop_top),
            });
            pi += 1;
        }
    }
    reference_trace::tick(state);
}

// Keep map-logic bootstrap out of play(): semantic/reference instrumentation
// makes that already-large MIPS function sensitive to PC16 branch span.
#[inline(never)]
#[optimize(size)]
unsafe fn init_room_logic(
    m: &Map,
    nlogic: usize,
    nents: usize,
    landmark: Option<[i32; 3]>,
    launch: &RoomLaunch,
) {
    init_logic_state(m, nlogic, nents, 0);
    // Cache every multisource's initial master state before any auto script
    // can consult it. Refresh never fires outputs.
    logic_check_multisources(m, nlogic, nents, 0);
    init_trains(m, nlogic, nents);
    restore_transition_trains(m, nlogic, landmark, launch.carry_count);
    logic_schedule_changelevel_post_target(m, launch.ride_seat, 0);
    // Untargeted scripted_sequences run at spawn in GoldSrc. A targeted script
    // with m_iszIdle also starts CineThink: it possesses/moves its actor now,
    // then remains primed until the sequence targetname is fired.
    let mut li = 0usize;
    while li < nlogic {
        let rec = m.logic(li);
        if rec.kind == map::LOGIC_SCRIPTED {
            if rec.targetname == 0 {
                let idle_only = scientist_logic::script_untargeted_idle_holds(
                    rec.flags & map::LOGIC_SCRIPTED_HAS_IDLE != 0,
                    rec.flags & map::LOGIC_SCRIPTED_HAS_PLAY != 0,
                );
                if idle_only {
                    if let Some(pi) = script_find_actor(rec) {
                        script_prime_idle_actor(m, li, rec, pi);
                    }
                } else {
                    logic_use_entity(
                        m,
                        nlogic,
                        nents,
                        li,
                        map::USE_TOGGLE,
                        0,
                        0,
                        logic_state::CALLER_NONE,
                    );
                }
            } else if rec.flags & map::LOGIC_SCRIPTED_HAS_IDLE != 0 {
                if let Some(pi) = script_find_actor(rec) {
                    script_prime_idle_actor(m, li, rec, pi);
                }
            }
        }
        li += 1;
    }
}

fn play(
    fb: &mut FrameBuffer,
    launch: RoomLaunch,
    keep_frame: bool,
    #[cfg(feature = "semantic-input")] semantic_player: &mut semantic_input::Player<'static>,
    #[cfg(feature = "semantic-input")] semantic_checkpoint_pending: &mut bool,
    #[cfg(feature = "route-follow")] follow_route: route_follow::Route,
    #[cfg(feature = "route-follow")] follower: &mut route_follow::Follower,
) -> PlayExit {
    let _ = enable_analog_port1();
    settings::apply_all(); // honour the options menu's screen offset + volumes
    unsafe {
        // A charger voice is map-local. End it before any WORLD.PAK streaming
        // even if the previous room changed level while +use was still held.
        sfx::charger_stop();
        CHANGE_REQUEST_ACTIVE = 0;
        TRAINING_COMPLETE_REQUEST = false;
    }
    telemetry::frame_begin(0);
    telemetry::task_begin(telemetry::task::FIXED_UPDATE);
    let texture_chunk_id = room_texture_chunk_id(launch.room_id as u32);
    let world_chunk_id = room_world_chunk_id(launch.room_id as u32);
    let map_name = menu::MAPS
        .get(launch.room_id as usize)
        .copied()
        .unwrap_or("unknown");
    telemetry::debug_log("hl-psx: loading room");
    telemetry::debug_log(map_name);
    begin_loading(fb);
    draw_next_loading_screen(fb);

    let tex_load = load_streamed_chunk(texture_chunk_id, unsafe { map_buf() });
    let tex_len = tex_load.map_or(0, |load| load.raw_len);
    let mut stream_bytes = 0u32;
    let mut stream_chunks = 0u32;
    let mut stream_sectors = 0u32;
    if let Some(load) = tex_load {
        account_streamed_chunk(
            load,
            &mut stream_chunks,
            &mut stream_bytes,
            &mut stream_sectors,
        );
    }
    if tex_len == 0 {
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_CHUNKS, 0);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_BYTES, 0);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_SECTORS, 0);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_STATUS, 0);
        telemetry::task_end(telemetry::task::FIXED_UPDATE);
        tty::println("hl-psx: WORLD.PAK texture stream failed");
        telemetry::debug_log("hl-psx: WORLD.PAK texture stream failed");
        end_loading();
        return PlayExit::BackToMenu;
    }
    telemetry::debug_log("hl-psx: WORLD.PAK texture chunk loaded");

    draw_next_loading_screen(fb);
    let tex_bytes = unsafe { streamed_map_bytes(tex_len) };
    telemetry::stage_begin(telemetry::stage::VRAM_UPLOAD);
    let (room_texs, tex_failed) = match unsafe {
        vram::upload_tex_chunk_raw(
            tex_bytes,
            core::ptr::addr_of_mut!(TEX_SLOTS).cast::<TexSlot>(),
            MAX_TEX_SLOTS,
        )
    } {
        Some(v) => v,
        None => {
            telemetry::stage_end(telemetry::stage::VRAM_UPLOAD);
            telemetry::counter(telemetry::counter::CD_WORLD_PACK_CHUNKS, stream_chunks);
            telemetry::counter(telemetry::counter::CD_WORLD_PACK_BYTES, stream_bytes);
            telemetry::counter(telemetry::counter::CD_WORLD_PACK_SECTORS, stream_sectors);
            telemetry::counter(telemetry::counter::CD_WORLD_PACK_STATUS, 0);
            telemetry::task_end(telemetry::task::FIXED_UPDATE);
            tty::println("hl-psx: WORLD.PAK texture chunk invalid");
            telemetry::debug_log("hl-psx: WORLD.PAK texture chunk invalid");
            end_loading();
            return PlayExit::BackToMenu;
        }
    };
    telemetry::stage_end(telemetry::stage::VRAM_UPLOAD);
    let model_tex_failed = 0usize;
    let model_texs = 0usize;
    draw_next_loading_screen(fb);
    // Real HUD sprite sheet -> free gameplay tpage. Streams from the pack
    // (MAP_BUF is free until the world chunk below); a failed read leaves the
    // stale VRAM copy from the previous map, which is the same sheet anyway.
    let hud_mat = {
        let n = unsafe {
            load_accounted_map_chunk(
                hud::HUD_CHUNK_ID,
                &mut stream_chunks,
                &mut stream_bytes,
                &mut stream_sectors,
            )
        }
        .map(|load| load.raw_len)
        .unwrap_or(0);
        let blob = unsafe { streamed_map_bytes(n.max(68)) };
        hud::upload(blob)
    };

    // These dialogue-heavy maps cannot emit most of the complete campaign
    // combat bank. Fixed-id profiles reclaim that SPU RAM without changing any
    // SFX call sites. Hazard Course upgrades to its weapon profile exactly
    // when the weapon section begins; other chapters restore the full bank.
    let wanted_sfx = if (6..=11).contains(&launch.room_id)
        || (menu::TRAINING_START_ROOM as u16..=menu::TRAINING_START_ROOM as u16 + 1)
            .contains(&launch.room_id)
    {
        sfx::CHUNK_ID_LIGHT
    } else if launch.room_id >= menu::TRAINING_START_ROOM as u16 + 2 {
        sfx::CHUNK_ID_TRAINING_WEAPONS
    } else {
        sfx::CHUNK_ID
    };
    if unsafe { ACTIVE_SFX_CHUNK } != wanted_sfx {
        let n = unsafe {
            load_accounted_map_chunk(
                wanted_sfx,
                &mut stream_chunks,
                &mut stream_bytes,
                &mut stream_sectors,
            )
        }
        .map(|load| load.raw_len)
        .unwrap_or(0);
        let blob = unsafe { streamed_map_bytes(n) };
        if n >= 8 && unsafe { sfx::init_from_pack(blob) } > 0 {
            unsafe { ACTIVE_SFX_CHUNK = wanted_sfx };
        }
    }

    // Per-map dialogue: stream this map's voice pack (chunk 3100 + room) into
    // the SPU region above the resident core SFX, replacing the previous map's
    // lines. MAP_BUF is still free here (the world loads below). A missing
    // chunk clears the dialogue table -> that map is simply silent.
    {
        let vc = sfx::VOICE_CHUNK_BASE + launch.room_id as u32;
        let n = unsafe {
            load_accounted_map_chunk(
                vc,
                &mut stream_chunks,
                &mut stream_bytes,
                &mut stream_sectors,
            )
        }
        .map(|load| load.raw_len)
        .unwrap_or(0);
        if n >= 8 {
            let blob = unsafe { streamed_map_bytes(n) };
            unsafe { sfx::load_dialogue_pack(blob) };
        } else {
            unsafe { sfx::load_dialogue_pack(&[]) };
        }
    }

    // Sprite billboards: stream this map's pack (chunk 3300 + room) into the now-
    // free MAP_BUF, decompress, and append its frame textures to the atlas. The
    // map textures are already resident (uploaded above); models append after
    // this, so sprites reserve their ~14 small slots between the two. Runs before
    // the world chunk overwrites MAP_BUF; the DEFS/atlas persist past that.
    {
        let spr_chunk = sprite::SPRITE_CHUNK_BASE + launch.room_id as u32;
        let sn = unsafe {
            load_accounted_map_chunk(
                spr_chunk,
                &mut stream_chunks,
                &mut stream_bytes,
                &mut stream_sectors,
            )
        }
        .map(|load| load.raw_len)
        .unwrap_or(0);
        if sn >= 8 {
            let blob = unsafe { streamed_map_bytes(sn) };
            unsafe { sprite::load_pack(blob) };
        } else {
            unsafe { sprite::reset() };
        }
    }

    // Resident explosion sprite (s_explod.spr): weapon blasts happen on any map,
    // so load it every map (like the HUD) into its own slots, appended to the
    // atlas right after the per-map sprites. MAP_BUF is still free (world below).
    {
        let en = unsafe {
            load_accounted_map_chunk(
                sprite::EXPL_CHUNK_ID,
                &mut stream_chunks,
                &mut stream_bytes,
                &mut stream_sectors,
            )
        }
        .map(|load| load.raw_len)
        .unwrap_or(0);
        if en >= 20 {
            let blob = unsafe { streamed_map_bytes(en) };
            unsafe { sprite::load_explosion(blob) };
        }
    }

    draw_next_loading_screen(fb);
    let map_len = unsafe {
        load_accounted_map_chunk(
            world_chunk_id,
            &mut stream_chunks,
            &mut stream_bytes,
            &mut stream_sectors,
        )
    }
    .map(|load| load.raw_len)
    .unwrap_or(0);
    if map_len == 0 {
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_CHUNKS, stream_chunks);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_BYTES, stream_bytes);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_SECTORS, stream_sectors);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_STATUS, 0);
        telemetry::task_end(telemetry::task::FIXED_UPDATE);
        tty::println("hl-psx: WORLD.PAK world stream failed");
        telemetry::debug_log("hl-psx: WORLD.PAK world stream failed");
        end_loading();
        return PlayExit::BackToMenu;
    }
    telemetry::debug_log("hl-psx: WORLD.PAK world chunk loaded");
    unsafe {
        // Hand the arena above this map to the model pool. 16-byte alignment
        // keeps every streamed chunk on the same boundary it had when the pool
        // was its own static, so the aligned TriRec/frame decoders are unmoved.
        MODEL_BASE_WORDS = map_len.div_ceil(4).next_multiple_of(4);
    }
    draw_next_loading_screen(fb);
    // Stream the resident Glock; other viewmodels load on first selection and
    // share the fixed MODEL_BUF reserve without reducing the enemy pool.
    // This has to follow the base assignment above: every viewmodel offset is
    // relative to `model_ptr()`, so streaming while the base is still the
    // conservative staging capacity leaves the chunk stranded above the real
    // pool -- where `stream_map_models` then writes enemy geometry over it on
    // any small-BSP/heavy-roster map (c1a2 lost its held weapon this way).
    let glock_vm_ok = unsafe {
        load_resident_viewmodels(&mut stream_chunks, &mut stream_bytes, &mut stream_sectors)
    };
    if !glock_vm_ok {
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_CHUNKS, stream_chunks);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_BYTES, stream_bytes);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_SECTORS, stream_sectors);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_STATUS, 0);
        telemetry::task_end(telemetry::task::FIXED_UPDATE);
        tty::println("hl-psx: WORLD.PAK viewmodel stream failed");
        telemetry::debug_log("hl-psx: WORLD.PAK viewmodel stream failed");
        end_loading();
        return PlayExit::BackToMenu;
    }
    telemetry::counter(
        telemetry::counter::ROOM_TEXTURE_UPLOADS,
        (room_texs.saturating_sub(tex_failed) + model_texs.saturating_sub(model_tex_failed)) as u32,
    );
    telemetry::counter(
        telemetry::counter::ROOM_MATERIAL_TEXTURE_DROPS,
        (tex_failed + model_tex_failed) as u32,
    );
    telemetry::debug_log("hl-psx: WORLD.PAK viewmodels loaded");
    unsafe { invalidate_weapon_tri_cache() }

    let map_bytes = unsafe { streamed_map_bytes(map_len) };
    // Map's field readers are intentionally unchecked on the PS1 hot path.
    // Reject a truncated or unknown payload once, before any offset/count can
    // turn into an out-of-bounds read. Transitional formats remain readable
    // for diagnostics; HLMH alone carries the larger source-addressed header.
    if map_bytes.len() < cooked::LEGACY_HEADER_SIZE
        || (&map_bytes[0..4] == b"HLMH" && map_bytes.len() < cooked::HEADER_SIZE)
        || (&map_bytes[0..4] != b"HLME"
            && &map_bytes[0..4] != b"HLMF"
            && &map_bytes[0..4] != b"HLMG"
            && &map_bytes[0..4] != b"HLMH")
    {
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_CHUNKS, stream_chunks);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_BYTES, stream_bytes);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_SECTORS, stream_sectors);
        telemetry::counter(telemetry::counter::CD_WORLD_PACK_STATUS, 0);
        telemetry::task_end(telemetry::task::FIXED_UPDATE);
        tty::println("hl-psx: unsupported world map format");
        telemetry::debug_log("hl-psx: unsupported world map format");
        end_loading();
        return PlayExit::BackToMenu;
    }
    // Loading is over: the CD hook must not survive into gameplay, where the
    // weapon-switch and model streams would redraw the strip over the world.
    end_loading();
    let m = Map::load(map_bytes);
    #[cfg(feature = "semantic-input")]
    if semantic_player.begin_map(map_name).is_err() {
        panic!("HLINPUT1 map order mismatch");
    }
    #[cfg(feature = "route-follow")]
    follower.begin_map(follow_route, map_name);
    #[cfg(feature = "reference-trace")]
    reference_trace::begin_map(map_name, launch.room_id);
    m.expand_light_palette(); // per-corner light lookups read the expanded table
    if room_texs != m.n_texs {
        tty::println("hl-psx: texture/world count mismatch");
        telemetry::debug_log("hl-psx: texture/world count mismatch");
    }
    phys::set_gravity_scale(4096); // fresh map: normal gravity until a zone says otherwise
    let nents = m.n_ents.min(MAX_ENTS);
    let nlogic = m.n_logic.min(MAX_LOGIC);
    // Stack-local map capability bit: maps without func_pushable pay no
    // per-tick entity scan and the fixed resident/BSS layout stays unchanged.
    let mut has_pushables = false;
    // Resolve before prop init: incoming actor coordinates are relative to the
    // same destination landmark used for the player spawn.
    let landmark_found = launch_landmark_origin(&m, nlogic, launch.landmark);
    unsafe {
        invalidate_world_packet_cache();
        WORLD_AFFINE_PREVIOUS_COUNT = 0;
        WORLD_AFFINE_SELECTED_COUNT = 0;
        WORLD_AFFINE_NEXT_COUNT = 0;
        WORLD_AFFINE_POLICY_READY = false;
        WORLD_AFFINE_RANK_FRAME = true;
        WORLD_AFFINE_EDGES_PENDING = false;
        WORLD_AFFINE_FORCE_RANK = true;
        pvs_cam_leaf_store(-1);
        PVS_LEAF_COUNT = 0;
        PVS_ENT_COUNT = 0;
        TRAM_CACHE_VALID = false;
        TRAM_CACHE_BUILDING = false;
        TRAM_TRI_COUNT = 0;
        TRAM_QUAD_COUNT = 0;
        WORLD_BAND_STATE = WORLD_BAND_NEEDS;
        // Liquid/glass translucency is per-face now: the cook keeps the
        // translucent flag only where this map's vis shows the far side
        // (watervis water); the emit paths pick a blended packet on demand
        // (EMIT_BLEND) and sway liquid UVs. Blocked water renders opaque and
        // animated, exactly like vanilla GoldSrc.
        BLEND_PACKET_KEY = u32::MAX;
        // Brush entities load BEFORE props so the spawn ground snap can treat
        // grates/doors/crates as solid (point_in_ent_solid reads ENT_CACHE).
        let nents_early = m.n_ents.min(MAX_ENTS);
        for ei in 0..nents_early {
            let e = m.entity(ei);
            ENT_CACHE[ei] = e;
            ENT_RADIUS[ei] = isqrt_i32(e.r2);
            ENT_ACTIVE[ei] = 1;
            ENT_PHASE[ei] = 0;
            has_pushables |= e.kind == ENT_KIND_PUSHABLE;
        }
        ENT_SOLID_COUNT = nents_early;
        // Animated-texture chains (+0../+9, +a../+j): per-map masks + the
        // frame-0 display tables. Needs ENT_CACHE for the per-brush flags.
        tex_anim_init(&m, nents_early);
        init_prop_state(&m, launch.room_id as usize, !launch.preserve_view);
        let restored = restore_transition_actors(&m, landmark_found, launch.carry_count);
        stream_map_models(
            VM_POOL_WORDS * 4,
            if landmark_found.is_some() {
                launch.carry_count
            } else {
                restored
            },
            launch.room_id as usize,
            &mut stream_chunks,
            &mut stream_bytes,
            &mut stream_sectors,
        ); // enemies stream after the viewmodel reserve
           // Pre-scale the modal font into the unused right strip of the HUD tpage.
           // This has no resident RAM cost and turns chapter-card glyphs into one
           // transparent textured quad each instead of hundreds of flat pixel runs.
        hltext::upload_gameplay_atlas();
        // Every non-viewmodel texture plus the glock is resident now. Snapshot
        // the allocators so each switch can free the selected weapon's textures;
        // only the glock slot prefix survives as a cheap failure fallback.
        vram::vm_checkpoint();
        VM_FILL_BASE_SLOT = VM_FILL_SLOT;
        VM_CACHED_WM = VM_NONE;
        VM_CACHED_CHUNK_WORDS = 0;
        VM_CACHED_CHUNK_BYTES = 0;
        VM_TAIL_READY = vm_tail_capacity_words()
            >= VM_TAIL_CACHE_WORDS + VM_TAIL_BACKUP_WORDS + VM_TAIL_GUARD_WORDS;
        vm_backup_live_tail();
        clear_combat_fx();
    }
    telemetry::counter(telemetry::counter::CD_WORLD_PACK_CHUNKS, stream_chunks);
    telemetry::counter(telemetry::counter::CD_WORLD_PACK_BYTES, stream_bytes);
    telemetry::counter(telemetry::counter::CD_WORLD_PACK_SECTORS, stream_sectors);
    telemetry::counter(telemetry::counter::CD_WORLD_PACK_STATUS, 1);
    telemetry::task_end(telemetry::task::FIXED_UPDATE);
    let nv = if m.n_verts < MAX_VERTS {
        m.n_verts
    } else {
        MAX_VERTS
    };

    let mut carried_velocity = [0i32; 3];
    let mut landmark_offset = [0i32; 3];
    let mut axis = 0usize;
    while axis < 3 {
        let (offset, velocity) = logic_state::unpack_landmark_axis(launch.landmark_offset[axis]);
        landmark_offset[axis] = offset;
        carried_velocity[axis] = velocity;
        axis += 1;
    }
    let spawn_pos = if let Some(origin) = landmark_found {
        telemetry::debug_log("hl-psx: spawning at landmark");
        [
            origin[0] + landmark_offset[0],
            origin[1] + landmark_offset[1],
            origin[2] + landmark_offset[2],
        ]
    } else {
        if launch.landmark.len > 0 {
            telemetry::debug_log("hl-psx: landmark missing, using spawn");
        }
        m.spawn_pos
    };
    // Ride transfer (Black Mesa Inbound) WITHOUT a landmark: nothing anchors
    // the arrival, so seat the rider at the authored track start. With a
    // landmark the spawn above already puts the player where they left off;
    // the tram init below seeks the car to them (GoldSrc transfers the train entity
    // itself via globalname; the landmark-relative seek is our equivalent).
    let spawn_pos =
        if launch.riding && landmark_found.is_none() && m.n_way > 0 && m.tram_submodel > 0 {
            let w = tram_reference_waypoint(&m);
            [w[0], w[1] + 70, w[2]]
        } else {
            spawn_pos
        };
    let mut player = phys::Player::new(spawn_pos);
    if launch.preserve_view {
        player.vel = carried_velocity;
        // The landmark offset already carries the centred crouch origin, so
        // restore the short collision hull without applying another 18-unit
        // grounded origin shift in the destination map.
        player.crouch = logic_state::carry_player_crouched(launch.carry_count);
    }
    let mut yaw: u16 = if launch.preserve_view {
        launch.yaw
    } else {
        (m.spawn_yaw as u16) & 0xFFF
    };
    let mut pitch: i16 = if launch.preserve_view {
        launch.pitch
    } else {
        0
    };
    #[cfg(feature = "debug-regression-viewpoints")]
    if launch.pitch == i16::MIN
        || launch.pitch == DEBUG_SAVED_VIEW_PITCH_SENTINEL
        || launch.pitch == DEBUG_LADDER_VIEW_PITCH_SENTINEL
        || launch.pitch == DEBUG_MOMENTARY_VIEW_PITCH_SENTINEL
        || launch.pitch == DEBUG_PUSHABLE_VIEW_PITCH_SENTINEL
        || launch.pitch == DEBUG_ENTRY_VIEW_PITCH_SENTINEL
        || launch.pitch == DEBUG_PANEL_VIEW_PITCH_SENTINEL
        || launch.pitch == DEBUG_TRAIN_VIEW_PITCH_SENTINEL
        || launch.pitch == DEBUG_GUNTARGET_VIEW_PITCH_SENTINEL
    {
        if let Some((position, view_yaw, view_pitch)) = regression_viewpoint(
            launch.room_id as usize,
            launch.pitch == DEBUG_SAVED_VIEW_PITCH_SENTINEL,
            launch.pitch == DEBUG_LADDER_VIEW_PITCH_SENTINEL,
            launch.pitch == DEBUG_MOMENTARY_VIEW_PITCH_SENTINEL,
            launch.pitch == DEBUG_PUSHABLE_VIEW_PITCH_SENTINEL,
            launch.pitch == DEBUG_ENTRY_VIEW_PITCH_SENTINEL,
            launch.pitch == DEBUG_PANEL_VIEW_PITCH_SENTINEL,
            launch.pitch == DEBUG_TRAIN_VIEW_PITCH_SENTINEL,
            launch.pitch == DEBUG_GUNTARGET_VIEW_PITCH_SENTINEL,
        ) {
            player = phys::Player::new(position);
            yaw = view_yaw;
            pitch = view_pitch;
        }
    }
    #[cfg(feature = "semantic-input")]
    let checkpoint_health = if *semantic_checkpoint_pending {
        reference_checkpoint::INITIAL_HEALTH
    } else {
        None
    };
    #[cfg(feature = "semantic-input")]
    if *semantic_checkpoint_pending {
        if let Some(origin) = reference_checkpoint::INITIAL_ORIGIN {
            player.pos = origin;
            player.clear_velocity();
            player.on_ground = false;
            player.ground_mover = -1;
        }
        if let Some(initial_yaw) = reference_checkpoint::INITIAL_YAW {
            yaw = initial_yaw;
        }
        if let Some(initial_pitch) = reference_checkpoint::INITIAL_PITCH {
            pitch = initial_pitch.clamp(-PITCH_MAX, PITCH_MAX);
        }
        *semantic_checkpoint_pending = false;
    }
    unsafe {
        // Map ambience and active train beds can start during logic bootstrap.
        // Seed their attenuation from this room's effective player position,
        // not the listener position retained from the previous room.
        sfx::set_ear(player.pos);
        init_room_logic(&m, nlogic, nents, landmark_found, &launch);
        #[cfg(feature = "debug-regression-viewpoints")]
        if launch.pitch == i16::MIN
            || launch.pitch == DEBUG_SAVED_VIEW_PITCH_SENTINEL
            || launch.pitch == DEBUG_LADDER_VIEW_PITCH_SENTINEL
            || launch.pitch == DEBUG_MOMENTARY_VIEW_PITCH_SENTINEL
            || launch.pitch == DEBUG_PUSHABLE_VIEW_PITCH_SENTINEL
            || launch.pitch == DEBUG_ENTRY_VIEW_PITCH_SENTINEL
            || launch.pitch == DEBUG_PANEL_VIEW_PITCH_SENTINEL
            || launch.pitch == DEBUG_TRAIN_VIEW_PITCH_SENTINEL
        {
            // A deterministic subject camera must not be hidden by an
            // authored start-dark/title card. Gameplay builds retain both.
            FADE_ACTIVE = false;
            FADE_STARTDARK = false;
            GAMETITLE_TICKS = 0;
        }
        // Build tail-indexed actor candidate lists only after every map-load
        // initializer has finished. Reading the live count explicitly here
        // also prevents this cold optimization from observing the pre-init
        // zero across the large inlined load block on MIPS LTO builds.
        rebuild_prop_hotlists();
        #[cfg(feature = "reference-trace")]
        trace_prop_hotlist_state(1);
    }
    let mut frame_no: u16 = 0;
    // Render-owned PVS key. The shared static is only an invalidation channel
    // for logic/simulation; keeping the hot key local prevents code layout
    // from turning every visual into a complete visibility rebuild.
    let mut render_pvs_leaf = -1i32;
    // Vis-row offset of the built PVS (-1 = none/underwater-merged). Leaf
    // changes that land on the same deduplicated row skip the whole rebuild.
    let mut render_pvs_visofs = -1i32;
    let mut render_pvs_underwater = false;
    let mut telemetry_frame: u32 = 1;
    let mut sim_frame_no: u32 = 0;
    let mut weapon = Arsenal::new();
    // Ammo is granted only WITH a weapon: the changelevel carry restores it
    // (CARRY_AMMO below), chapter-select seeds it in give_chapter_loadout. A
    // suitless fresh start (c1a0 before you find a gun) keeps empty hands + no
    // ammo -- seeding glock ammo here made the HUD show rounds you couldn't fire.
    unsafe {
        if launch.preserve_view && CARRY_VALID {
            weapon.owned = CARRY_OWNED;
            weapon.clip = CARRY_CLIPS;
            weapon.ammo = CARRY_AMMO;
            let cur = CARRY_CURRENT as usize;
            if cur < N_WEAPONS && weapon.owns(cur) {
                weapon.current = cur;
            }
            phys::set_longjump(logic_state::carry_longjump(launch.carry_count));
        } else {
            CARRY_VALID = false;
            GLOBAL_COUNT = 0; // fresh menu launch: clear cross-map global state
            phys::set_longjump(false); // fresh start: no module yet
            if DEBUG_ALL_WEAPONS
                && launch.pitch != DEBUG_SAVED_VIEW_PITCH_SENTINEL
                && launch.pitch != DEBUG_ENTRY_VIEW_PITCH_SENTINEL
            {
                weapon.give_all_debug();
                weapon.current = DEBUG_GALLERY_WEAPON as usize;
            } else if launch.suit_equipped {
                // Mid-campaign chapter select: the arsenal earned by this chapter.
                weapon.give_chapter_loadout(launch.room_id as usize);
            }
        }
    }
    let mut viewmodel_anim = VM_ANIM_IDLE;
    let mut viewmodel_anim_start = sim_frame_no;
    let mut satchel_mode = SATCHEL_PACK;
    let mut sec_was_held = false; // rising-edge latch for L2 secondary fire
    let mut fire_was_held = false; // hand-grenade press/hold/release latch
    let mut grenade_cooking = false;
    let mut grenade_cook_start = sim_frame_no;
    let mut jump_was_held = false; // HL requires a release between jumps
                                   // GoldSrc keeps a 2-second wall-normal movement state after a successful
                                   // waist-deep water-exit probe. Map-local storage preserves Player's strict
                                   // 36-byte resident layout.
    let mut water_jump = phys::WaterJumpState::new();
    // PM_Duck's 0.4 s standing-hull transition. Keeping this map-local rather
    // than in Player preserves the latter's strict 36-byte resident footprint.
    let mut duck_transition_ticks = 0u8;
    // Physical overlap is not attachment. Keeping a distinct latch means an
    // idle brush against a ladder cannot consume the later, intentional mount
    // snap, while an established climb gets a tiny tangential quantization
    // tolerance until jump, side exit, or the strict top plane releases it.
    let mut active_ladder = -1i16;
    // Ignore strafe briefly after a successful upper-plane mantle. This keeps
    // the climb's final lateral input from becoming a sideways launch while
    // ordinary forward motion and collision settle onto the landing.
    let mut view_h_cur: i32 = if player.crouch {
        CROUCH_VIEW_HEIGHT
    } else {
        VIEW_HEIGHT
    }; // eased duck eye (HL's 0.4 s spline, linearized)
    let mut switch_prev = false; // rising-edge latch for L1/R1 weapon cycling
    let mut weapon_icon_ticks = 0u8; // select-icon flash countdown after a switch
                                     // Rising-edge latch: the all-weapons cheat grants once per enable so a
                                     // later pickup or weaponstrip is not silently undone every tick.
    let mut debug_weapons_given = false;
    let mut pending_vm_switch = weapon.current != W_GLOCK; // restore carried non-glock geometry
    if pending_vm_switch {
        viewmodel_anim = VM_ANIM_DRAW;
        viewmodel_anim_start = sim_frame_no;
    }
    let mut health: u16 = launch.health;
    #[cfg(feature = "semantic-input")]
    if let Some(initial_health) = checkpoint_health {
        health = initial_health;
    }
    let mut armor: u16 = launch.armor.min(HEV_MAX_ARMOR);
    let mut death_ticks: u8 = 0; // >0 while dead; respawns at 0
    let mut restart_requested = false;
    unsafe {
        MOUNTED_TANK = -1; // never carry a mount across maps
        TANK_FIRE_CD = 0;
    }
    let mut suit_equipped = launch.suit_equipped
        // Standalone/menu convenience only: a changelevel arrival (preserve_view)
        // carries the real suit state, so a playthrough picks the suit up in
        // c1a0d instead of being handed it.
        || (!launch.preserve_view && standalone_room_starts_with_hev(launch.room_id as usize))
        || armor > 0;
    if !suit_equipped {
        armor = PLAYER_START_ARMOR;
    }
    // A loaded save overrides the spawn, arsenal and globals this map would
    // otherwise start with. It runs after the normal setup rather than instead
    // of it, so every map-local system is initialised exactly as usual first.
    unsafe {
        if PENDING_RESTORE_ACTIVE && PENDING_RESTORE.room_id == launch.room_id {
            let cp = PENDING_RESTORE;
            PENDING_RESTORE_ACTIVE = false;
            if cp.has_pos {
                player.pos = cp.pos;
                player.vel = [0; 3];
                player.crouch = cp.crouch;
                yaw = cp.yaw & 0xFFF;
                pitch = cp.pitch;
            }
            health = cp.health.max(1);
            armor = cp.armor.min(HEV_MAX_ARMOR);
            suit_equipped = cp.suit;
            weapon.owned = cp.owned;
            weapon.clip = cp.clips;
            weapon.ammo = cp.ammo;
            if (cp.current as usize) < N_WEAPONS && weapon.owns(cp.current as usize) {
                weapon.current = cp.current as usize;
            }
            phys::set_longjump(cp.longjump);
            GLOBAL_HASH = cp.global_hash;
            GLOBAL_ON = cp.global_on;
            GLOBAL_COUNT = (cp.global_count as usize).min(GLOBAL_HASH.len());
            pending_vm_switch = true;
        } else {
            PENDING_RESTORE_ACTIVE = false;
        }
    }
    let mut pickup_kind: u8 = hud::PICKUP_NONE;
    let mut pickup_ticks: u8 = 0;
    let mut use_cooldown: u8 = 0;
    let mut charger_sound: u8 = 0;
    let mut charger_intro_ticks: u8 = 0;

    // Tracktrain mover: the BSP cooker stores the train's path_track chain, and
    // the logic system toggles it through the func_tracktrain targetname.
    let tram_ref = tram_reference_waypoint(&m);
    let mut recoil = 0i32; // viewmodel kick when firing
    let mut zoom_aim = false; // crossbow L2 toggled 20-degree sight state
    let mut rpg_laser = true; // CRpg::Spawn enables the LTD by default
    let mut egon_firing = false; // prevents restarting the beam sound every pulse
    let mut crouching = player.crouch; // TRIANGLE held: lower eye + slower, persists into render
    let mut flashlight = launch.preserve_view && suit_equipped && unsafe { FLASHLIGHT_ON };
    let mut flashlight_battery = if launch.preserve_view {
        unsafe { FLASHLIGHT_BATTERY }
    } else {
        99
    };
    let mut flashlight_timer = if launch.preserve_view {
        unsafe { FLASHLIGHT_TIMER }
    } else {
        1
    };
    unsafe {
        FLASHLIGHT_ON = flashlight;
        FLASHLIGHT_BATTERY = flashlight_battery;
        FLASHLIGHT_TIMER = flashlight_timer;
    }
    let mut flash_prev = false; // rising-edge latch for the flashlight toggle
    let mut tram_active = false;
    // The selected player tram uses the curved-path runtime rather than the
    // shared brush-train pool, but it retains the same three authored sounds.
    let mut tram_audio_li = u16::MAX;
    let mut tram_audio_scan = 0usize;
    while tram_audio_scan < nlogic {
        let rec = m.logic(tram_audio_scan);
        if rec.kind == map::LOGIC_FUNC_TRACKTRAIN
            && rec.arg1 != 0
            && rec.arg1 == unsafe { TRACKTRAIN_SUBMODEL }
        {
            tram_audio_li = tram_audio_scan as u16;
            break;
        }
        tram_audio_scan += 1;
    }
    // Authored speed; path_track "speed" keys re-pace it per section as the
    // ride passes them (tram_advance), exactly like CPathTrack.
    let mut tram_speed = m.tram_speed.max(0);
    let mut tram_speed_remainder = 0i32;
    let mut tram_player_attached = false;
    let mut tram_controlling = false;
    let mut tram_drive_axis_prev = 0i8;
    let mut tram_player_left_stopped = false;
    // A rider who walks out of the moving car must stay off it. The broad
    // acquisition radius would otherwise re-seat them on the very next tick.
    let mut tram_walked_off = false;
    // Fresh visits park at the map-authored func_tracktrain target. Upstream
    // waypoints remain searchable only for a train carried across a transition.
    let mut tram_seg = m.tram_start;
    let mut tram_seg_dist = 0i32;
    let mut ride_off = [0i32; 3];
    // Ride-transfer approach leg: the car may arrive BEFORE the new map's
    // chain starts (HL's transferred train drives toward its carried target
    // track). While pre_left > 0 the car runs pre_from -> authored waypoint.
    let mut tram_pre_from = [0i32; 3];
    let mut tram_pre_total = 0i32;
    let mut tram_pre_left = 0i32;
    // GoldSrc keeps the global train's physical angle and angular controller
    // through changelevels. Q28 preserves the sub-Q12 motion that its 16-bit
    // svc_addangle flooring turns into the opening ride's visible view drift.
    let carried_dynamics = unsafe { TRAM_DYNAMICS_CARRY };
    let tram_controller_carried = launch.riding && carried_dynamics.meta & 0x20 != 0;
    let authored_yaw_q28 = tram_authored_heading_q28(&m);
    let mut tram_actual_yaw_q28 = if tram_controller_carried {
        carried_dynamics.actual_yaw_q28
    } else {
        authored_yaw_q28
    };
    let mut tram_target_yaw_q28 = if tram_controller_carried {
        carried_dynamics.desired_yaw_q28
    } else {
        authored_yaw_q28
    };
    let mut tram_pending_push_q28 = if tram_controller_carried {
        carried_dynamics.pending_push_q28
    } else {
        0
    };
    let mut tram_camera_frac_q16 = if tram_controller_carried {
        (carried_dynamics.meta & 0x0f) as u8
    } else {
        0
    };
    let mut tram_controller_primed = tram_controller_carried && carried_dynamics.meta & 0x10 != 0;
    let mut prev_tram_yaw = tram_logic::visible_yaw_q12(tram_actual_yaw_q28);
    let mut tram_yaw_render = prev_tram_yaw;
    let launch_ride_seat = logic_state::unpack_ride_seat(launch.ride_seat);
    if launch.riding && m.n_way > 0 && m.tram_submodel > 0 {
        tram_active = logic_state::carry_tram_active(launch.carry_count);
        tram_player_attached = true;
        // The car arrives exactly where the rider's seat offset says it is
        // (carried across the changelevel). If that spot is on this map's
        // chain, continue from there; otherwise drive the approach leg.
        // Clamp the carried seat into the car interior: the descent can leave
        // the rider sagged below the floor (no pitch on our car yet), and an
        // out-of-body seat re-ejects them on arrival. The snap happens behind
        // the loading screen.
        let seat = [
            launch_ride_seat[0].clamp(-120, 120),
            launch_ride_seat[1].clamp(30, 70),
            launch_ride_seat[2].clamp(-120, 120),
        ];
        let car = [
            player.pos[0] - seat[0],
            player.pos[1] - seat[1],
            player.pos[2] - seat[2],
        ];
        player.pos = [car[0] + seat[0], car[1] + seat[1], car[2] + seat[2]];
        let (s, d) = tram_seek_nearest(&m, car);
        let on_path = tram_path_pos(&m, s, d);
        // A train transferred a few units before waypoint zero projects to
        // exactly (0,0). Keep that authored cross-BSP overlap as the existing
        // approach leg instead of snapping it forward to the waypoint.
        let short_upstream = m.tram_start == 0
            && m.n_way >= 2
            && s == 0
            && d == 0
            && tram_logic::is_upstream_of_first(car, m.waypoint(0), m.waypoint(1));
        if dist2_3(car, on_path) <= TRAM_CARRY_RADIUS2 && !short_upstream {
            tram_seg = s;
            tram_seg_dist = d;
        } else {
            tram_pre_from = car;
            tram_pre_total = seg_len(car, tram_ref).max(1);
            tram_pre_left = tram_pre_total;
        }
        let tp = tram_pos_ext(
            &m,
            tram_seg,
            tram_seg_dist,
            tram_pre_from,
            tram_pre_total,
            tram_pre_left,
        );
        ride_off = [
            tp[0] - tram_ref[0],
            tp[1] - tram_ref[1],
            tp[2] - tram_ref[2],
        ];
        // Re-place the rider once the car has snapped onto this map's path.
        // The seat above only estimated where the car was; the snap then moved
        // it, and leaving the rider at his transferred world position folded
        // that snap distance into his seat. c0a0a landed him ten units past
        // the end of the aisle floor, so he rode the whole map airborne --
        // no ground entity, no footsteps, and nothing to stand on.
        player.pos = [tp[0] + seat[0], tp[1] + seat[1], tp[2] + seat[2]];
        #[cfg(feature = "emulator-telemetry")]
        debug_line(
            "tram arrive",
            &[
                ("seg=", tram_seg as i32),
                ("dist=", tram_seg_dist),
                ("pre=", tram_pre_left),
                ("nway=", m.n_way as i32),
                ("spd=", tram_speed),
                ("py=", player.pos[1]),
                ("sx=", launch_ride_seat[0]),
                ("sy=", launch_ride_seat[1]),
                ("sz=", launch_ride_seat[2]),
                ("cx=", car[0]),
                ("cz=", car[2]),
            ],
        );
    }
    if !tram_controller_carried {
        tram_target_yaw_q28 = tram_desired_yaw_q28(
            &m,
            tram_seg,
            tram_seg_dist,
            tram_pre_from,
            tram_pre_total,
            tram_pre_left,
            tram_actual_yaw_q28,
        );
    }
    let initial_tram_pos = tram_pos_ext(
        &m,
        tram_seg,
        tram_seg_dist,
        tram_pre_from,
        tram_pre_total,
        tram_pre_left,
    );
    let mut tram_rider_local = tram_seat_to_local(player.pos, initial_tram_pos, prev_tram_yaw);
    if tram_player_attached {
        if launch.riding {
            tram_rider_local[2] = tram_logic::clamp_transfer_rider_local_z(tram_rider_local[2]);
        }
        // Keep one stable car-local seat for the whole neutral ride. Repeating
        // world->car->world with Q12 matrices every tick drifts several units
        // even with symmetric rounding; by c0a0e that put the passenger just
        // outside the stopped-car support edge.
        player.pos = tram_seat_to_world(initial_tram_pos, tram_rider_local, prev_tram_yaw);
    }
    unsafe {
        if let Some((use_type, speed)) = logic_take_tracktrain_command() {
            // init_logic_state queues the selected func_tracktrain's authored
            // startspeed here. GoldSrc's global transition overlay supersedes
            // that spawn state; delayed trigger_auto commands arrive through
            // the ordinary per-tick command path below and remain effective.
            if tram_logic::should_apply_spawn_startspeed(launch.riding) {
                let started =
                    tram_apply_command(use_type, speed, &mut tram_active, &mut tram_speed);
                if started {
                    let train_pos = tram_pos_ext(
                        &m,
                        tram_seg,
                        tram_seg_dist,
                        tram_pre_from,
                        tram_pre_total,
                        tram_pre_left,
                    );
                    tram_player_attached = tram_should_carry_player(player.pos, train_pos);
                    if tram_player_attached {
                        tram_rider_local = tram_seat_to_local(player.pos, train_pos, prev_tram_yaw);
                    }
                }
            }
        }
    }
    if tram_active {
        unsafe { player_tram_audio_start(&m, tram_audio_li, initial_tram_pos) };
    }

    telemetry::stage_begin(telemetry::stage::ROOM_SURFACE_CACHE);
    unsafe {
        let initial_eye = [player.pos[0], player.pos[1] + view_h_cur, player.pos[2]];
        let initial_train_hint = tram_pos_ext(
            &m,
            tram_seg,
            tram_seg_dist,
            tram_pre_from,
            tram_pre_total,
            tram_pre_left,
        );
        let initial_leaf = recover_camera_leaf(&m, initial_eye, player.pos, initial_train_hint);
        if valid_pvs_leaf(&m, initial_leaf) {
            let initial_eye_under = m.leaf_liquid(initial_leaf as usize) != 0;
            rebuild_pvs_cache(&m, initial_leaf, nents, initial_eye, initial_eye_under);
            telemetry::counter(telemetry::counter::ROOM_SURFACE_CACHE_BUILDS, 1);
            telemetry::counter(
                telemetry::counter::ROOM_SURFACE_CACHE_BUILD_SURFACES,
                PVS_FACE_COUNT as u32,
            );
            telemetry::counter(
                telemetry::counter::ROOM_SURFACE_CACHE_BUILD_VERTICES,
                PVS_TRI_REF_COUNT as u32,
            );
        }
    }
    telemetry::stage_end(telemetry::stage::ROOM_SURFACE_CACHE);

    // Menu loading cards are drawn directly into the double buffers, so clear
    // both pages once before the first gameplay frame -- otherwise sparse world
    // coverage could leave a stale loading panel behind. On a level->level
    // transition (keep_frame) we deliberately DON'T clear: the previous scene
    // stays frozen (with the tiny overlay) until the first rendered frame of the
    // new level swaps over it, so there is no black flash between levels.
    if !keep_frame {
        fb.clear(0, 0, 0);
        gpu::draw_sync();
        fb.swap();
        fb.clear(0, 0, 0);
        gpu::draw_sync();
        fb.swap();
    }

    gpu::configure_vsync_timer();
    interrupts::install_vblank_counter();
    let mut next_sim_vblank = interrupts::vblank_count().wrapping_add(SIM_VBLANKS);
    #[cfg(feature = "decoupled-present")]
    unsafe {
        // Seed both interpolation poses with the spawn camera so the first
        // presented frames do not sweep in from stale coordinates.
        tick_camera_snapshot(player.pos, view_h_cur, yaw, pitch);
        tick_camera_snapshot(player.pos, view_h_cur, yaw, pitch);
        tick_tram_snapshot(ride_off, tram_yaw_render);
        tick_tram_snapshot(ride_off, tram_yaw_render);
    }
    #[cfg(not(feature = "semantic-input"))]
    let mut prev_pause_button = true;
    // A malformed ID handshake is not proof that the DualShock left analog
    // mode. Keep the last clean sample so a one-frame wire glitch cannot look
    // like a release/re-press, and only run the expensive config transaction
    // after a confirmed Digital/Config response.
    // Seed with the robust retrying path outside the deadline-critical loop.
    // Gameplay then performs one hardware-tested transaction per tick and
    // holds this sample across the occasional malformed response.
    #[cfg(not(feature = "semantic-input"))]
    let mut last_pad = poll_port1();

    // A frame has been built and submitted but not yet swapped in.
    let mut present_pending = false;
    // The finished frame's display flip sits in the VBlank handler's GP1
    // queue; the clear below gates on it having been applied.
    #[cfg(feature = "decoupled-present")]
    let mut flip_queued = false;

    'gameplay: loop {
        // Decoupled presentation free-runs: the present path already fences on
        // a VBlank edge, so removing this wait caps rendering at 60 Hz while
        // simulation ticks keep firing on their unchanged 20 Hz schedule below.
        #[cfg(not(feature = "decoupled-present"))]
        wait_until_vblank(next_sim_vblank);
        let mut ticks_this_visual = 0u16;
        while vblank_reached(interrupts::vblank_count(), next_sim_vblank) {
            telemetry::frame_begin(telemetry_frame);
            // Reuse PSoXide's standard current-room column for this linear
            // campaign. It makes direct-boot regression tapes self-verifying.
            telemetry::counter(
                telemetry::counter::PORTAL_VIS_CURRENT_ROOM,
                launch.room_id as u32,
            );
            #[cfg(feature = "emulator-telemetry")]
            if telemetry_frame & 63 == 0 {
                stackprobe::report();
                let cp = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                let cp2 = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                let w0 = tram_reference_waypoint(&m);
                let (train0_state, train0_off) = unsafe {
                    if TRAIN_COUNT > 0 {
                        (TRAIN_STATE[0], TRAIN_OFF[0])
                    } else {
                        (0, [0; 3])
                    }
                };
                debug_line(
                    "tram",
                    &[
                        ("cx2=", cp2[0]),
                        ("w0x=", w0[0]),
                        ("w0z=", w0[2]),
                        ("seg=", tram_seg as i32),
                        ("dist=", tram_seg_dist),
                        ("act=", tram_active as i32),
                        ("att=", tram_player_attached as i32),
                        ("tyaw=", prev_tram_yaw as i32),
                        ("vyaw=", yaw as i32),
                        ("spd=", tram_speed),
                        ("px=", player.pos[0]),
                        ("py=", player.pos[1]),
                        ("pz=", player.pos[2]),
                        ("cx=", cp[0]),
                        ("cy=", cp[1]),
                        ("cz=", cp[2]),
                        ("pfx=", tram_pre_from[0]),
                        ("pfy=", tram_pre_from[1]),
                        ("pfz=", tram_pre_from[2]),
                        ("ptot=", tram_pre_total),
                        ("plft=", tram_pre_left),
                        ("tr0s=", train0_state as i32),
                        ("tr0x=", train0_off[0] as i32),
                        ("tr0y=", train0_off[1] as i32),
                        ("tr0z=", train0_off[2] as i32),
                    ],
                );
            }
            telemetry::task_begin(telemetry::task::FIXED_UPDATE);
            telemetry::stage_begin(telemetry::stage::UPDATE);
            // Normalize either the live DualShock or the deterministic route
            // to the same post-deadzone semantic command. Replay builds never
            // consult hardware, pause, or controller mode inside gameplay.
            #[cfg(feature = "semantic-input")]
            let input_sample = match semantic_player.consume(map_name, sim_frame_no) {
                Ok(sample) => sample,
                Err(_) => panic!("HLINPUT1 replay exhausted or out of sequence"),
            };
            #[cfg(not(feature = "semantic-input"))]
            let input_sample = match poll_live_semantic_input(
                fb,
                &mut last_pad,
                &mut prev_pause_button,
                &mut next_sim_vblank,
            ) {
                LiveInputPoll::Sample(sample) => sample,
                LiveInputPoll::Resumed => continue 'gameplay,
                LiveInputPoll::MainMenu => return PlayExit::BackToMenu,
                LiveInputPoll::Chapter(room) => return PlayExit::Chapter(menu_launch(room)),
            };
            #[cfg(feature = "performance-telemetry")]
            let input_sample = if unsafe { DEBUG_PERF_WALK_ROUTE } {
                performance_walk_sample(sim_frame_no)
            } else {
                input_sample
            };
            // Closed-loop demo-route replay: steer the live player toward the
            // next waypoint with normal physics. Overrides the (neutral) pad
            // sample so menu/pause handling above stays intact.
            #[cfg(feature = "route-follow")]
            let input_sample = follower.steer(follow_route, player.pos, yaw, pitch, sim_frame_no);
            #[cfg(feature = "reference-trace")]
            reference_trace::input(
                sim_frame_no,
                input_sample.forward,
                input_sample.strafe,
                input_sample.turn,
                input_sample.look,
                input_sample.actions,
            );
            // R2 fires at the Glock cadence; the actual hit-test runs after
            // movement/movers update so it uses the current camera and doors.
            recoil = (recoil - 3).max(0);
            if let Some(reload_anim) = weapon.tick() {
                viewmodel_anim = reload_anim;
                viewmodel_anim_start = sim_frame_no;
            }
            // Non-looping source clips return to idle explicitly. Automatic
            // weapons can then loop their authored fire sequence while held
            // instead of restarting on frame zero for every rapid shot.
            if viewmodel_anim != VM_ANIM_IDLE {
                unsafe {
                    let requested_wm = weapon_viewmodel(weapon.current, satchel_mode);
                    let (vm_model, _, _, vm_weapon) = viewmodel_for(requested_wm);
                    let holding_grenade_pin = grenade_cooking
                        && weapon.current == W_GRENADE
                        && viewmodel_anim == VM_ANIM_ALT;
                    if !holding_grenade_pin
                        && viewmodel_anim_finished(
                            &vm_model,
                            vm_weapon,
                            viewmodel_anim,
                            viewmodel_anim_start,
                            sim_frame_no,
                        )
                    {
                        viewmodel_anim = VM_ANIM_IDLE;
                        viewmodel_anim_start = sim_frame_no;
                        let completed_satchel_transition = match satchel_mode {
                            SATCHEL_TO_RADIO => {
                                satchel_mode = SATCHEL_RADIO;
                                true
                            }
                            SATCHEL_TO_PACK => {
                                satchel_mode = SATCHEL_PACK;
                                true
                            }
                            _ => false,
                        };
                        if completed_satchel_transition && weapon.current == W_SATCHEL {
                            pending_vm_switch = true;
                            viewmodel_anim = VM_ANIM_DRAW;
                        }
                    }
                }
            }
            unsafe {
                decay_combat_fx();
            }
            if pickup_ticks > 0 {
                pickup_ticks -= 1;
                if pickup_ticks == 0 {
                    pickup_kind = hud::PICKUP_NONE;
                }
            }
            unsafe { tick_screen_fx(sim_frame_no) };
            // Player death: freeze for DEATH_TICKS (a red death screen renders),
            // then reload the immutable entry handoff. That handoff is either
            // the latest successful changelevel (full carried player state) or
            // the selected chapter start; the current room's pickups/damage
            // never leak into the retry.
            if death_ticks > 0 {
                death_ticks -= 1;
                if death_ticks == 0 {
                    restart_requested = true;
                }
            }
            let dead = death_ticks > 0 || restart_requested;
            if dead {
                grenade_cooking = false;
                fire_was_held = false;
                sec_was_held = false;
                zoom_aim = false;
                weapon.gauss_charge = 0;
            }
            // GoldSrc's ItemPostFrame calls PrimaryAttack every frame while
            // IN_ATTACK is held; each weapon's next-attack timer rate-limits
            // the actual shots/swings. Edge-triggering non-auto weapons made a
            // held crowbar swing only once, so c1a1a's route missed while out
            // of range and then remained pinned against the zombie forever.
            let fire_held = !dead && input_sample.held(semantic_input::ACTION_ATTACK);
            let grenade_pressed = weapon.current == W_GRENADE && fire_held && !fire_was_held;
            let grenade_released = weapon.current == W_GRENADE && !fire_held && fire_was_held;
            fire_was_held = fire_held;
            let grenade_cook_age = sim_frame_no.wrapping_sub(grenade_cook_start);
            let grenade_throw =
                grenade_cooking && (grenade_released || grenade_cook_age >= GRENADE_FUSE_TICKS);
            let grenade_throw_life =
                GRENADE_FUSE_TICKS.saturating_sub(grenade_cook_age).max(1) as u8;
            // Every other weapon follows GoldSrc's held ItemPostFrame cadence;
            // the hand grenade pays ammo and spawns only when the pin-pulled
            // throw is released (or its three-second fuse expires).
            let mut want_fire = if weapon.current == W_GRENADE {
                grenade_throw
            } else {
                fire_held
            };
            // L2 is a real second trigger. Repeating guns/charge modes consume
            // the held state; toggles consume only the rising edge.
            let sec_held = !dead && input_sample.held(semantic_input::ACTION_ATTACK2);
            let sec_pressed = sec_held && !sec_was_held;
            sec_was_held = sec_held;
            let secondary_claims_trigger = sec_held
                && (matches!(
                    weapon.current,
                    W_GLOCK | W_MP5 | W_SHOTGUN | W_CROSSBOW | W_RPG | W_GAUSS | W_HORNET
                ) || (weapon.current == W_SATCHEL && satchel_mode == SATCHEL_RADIO));
            // GoldSrc gives IN_ATTACK2 priority over IN_ATTACK in ItemPostFrame.
            // Without this, holding both pads could spend primary ammo first
            // and starve the requested secondary path on the same tick.
            if secondary_claims_trigger {
                want_fire = false;
            }
            // Crouch (TRIANGLE held): lower stance + slower move; the world
            // trace runs on the cooked GoldSrc crouch hull (M48), so ducking
            // fits under low vents.
            let duck_requested = !dead
                && unsafe { MOUNTED_TANK } < 0
                && input_sample.held(semantic_input::ACTION_DUCK);
            crouching = duck_requested;
            // GoldSrc drains one battery unit every 1.2 s while on and restores
            // one every 0.2 s while off. Tick before input so a fresh toggle gets
            // the complete authored interval rather than losing this tick.
            if dead && flashlight {
                flashlight = false;
                flashlight_timer = FLASH_CHARGE_TICKS;
            }
            let (next_flashlight, next_battery, next_timer, auto_off) =
                tick_flashlight_battery(flashlight, flashlight_battery, flashlight_timer);
            flashlight = next_flashlight;
            flashlight_battery = next_battery;
            flashlight_timer = next_timer;
            if auto_off {
                unsafe { sfx::play(sfx::FLASHLIGHT) };
            }
            // Flashlight (L3 toggles the HEV lamp; needs the suit and charge).
            let flash_now = input_sample.held(semantic_input::ACTION_FLASHLIGHT);
            if flash_now && !flash_prev && suit_equipped && !dead {
                if flashlight {
                    flashlight = false;
                    flashlight_timer = FLASH_CHARGE_TICKS;
                    unsafe { sfx::play(sfx::FLASHLIGHT) };
                } else if flashlight_battery > 0 {
                    flashlight = true;
                    flashlight_timer = FLASH_DRAIN_TICKS;
                    unsafe { sfx::play(sfx::FLASHLIGHT) };
                }
            }
            flash_prev = flash_now;
            unsafe {
                FLASHLIGHT_ON = flashlight && suit_equipped && !dead;
                FLASHLIGHT_BATTERY = flashlight_battery;
                FLASHLIGHT_TIMER = flashlight_timer;
            }
            let want_reload = input_sample.held(semantic_input::ACTION_RELOAD);
            // L1/R1 cycle owned weapons (rising edge so a hold steps once).
            let sw_next = input_sample.held(semantic_input::ACTION_NEXT_WEAPON);
            let sw_prev = input_sample.held(semantic_input::ACTION_PREV_WEAPON);
            let sw_held = sw_next || sw_prev;
            if !dead && sw_held && !switch_prev && weapon.cycle(sw_next) {
                grenade_cooking = false;
                zoom_aim = false; // CCrossbow::Holster restores the default FOV
                pending_vm_switch = true;
                weapon_icon_ticks = WEAPON_ICON_TICKS; // flash the select icon
                viewmodel_anim = VM_ANIM_DRAW;
                viewmodel_anim_start = sim_frame_no;
            }
            if weapon_icon_ticks > 0 {
                weapon_icon_ticks -= 1;
            }
            switch_prev = sw_held;
            if pending_vm_switch {
                pending_vm_switch = false;
                unsafe {
                    // OC-02: a switch no longer streams its chunk inside this
                    // tick (a blocking ~38-sector read froze every render for
                    // ~15 vblanks). Open the bounded per-tick pump instead: the
                    // hands render empty while sectors land across ticks, then
                    // the draw animation plays on the completion tick. A newer
                    // request supersedes an in-flight stream. A begin that
                    // cannot open at all falls back to streaming the glock.
                    let requested_wm = weapon_viewmodel(weapon.current, satchel_mode);
                    if vm_switch_begin(requested_wm) == VmSwitchBegin::Failed && requested_wm != 0 {
                        let _ = vm_switch_begin(0);
                    }
                }
            }
            // Advance any in-flight switch stream by its per-tick budget;
            // renders continue between pumps. Ready publishes the weapon and
            // starts its draw animation exactly like the old same-tick path.
            match unsafe { vm_switch_pump() } {
                VmSwitchPump::Ready => {
                    viewmodel_anim = VM_ANIM_DRAW;
                    viewmodel_anim_start = sim_frame_no;
                    #[cfg(feature = "emulator-telemetry")]
                    if DEBUG_ALL_WEAPONS {
                        unsafe {
                            let requested_wm = weapon_viewmodel(weapon.current, satchel_mode);
                            let (vm, _, slots, actual) = viewmodel_for(requested_wm);
                            debug_line(
                                "weapon load",
                                &[
                                    ("id=", weapon.current as i32),
                                    ("actual=", actual as i32),
                                    ("verts=", vm.n_verts as i32),
                                    ("tris=", vm.n_tris as i32),
                                    ("slots=", slots as i32),
                                ],
                            );
                        }
                    }
                    unsafe { invalidate_weapon_tri_cache() }; // re-project the replacement geometry
                }
                VmSwitchPump::Failed => {
                    unsafe {
                        // Stream failure: restore the known glock geometry (its
                        // retained texture prefix survives the eviction). If even
                        // that stream cannot open, the hands stay empty until the
                        // next switch request.
                        let _ = vm_switch_begin(0);
                    }
                }
                VmSwitchPump::InFlight => {
                    // DefaultDeploy blocks attacks for 0.5 s. If physical CD
                    // delivery lasts longer, keep the final tick armed until
                    // the new model is actually published.
                    weapon.switch_ticks = weapon.switch_ticks.max(1);
                }
                VmSwitchPump::Idle => {}
            }
            if use_cooldown > 0 {
                use_cooldown -= 1;
            }
            let use_held_raw = !dead && input_sample.held(semantic_input::ACTION_USE);
            #[cfg(feature = "debug-regression-viewpoints")]
            if launch.pitch == DEBUG_PANEL_VIEW_PITCH_SENTINEL && use_held_raw {
                let mut panel_li = 0usize;
                while panel_li < nlogic {
                    unsafe {
                        let panel = m.logic(panel_li);
                        // t0a0's jump-completion panels are qrad styles 36-38,
                        // compact slots 5-7 (styles 32-35 precede them). The
                        // old proof enabled every named light in the map and
                        // therefore made unrelated course lighting satisfy the
                        // screenshot diff.
                        if panel.kind == map::LOGIC_LIGHTSTYLE
                            && (5..=7).contains(&(panel.arg0 as u8))
                        {
                            logic_use_entity(
                                &m,
                                nlogic,
                                nents,
                                panel_li,
                                map::USE_ON,
                                sim_frame_no as u16,
                                0,
                                logic_state::CALLER_NONE,
                            );
                        }
                    }
                    panel_li += 1;
                }
            }
            let want_use = use_held_raw && use_cooldown == 0;
            if want_use {
                use_cooldown = 8;
            }
            let (mut fwd, mut strafe, mut turn, mut look) = (
                input_sample.forward as i32,
                input_sample.strafe as i32,
                input_sample.turn as i32,
                input_sample.look as i32,
            );
            if dead {
                fwd = 0;
                strafe = 0;
                turn = 0;
                look = 0;
            }
            // Mounted on a tank: rooted in place, but still free to aim + fire.
            if unsafe { MOUNTED_TANK } >= 0 {
                fwd = 0;
                strafe = 0;
            }
            // GoldSrc scales the command only when FL_DUCKING was already set
            // at the start of PM_Duck. The initial 0.4-second transition (and
            // the first airborne frame of a duck-jump) still use full input.
            if player.crouch {
                fwd /= 3; // duck factor 0.333 (pm_shared.c:1998)
                strafe /= 3;
            }
            // GoldSrc PFLAG_ONTRAIN: Square enters a persistent controller;
            // forward/back rising edges move through quarter-speed notches,
            // while strafe or jump relinquishes control. The Hazard Course rail
            // is forward-only in practice, so a back notch decelerates to zero.
            if tram_controlling {
                let drive_axis = if fwd > 32 {
                    1i8
                } else if fwd < -32 {
                    -1i8
                } else {
                    0i8
                };
                if strafe != 0 || input_sample.held(semantic_input::ACTION_JUMP) {
                    tram_controlling = false;
                    tram_drive_axis_prev = 0;
                } else {
                    if drive_axis != 0 && tram_drive_axis_prev == 0 {
                        let maximum = unsafe { TRACKTRAIN_USE_SPEED as i32 }.max(1);
                        let notch = ((tram_speed * 4) / maximum + drive_axis as i32).clamp(0, 4);
                        let requested = maximum * notch / 4;
                        unsafe {
                            TRACKTRAIN_CMD_ACTIVE = 1;
                            TRACKTRAIN_CMD_USE_TYPE = if requested == 0 {
                                map::USE_OFF
                            } else {
                                map::USE_ON
                            };
                            TRACKTRAIN_CMD_SPEED = requested as u16;
                        }
                    }
                    tram_drive_axis_prev = drive_axis;
                    fwd = 0;
                    strafe = 0;
                }
            } else {
                tram_drive_axis_prev = 0;
            }
            // Crossbow zoom = steady aim: halve look rate while held. ponytail: a
            // sensitivity cut, not a real FOV magnify (that needs a projection change).
            let (yaw_rate, pitch_rate) = if zoom_aim {
                (YAW_RATE / 2, PITCH_RATE / 2)
            } else {
                (YAW_RATE, PITCH_RATE)
            };
            yaw = (((yaw as i32) + semantic_input::angle_step_nearest(turn, yaw_rate)) & 0xFFF)
                as u16;
            pitch = (pitch + semantic_input::angle_step_nearest(look, pitch_rate) as i16)
                .clamp(-PITCH_MAX, PITCH_MAX);
            unsafe {
                LOGIC_PLAYER_POS = player.pos;
                LOGIC_PLAYER_YAW = yaw;
                LOGIC_PLAYER_PITCH = pitch;
                // A stopped tracktrain still carries its standing passenger
                // across a changelevel. GoldSrc transfers the ground entity;
                // tying this to motion stranded the neutral rider in c0a0b.
                LOGIC_TRAM_RIDING = tram_player_attached as u8;
                let car_now = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                LOGIC_TRAM_SEAT = [
                    player.pos[0] - car_now[0],
                    player.pos[1] - car_now[1],
                    player.pos[2] - car_now[2],
                ];
                LOGIC_PLAYER_HEALTH = health;
                LOGIC_PLAYER_SUIT = if suit_equipped { 1 } else { 0 };
                LOGIC_PLAYER_ARMOR = armor;
                LOGIC_PLAYER_CLIP_AMMO = weapon.clip_display();
                LOGIC_PLAYER_RESERVE_AMMO = weapon.reserve_display();
                SIM_NOW = sim_frame_no as u16;
                logic_pre_tick(&m, nlogic, nents, sim_frame_no as u16);
            }

            let prev_train_pos = tram_pos_ext(
                &m,
                tram_seg,
                tram_seg_dist,
                tram_pre_from,
                tram_pre_total,
                tram_pre_left,
            );
            let mut tram_started_this_tick = false;
            let tram_active_before_command = tram_active;
            unsafe {
                if let Some((use_type, speed)) = logic_take_tracktrain_command() {
                    // Same transfer guard as the arrival: the approach leg
                    // ignores the map's auto-start toggle (see above).
                    if !(tram_pre_left > 0 && tram_active) {
                        let started =
                            tram_apply_command(use_type, speed, &mut tram_active, &mut tram_speed);
                        tram_started_this_tick = started;
                        if !tram_active {
                            // Keep the passenger attached while the authored
                            // tram pauses. They are detached by the geometric
                            // carry check when the car moves again, not merely
                            // because its speed reached zero.
                            tram_speed_remainder = 0;
                        } else if started && !tram_player_attached {
                            tram_player_attached =
                                tram_should_carry_player(player.pos, prev_train_pos);
                            if tram_player_attached {
                                tram_rider_local =
                                    tram_seat_to_local(player.pos, prev_train_pos, prev_tram_yaw);
                            }
                        }
                    }
                }
            }
            if tram_active != tram_active_before_command {
                unsafe {
                    if tram_active {
                        player_tram_audio_start(&m, tram_audio_li, prev_train_pos);
                    } else {
                        player_tram_audio_stop(&m, tram_audio_li, prev_train_pos);
                    }
                }
            }
            if tram_started_this_tick {
                // Use computes the next linear/angular velocity immediately,
                // but GoldSrc's pusher does not integrate it until the next
                // 50 ms physics frame.
                tram_controller_primed = false;
                tram_player_left_stopped = false;
            }

            // The client's svc_addangle FIFO is one physical frame behind the
            // pusher. Apply the saved high-resolution step after 16-bit floor
            // quantization, retaining four sub-Q12 view bits across maps.
            if tram_pending_push_q28 != 0 {
                let (next_yaw, next_frac) = tram_logic::add_camera_step_q16(
                    yaw,
                    tram_camera_frac_q16,
                    tram_logic::camera_step_q16_from_physical_q28(tram_pending_push_q28),
                );
                yaw = next_yaw;
                tram_camera_frac_q16 = next_frac;
            }
            tram_pending_push_q28 = 0;

            let integrate_tram = tram_active && tram_controller_primed;
            let seg_before_move = tram_seg;
            let dist_before_move = tram_seg_dist;
            let prev_ride_off = ride_off;
            if integrate_tram {
                // Consume the ride-transfer approach leg first; leftover step
                // rolls straight onto the cooked chain.
                let restore_relink_frame = launch.riding && sim_frame_no == 4;
                let mut step = if restore_relink_frame {
                    // OverrideReset schedules NearestPath for 0.1 s after a
                    // global transition. Xash executes that relink on the
                    // fourth comparable destination frame without integrating
                    // the pusher; both moving c0a0 transfers show this exact
                    // single-frame hold in the reference trace.
                    0
                } else {
                    tram_step_for_speed(tram_speed, &mut tram_speed_remainder)
                };
                if tram_pre_left > 0 {
                    let used = step.min(tram_pre_left);
                    tram_pre_left -= used;
                    step -= used;
                }
                let (still_moving, crossed_tram_phase) = if step > 0 {
                    tram_advance(&m, &mut tram_seg, &mut tram_seg_dist, step, &mut tram_speed)
                } else {
                    (true, false)
                };
                if crossed_tram_phase {
                    tram_speed_remainder = 0;
                }
                // path_track fire-on-pass ("message"): the TRAIN's passage
                // fires these in HL -- the intro ride's changelevels and
                // station scripts hang off them.
                for w in (seg_before_move + 1)..=tram_seg {
                    let pid = m.way_pass(w);
                    if pid != 0 {
                        unsafe {
                            logic_fire_targets(
                                &m,
                                nlogic,
                                nents,
                                pid,
                                map::USE_TOGGLE,
                                sim_frame_no as u16,
                                0,
                                logic_state::CALLER_NONE,
                            );
                        }
                    }
                }
                let train_pos = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                ride_off = [
                    train_pos[0] - tram_ref[0],
                    train_pos[1] - tram_ref[1],
                    train_pos[2] - tram_ref[2],
                ];
                if !still_moving {
                    tram_active = false;
                    tram_speed = 0;
                    tram_speed_remainder = 0;
                    unsafe { player_tram_audio_stop(&m, tram_audio_li, train_pos) };
                    telemetry::debug_log("hl-psx: tram path end");
                }
            }
            let (next_actual_yaw_q28, physical_yaw_step_q28) = tram_integrate_yaw_q28(
                &m,
                integrate_tram,
                seg_before_move,
                dist_before_move,
                tram_seg,
                tram_seg_dist,
                tram_actual_yaw_q28,
                tram_target_yaw_q28,
            );
            tram_actual_yaw_q28 = next_actual_yaw_q28;
            // Next() runs after pusher integration and prepares the following
            // frame's angular velocity from a wheels-unit forward path point.
            if tram_active {
                tram_target_yaw_q28 = tram_desired_yaw_q28(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                    tram_target_yaw_q28,
                );
                tram_controller_primed = true;
            }
            let tram_yaw_now = tram_logic::visible_yaw_q12(tram_actual_yaw_q28);
            tram_yaw_render = tram_yaw_now;
            let tram_delta = [
                ride_off[0] - prev_ride_off[0],
                ride_off[1] - prev_ride_off[1],
                ride_off[2] - prev_ride_off[2],
            ];
            if tram_delta != [0, 0, 0] || tram_yaw_now != prev_tram_yaw {
                let train_pos = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                if !tram_player_attached && tram_walked_off {
                    // Standing back on the car clears the walk-off latch, the
                    // way landing on a GoldSrc pusher makes it your ground
                    // entity again.
                    let raw = tram_seat_raw_local(player.pos, prev_train_pos, tram_yaw_now);
                    if player.on_ground && tram_logic::rider_over_tram_footprint(raw[0], raw[2]) {
                        tram_walked_off = false;
                    }
                }
                if !tram_player_attached
                    && !tram_walked_off
                    && tram_should_carry_player(player.pos, prev_train_pos)
                {
                    tram_player_attached = true;
                    prev_tram_yaw = tram_yaw_now; // no yaw jump on attach
                    tram_rider_local = tram_seat_to_local(player.pos, prev_train_pos, tram_yaw_now);
                }
                if tram_player_attached {
                    if tram_should_carry_player(player.pos, prev_train_pos)
                        || tram_should_carry_player(player.pos, train_pos)
                    {
                        // Rotate one stable car-local seat by the full physical
                        // yaw. Re-deriving the seat from a quantized world pose
                        // each tick accumulated five units of edge drift by
                        // c0a0e even though the input was perfectly neutral.
                        player.pos = tram_seat_to_world(train_pos, tram_rider_local, tram_yaw_now);
                        // The car supports the rider: without this, gravity
                        // accumulates whenever the probe misses the receding
                        // floor (descents/bends) and the eventual catch
                        // registers as a lethal fall (land_impact) -- the
                        // faithful fall damage was killing tram passengers.
                        if player.vel[1] < 0 {
                            player.set_vertical_velocity(0);
                        }
                        player.on_ground = true;
                        player.ground_mover = -2; // compact synthetic tram support
                        player.land_impact = 0;
                    } else {
                        tram_player_attached = false;
                        #[cfg(feature = "emulator-telemetry")]
                        debug_line(
                            "tram detach",
                            &[
                                ("px=", player.pos[0]),
                                ("py=", player.pos[1]),
                                ("pz=", player.pos[2]),
                                ("cx=", train_pos[0]),
                                ("cy=", train_pos[1]),
                                ("cz=", train_pos[2]),
                            ],
                        );
                    }
                }
            }
            if tram_player_attached && physical_yaw_step_q28 != 0 {
                tram_pending_push_q28 = physical_yaw_step_q28;
            }
            prev_tram_yaw = tram_yaw_now;

            unsafe {
                TRAM_DYNAMICS_CARRY = TramDynamicsCarry {
                    actual_yaw_q28: tram_actual_yaw_q28,
                    desired_yaw_q28: tram_target_yaw_q28,
                    pending_push_q28: tram_pending_push_q28,
                    meta: tram_camera_frac_q16 as u32
                        | ((tram_controller_primed as u32) << 4)
                        | 0x20,
                };
            }

            #[cfg(feature = "debug-regression-viewpoints")]
            if launch.pitch == DEBUG_TRAIN_VIEW_PITCH_SENTINEL && sim_frame_no == 20 {
                unsafe {
                    let mut li = 0usize;
                    while li < nlogic {
                        let rec = m.logic(li);
                        if rec.kind == map::LOGIC_FUNC_TRAIN {
                            logic_apply_brush_train_command(li, rec, map::USE_ON);
                            break;
                        }
                        li += 1;
                    }
                }
            }
            #[cfg(feature = "debug-regression-viewpoints")]
            if launch.pitch == DEBUG_GUNTARGET_VIEW_PITCH_SENTINEL && sim_frame_no == 1 {
                unsafe {
                    let mut t = 0usize;
                    while t < TRAIN_COUNT {
                        let li = train_logic_index(TRAIN_LI[t]);
                        let rec = m.logic(li);
                        if rec.kind == map::LOGIC_FUNC_GUNTARGET {
                            // Target 1 begins at path corner 0 (the authored
                            // lower position). Slot 13 was captured after it
                            // reached corner 1, which crosses into the camera's
                            // PVS while the observer stays in the same leaf.
                            let (raised, _, _, _) = train_corner(&m, li, 1);
                            TRAIN_SEG[t] = 1;
                            TRAIN_DIST[t] = 0;
                            TRAIN_STATE[t] = 0;
                            train_set_offset(rec, t, raised);
                            break;
                        }
                        t += 1;
                    }
                }
            }
            unsafe { tick_trains(&m, nlogic, nents) };
            // Collision movers: every brush entity at its current offset (doors at
            // their open amount, statics at origin) + the tram at its ride offset.
            // Static: 0..nmov is fully written below; a local was memset-ing
            // ~7.7 KB every frame (3.2% of the profile).
            let movers = unsafe { &mut *core::ptr::addr_of_mut!(MOVERS) };
            let previous_mover_count = unsafe { MOVER_COUNT };
            let mut mover_visibility_changed = false;
            let mut mover_membership_changed = false;
            let mut nmov = 0;
            unsafe {
                for ei in 0..nents {
                    if ENT_ACTIVE[ei] == 0 {
                        continue;
                    }
                    let e = ENT_CACHE[ei];
                    let off = ent_draw_offset(ei);
                    // kind 2 = nonsolid visual, kind 4 = ladder volume (no hull).
                    if e.kind != 2
                        && e.kind != 4
                        && !fan_collision_disabled(ei, e)
                        && !pendulum_collision_disabled(e)
                        && nmov < movers.len()
                    {
                        // A continuously rotating fan, or a swinging door while
                        // between endpoints, cannot use the translated BSP LOS
                        // walker: its cooked nodes are in world coordinates and
                        // need pivot-aware rotation. Translucent/additive brushes
                        // are visible surfaces, not opaque occluders: c1a0d's
                        // closed glass cabinet must show its HEV suit from load.
                        let visual_rotating = e.kind == 5
                            || (e.kind == ENT_KIND_PLATROT
                                && (ENT_PHASE[ei] != 0 || e.mv[2] as u32 & 0x00ff_ffff != 0))
                            || ((e.kind == 7 || e.kind == ENT_KIND_ROT_BUTTON)
                                && (ENT_PHASE[ei] != 0 || e.mv[2] != 0))
                            || (e.kind == ENT_KIND_PENDULUM && pendulum_phase_q19(ei) != 0);
                        let mut head0 = if !visibility_logic::brush_blocks_actor_visual_los(
                            e.blend,
                            visual_rotating,
                        ) {
                            e.head0 | phys::MOVER_VISUAL_DISABLED
                        } else {
                            e.head0
                        };
                        if e.kind == ENT_KIND_PENDULUM
                            || e.kind == 7
                            || e.kind == ENT_KIND_ROT_BUTTON
                        {
                            head0 |= phys::mover_rotation_axis_tag(pendulum_axis(e));
                        }
                        let (rc, rs) = if e.kind == ENT_KIND_PLATROT {
                            let packed = platrot_angles_q8(e, ENT_PHASE[ei]);
                            if e.mv[2] as u32 & 0x00ff_ffff != 0 || platrot_axis(e) != 0 {
                                (phys::MOVER_FULL_ROTATION, packed as i32)
                            } else {
                                let rm = platrot_rotation(e, ENT_PHASE[ei]);
                                (rm.m[0][0] as i32, rm.m[0][2] as i32)
                            }
                        } else if e.kind == 5 && e.mv[1] == 0 {
                            // phys::Mover rotates around world Y. This is the
                            // c1a2 fan's mapped Z_AXIS, so its collision stops at
                            // the same retained blade angle as the renderer.
                            let rm = fan_rotation(e, fan_angle_q12(ei, sim_frame_no));
                            (rm.m[0][0] as i32, rm.m[0][2] as i32)
                        } else if e.kind == ENT_KIND_PENDULUM {
                            let rm = pendulum_rotation(e, pendulum_angle_q12(ei));
                            match pendulum_axis(e) {
                                1 => (rm.m[1][1] as i32, rm.m[2][1] as i32),
                                2 => (rm.m[0][0] as i32, rm.m[1][0] as i32),
                                _ => (rm.m[0][0] as i32, rm.m[0][2] as i32),
                            }
                        } else if e.kind == 7 || e.kind == ENT_KIND_ROT_BUTTON {
                            let ang = (((ENT_PHASE[ei] * e.mv[0]) >> 12) as u16) & 0x0fff;
                            let packed = axial_brush_angles_q8(e, ang);
                            if e.mv[2] as u32 & 0x00ff_ffff != 0 {
                                (phys::MOVER_FULL_ROTATION, packed as i32)
                            } else {
                                let rm = axial_brush_rotation(e, ang);
                                match e.mv[1] {
                                    1 => (rm.m[1][1] as i32, rm.m[2][1] as i32),
                                    2 => (rm.m[0][0] as i32, rm.m[1][0] as i32),
                                    _ => (rm.m[0][0] as i32, rm.m[0][2] as i32),
                                }
                            }
                        } else {
                            (4096, 0)
                        };
                        let old = movers[nmov];
                        let visual_pose_changed = (head0 & phys::MOVER_VISUAL_DISABLED) == 0
                            && (old.rc != rc || old.rs != rs);
                        if nmov >= previous_mover_count || old.id != ei as i32 {
                            mover_membership_changed = true;
                        }
                        if nmov >= previous_mover_count
                            || old.id != ei as i32
                            || old.off != off
                            || old.head0 != head0
                            || visual_pose_changed
                        {
                            mover_visibility_changed = true;
                        }
                        let mover_center = phys::mover_bounds_center(e.center, off, rc, rs, head0);
                        movers[nmov] = phys::Mover {
                            head: e.head,
                            head0,
                            off,
                            center: mover_center,
                            radius: ENT_RADIUS[ei],
                            id: ei as i32,
                            rc,
                            rs,
                        };
                        nmov += 1;
                    }
                }
                if m.tram_submodel > 0 && !tram_player_left_stopped && nmov < movers.len() {
                    let toff = [
                        ride_off[0] + m.tram_base[0],
                        ride_off[1] + m.tram_base[1],
                        ride_off[2] + m.tram_base[2],
                    ];
                    // The tram's hull is entity-local (off = its world pivot),
                    // so hand phys the SAME quantized rotation the render uses:
                    // the car's collision turns with its walls through bends.
                    let rm = tram_world_rotation(tram_yaw_now);
                    let old = movers[nmov];
                    if nmov >= previous_mover_count || old.id != -2 {
                        mover_membership_changed = true;
                    }
                    if nmov >= previous_mover_count
                        || old.id != -2
                        || old.off != toff
                        || old.rc != rm.m[0][0] as i32
                        || old.rs != rm.m[0][2] as i32
                    {
                        mover_visibility_changed = true;
                    }
                    movers[nmov] = phys::Mover {
                        head: m.tram_head,
                        // No cooked render-BSP root; visual LOS recognizes the
                        // synthetic tram id and skips its inflated gameplay hull.
                        head0: 0,
                        off: toff,
                        center: toff,
                        radius: 0,
                        id: -2, // the tram has its own carry path
                        rc: rm.m[0][0] as i32,
                        rs: rm.m[0][2] as i32,
                    };
                    nmov += 1;
                }
            }
            if nmov != previous_mover_count {
                mover_visibility_changed = true;
                mover_membership_changed = true;
            }
            unsafe {
                if mover_membership_changed {
                    // Nearby broadphase records pack mover *slots*. If an
                    // opening door or destroyed brush shifts the compact mover
                    // list, force moving actors to rebuild before this tick's
                    // collision rather than interpreting an old slot as its
                    // new neighbour. Pose-only movement keeps slots valid.
                    let mut pi = 0usize;
                    while pi < PROP_COUNT.min(CARRY_MAILBOX_FIRST) {
                        PROP_NEAR_COUNT[pi] = 0xFF;
                        pi += 1;
                    }
                }
                if mover_visibility_changed {
                    // Fail open immediately while a door/plat/tram moves, then
                    // let the staggered probes converge. Opening geometry can
                    // never leave an actor hidden behind a stale verdict.
                    let mut oi = 0usize;
                    while oi < PROP_COUNT.min(CARRY_MAILBOX_FIRST) {
                        PROP_OCC_VIS[oi] |= PROP_OCC_VISIBLE | PROP_OCC_DIRTY;
                        oi += 1;
                    }
                }
                MOVER_COUNT = nmov;
            }
            let movers = &mut movers[..nmov];

            // Ride moving brushes: establish cart-on-lift motion first, then
            // carry a player standing on either the lift or the translated
            // cart before publishing every mover's previous pose.
            unsafe {
                if has_pushables {
                    carry_pushables_on_support(&m, movers, nents);
                }
                carry_player_on_brush_mover(&mut player, &mut yaw, nents, &m, movers);
            }
            let player_actor_start = player.pos;

            // Full player physics always runs; moving trains carry the player by
            // delta before the update, then block them through their shifted hull.
            telemetry::stage_begin(telemetry::stage::SIM_COLLISION);
            // Jump is edge-triggered like HL (holding Cross does not pogo --
            // pm_shared.c:2554 requires a release between jumps), with the
            // 2-tick buffer forgiving a press just before touchdown.
            let jump_held = input_sample.held(semantic_input::ACTION_JUMP);
            let jump_edge = semantic_input::rising_edge(jump_held, jump_was_held);
            jump_was_held = jump_held;
            let jump_want = unsafe {
                let want = (jump_edge || JUMP_BUFFER > 0) && player.on_ground;
                // A press on the ladder is the detach input, not a queued
                // hop: HL needs a release between jumps, so dismounting near
                // the floor must land silent instead of buffer-bouncing.
                if jump_edge && !player.on_ground && active_ladder < 0 {
                    JUMP_BUFFER = JUMP_BUFFER_TICKS;
                } else if JUMP_BUFFER > 0 {
                    JUMP_BUFFER -= 1;
                }
                if want {
                    JUMP_BUFFER = 0; // consumed on the landing tick
                }
                want
            };
            let was_attached = active_ladder >= 0;
            let contact = unsafe {
                ladder_touch(
                    nents,
                    player.pos,
                    !was_attached && fwd > 0,
                    ladder_logic::wants_descend(pitch),
                    active_ladder,
                )
            };
            let mut ladder = None;
            if let Some((ei, center, half, assisted)) = contact {
                if was_attached {
                    ladder = Some((center, half));
                } else if assisted {
                    // This contact exists only because the intentional-entry
                    // helper widens a tangential edge by two integer units.
                    // Clamp that edge, but preserve the ladder-normal origin:
                    // GoldSrc PM_LadderMove never moves through/away from the
                    // face when mounting.
                    let target = ladder_logic::mount_target(player.pos, center, half);
                    if player.try_set_planar_position(&m, movers, target[0], target[2]) {
                        active_ladder = ei as i16;
                        ladder = Some((center, half));
                    }
                } else {
                    // Direct hull contact attaches even at rest, exactly like
                    // PM_Ladder. There is no mount snap in the original game.
                    active_ladder = ei as i16;
                    ladder = Some((center, half));
                }
            }
            if ladder.is_none() {
                // GoldSrc has no special top-out/mantle. Once PM_Ladder no
                // longer finds hull contact, this same command runs through
                // ordinary walking physics. In particular, never mirror or
                // centre the origin: both invented snaps could throw Gordon in
                // a direction unrelated to the held input.
                active_ladder = -1;
            }
            let on_ladder = ladder.is_some();
            // PM_Duck changes to hull 3 after 0.4 seconds on the ground, or at
            // once while airborne. It executes before PM_Jump, so pressing
            // duck+jump from standing deliberately performs this frame's move
            // with hull 1; the next tick activates hull 3 without shifting the
            // airborne origin. This timing is required by c1a1f's slanted
            // computer-bank crawlspace.
            let (next_duck_timer, activate_duck_hull) = ground_logic::advance_duck_activation(
                player.crouch,
                duck_requested,
                player.on_ground,
                duck_transition_ticks,
            );
            duck_transition_ticks = next_duck_timer;
            if activate_duck_hull {
                player.set_crouch(&m, movers, true);
            } else if !duck_requested {
                player.set_crouch(&m, movers, false);
            }
            // View interpolation begins with the request; a blocked un-duck
            // remains visually crouched because the short hull is still live.
            crouching = duck_requested || player.crouch;
            let swim_eye_height = if crouching {
                CROUCH_VIEW_HEIGHT
            } else {
                VIEW_HEIGHT
            };
            let movement_water_pos = player.pos;
            let movement_water = if on_ladder {
                WaterState {
                    level: 0,
                    eye_under: false,
                }
            } else {
                unsafe { water_state(&m, nents, player.pos, player.half_height(), swim_eye_height) }
            };
            let in_water = movement_water.level >= 2;
            // PlayerUse runs before the movement that its held command drives.
            // Resolve a continuous-use pushable now, while the first backward
            // step is still adjacent; later ticks retain it through GoldSrc's
            // 64-unit aimed use search rather than requiring hull overlap.
            let pushable_pull_target = if has_pushables && use_held_raw {
                unsafe {
                    pushable_use_target(
                        nents,
                        player.pos,
                        [player.pos[0], player.pos[1] + view_h_cur, player.pos[2]],
                        yaw,
                        pitch,
                    )
                }
            } else {
                usize::MAX
            };
            #[cfg(feature = "deep-reference-trace")]
            {
                phys::set_player_step_tick(sim_frame_no);
                trace_player_hull_probes(sim_frame_no, &m, movers, &player, fwd, yaw, jump_want);
            }
            if settings::debug_on(settings::DEBUG_FLY) {
                fly_move(&mut player, fwd, strafe, jump_held, yaw, pitch);
            } else if let Some((center, half)) = ladder {
                // PM_LadderMove checks the current IN_JUMP bit, not the
                // ground-jump rising edge. Release Cross before grabbing a
                // ladder after a jump, exactly as in GoldSrc.
                player.update_climb(&m, movers, fwd, strafe, jump_held, yaw, pitch, center, half);
                if jump_held {
                    active_ladder = -1;
                }
            } else if in_water || water_jump.active() {
                player.update_swim(
                    &m,
                    movers,
                    movement_water.level,
                    &mut water_jump,
                    fwd,
                    strafe,
                    jump_held,
                    yaw,
                    pitch,
                );
            } else {
                player.update(&m, movers, fwd, strafe, jump_want, duck_requested, yaw);
            }
            unsafe { resolve_player_actor_collision(&mut player, player_actor_start) };
            // The moving-car carry path intentionally keeps one stable
            // car-local seat so neutral input cannot accumulate Q12
            // round-trip drift. Deliberate player motion must publish a new
            // seat, though; otherwise the next tram tick restores the old
            // coordinate and makes walking inside the opening tram appear
            // completely frozen.
            if tram_player_attached && (fwd != 0 || strafe != 0) {
                let car_now = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                // GoldSrc carries whoever is standing ON the pusher, so walking
                // out of the car's open side hands the rider back to gravity.
                // The broad acquisition radius must not double as retention:
                // it reaches 384 units, so a rider who leaves through the
                // doorway was being re-seated at the clamp limit every tick and
                // floated alongside the moving car. A parked car keeps the
                // looser station footprint -- there the platform, not the
                // brush, is holding the player up.
                let raw = tram_seat_raw_local(player.pos, car_now, tram_yaw_render);
                let supported = if tram_active {
                    tram_logic::rider_over_moving_tram(raw[0], raw[2])
                } else {
                    tram_logic::rider_over_tram_footprint(raw[0], raw[2])
                };
                let clear_of_tram_hull = phys::mover_clear_at(&m, movers, -2, player.pos);
                match tram_logic::rider_motion_decision(supported, clear_of_tram_hull) {
                    tram_logic::RiderMotionDecision::Restore => {
                        // Ordinary mover traces suppress startsolid so a tiny
                        // rounded overlap cannot freeze the player. That broad
                        // escape rule must not turn a solid tram wall into a
                        // one-way exit: put this rider back at the last clear,
                        // stable car-local seat and try the held input again.
                        #[cfg(feature = "emulator-telemetry")]
                        let rejected = player.pos;
                        player.pos = tram_seat_to_world(car_now, tram_rider_local, tram_yaw_render);
                        player.on_ground = true;
                        player.ground_mover = -2;
                        player.land_impact = 0;
                        #[cfg(feature = "emulator-telemetry")]
                        debug_line(
                            "tram seat restore",
                            &[
                                ("rx=", rejected[0]),
                                ("ry=", rejected[1]),
                                ("rz=", rejected[2]),
                                ("lx=", raw[0]),
                                ("ly=", raw[1]),
                                ("lz=", raw[2]),
                                ("px=", player.pos[0]),
                                ("py=", player.pos[1]),
                                ("pz=", player.pos[2]),
                            ],
                        );
                    }
                    tram_logic::RiderMotionDecision::Publish => {
                        // Publish where the trace actually left them. The seat is
                        // re-applied next tick WITHOUT a collision trace, so a
                        // clamp here teleports the rider into whatever occupies
                        // the clamped cell: walking to the front of the c0a0 car
                        // pinned local x at 130, which is inside its bulkhead, and
                        // the slide-move then pushed them out through it. Height
                        // still normalizes -- that keeps a descending car from
                        // desynchronizing the rider's gravity.
                        tram_rider_local = [raw[0], raw[1].clamp(30, 100), raw[2]];
                    }
                    tram_logic::RiderMotionDecision::Detach => {
                        tram_player_attached = false;
                        tram_walked_off = true;
                    }
                }
            }
            // GoldSrc pushables react only to a grounded side touch. Resolve
            // their sweep after player movement, then publish the translated
            // mover immediately so combat, actor LOS and trigger logic in this
            // same simulation tick all observe the new cart position.
            unsafe {
                if has_pushables {
                    tick_pushables(
                        &m,
                        nlogic,
                        nents,
                        movers,
                        &mut player,
                        fwd,
                        strafe,
                        yaw,
                        use_held_raw,
                        pushable_pull_target,
                        sim_frame_no as u16,
                    );
                }
                update_platrot_rider_local(&player, nents, fwd != 0 || strafe != 0);
            }
            // Landing (per-tick units now: 1 u/t = 20 u/s). HL only dips the
            // view above 350 u/s (a normal jump lands at ~260 and stays
            // silent, pm_shared.c:2681), and fall damage starts at the
            // PLAYER_MAX_SAFE_FALL_SPEED 580 u/s = 29 u/t, scaling by
            // DAMAGE_FOR_FALL_SPEED to 100 at ~1024 u/s. Fall damage bypasses
            // armor (DMG_FALL is not in the suit's absorb set) and is uncapped
            // -- long drops are lethal, as authored.
            {
                let li = player.land_impact as i32;
                if li > 17 {
                    unsafe { add_view_punch(-(li.min(60) / 2), 0) };
                }
                if li > 29 {
                    let d = ((li - 29) * 9 / 2).max(1) as u16;
                    fall_damage_player(&mut health, d);
                }
            }
            // HEV suit voice: announce each worsening health threshold once.
            unsafe {
                let hstate = if health == 0 || !suit_equipped {
                    0
                } else if health < 10 {
                    2
                } else if health < 25 {
                    1
                } else {
                    0
                };
                if hstate > HEV_HEALTH_STATE {
                    sfx::play(if hstate == 2 {
                        sfx::HEV_NEAR_DEATH
                    } else {
                        sfx::HEV_HEALTH_CRIT
                    });
                }
                HEV_HEALTH_STATE = hstate;
            }
            // Footsteps: input-magnitude cadence while grounded (full run =
            // a step roughly every 8 ticks), alternating the two samples.
            unsafe {
                // View-bob phase advances with horizontal ground speed; the render
                // derives a vertical head-bob + strafe roll from it. Frozen while
                // airborne/stopped (the amplitude, speed-scaled, eases it to rest).
                let hspeed =
                    isqrt_i32(player.vel[0] * player.vel[0] + player.vel[2] * player.vel[2]);
                if player.on_ground && hspeed > 4 {
                    BOB_PHASE = BOB_PHASE.wrapping_add(((hspeed as u32) / 3 + 3).min(22));
                }
                if player.on_ground {
                    let mag = (fwd.unsigned_abs()).max(strafe.unsigned_abs()) as u32;
                    if mag > 20 {
                        STEP_ACC += mag;
                        if STEP_ACC >= 1000 {
                            STEP_ACC = 0;
                            STEP_ALT ^= 1;
                            sfx::play_vol(
                                if STEP_ALT == 0 {
                                    sfx::STEP1
                                } else {
                                    sfx::STEP2
                                },
                                3,
                            );
                        }
                    } else {
                        STEP_ACC = 0;
                    }
                }
            }
            telemetry::stage_end(telemetry::stage::SIM_COLLISION);
            let view_h_target = if crouching {
                CROUCH_VIEW_HEIGHT
            } else {
                VIEW_HEIGHT
            };
            view_h_cur += (view_h_target - view_h_cur).clamp(-4, 4);
            let view_h = view_h_cur;
            // Drowning (player.cpp:1215-1329): 12 s of air once the eye goes
            // under, then escalating 2,3,4,5,5.. damage per second straight to
            // health (the suit doesn't absorb DMG_DROWN); surfacing restores
            // the drowned-off health.
            let eye_under = health > 0
                && if !on_ladder && player.pos == movement_water_pos && view_h == swim_eye_height {
                    movement_water.eye_under
                } else {
                    unsafe {
                        water_touch(
                            &m,
                            nents,
                            [player.pos[0], player.pos[1] + view_h, player.pos[2]],
                        )
                    }
                };
            unsafe {
                PLAYER_EYE_UNDER = eye_under;
                if eye_under {
                    if DROWN_AIR > 0 {
                        DROWN_AIR -= 1;
                    } else {
                        DROWN_TICK += 1;
                        if DROWN_TICK >= 20 {
                            DROWN_TICK = 0;
                            let d = DROWN_NEXT.min(5);
                            DROWN_NEXT += 1;
                            DROWN_TAKEN = DROWN_TAKEN.saturating_add(d);
                            fall_damage_player(&mut health, d);
                        }
                    }
                } else {
                    DROWN_AIR = DROWN_AIR_TICKS;
                    DROWN_NEXT = 2;
                    DROWN_TICK = 0;
                    if DROWN_TAKEN > 0
                        && health > 0
                        && health < PLAYER_START_HEALTH
                        && (sim_frame_no % 10) == 0
                    {
                        DROWN_TAKEN -= 1;
                        health += 1;
                    }
                }
            }
            // A paused tracktrain remains the rider's ground entity in
            // GoldSrc. Our generic player trace sees only the car's authored
            // brush floor, which can sit hundreds of units below the path
            // pivot (c0a0c is ~695); during a scripted pause the rider fell to
            // that floor and failed the carry check when the car resumed.
            // Support a non-jumping attached rider at the same normalized seat
            // height. Horizontal movement can still leave the carry radius,
            // and an upward jump explicitly detaches into normal physics.
            if tram_player_attached && !tram_active {
                let car_now = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                if player.vel[1] > 0 {
                    tram_player_attached = false;
                } else {
                    let car_rot = tram_world_rotation(prev_tram_yaw);
                    let dx = player.pos[0] - car_now[0];
                    let dz = player.pos[2] - car_now[2];
                    // World -> car space (transpose the Y-rotation), matching
                    // the moving-rider carry path above.
                    let local_xz = tram_logic::inverse_rotate_rider_xz(
                        car_rot.m[0][0] as i32,
                        car_rot.m[0][2] as i32,
                        dx,
                        dz,
                    );
                    if tram_logic::rider_over_tram_footprint(local_xz[0], local_xz[1]) {
                        let seat_y = (player.pos[1] - car_now[1]).clamp(30, 100);
                        player.pos[1] = car_now[1] + seat_y;
                        player.set_vertical_velocity(0);
                        player.land_impact = 0;
                        player.on_ground = true;
                    } else {
                        tram_player_attached = false;
                        // The compact rotated tram hull is conservative around
                        // its doorway. Once the rider has crossed the real
                        // stopped-car footprint it can leave them startsolid
                        // and freeze every subsequent input. Gold no longer
                        // treats the car as their ground entity here; retire
                        // this synthetic mover until the train starts again.
                        tram_player_left_stopped = true;
                    }
                }
            }
            #[cfg(feature = "debug-regression-viewpoints")]
            if (launch.pitch == i16::MIN
                || launch.pitch == DEBUG_SAVED_VIEW_PITCH_SENTINEL
                || launch.pitch == DEBUG_MOMENTARY_VIEW_PITCH_SENTINEL
                || launch.pitch == DEBUG_ENTRY_VIEW_PITCH_SENTINEL
                || launch.pitch == DEBUG_PANEL_VIEW_PITCH_SENTINEL
                || launch.pitch == DEBUG_TRAIN_VIEW_PITCH_SENTINEL
                || launch.pitch == DEBUG_GUNTARGET_VIEW_PITCH_SENTINEL)
                && launch.room_id as usize != 64
                && launch.room_id as usize != 101
            {
                if let Some((position, view_yaw, view_pitch)) = regression_viewpoint(
                    launch.room_id as usize,
                    launch.pitch == DEBUG_SAVED_VIEW_PITCH_SENTINEL,
                    false,
                    launch.pitch == DEBUG_MOMENTARY_VIEW_PITCH_SENTINEL,
                    false,
                    launch.pitch == DEBUG_ENTRY_VIEW_PITCH_SENTINEL,
                    launch.pitch == DEBUG_PANEL_VIEW_PITCH_SENTINEL,
                    launch.pitch == DEBUG_TRAIN_VIEW_PITCH_SENTINEL,
                    launch.pitch == DEBUG_GUNTARGET_VIEW_PITCH_SENTINEL,
                ) {
                    // Subject tapes are camera tests, not traversal routes.
                    // Keep the observer position fixed while every world/entity
                    // tick continues normally. A held D-pad strafe performs a
                    // slow deterministic look sweep so temporal ordering can be
                    // checked across changing view angles; neutral input restores
                    // the authored comparison view. The water tape intentionally
                    // keeps real physics to prove surface entry and buoyancy.
                    player.pos = position;
                    player.clear_velocity();
                    player.on_ground = true;
                    player.ground_mover = -1;
                    if input_sample.strafe == 0 {
                        yaw = view_yaw;
                    } else {
                        yaw = (((yaw as i32)
                            + semantic_input::angle_step_nearest(
                                input_sample.strafe as i32,
                                YAW_RATE / 8,
                            ))
                            & 0xFFF) as u16;
                    }
                    pitch = view_pitch;
                }
            }
            let eye = [player.pos[0], player.pos[1] + view_h, player.pos[2]];
            let pickup_weapon_before = weapon.current;
            let pickup_owned_before = weapon.owned;
            unsafe {
                collect_pickups(
                    &m,
                    nlogic,
                    nents,
                    sim_frame_no as u16,
                    player.pos,
                    player.half_height(),
                    &mut suit_equipped,
                    &mut armor,
                    &mut health,
                    &mut weapon,
                    &mut pickup_kind,
                    &mut pickup_ticks,
                );
                if weapon.current != pickup_weapon_before
                    || (pickup_owned_before == 0 && weapon.owned != 0)
                {
                    pending_vm_switch = true;
                    viewmodel_anim = VM_ANIM_DRAW;
                    viewmodel_anim_start = sim_frame_no;
                    weapon_icon_ticks = WEAPON_ICON_TICKS;
                }
                LOGIC_PLAYER_POS = player.pos;
                LOGIC_PLAYER_YAW = yaw;
                LOGIC_PLAYER_PITCH = pitch;
                LOGIC_TRAM_RIDING = tram_player_attached as u8;
                let car_now = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                LOGIC_TRAM_SEAT = [
                    player.pos[0] - car_now[0],
                    player.pos[1] - car_now[1],
                    player.pos[2] - car_now[2],
                ];
                LOGIC_PLAYER_HEALTH = health;
                LOGIC_PLAYER_SUIT = if suit_equipped { 1 } else { 0 };
                LOGIC_PLAYER_ARMOR = armor;
                LOGIC_PLAYER_CLIP_AMMO = weapon.clip_display();
                LOGIC_PLAYER_RESERVE_AMMO = weapon.reserve_display();
                LIVE_CHECKPOINT = save::Checkpoint {
                    room_id: launch.room_id,
                    pos: player.pos,
                    yaw,
                    pitch,
                    health,
                    armor,
                    suit: suit_equipped,
                    crouch: player.crouch,
                    longjump: phys::longjump_enabled(),
                    owned: weapon.owned,
                    current: weapon.current as u8,
                    clips: weapon.clip,
                    ammo: weapon.ammo,
                    global_hash: GLOBAL_HASH,
                    global_on: GLOBAL_ON,
                    global_count: GLOBAL_COUNT as u16,
                    has_pos: true,
                    sequence: 0, // stamped by save::write
                };
                let mut charger_pulse = 0u8;
                if want_use && MOUNTED_TANK >= 0 {
                    // Any use press while mounted dismounts (works even if the
                    // player has swung the view off the tank brush).
                    MOUNTED_TANK = -1;
                    sfx::play(sfx::BUTTON);
                } else if want_use {
                    // Standing on the tracktrain + use = drive it (On A Rail);
                    // otherwise aim-use doors/buttons/chargers/tanks.
                    let train_pos = tram_pos_ext(
                        &m,
                        tram_seg,
                        tram_seg_dist,
                        tram_pre_from,
                        tram_pre_total,
                        tram_pre_left,
                    );
                    if m.tram_submodel > 0
                        && TRACKTRAIN_USE_SPEED > 0
                        && tram_should_carry_player(player.pos, train_pos)
                    {
                        tram_controlling = !tram_controlling;
                        tram_drive_axis_prev = 0;
                        sfx::play(sfx::BUTTON);
                    } else {
                        charger_pulse = logic_try_use(
                            &m,
                            nlogic,
                            nents,
                            player.pos,
                            eye,
                            yaw,
                            pitch,
                            sim_frame_no as u16,
                            &mut health,
                            &mut armor,
                        );
                    }
                }
                if charger_pulse != 0 {
                    if charger_sound != charger_pulse {
                        // GoldSrc plays a short acceptance sample, waits 0.56 s,
                        // then starts the static charging bed. Keeping that bed
                        // on the reserved voice prevents each health increment
                        // from restarting it.
                        sfx::charger_stop();
                        sfx::play(if charger_pulse == sfx::CHARGER_HEALTH_LOOP {
                            sfx::MEDSHOT
                        } else {
                            sfx::SUIT
                        });
                        charger_sound = charger_pulse;
                        charger_intro_ticks = 12;
                    }
                } else if !use_held_raw || want_use {
                    // Between successful eight-tick charge pulses, leave the
                    // same decoder running. A failed pulse (full/depleted/lost
                    // aim) or button release ends it without an ADSR tail.
                    if charger_sound != 0 {
                        sfx::charger_stop();
                        charger_sound = 0;
                        charger_intro_ticks = 0;
                    }
                }
                if charger_sound != 0 && charger_intro_ticks > 0 {
                    charger_intro_ticks -= 1;
                    if charger_intro_ticks == 0 {
                        sfx::play(charger_sound);
                    }
                }
                // Hold-to-turn valve wheels: ramp while +use is held (raw, not
                // the edge-triggered want_use), independent of tank/train.
                if use_held_raw && MOUNTED_TANK < 0 {
                    tick_momentary(&m, nlogic, nents, player.pos, eye, yaw, pitch);
                }
                logic_touch_triggers(
                    &m,
                    nlogic,
                    nents,
                    player.pos,
                    &mut health,
                    &mut armor,
                    sim_frame_no as u16,
                );
                // Teleport lands before this frame renders (the render eye is
                // recomputed below); push adds velocity while inside the volume.
                if let Some((dest, dyaw)) = TELEPORT_REQUEST.take() {
                    player.pos = dest;
                    player.clear_velocity();
                    player.on_ground = false;
                    yaw = dyaw & 0xFFF;
                }
                if PUSH_IMPULSE != [0, 0, 0] {
                    // HL applies push as basevelocity: the stream SETS your
                    // vertical speed while inside (triggers.cpp), it does not
                    // integrate -- integration would scale with gravity and
                    // overshoot wildly now that gravity is the faithful 2 u/t^2.
                    if PUSH_IMPULSE[1] > 0 {
                        player.set_vertical_velocity(player.vel[1].max(PUSH_IMPULSE[1]));
                    } else if PUSH_IMPULSE[1] < 0 {
                        player.set_vertical_velocity(player.vel[1].min(PUSH_IMPULSE[1]));
                    }
                    // Lateral push nudges the position directly (vel xz is
                    // recomputed from the stick every tick).
                    player.pos[0] += PUSH_IMPULSE[0];
                    player.pos[2] += PUSH_IMPULSE[2];
                    PUSH_IMPULSE = [0; 3];
                }
            }
            unsafe {
                if WEAPONSTRIP_REQUEST {
                    // player_weaponstrip (the Apprehension capture): empty
                    // hands until the map hands gear back.
                    WEAPONSTRIP_REQUEST = false;
                    weapon.owned = 0;
                    weapon.current = W_CROWBAR;
                    satchel_mode = SATCHEL_PACK;
                    grenade_cooking = false;
                }
            }
            let reload_before = weapon.reload_ticks;
            if want_reload {
                if weapon.start_reload() {
                    if weapon.current == W_CROSSBOW {
                        zoom_aim = false; // CCrossbow::Reload exits zoom first
                    }
                    viewmodel_anim = weapon.reload_anim();
                    viewmodel_anim_start = sim_frame_no;
                    #[cfg(feature = "emulator-telemetry")]
                    if DEBUG_ALL_WEAPONS {
                        debug_line(
                            "weapon reload",
                            &[
                                ("id=", weapon.current as i32),
                                ("tick=", sim_frame_no as i32),
                            ],
                        );
                    }
                }
            }
            if grenade_pressed && unsafe { MOUNTED_TANK } < 0 {
                if weapon.owns(W_GRENADE)
                    && weapon.cooldown == 0
                    && weapon.reload_ticks == 0
                    && weapon.switch_ticks == 0
                    && weapon.ammo[AMMO_GREN] > 0
                {
                    grenade_cooking = true;
                    grenade_cook_start = sim_frame_no;
                    viewmodel_anim = VM_ANIM_ALT; // retail pinpull sequence
                    viewmodel_anim_start = sim_frame_no;
                    #[cfg(feature = "emulator-telemetry")]
                    if DEBUG_ALL_WEAPONS {
                        debug_line("grenade pin", &[("tick=", sim_frame_no as i32)]);
                    }
                } else if weapon.ammo[AMMO_GREN] == 0 {
                    weapon.cooldown = GLOCK_EMPTY_COOLDOWN_TICKS;
                    weapon.dry_ticks = GLOCK_EMPTY_COOLDOWN_TICKS;
                    unsafe { sfx::play(sfx::DRY) };
                }
            }

            // Edge-triggered secondary modes. They do not recoil or play a
            // generic attack animation: GoldSrc only changes the sight/radio
            // state here.
            if sec_pressed
                && weapon.current == W_CROSSBOW
                && weapon.dry_ticks == 0
                && weapon.switch_ticks == 0
            {
                zoom_aim = !zoom_aim;
                weapon.dry_ticks = 20; // crossbow.cpp: next secondary = 1.0 s
                unsafe { sfx::play(sfx::BUTTON) };
            }
            if sec_pressed
                && weapon.current == W_RPG
                && weapon.dry_ticks == 0
                && weapon.switch_ticks == 0
            {
                rpg_laser = !rpg_laser;
                weapon.dry_ticks = 4; // rpg.cpp: next secondary = 0.2 s
                unsafe { sfx::play(sfx::BUTTON) };
            }
            if weapon.current != W_CROSSBOW {
                zoom_aim = false;
            }
            if weapon.current != W_EGON || !fire_held {
                egon_firing = false;
            }

            let alt_rot = unsafe { aim_rotation(yaw, pitch) };
            let alt_base_t = [
                -dot12(alt_rot.m[0], eye),
                -dot12(alt_rot.m[1], eye),
                -dot12(alt_rot.m[2], eye),
            ];
            unsafe {
                update_rpg_spot(
                    &m,
                    movers,
                    eye,
                    &alt_rot,
                    weapon.current == W_RPG && rpg_laser,
                );
                match tick_gauss_secondary(
                    &mut weapon,
                    sec_held && MOUNTED_TANK < 0,
                    eye_under,
                    &m,
                    movers,
                    eye,
                    &alt_rot,
                    alt_base_t,
                ) {
                    GAUSS_EVENT_START => {
                        viewmodel_anim = VM_ANIM_ALT;
                        viewmodel_anim_start = sim_frame_no;
                    }
                    GAUSS_EVENT_SPIN => {
                        viewmodel_anim = VM_ANIM_CHARGE_LOOP;
                        viewmodel_anim_start = sim_frame_no;
                    }
                    GAUSS_EVENT_FIRE => {
                        viewmodel_anim = VM_ANIM_CHARGED_FIRE;
                        viewmodel_anim_start = sim_frame_no;
                        recoil = 20;
                        add_view_punch(WEAPON_KICK[W_GAUSS] * 2, 0);
                    }
                    GAUSS_EVENT_OVERCHARGE => {
                        viewmodel_anim = VM_ANIM_IDLE;
                        viewmodel_anim_start = sim_frame_no;
                    }
                    _ => {}
                }
            }

            // Satchel primary throws; secondary operates the radio. The old
            // path put detonation on R2, which was the inverse of satchel.cpp.
            if sec_held
                && unsafe { MOUNTED_TANK } < 0
                && weapon.current == W_SATCHEL
                && satchel_mode == SATCHEL_RADIO
                && weapon.cooldown == 0
                && weapon.reload_ticks == 0
                && weapon.switch_ticks == 0
            {
                unsafe {
                    let _ = detonate_satchels(&m);
                    sfx::play(sfx::BUTTON);
                }
                weapon.cooldown = 10;
                viewmodel_anim = VM_ANIM_FIRE;
                viewmodel_anim_start = sim_frame_no;
                satchel_mode = SATCHEL_TO_PACK;
                #[cfg(feature = "emulator-telemetry")]
                if DEBUG_ALL_WEAPONS {
                    debug_line("satchel secondary", &[("tick=", sim_frame_no as i32)]);
                }
            }
            if unsafe { MOUNTED_TANK } >= 0 {
                // Operating a func_tank: auto-fire hitscan from the gun barrel
                // along the view, rate-limited by the tank's cooldown. ponytail:
                // the barrel does not visually track the aim (brush stays static).
                unsafe {
                    if TANK_FIRE_CD > 0 {
                        TANK_FIRE_CD -= 1;
                    }
                    if fire_held && TANK_FIRE_CD == 0 {
                        let trec = m.logic(MOUNTED_TANK as usize);
                        let barrel = logic_center(trec);
                        let fire_rot = view_rotation(yaw, pitch);
                        let base_t = [
                            -dot12(fire_rot.m[0], barrel),
                            -dot12(fire_rot.m[1], barrel),
                            -dot12(fire_rot.m[2], barrel),
                        ];
                        fire_hitscan(
                            &m,
                            movers,
                            barrel,
                            &fire_rot,
                            base_t,
                            trec.arg0 as u8,
                            false,
                            8192,
                            2,
                            2,
                            0,
                            0,
                        );
                        sfx::play(sfx::MP5); // a mounted machine gun
                        TANK_FIRE_CD = trec.speed.max(2);
                        recoil = 8;
                    }
                }
            } else if want_fire && weapon.current == W_SATCHEL && satchel_mode != SATCHEL_PACK {
                // Primary is intentionally inert while holding the radio;
                // detonation belongs to L2. It is also blocked during either
                // pack/radio authored transition.
            } else if want_fire
                && eye_under
                && matches!(weapon.current, W_357 | W_MP5 | W_SHOTGUN | W_GAUSS | W_EGON)
            {
                if weapon.cooldown == 0 {
                    weapon.cooldown = 3;
                    unsafe { sfx::play(sfx::DRY) };
                }
            } else if want_fire && weapon.try_fire() {
                let throwing_cooked_grenade = weapon.current == W_GRENADE && grenade_throw;
                if throwing_cooked_grenade {
                    grenade_cooking = false;
                }
                if weapon.def().fire != FIRE_AUTO || viewmodel_anim != VM_ANIM_FIRE {
                    viewmodel_anim = VM_ANIM_FIRE;
                    viewmodel_anim_start = sim_frame_no;
                }
                recoil = 16;
                #[cfg(feature = "emulator-telemetry")]
                if DEBUG_ALL_WEAPONS {
                    debug_line(
                        "weapon fire",
                        &[
                            ("id=", weapon.current as i32),
                            ("anim=", viewmodel_anim as i32),
                            ("tick=", sim_frame_no as i32),
                        ],
                    );
                }
                // Aim along the punch accumulated so far, THEN add this shot's
                // kick -- CGlock::GlockFire makes its vectors before
                // `punchangle.x -= 2`, so a shot never eats its own recoil.
                let fire_rot = unsafe { aim_rotation(yaw, pitch) };
                unsafe {
                    // Camera kick: up per the weapon's class + a small random
                    // horizontal jolt so bursts wander like the real guns.
                    let k = WEAPON_KICK[weapon.current];
                    let yj = (IMPACT_RNG.below(5) as i32) - 2;
                    add_view_punch(k, yj * k / 24);
                }
                let fire_base_t = [
                    -dot12(fire_rot.m[0], eye),
                    -dot12(fire_rot.m[1], eye),
                    -dot12(fire_rot.m[2], eye),
                ];
                unsafe {
                    // Cone-of-fire: shots wander more while moving fast or airborne.
                    let hs =
                        isqrt_i32(player.vel[0] * player.vel[0] + player.vel[2] * player.vel[2]);
                    let inacc = (hs / 12).min(6) + if player.on_ground { 0 } else { 5 };
                    // GoldSrc's first crowbar swing after a one-second idle gap
                    // does full damage; a held combo does half. `dry_ticks` was
                    // otherwise write-only and is zeroed on weapon switches, so
                    // it can retain this timer without growing Arsenal.
                    let crowbar_combo = weapon.current == W_CROWBAR && weapon.dry_ticks != 0;
                    let damage = if crowbar_combo {
                        weapon.def().damage / 2
                    } else {
                        weapon.def().damage
                    };
                    let hit = if throwing_cooked_grenade {
                        let slot =
                            spawn_projectile(PROJ_GRENADE, weapon.def().damage, eye, &fire_rot);
                        PROJECTILES[slot].life = grenade_throw_life;
                        false
                    } else if weapon.current == W_CROSSBOW && eye_under {
                        // crossbow.cpp: 1000 u/s submerged versus 2000 in air.
                        spawn_projectile(PROJ_BOLT_WATER, weapon.def().damage, eye, &fire_rot);
                        false
                    } else {
                        if weapon.current == W_CROWBAR {
                            CROWBAR_HIT_VOLUME_DEN = 1;
                        }
                        fire_weapon(
                            weapon.def(),
                            damage,
                            &m,
                            movers,
                            eye,
                            &fire_rot,
                            fire_base_t,
                            inacc,
                        )
                    };
                    if weapon.current == W_CROWBAR {
                        if hit {
                            viewmodel_anim = VM_ANIM_ALT;
                        }
                        weapon.cooldown = if hit {
                            CROWBAR_HIT_COOLDOWN_TICKS
                        } else {
                            CROWBAR_MISS_COOLDOWN_TICKS
                        };
                        weapon.dry_ticks = CROWBAR_FULL_DAMAGE_IDLE_TICKS;
                    }
                    let start_sound = weapon.current != W_EGON || !egon_firing;
                    if weapon.current == W_EGON {
                        egon_firing = true;
                    }
                    if start_sound {
                        if weapon.current == W_CROWBAR && hit {
                            if CROWBAR_HIT_VOLUME_DEN != 0 {
                                sfx::play_vol(sfx::CBAR_HIT, CROWBAR_HIT_VOLUME_DEN);
                            }
                        } else {
                            sfx::play(weapon_fire_sfx(weapon.current, hit));
                        }
                    }
                    if weapon.current == W_SATCHEL {
                        // Keep the thrown-pack model alive until its authored
                        // drop clip completes, then stream the retail radio.
                        satchel_mode = SATCHEL_TO_RADIO;
                    }
                    // Eject a brass casing (bullet weapons only).
                    if matches!(weapon.current, W_GLOCK | W_MP5 | W_SHOTGUN) {
                        eject_casing(eye, &fire_rot);
                    }
                }
            }
            // Repeating secondary guns consume held L2 and their own authored
            // cooldown. Toggle/charge/radio weapons were handled above.
            if sec_held
                && unsafe { MOUNTED_TANK } < 0
                && weapon.any_weapon()
                && matches!(weapon.current, W_GLOCK | W_MP5 | W_SHOTGUN | W_HORNET)
            {
                unsafe {
                    if fire_secondary(
                        &mut weapon,
                        &m,
                        movers,
                        eye,
                        &alt_rot,
                        alt_base_t,
                        eye_under,
                    ) {
                        viewmodel_anim = VM_ANIM_ALT;
                        viewmodel_anim_start = sim_frame_no;
                        recoil = 16;
                        add_view_punch(WEAPON_KICK[weapon.current], 0);
                        if matches!(weapon.current, W_GLOCK | W_SHOTGUN) {
                            eject_casing(eye, &alt_rot);
                        }
                        #[cfg(feature = "emulator-telemetry")]
                        if DEBUG_ALL_WEAPONS {
                            debug_line(
                                "weapon alt",
                                &[
                                    ("id=", weapon.current as i32),
                                    ("tick=", sim_frame_no as i32),
                                ],
                            );
                        }
                    }
                }
            }
            // Empty-magazine primary and secondary paths can both start a
            // reload internally while returning `false`. Detect the transition
            // only after both attacks so neither path misses its viewmodel.
            if reload_before == 0 && weapon.reload_ticks > 0 {
                viewmodel_anim = weapon.reload_anim();
                viewmodel_anim_start = sim_frame_no;
            }
            unsafe {
                sfx::set_ear(player.pos);
                if PAIN_SFX_COOLDOWN > 0 {
                    PAIN_SFX_COOLDOWN -= 1;
                }
                MOVE_TICK = MOVE_TICK.wrapping_add(1);
                if MON_PAIN_COOLDOWN > 0 {
                    MON_PAIN_COOLDOWN -= 1;
                }
                tick_projectiles(&m, movers);
                tick_env_sparks(&m, nlogic);
                tick_beams(&m, nlogic);
                if PENDING_PLAYER_DAMAGE > 0 {
                    let d = PENDING_PLAYER_DAMAGE;
                    PENDING_PLAYER_DAMAGE = 0;
                    damage_player(&mut health, &mut armor, d);
                }
                if PENDING_GAUSS_SHOVE != [0; 3] {
                    player.vel[0] += PENDING_GAUSS_SHOVE[0];
                    player.vel[2] += PENDING_GAUSS_SHOVE[2];
                    PENDING_GAUSS_SHOVE = [0; 3];
                }
                telemetry::stage_begin(telemetry::stage::UPDATE_ACTOR);
                snapshot_prop_transforms();
                tick_props(
                    &m,
                    movers,
                    player.pos,
                    &mut health,
                    &mut armor,
                    launch.room_id,
                );
                telemetry::stage_end(telemetry::stage::UPDATE_ACTOR);
                apply_debug_toggles(
                    &mut health,
                    &mut armor,
                    &mut suit_equipped,
                    &mut weapon,
                    &mut debug_weapons_given,
                );
                LOGIC_PLAYER_HEALTH = health;
                LOGIC_PLAYER_ARMOR = armor;
                LOGIC_PLAYER_CLIP_AMMO = weapon.clip_display();
                LOGIC_PLAYER_RESERVE_AMMO = weapon.reserve_display();
            }
            #[cfg(feature = "reference-trace")]
            {
                let trace_train = tram_pos_ext(
                    &m,
                    tram_seg,
                    tram_seg_dist,
                    tram_pre_from,
                    tram_pre_total,
                    tram_pre_left,
                );
                unsafe {
                    trace_sim_tick(
                        &m,
                        reference_trace::TickState {
                            map_tick: sim_frame_no,
                            player_pos: player.pos,
                            player_vel: player.vel,
                            yaw,
                            pitch,
                            health,
                            armor,
                            weapon: weapon.current as u8,
                            owned: weapon.owned,
                            clip: weapon.clip_display(),
                            reserve: weapon.reserve_display(),
                            on_ground: player.on_ground,
                            ground_mover: player.ground_mover as i32,
                            train_pos: trace_train,
                            train_yaw: tram_yaw_render,
                            train_seg: tram_seg.min(u16::MAX as usize) as u16,
                            train_dist: tram_seg_dist,
                            train_speed: tram_speed,
                            train_active: tram_active,
                            train_attached: tram_player_attached,
                            train_pre_left: tram_pre_left,
                        },
                    );
                }
            }
            if health == 0 && death_ticks == 0 {
                death_ticks = DEATH_TICKS; // enemies killed the player -> start the death window
                unsafe { CHANGE_REQUEST_ACTIVE = 0 };
            }
            telemetry::counter(
                telemetry::counter::ROOM_CAMERA_GLOBAL_X_BIASED,
                (eye[0] + 32768).max(0) as u32,
            );
            telemetry::counter(
                telemetry::counter::ROOM_CAMERA_GLOBAL_Y_BIASED,
                (eye[1] + 32768).max(0) as u32,
            );
            telemetry::counter(
                telemetry::counter::ROOM_CAMERA_GLOBAL_Z_BIASED,
                (eye[2] + 32768).max(0) as u32,
            );
            telemetry::counter(telemetry::counter::ROOM_PLAYER_VIEW_YAW_Q12, yaw as u32);

            telemetry::stage_end(telemetry::stage::UPDATE);
            telemetry::counter(telemetry::counter::SIM_TICKS, 1);
            telemetry::counter(telemetry::counter::VISUAL_INTERVAL_VBLANKS, SIM_VBLANKS);
            telemetry::task_end(telemetry::task::FIXED_UPDATE);

            unsafe {
                if restart_requested {
                    sfx::charger_stop();
                    return PlayExit::Restart(launch);
                }
                if TRAINING_COMPLETE_REQUEST {
                    sfx::charger_stop();
                    return PlayExit::BackToMenu;
                }
                if CHANGE_REQUEST_ACTIVE != 0 {
                    // Snapshot the post-physics trigger tick before either the
                    // player or a moving global pusher advances again.
                    if let Some(next) = tick_pending_changelevel(
                        &m,
                        nlogic,
                        &player,
                        yaw,
                        pitch,
                        health,
                        suit_equipped,
                        armor,
                        &weapon,
                        tram_player_attached,
                        tram_active,
                    ) {
                        sfx::charger_stop();
                        if settings::autosave_enabled() {
                            // Opt-in autosave at the level change. The
                            // destination map is what the player wants to
                            // resume from, so stamp the checkpoint with it
                            // rather than the map being left.
                            let mut cp = LIVE_CHECKPOINT;
                            cp.room_id = next.room_id;
                            cp.has_pos = false; // arrive at the destination's own spawn
                            cp.health = health.max(1);
                            cp.armor = armor;
                            cp.suit = suit_equipped;
                            let _ = save_with_badge(
                                fb,
                                save::Target {
                                    port: save::Port::One,
                                    slot: save::Slot::Auto,
                                },
                                &cp,
                            );
                        }
                        return PlayExit::ChangeLevel(next);
                    }
                }
            }
            telemetry_frame = telemetry_frame.wrapping_add(1);
            sim_frame_no = sim_frame_no.wrapping_add(1);
            ticks_this_visual = ticks_this_visual.saturating_add(1);
            next_sim_vblank = next_sim_vblank.wrapping_add(SIM_VBLANKS);
            #[cfg(feature = "decoupled-present")]
            unsafe {
                tick_camera_snapshot(player.pos, view_h_cur, yaw, pitch);
                tick_tram_snapshot(ride_off, tram_yaw_render);
            }
        }
        if ticks_this_visual > 1 {
            telemetry::counter(
                telemetry::counter::VISUAL_SKIPPED_VBLANKS,
                ticks_this_visual.saturating_sub(1) as u32,
            );
        }

        if DBG_CAM {
            player.pos = DBG_CAM_POS;
            yaw = DBG_CAM_YAW;
            pitch = DBG_CAM_PITCH;
        }
        // Build-time pose pin (HLPSX_DBG_CAM="x y z yaw pitch", raw runtime
        // units = the debug-stats pose lines): reproduce a real-hardware
        // capture's exact view for emulator/hardware differential shots.
        if let Some((dbg_pos, dbg_yaw, dbg_pitch)) = reference_checkpoint::DBG_CAM_OVERRIDE {
            player.pos = dbg_pos;
            yaw = dbg_yaw;
            pitch = dbg_pitch;
            settings::debug_force(settings::DEBUG_STATS);
        }
        // Decoupled presentation samples the view between the last two ticks:
        // phase 0 right after a tick (previous pose), sweeping into the current
        // pose as the next tick's deadline approaches. Simulation state is
        // untouched; only what the camera looks like this frame changes.
        #[cfg(feature = "decoupled-present")]
        let render_phase_q12: i32 = {
            let ahead = next_sim_vblank.wrapping_sub(interrupts::vblank_count()) as i32;
            if ahead <= 0 {
                4096
            } else {
                ((SIM_VBLANKS as i32 - ahead.min(SIM_VBLANKS as i32)) << 12) / SIM_VBLANKS as i32
            }
        };
        #[cfg(feature = "decoupled-present")]
        let (cam_pos, cam_h, cam_yaw, cam_pitch) =
            if DBG_CAM || reference_checkpoint::DBG_CAM_OVERRIDE.is_some() {
                (player.pos, view_h_cur, yaw, pitch)
            } else {
                let cam = unsafe { interpolated_camera(render_phase_q12) };
                (cam.pos, cam.view_h, cam.yaw, cam.pitch)
            };
        #[cfg(not(feature = "decoupled-present"))]
        let (cam_pos, cam_h, cam_yaw, cam_pitch) = (player.pos, view_h_cur, yaw, pitch);
        // env_shake: jitter the view (yaw/pitch/eye height) by a decaying random
        // amount while a shake is active -- explosions/quakes rattle the camera.
        let (mut eye, mut view_yaw, mut view_pitch) = (
            [cam_pos[0], cam_pos[1] + cam_h, cam_pos[2]],
            cam_yaw,
            cam_pitch,
        );
        // Head-bob: a vertical bob (doubled frequency, like HL) scaled by ground
        // speed, plus a subtle strafe roll -- both derived from BOB_PHASE + the
        // current horizontal velocity so a walking camera breathes instead of
        // gliding on rails.
        let mut view_roll = 0i16;
        unsafe {
            let hspeed = isqrt_i32(player.vel[0] * player.vel[0] + player.vel[2] * player.vel[2]);
            // No bob on a ladder: BOB_PHASE freezes off the ground, but the
            // climb's lateral velocity kept scaling the stale phase into a
            // per-tick eye jiggle. HL suspends the walk bob while climbing.
            let bob_amp = if active_ladder >= 0 {
                0
            } else {
                (hspeed.min(90) * 5) >> 4 // world units of vertical bob
            };
            let bob_sin = Mat3I16::rotate_z(((BOB_PHASE * 2) as u16) & 0xFF).m[1][0] as i32;
            eye[1] += (bob_amp * bob_sin) >> 12;
            // Strafe bank: the perpendicular (right) component of velocity tilts
            // the horizon a few degrees. rot.m[0] would be circular, so derive the
            // world right vector straight from the yaw.
            let right = Mat3I16::rotate_y(0u16.wrapping_sub(cam_yaw >> 4));
            let side =
                (right.m[0][0] as i32 * player.vel[0] + right.m[0][2] as i32 * player.vel[2]) >> 12;
            view_roll = (side / 12).clamp(-4, 4) as i16;
            // View punch (recoil / landing / damage), decaying via tick_screen_fx.
            view_pitch =
                (view_pitch as i32 + PUNCH_PITCH).clamp(-PITCH_MAX as i32, PITCH_MAX as i32) as i16;
            view_yaw = ((view_yaw as i32 + PUNCH_YAW) & 0xFFF) as u16;
            if SHAKE_TICKS > 0 {
                let amp = SHAKE_AMP as i32 * SHAKE_TICKS as i32 / SHAKE_DUR.max(1) as i32;
                // Presented-frame randomness must not advance the simulation's
                // RNG once render count decouples from tick count.
                #[cfg(feature = "decoupled-present")]
                let j = |m: i32| (VIEW_RNG.next() as i32 % (2 * m + 1)) - m;
                #[cfg(not(feature = "decoupled-present"))]
                let j = |m: i32| (IMPACT_RNG.below((2 * m + 1) as u32) as i32) - m;
                view_yaw = ((view_yaw as i32 + j(amp * 6)) & 0xFFF) as u16;
                view_pitch = (view_pitch as i32 + j(amp * 6))
                    .clamp(-PITCH_MAX as i32, PITCH_MAX as i32) as i16;
                eye[1] += j(amp);
            }
        }
        let eye = eye;
        let projection_h = if zoom_aim { CROSSBOW_PROJ_H } else { H_PROJ };
        scene::set_projection_plane(projection_h);
        unsafe { render::set_projection_h(projection_h as i32) };
        let rot = view_rotation_roll(view_yaw, view_pitch, view_roll);
        scene::load_rotation(&rot);
        let base_t = [
            -dot12(rot.m[0], eye),
            -dot12(rot.m[1], eye),
            -dot12(rot.m[2], eye),
        ];
        scene::load_translation(Vec3I32::new(base_t[0], base_t[1], base_t[2]));
        unsafe { set_view_fix(&rot, base_t) };

        // Drain queued explosions: project each and spawn a big bright burst
        // (weapon blasts + scripted env_explosion; they had no visual before).
        unsafe {
            for i in 0..PENDING_EXPLO_N {
                if let Some((sx, sy, _)) = project_world_point(PENDING_EXPLO[i], &rot, base_t) {
                    let cnt = (PENDING_EXPLO_MAG[i] as usize / 5).clamp(14, 44);
                    #[cfg(feature = "decoupled-present")]
                    let rng = core::ptr::addr_of_mut!(VIEW_RNG);
                    #[cfg(not(feature = "decoupled-present"))]
                    let rng = core::ptr::addr_of_mut!(IMPACT_RNG);
                    IMPACT_PARTICLES.spawn_burst(&mut *rng, (sx, sy), (250, 170, 40), cnt, 96, 20);
                }
            }
            PENDING_EXPLO_N = 0;
        }

        frame_no = frame_no.wrapping_add(1);
        if frame_no == 0 {
            frame_no = 1; // sway/anim phase counter; the proj cache has its own token
        }
        let proj_token =
            unsafe { world_projection_token(launch.room_id, projection_h, &rot, base_t) };
        telemetry::task_begin(telemetry::task::VISUAL_RENDER);
        telemetry::stage_begin(telemetry::stage::RENDER);

        // A deferred present means the previous frame's channel-2 walk can
        // still be reading the ordering tables and packet arenas this build
        // is about to rebuild -- and the pre-decoupling late-frame deferral
        // carried the same latent race, which is a credible source of the
        // intermittent black geometry seen on real hardware. Fence the WALK
        // only (submit_linked_list_wait), not the raster: rasterisation keeps
        // overlapping the whole build, while the chain storage becomes safely
        // ours again. When the walk already drained this is one register
        // read.
        gpu::submit_linked_list_wait();
        // Queue the previous frame's display flip NOW and let the VBlank
        // handler apply it exactly at the next blank edge, so the whole CPU
        // build below overlaps what used to be a blocking edge spin (the
        // ride profile measured that spin at ~12% of moving frames). The
        // draw side switches immediately -- nothing touches the framebuffer
        // until the gated clear -- and the raster of the finished buffer is
        // fenced by draw_sync first. In-target the raster has already
        // drained; a real-hardware build pays the sync here by design until
        // the decoupled path settles its GPU bill.
        // No CPU-side draw_sync here: syncing at build start measured 14.8%
        // of moving frames (it serialises against the previous frame's
        // charged fill/walk time that the old late placement overlapped).
        // The VBlank handler applies the flip only when GPUSTAT reports the
        // GPU idle, so a busy raster just retries at the next edge.
        #[cfg(feature = "decoupled-present")]
        if present_pending {
            telemetry::stage_begin(telemetry::stage::PRESENT);
            interrupts::queue_gp1_at_vblank(fb.begin_deferred_swap());
            telemetry::stage_end(telemetry::stage::PRESENT);
            present_pending = false;
            flip_queued = true;
        }
        unsafe {
            OT.clear();
            HUD_OT.clear();
            FX_OT.clear();
            update_flashlight_reach(&m, eye, &rot);
            XHAIR = EMPTY_XHAIR; // DEBUG: reset crosshair-tri pick for this frame
                                 // Disc streaming borrows this arena for its WORLD.PAK table while
                                 // no GPU packets exist. From here onward the table is invalid and
                                 // the next stream (weapon switch/changelevel/menu) rebuilds it.
            cdstream::invalidate_cache();
            // Advance the 10 Hz animated-texture clock (blinking screens,
            // scanner chains) and start the frame on the frame-0 display row.
            tex_anim_tick(&m);
            map::tex_anim_select(false);
            #[cfg(any(feature = "emulator-telemetry", feature = "performance-telemetry"))]
            {
                RENDER_PACKET_DROPS = 0;
                MODEL_PACKET_DROPS = 0;
            }
            let mut packets = PrimitivePacketArena::new(&mut PRIMITIVE_PACKETS);
            let mut np = 0usize;
            let mut nq = 0usize;
            let mut world_cache_action = WORLD_CACHE_NONE;
            let mut world_cache_key = WorldPacketCacheKey::EMPTY;
            let mut brush_cache_hit = false;
            let mut world_cache_emit_calls = 0u32;
            let room_affine_split_tris: u32;
            reset_world_affine_frame();

            // World (model 0): PVS-visible faces cached by leaf. Runtime does
            // one backface test per cooked plane group, cheap face-bounds
            // rejection, then emits triangle fans with PS1 quad pairing.
            telemetry::stage_begin(telemetry::stage::ROOM);
            let train_hint = tram_pos_ext(
                &m,
                tram_seg,
                tram_seg_dist,
                tram_pre_from,
                tram_pre_total,
                tram_pre_left,
            );
            let mut cam_leaf = recover_camera_leaf(&m, eye, player.pos, train_hint);
            let mut have_pvs = valid_pvs_leaf(&m, cam_leaf);
            let render_eye_under =
                PLAYER_EYE_UNDER || (have_pvs && m.leaf_liquid(cam_leaf as usize) != 0);
            EMIT_EYE_UNDER_LIQUID = render_eye_under;
            let mut reused_last_pvs = false;
            // The shared leaf only carries invalidation from simulation. The
            // render-owned key remains local across frames and is updated only
            // after a successful rebuild.
            if pvs_cam_leaf_load() < 0 {
                render_pvs_leaf = -1;
                render_pvs_visofs = -1;
            }
            let cached_pvs_leaf = render_pvs_leaf;
            if !have_pvs && valid_pvs_leaf(&m, cached_pvs_leaf) {
                cam_leaf = cached_pvs_leaf;
                have_pvs = true;
                reused_last_pvs = true;
            }
            let visibility = CameraVisibility {
                rot: &rot,
                base_t,
                have_pvs,
            };
            if have_pvs {
                let mut pvs_rebuilt = false;
                if !reused_last_pvs
                    && (cached_pvs_leaf != cam_leaf || render_pvs_underwater != render_eye_under)
                {
                    // Compilers deduplicate identical vis rows, so adjacent
                    // leaves frequently share one. A leaf change whose row
                    // offset matches the built PVS (dry both sides -- the
                    // underwater merge also depends on the eye) derives the
                    // exact same visible set, marks, and plan: skip the whole
                    // rebuild and just move the bookkeeping to the new leaf.
                    let same_row = cached_pvs_leaf >= 0
                        && !render_pvs_underwater
                        && !render_eye_under
                        && render_pvs_visofs >= 0
                        && m.leaf(cam_leaf as usize).0 == render_pvs_visofs;
                    if same_row {
                        render_pvs_leaf = cam_leaf;
                    } else {
                        telemetry::stage_begin(telemetry::stage::ROOM_VISIBLE_LIST);
                        rebuild_pvs_cache(&m, cam_leaf, nents, eye, render_eye_under);
                        pvs_rebuilt = true;
                        telemetry::stage_end(telemetry::stage::ROOM_VISIBLE_LIST);
                        render_pvs_leaf = cam_leaf;
                        render_pvs_visofs = if render_eye_under {
                            -1
                        } else {
                            m.leaf(cam_leaf as usize).0
                        };
                        render_pvs_underwater = render_eye_under;
                        // Start a new leaf with the normal single pass. An observed
                        // overflow arms near-first banding for the following frame;
                        // pre-arming every leaf made ordinary movement reproject the
                        // complete room up to eight times even when the arena fit.
                    }
                }
                // The camera PVS may be unchanged while a brush crosses one of
                // its portals. Refresh only moving candidates from their live
                // bounds; static entity membership remains camera-leaf cached.
                refresh_live_entity_pvs(&m, pvs_rebuilt);

                // Presentation happens just before `fb.clear` (see below): the entire
                // world build is framebuffer-independent, so it all hides the
                // previous frame's raster.
                let mut room_counts = WorldCounters::new();
                room_counts.cells_considered = PVS_LEAF_COUNT as u32;
                room_counts.cells_drawn = PVS_LEAF_COUNT as u32;
                room_counts.surfaces_considered = PVS_FACE_COUNT as u32;
                telemetry::stage_begin(telemetry::stage::ROOM_SURFACE_DRAW);
                // Front-to-back banded emit: when a view exposes more geometry
                // than the packet arena can hold (huge open rooms), process near
                // faces first so the arena fills with close geometry and only the
                // farthest faces drop -- the wall in front of you always draws,
                // never a black hole up close. Normal views run a single pass.
                const N_DEPTH_BANDS: i32 = 8;
                const DEPTH_BAND_SHIFT: u32 = 8; // 256 world units per band
                                                 // Band only when the arena would overflow; otherwise one pass (the
                                                 // common case, no cost). On overflow use just enough bands to span
                                                 // FAR_VIEW -- no empty re-walks past the view distance, and if a band
                                                 // is wider than FAR_VIEW this collapses to 1 on its own. Emitting near
                                                 // bands first means an overflowing arena drops the FARTHEST faces, not
                                                 // the floor under your feet (which is what an unbanded late-group emit
                                                 // would drop -- the missing-near-geometry bug this fixes).
                                                 // Liquid sway phase for this frame; blend state starts opaque.
                                                 // Decoupled presentation animates sway at simulation rate so
                                                 // water speed no longer scales with presented frame rate.
                #[cfg(feature = "decoupled-present")]
                let wi = ((sim_frame_no >> 3) & 15) as usize;
                #[cfg(not(feature = "decoupled-present"))]
                let wi = ((frame_no >> 3) & 15) as usize;
                WAVE_DU = WAVE_TAB[wi] as u8;
                WAVE_DV = WAVE_TAB[(wi + 4) & 15] as u8;
                reset_emit_policy();

                let cell_path_active = false;
                // The cold PVS builder preclassifies ordinary static opaque
                // faces. Keep their shared zero policy/light context resident
                // across the stream instead of resetting and re-probing sparse
                // lightstyle metadata at every face boundary.
                let mut opaque_stream_ready = true;
                let use_bands = WORLD_BAND_STATE & WORLD_BAND_NEEDS != 0;
                WORLD_BAND_STATE &= WORLD_BAND_NEEDS; // clear prior overflow bit
                let nbands = if use_bands {
                    ((FAR_VIEW >> DEPTH_BAND_SHIFT) + 1).min(N_DEPTH_BANDS)
                } else {
                    1
                };
                // Pre-pass, once per frame: each group's backface verdict.
                // In multi-band (overflow) mode, faces of visible groups are
                // counting-sorted into near-to-far order here.
                let bucketed = nbands > 1 && PVS_FACE_COUNT <= PVS_BAND_CAP;
                world_cache_key = WorldPacketCacheKey {
                    leaf: cam_leaf,
                    projection_h: projection_h as u16,
                    flashlight_state: if FLASHLIGHT_ON {
                        FLASHLIGHT_REACH.max(1)
                    } else {
                        0
                    },
                    // Filled below only after this exact camera view repeats.
                    // A moving view cannot hit or build the packet cache, so
                    // hashing every visible brush here was pure per-frame work.
                    static_brush_state: 0,
                    rot: rot.m,
                    base_t,
                    eye,
                    // Phase-dependent payloads rebuild only when their coarse
                    // animation step changes. Cached packets remain immutable
                    // while either framebuffer may still be consuming them.
                    wave_du: if PVS_HAS_TRANSLUCENT { WAVE_DU } else { 0 },
                    wave_dv: if PVS_HAS_TRANSLUCENT { WAVE_DV } else { 0 },
                    tex_anim: if PVS_HAS_TEXANIM { PVS_TEX_ANIM_GEN } else { 0 },
                    // Affine dense-view policy deliberately stays out of this
                    // key. Camera movement already changes the transform and
                    // receives the current bounded policy; invalidating an
                    // exact stationary cache when cooldown changes creates a
                    // rebuild/missed-deadline feedback loop.
                    band_mode: nbands as u8
                        | ((bucketed as u8) << 4)
                        | ((use_bands as u8) << 5)
                        | ((render_eye_under as u8) << 6),
                    affine_generation: WORLD_AFFINE_EDGE_GENERATION,
                };
                // Hash mutable brush state only when an existing cache or an
                // armed candidate has the same exact camera. A newly seen view
                // is recorded with the zero sentinel; if it repeats, the real
                // state becomes the candidate key, and a third stable frame
                // builds it. This trades one extra uncached stationary frame
                // for removing the full entity/hash walk during normal motion.
                let brush_state_needed = (WORLD_CACHE_VALID
                    && WORLD_CACHE_KEY.same_view(&world_cache_key))
                    || (WORLD_CACHE_CANDIDATE_STATE == WORLD_CACHE_CANDIDATE_ARMED
                        && WORLD_CACHE_CANDIDATE_KEY.same_view(&world_cache_key));
                if brush_state_needed {
                    world_cache_key.static_brush_state = static_brush_state(have_pvs, nents);
                }
                ROOM_PROJECTED_COUNT = 0;
                telemetry::stage_begin(telemetry::stage::ROOM_DEPTH_PREP);
                world_cache_action = prepare_world_packet_cache(
                    world_cache_key,
                    if bucketed { PVS_FACE_COUNT } else { 0 },
                );
                telemetry::stage_end(telemetry::stage::ROOM_DEPTH_PREP);
                let mut room_cache_hit = if world_cache_action == WORLD_CACHE_HIT
                    || world_cache_action == WORLD_CACHE_BRUSH_REBUILD
                {
                    telemetry::stage_begin(telemetry::stage::ROOM_PROJECT);
                    let room_only = world_cache_action == WORLD_CACHE_BRUSH_REBUILD;
                    let hit = replay_world_packet_cache(
                        &mut packets,
                        &mut np,
                        &mut nq,
                        &mut room_counts,
                        if room_only {
                            WORLD_CACHE_ROOM_COUNT as usize
                        } else {
                            WORLD_CACHE_COUNT
                        },
                        if room_only {
                            WORLD_CACHE_ROOM_NP as usize
                        } else {
                            WORLD_CACHE_NP as usize
                        },
                        if room_only {
                            WORLD_CACHE_ROOM_NQ as usize
                        } else {
                            WORLD_CACHE_NQ as usize
                        },
                    );
                    telemetry::stage_end(telemetry::stage::ROOM_PROJECT);
                    hit
                } else {
                    false
                };
                if !room_cache_hit
                    && (world_cache_action == WORLD_CACHE_HIT
                        || world_cache_action == WORLD_CACHE_BRUSH_REBUILD)
                {
                    world_cache_action = WORLD_CACHE_NONE;
                }
                brush_cache_hit = room_cache_hit && world_cache_action == WORLD_CACHE_HIT;

                if !room_cache_hit {
                    prepare_world_affine_candidates(&visibility, frame_no as u16);
                    if use_bands && WORLD_CLASSIC_AFFINE_SELECTION {
                        WORLD_AFFINE_EXTRA_BUDGET_LEFT =
                            WORLD_AFFINE_EXTRA_BUDGET_LEFT.min(WORLD_CLASSIC_BANDED_EXTRA_PACKETS);
                    }
                }
                telemetry::stage_begin(telemetry::stage::ROOM_CELL_SELECT);
                if !room_cache_hit && bucketed {
                    for c in PVS_BAND_START.iter_mut() {
                        *c = 0;
                    }
                }
                let group_passes = if room_cache_hit { 0 } else { PVS_GROUP_COUNT };
                let group_vis = group_vis_bits();
                for gi in 0..group_passes {
                    let group = PVS_GROUP_ACTIVE[gi] as usize;
                    let (plane_n, plane_d) = m.cooked_group_plane(group);
                    let vis = dot_plane(plane_n, eye) > plane_d
                        || (render_eye_under && PVS_GROUP_FACE[group] & PVS_GROUP_LIQUID != 0);
                    scratch_bit_assign(group_vis, gi, vis);
                    if vis && nbands > 1 {
                        let mut entry = PVS_GROUP_FIRST[group];
                        while entry != PVS_LINK_END {
                            let e = entry as usize;
                            entry = PVS_FACE_NEXT.0[e];
                            if !bucketed && e < MAX_PVS_FACE_RECS {
                                // Non-bucketed overflow view: just refresh the
                                // cached band for the link-walk emit below.
                                let rec = &mut PVS_FACE_REC.0[e];
                                let c = [
                                    rec.center[0] as i32,
                                    rec.center[1] as i32,
                                    rec.center[2] as i32,
                                ];
                                let depth = (dot12(rot.m[2], c) + base_t[2]).max(0);
                                rec.set_band(((depth >> DEPTH_BAND_SHIFT).min(nbands - 1)) as u8);
                                continue;
                            }
                            if !bucketed {
                                continue;
                            }
                            let band = if e < MAX_PVS_FACE_RECS {
                                let rec = &mut PVS_FACE_REC.0[e];
                                let c = [
                                    rec.center[0] as i32,
                                    rec.center[1] as i32,
                                    rec.center[2] as i32,
                                ];
                                let depth = (dot12(rot.m[2], c) + base_t[2]).max(0);
                                let band = ((depth >> DEPTH_BAND_SHIFT).min(nbands - 1)) as u8;
                                rec.set_band(band);
                                band
                            } else {
                                let face = PVS_FACE_INDEX.0[e] as usize;
                                let (bc, _) = m.face_bounds(face);
                                let depth = (dot12(rot.m[2], bc) + base_t[2]).max(0);
                                ((depth >> DEPTH_BAND_SHIFT).min(nbands - 1)) as u8
                            };
                            let kind = pvs_entry_kind(e);
                            // Store each bucket count one slot after its start.
                            // The previous `(band + 1) * kinds + kind` layout
                            // gave all three kinds in band zero the same start,
                            // so scattering overwrote earlier kinds and could
                            // silently discard world geometry.
                            let bucket = band as usize * PVS_BAND_KINDS + kind;
                            PVS_BAND_START[bucket + 1] += 1;
                        }
                    }
                }
                if !room_cache_hit && bucketed {
                    // Prefix-sum the counts, then scatter (second link walk).
                    let mut acc = 0u16;
                    let slots = nbands as usize * PVS_BAND_KINDS + 1;
                    for k in 0..slots {
                        acc += PVS_BAND_START[k];
                        PVS_BAND_START[k] = acc;
                    }
                    let mut cursor = [0u16; 10 * PVS_BAND_KINDS];
                    cursor[..slots].copy_from_slice(&PVS_BAND_START[..slots]);
                    for gi in 0..PVS_GROUP_COUNT {
                        if !scratch_bit(group_vis, gi) {
                            continue;
                        }
                        let group = PVS_GROUP_ACTIVE[gi] as usize;
                        let mut entry = PVS_GROUP_FIRST[group];
                        while entry != PVS_LINK_END {
                            let e = entry as usize;
                            entry = PVS_FACE_NEXT.0[e];
                            let band = if e < MAX_PVS_FACE_RECS {
                                PVS_FACE_REC.0[e].band() as usize
                            } else {
                                let face = PVS_FACE_INDEX.0[e] as usize;
                                let (bc, _) = m.face_bounds(face);
                                let depth = (dot12(rot.m[2], bc) + base_t[2]).max(0);
                                (depth >> DEPTH_BAND_SHIFT).min(nbands - 1) as usize
                            };
                            let ci = band * PVS_BAND_KINDS + pvs_entry_kind(e);
                            let slot = cursor[ci] as usize;
                            if slot < PVS_BAND_CAP {
                                PVS_BAND_ORDER[slot] = e as u16;
                                cursor[ci] += 1;
                            }
                        }
                    }
                }
                telemetry::stage_end(telemetry::stage::ROOM_CELL_SELECT);
                telemetry::stage_begin(telemetry::stage::ROOM_PROJECT);

                let mut band = if room_cache_hit { nbands } else { 0 };
                while band < nbands {
                    for gi in 0..PVS_GROUP_COUNT {
                        if bucketed {
                            break; // bucketed path below handles multi-band
                        }
                        if !scratch_bit(group_vis, gi) {
                            continue;
                        }
                        let group = PVS_GROUP_ACTIVE[gi] as usize;
                        let mut entry = PVS_GROUP_FIRST[group];
                        while entry != PVS_LINK_END {
                            let e = entry as usize;
                            entry = PVS_FACE_NEXT.0[e];
                            if e < MAX_PVS_FACE_RECS {
                                let rec = PVS_FACE_REC.0[e];
                                if nbands > 1 && rec.band() as i32 != band {
                                    continue;
                                }
                                let face = PVS_FACE_INDEX.0[e] as usize;

                                if !WORLD_BOUNDS_CULL
                                    || visibility.world_sphere_gte(rec.center, rec.radius as i32)
                                {
                                    if !WORLD_OPAQUE_STREAM_FAST || rec.special() {
                                        set_emit_cached_face(&m, face, rec);
                                        opaque_stream_ready = false;
                                    } else if !opaque_stream_ready {
                                        reset_emit_policy();
                                        opaque_stream_ready = true;
                                    }
                                    if rec.is_patch() {
                                        emit_world_face_patches(
                                            &mut packets,
                                            &m,
                                            rec.tex as usize,
                                            rec.first as usize,
                                            rec.count(),
                                            rec.refined_topology(),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    } else if rec.is_loop() {
                                        emit_world_face_loop(
                                            &mut packets,
                                            &m,
                                            rec.tex as usize,
                                            rec.first as usize,
                                            rec.count(),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    } else {
                                        emit_world_face_tris(
                                            &mut packets,
                                            &m,
                                            rec.first as usize,
                                            rec.count(),
                                            rec.refined_topology(),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    }
                                }
                            } else {
                                let face = PVS_FACE_INDEX.0[e] as usize;

                                let (bc, be) = m.face_bounds(face);
                                let depth = (dot12(rot.m[2], bc) + base_t[2]).max(0);
                                if (depth >> DEPTH_BAND_SHIFT).min(nbands - 1) != band {
                                    continue;
                                }
                                if !WORLD_BOUNDS_CULL || visibility.sphere(bc, be) {
                                    let (first, cnt) = m.face_tris(face);
                                    if !WORLD_OPAQUE_STREAM_FAST
                                        || face_needs_generic_emit(&m, face)
                                    {
                                        set_emit_face(&m, face, 0);
                                        opaque_stream_ready = false;
                                    } else if !opaque_stream_ready {
                                        reset_emit_policy();
                                        opaque_stream_ready = true;
                                    }
                                    if m.face_is_patch(face) {
                                        emit_world_face_patches(
                                            &mut packets,
                                            &m,
                                            m.face_tex(face),
                                            first,
                                            cnt,
                                            m.face_refined_topology(face),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    } else if m.face_is_loop(face) {
                                        emit_world_face_loop(
                                            &mut packets,
                                            &m,
                                            m.face_tex(face),
                                            first,
                                            cnt,
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    } else {
                                        emit_world_face_tris(
                                            &mut packets,
                                            &m,
                                            first,
                                            cnt,
                                            m.face_refined_topology(face),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    }
                                }
                            }
                        }
                    }
                    if bucketed {
                        // Bucketed multi-band path: one contiguous slice per
                        // band (scattered near-to-far by the pre-pass).
                        let b = band as usize;
                        let start = PVS_BAND_START[b * PVS_BAND_KINDS] as usize;
                        let end = PVS_BAND_START[(b + 1) * PVS_BAND_KINDS] as usize;
                        let mut k = start;
                        while k < end.min(PVS_BAND_CAP) {
                            let e = PVS_BAND_ORDER[k] as usize;
                            k += 1;
                            if e < MAX_PVS_FACE_RECS {
                                let rec = PVS_FACE_REC.0[e];
                                let face = PVS_FACE_INDEX.0[e] as usize;

                                if !WORLD_BOUNDS_CULL
                                    || visibility.world_sphere_gte(rec.center, rec.radius as i32)
                                {
                                    if !WORLD_OPAQUE_STREAM_FAST || rec.special() {
                                        set_emit_cached_face(&m, face, rec);
                                        opaque_stream_ready = false;
                                    } else if !opaque_stream_ready {
                                        reset_emit_policy();
                                        opaque_stream_ready = true;
                                    }
                                    if rec.is_patch() {
                                        emit_world_face_patches(
                                            &mut packets,
                                            &m,
                                            rec.tex as usize,
                                            rec.first as usize,
                                            rec.count(),
                                            rec.refined_topology(),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    } else if rec.is_loop() {
                                        emit_world_face_loop(
                                            &mut packets,
                                            &m,
                                            rec.tex as usize,
                                            rec.first as usize,
                                            rec.count(),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    } else {
                                        emit_world_face_tris(
                                            &mut packets,
                                            &m,
                                            rec.first as usize,
                                            rec.count(),
                                            rec.refined_topology(),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    }
                                }
                            } else {
                                let face = PVS_FACE_INDEX.0[e] as usize;

                                let (bc, be) = m.face_bounds(face);
                                if !WORLD_BOUNDS_CULL || visibility.sphere(bc, be) {
                                    let (first, cnt) = m.face_tris(face);
                                    if !WORLD_OPAQUE_STREAM_FAST
                                        || face_needs_generic_emit(&m, face)
                                    {
                                        set_emit_face(&m, face, 0);
                                        opaque_stream_ready = false;
                                    } else if !opaque_stream_ready {
                                        reset_emit_policy();
                                        opaque_stream_ready = true;
                                    }
                                    if m.face_is_patch(face) {
                                        emit_world_face_patches(
                                            &mut packets,
                                            &m,
                                            m.face_tex(face),
                                            first,
                                            cnt,
                                            m.face_refined_topology(face),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    } else if m.face_is_loop(face) {
                                        emit_world_face_loop(
                                            &mut packets,
                                            &m,
                                            m.face_tex(face),
                                            first,
                                            cnt,
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    } else {
                                        emit_world_face_tris(
                                            &mut packets,
                                            &m,
                                            first,
                                            cnt,
                                            m.face_refined_topology(face),
                                            face,
                                            proj_token,
                                            &mut np,
                                            &mut nq,
                                            &mut room_counts,
                                        );
                                    }
                                }
                            }
                        }
                    }
                    band += 1;
                }
                telemetry::stage_end(telemetry::stage::ROOM_PROJECT);
                reset_emit_policy();
                world_cache_emit_calls = room_counts.emit_calls;
                room_affine_split_tris = WORLD_AFFINE_SPLIT_TRIS;
                if !room_cache_hit {
                    finish_world_affine_candidates();
                }
                affine_finalize_percentiles();
                affine_finalize_remaining_percentiles();
                telemetry::stage_end(telemetry::stage::ROOM_SURFACE_DRAW);

                telemetry::counter(
                    telemetry::counter::ROOM_CELLS_CONSIDERED,
                    room_counts.cells_considered,
                );
                telemetry::counter(
                    telemetry::counter::ROOM_CELLS_DRAWN,
                    room_counts.cells_drawn,
                );
                telemetry::counter(
                    telemetry::counter::ROOM_CELLS_CULLED,
                    room_counts.cells_culled,
                );
                telemetry::counter(
                    telemetry::counter::ROOM_SURFACES_CONSIDERED,
                    room_counts.surfaces_considered,
                );
                telemetry::counter(
                    telemetry::counter::ROOM_SURF_PROFILED,
                    room_counts.emit_calls,
                );
                telemetry::counter(
                    telemetry::counter::ROOM_PROJECTED_VERTICES,
                    ROOM_PROJECTED_COUNT,
                );
                telemetry::counter(telemetry::counter::ROOM_CACHED_DRAWS, room_cache_hit as u32);
                telemetry::counter(
                    telemetry::counter::ROOM_UNCACHED_DRAWS,
                    (!room_cache_hit) as u32,
                );
                telemetry::counter(
                    telemetry::counter::ROOM_VISIBILITY_FALLBACK_DRAWS,
                    if reused_last_pvs { 1 } else { 0 },
                );
            } else {
                let mut room_counts = WorldCounters::new();
                let mut face = 0usize;
                reset_emit_policy();
                ROOM_PROJECTED_COUNT = 0;
                prepare_world_affine_candidates(&visibility, frame_no as u16);
                telemetry::stage_begin(telemetry::stage::ROOM_SURFACE_DRAW);
                while face < m.n_faces {
                    emit_world_face(
                        &mut packets,
                        &m,
                        face,
                        proj_token,
                        eye,
                        &visibility,
                        &mut np,
                        &mut nq,
                        &mut room_counts,
                    );
                    face += 1;
                }
                #[cfg(feature = "seam-census")]
                {
                    SEAM_CENSUS_TINT = 0;
                }
                reset_emit_policy();
                room_affine_split_tris = WORLD_AFFINE_SPLIT_TRIS;
                finish_world_affine_candidates();
                affine_finalize_percentiles();
                affine_finalize_remaining_percentiles();
                telemetry::stage_end(telemetry::stage::ROOM_SURFACE_DRAW);
                telemetry::counter(telemetry::counter::ROOM_CELLS_CONSIDERED, 0);
                telemetry::counter(telemetry::counter::ROOM_CELLS_DRAWN, 0);
                telemetry::counter(telemetry::counter::ROOM_CELLS_CULLED, 0);
                telemetry::counter(
                    telemetry::counter::ROOM_SURFACES_CONSIDERED,
                    room_counts.surfaces_considered,
                );
                telemetry::counter(
                    telemetry::counter::ROOM_SURF_PROFILED,
                    room_counts.emit_calls,
                );
                telemetry::counter(
                    telemetry::counter::ROOM_PROJECTED_VERTICES,
                    ROOM_PROJECTED_COUNT,
                );
                telemetry::counter(telemetry::counter::ROOM_CACHED_DRAWS, 0);
                telemetry::counter(telemetry::counter::ROOM_UNCACHED_DRAWS, 1);
                telemetry::counter(telemetry::counter::ROOM_VISIBILITY_FALLBACK_DRAWS, 1);
            }
            if world_cache_action == WORLD_CACHE_BUILD {
                WORLD_CACHE_ROOM_COUNT = WORLD_CACHE_COUNT.min(u16::MAX as usize) as u16;
                WORLD_CACHE_ROOM_PREFIX_HOLES =
                    WORLD_CACHE_PREFIX_HOLES.min(u16::MAX as usize) as u16;
                WORLD_CACHE_ROOM_NP = np.min(u16::MAX as usize) as u16;
                WORLD_CACHE_ROOM_NQ = nq.min(u16::MAX as usize) as u16;
            }
            // Preserve near-first sorting only where it is demonstrably needed.
            // A small reserve prevents a view hovering at the arena limit from
            // alternating modes; ordinary PVS views avoid two full face walks.
            WORLD_BAND_STATE = if WORLD_BAND_STATE & WORLD_BAND_OVERFLOW != 0
                || packets.remaining() < (MAX_RENDER_PACKETS / 8)
            {
                WORLD_BAND_NEEDS
            } else {
                0
            };
            telemetry::stage_end(telemetry::stage::ROOM);

            telemetry::stage_begin(telemetry::stage::MODEL_INSTANCES);
            let model_prims0 = np;
            let model_quads0 = nq;
            let mut model_draws = 0u32;
            let mut model_bounds_tests = 0u32;
            let mut model_bounds_culled = 0u32;
            let mut model_culled_tris = 0u32;
            let mut model_projected_vertices = 0u32;

            // Brush entities: doors slide open near the player. Each renders with
            // a per-entity GTE translation (base view shifted by the offset);
            // its few tris are projected fresh (not from the world cache).
            telemetry::stage_begin(telemetry::stage::MODEL_BOUNDS);
            // World-aligned static brush faces share signed plane groups. The
            // room pass no longer needs active-list-indexed verdicts, so reuse
            // those scratchpad words as a group-id cache and pay the plane
            // decode/dot product once per static group in this view.
            let group_vis = group_vis_bits();
            let group_seen = group_seen_bits();
            clear_group_bits(group_seen);
            let brush_iter_count = if have_pvs { PVS_ENT_COUNT } else { nents };
            // Cacheable world-aligned brushes must directly follow the room
            // arena prefix. Moving/rotating brushes form the second pass and
            // remain freshly projected, so doors and rotors never freeze.
            SUBMODEL_OCCLUSION_EXTRAS = 160;
            let mut brush_pass = 0u8;
            while brush_pass < 2 {
                for bi in 0..brush_iter_count {
                    let ei = if have_pvs { PVS_ENTS[bi] as usize } else { bi };
                    let e = ENT_CACHE[ei];
                    if have_pvs
                        && !visibility_logic::pvs_visible_now(
                            entity_uses_live_pvs(ei, e),
                            true,
                            live_entity_pvs_visible(ei),
                        )
                    {
                        continue;
                    }
                    let cacheable = static_brush_cacheable(ei, e);
                    if cacheable != (brush_pass == 0) {
                        continue;
                    }
                    if cacheable && brush_cache_hit {
                        // This packet range was relinked with the room prefix.
                        model_draws = model_draws.saturating_add(1);
                        continue;
                    }
                    if ENT_ACTIVE[ei] == 0 || e.blend & 0x80 != 0 {
                        continue;
                    }
                    SUBMODEL_ACTOR_OVERLAP = false;
                    let off = ent_draw_offset(ei);
                    if e.r2 > 0 {
                        model_bounds_tests = model_bounds_tests.saturating_add(1);
                        let radius = ENT_RADIUS[ei];
                        let center = if e.kind == ENT_KIND_PLATROT {
                            platrot_local_to_world(
                                e.center,
                                off,
                                &platrot_rotation(e, ENT_PHASE[ei]),
                            )
                        } else if e.kind == 5 {
                            let rm = fan_rotation(e, fan_angle_q12(ei, sim_frame_no));
                            rotating_local_center(e, rm)
                        } else if e.kind == ENT_KIND_PENDULUM {
                            rotating_local_center(e, pendulum_rotation(e, pendulum_angle_q12(ei)))
                        } else if e.kind == 7 || e.kind == ENT_KIND_ROT_BUTTON {
                            let ang = (((ENT_PHASE[ei] * e.mv[0]) >> 12) as u16) & 0x0fff;
                            let rm = axial_brush_rotation(e, ang);
                            [
                                off[0] + dot12(rm.m[0], e.center),
                                off[1] + dot12(rm.m[1], e.center),
                                off[2] + dot12(rm.m[2], e.center),
                            ]
                        } else {
                            [
                                e.center[0] + off[0],
                                e.center[1] + off[1],
                                e.center[2] + off[2],
                            ]
                        };
                        let visible = if e.kind == 6 {
                            // Liquid brushes can span several rooms; their sphere
                            // almost always intersects the frustum and made every
                            // pool in the PVS walk hundreds of off-screen faces.
                            visibility.box_bounds(center, e.mv)
                        } else {
                            visibility.sphere(center, radius)
                        };
                        if !visible {
                            model_bounds_culled = model_bounds_culled.saturating_add(1);
                            continue;
                        }
                        if !cacheable && e.blend == 0 {
                            SUBMODEL_ACTOR_OVERLAP = brush_touches_actor(center, radius, eye);
                        }
                    }
                    model_draws = model_draws.saturating_add(1);
                    if e.kind == ENT_KIND_PLATROT {
                        emit_platrot_entity(
                            &mut packets,
                            &m,
                            &visibility,
                            e,
                            ENT_PHASE[ei],
                            eye,
                            off,
                            &rot,
                            base_t,
                            &mut np,
                            &mut model_culled_tris,
                        );
                        continue;
                    }
                    // Rotating brushes (fans kind 5, swinging doors kind 7 and
                    // pendulums kind 10) have entity-local vertices and draw at
                    // pivot + rotation*vertex.
                    // Targeted fans retain their integrated phase; cosmetic fans
                    // derive it from the map tick. Doors use their state phase.
                    if e.kind == 5
                        || e.kind == 7
                        || e.kind == ENT_KIND_ROT_BUTTON
                        || e.kind == ENT_KIND_PENDULUM
                    {
                        let ang = if e.kind == 5 {
                            fan_angle_q12(ei, sim_frame_no)
                        } else if e.kind == ENT_KIND_PENDULUM {
                            pendulum_angle_q12(ei)
                        } else if e.kind == 7 || e.kind == ENT_KIND_ROT_BUTTON {
                            (((ENT_PHASE[ei] * e.mv[0]) >> 12) as u16) & 0xFFF
                        } else {
                            0
                        };
                        let local_rotation = if e.kind == 5 {
                            fan_rotation(e, ang)
                        } else if e.kind == ENT_KIND_PENDULUM {
                            pendulum_rotation(e, ang)
                        } else {
                            axial_brush_rotation(e, ang)
                        };
                        let mr = rot.mul(&local_rotation);
                        scene::load_rotation(&mr);
                        // ent_draw_offset is the authored origin for rotating
                        // doors and the live path pivot for an axial train.
                        let o = off;
                        let ome = [o[0] - eye[0], o[1] - eye[1], o[2] - eye[2]];
                        let et = [
                            dot12(rot.m[0], ome),
                            dot12(rot.m[1], ome),
                            dot12(rot.m[2], ome),
                        ];
                        scene::load_translation(Vec3I32::new(et[0], et[1], et[2]));
                        set_view_fix(&mr, et);
                        let submodel_token = next_proj_token();
                        let (ff, nf) = m.submodel(e.submodel);
                        reset_emit_policy();
                        for f in ff..ff + nf {
                            set_emit_face(&m, f, visibility_logic::brush_packet_blend(e.blend));
                            let (first, cnt) = m.face_tris(f);
                            emit_submodel_face(
                                &mut packets,
                                &m,
                                f,
                                first,
                                cnt,
                                submodel_token,
                                &mut np,
                            );
                        }
                        reset_emit_policy();
                        scene::load_rotation(&rot); // restore the world transform
                        set_view_fix(&rot, et); // mirror registers (translation still ent's)
                        continue;
                    }
                    let translated_train = ENT_TRAIN_SLOT[ei] != 0xFF;
                    if !translated_train
                        && e.kind != 1
                        && e.kind != 3
                        && e.kind != ENT_KIND_PUSHABLE
                    {
                        // Statics draw at the world transform via the world proj
                        // token. RELOAD it: the GTE translation register still
                        // holds the previous entity's offset (a mid-open door),
                        // which displaced every vert first-projected here -- the
                        // "charger/grate rides the door" bug.
                        scene::load_translation(Vec3I32::new(base_t[0], base_t[1], base_t[2]));
                        set_view_fix(&rot, base_t);
                        // func_wall frame state (CFuncWall::Use toggles it via
                        // LOGIC_WALL_FRAME): nonzero swaps the brush's chain-
                        // member textures to the alternate row -- the retinal
                        // scanner's dark +a frame vs the animated +0/+1 scan.
                        // ENT_PHASE is otherwise unused for kind-0/2 statics.
                        let alt_tex = (e.kind == 0 || e.kind == 2) && ENT_PHASE[ei] != 0;
                        map::tex_anim_select(alt_tex);
                        let mut static_counts = WorldCounters::new();
                        let (ff, nf) = m.submodel(e.submodel);
                        for f in ff..ff + nf {
                            if e.kind == 6 {
                                let (fnrm, _) = m.face_plane(f);
                                if fnrm[1] < (map::PLANE_NORMAL_ONE / 2) as i16 {
                                    // Pool side/bottom walls are embedded in opaque
                                    // world brushes. Only the upward surface is ever
                                    // exposed; retaining it two-sided also makes the
                                    // waterline visible correctly from underwater.
                                    continue;
                                }
                            } else {
                                let group = m.face_group(f);
                                if !scratch_bit(group_seen, group) {
                                    scratch_bit_assign(group_seen, group, true);
                                    let (fnrm, fd) = m.cooked_group_plane(group);
                                    scratch_bit_assign(group_vis, group, dot_plane(fnrm, eye) > fd);
                                }
                                if !scratch_bit(group_vis, group) {
                                    let (_, cnt) = m.face_tris(f);
                                    model_culled_tris =
                                        model_culled_tris.saturating_add(cnt as u32);
                                    continue;
                                }
                            }
                            let (bc, be) = m.face_bounds(f);
                            if WORLD_BOUNDS_CULL
                                && !visibility.world_sphere_gte(
                                    [bc[0] as i16, bc[1] as i16, bc[2] as i16],
                                    be,
                                )
                            {
                                continue;
                            }
                            let (first, cnt) = m.face_tris(f);
                            // Glass/glow entities blend; liquid faces also sway.
                            set_emit_face(&m, f, visibility_logic::brush_packet_blend(e.blend));
                            if m.face_is_loop(f) {
                                emit_world_face_loop(
                                    &mut packets,
                                    &m,
                                    m.face_tex(f),
                                    first,
                                    cnt,
                                    f,
                                    proj_token,
                                    &mut np,
                                    &mut nq,
                                    &mut static_counts,
                                );
                            } else {
                                emit_world_face_tris(
                                    &mut packets,
                                    &m,
                                    first,
                                    cnt,
                                    m.face_refined_topology(f),
                                    f,
                                    proj_token,
                                    &mut np,
                                    &mut nq,
                                    &mut static_counts,
                                );
                            }
                        }
                        reset_emit_policy();
                        map::tex_anim_select(false);
                        continue;
                    }
                    let es = [eye[0] - off[0], eye[1] - off[1], eye[2] - off[2]];
                    let et = [
                        -dot12(rot.m[0], es),
                        -dot12(rot.m[1], es),
                        -dot12(rot.m[2], es),
                    ];
                    scene::load_translation(Vec3I32::new(et[0], et[1], et[2]));
                    set_view_fix(&rot, et);
                    let submodel_token = next_proj_token();
                    let (ff, nf) = m.submodel(e.submodel);
                    reset_emit_policy();
                    // GoldSrc buttons flip to their alternate texture chain
                    // while pressed (ButtonActivate sets pev->frame = 1); a
                    // kind-3 button's ENT_PHASE is nonzero exactly then.
                    let alt_tex = e.kind == 3 && ENT_PHASE[ei] != 0;
                    map::tex_anim_select(alt_tex);
                    for f in ff..ff + nf {
                        set_emit_face(&m, f, visibility_logic::brush_packet_blend(e.blend));
                        let (first, cnt) = m.face_tris(f);
                        let (fnrm, fd) = m.face_plane(f);
                        if dot_plane(fnrm, es) <= fd {
                            model_culled_tris = model_culled_tris.saturating_add(cnt as u32);
                            continue;
                        }
                        let (bc, be) = m.face_bounds(f);
                        let moved_center = [bc[0] + off[0], bc[1] + off[1], bc[2] + off[2]];
                        if WORLD_BOUNDS_CULL && !visibility.sphere(moved_center, be) {
                            continue;
                        }
                        emit_submodel_face(
                            &mut packets,
                            &m,
                            f,
                            first,
                            cnt,
                            submodel_token,
                            &mut np,
                        );
                    }
                    reset_emit_policy();
                    map::tex_anim_select(false);
                }
                if brush_pass == 0
                    && (world_cache_action == WORLD_CACHE_BUILD
                        || world_cache_action == WORLD_CACHE_BRUSH_REBUILD)
                {
                    finish_world_packet_cache(
                        world_cache_key,
                        np,
                        nq,
                        world_cache_emit_calls,
                        room_affine_split_tris,
                    );
                }
                brush_pass += 1;
            }
            SUBMODEL_ACTOR_OVERLAP = false;
            // Delay this snapshot until both passes have used the prior visual
            // state for the same cacheability decision and key.
            for ei in 0..nents {
                ENT_RENDER_PHASE[ei] = ENT_PHASE[ei];
            }
            telemetry::stage_end(telemetry::stage::MODEL_BOUNDS);

            // Tram car: render its submodel at the current ride offset, ROTATED
            // to face its direction of travel (the car yaws through the tunnel
            // curves instead of sliding sideways). Rotation is about the car's
            // authored path-attach point (tram_ref + ride_off); mirrors the
            // func_rotating pivot math. Plane/bounds culls are skipped.
            telemetry::stage_begin(telemetry::stage::MODEL_DRAW);
            if m.tram_submodel > 0 && m.tram_submodel < m.n_models {
                model_draws = model_draws.saturating_add(1);
                reset_emit_policy(); // opaque: don't inherit a glass ent's blend
                                     // Draw the car at the same inter-tick phase as the camera:
                                     // locked-ride frames then keep a bit-stable car-to-camera
                                     // transform, so the packet cache holds through the ride
                                     // instead of only while parked (render-only; the sim pose,
                                     // collision mover and carry logic keep the tick values).
                #[cfg(feature = "decoupled-present")]
                let (ride_off_draw, tram_yaw_draw) = interpolated_tram_pose(render_phase_q12);
                #[cfg(not(feature = "decoupled-present"))]
                let (ride_off_draw, tram_yaw_draw) = (ride_off, tram_yaw_render);
                let tram_rot = tram_world_rotation(tram_yaw_draw);
                let mr = rot.mul(&tram_rot);
                let train_pos = [
                    tram_ref[0] + ride_off_draw[0],
                    tram_ref[1] + ride_off_draw[1],
                    tram_ref[2] + ride_off_draw[2],
                ];
                let tp_e = [
                    train_pos[0] - eye[0],
                    train_pos[1] - eye[1],
                    train_pos[2] - eye[2],
                ];
                let tbw = [
                    m.tram_base[0] - tram_ref[0],
                    m.tram_base[1] - tram_ref[1],
                    m.tram_base[2] - tram_ref[2],
                ];
                // Face planes are authored in tram-local space. Transform the
                // eye there once, then reject back-facing car surfaces before
                // their vertices reach the expensive near-projection path.
                let eye_from_train = [
                    eye[0] - train_pos[0],
                    eye[1] - train_pos[1],
                    eye[2] - train_pos[2],
                ];
                let tram_eye = [
                    dot12(
                        [tram_rot.m[0][0], tram_rot.m[1][0], tram_rot.m[2][0]],
                        eye_from_train,
                    ) - tbw[0],
                    dot12(
                        [tram_rot.m[0][1], tram_rot.m[1][1], tram_rot.m[2][1]],
                        eye_from_train,
                    ) - tbw[1],
                    dot12(
                        [tram_rot.m[0][2], tram_rot.m[1][2], tram_rot.m[2][2]],
                        eye_from_train,
                    ) - tbw[2],
                ];
                let et = [
                    dot12(rot.m[0], tp_e) + dot12(mr.m[0], tbw),
                    dot12(rot.m[1], tp_e) + dot12(mr.m[1], tbw),
                    dot12(rot.m[2], tp_e) + dot12(mr.m[2], tbw),
                ];
                let cache_hit = TRAM_PACKET_CACHE
                    && TRAM_CACHE_VALID
                    && TRAM_CACHE_ROT == mr.m
                    && TRAM_CACHE_T == et
                    && TRAM_CACHE_EYE == tram_eye;
                if cache_hit {
                    let mut ti = 0usize;
                    let mut qi = 0usize;
                    while ti < TRAM_TRI_COUNT || qi < TRAM_QUAD_COUNT {
                        if qi < TRAM_QUAD_COUNT && TRAM_QUAD_AFTER_TRIS[qi] as usize <= ti {
                            OT.add(
                                TRAM_QUAD_OTZ[qi] as usize,
                                &mut TRAM_QUAD_CACHE[qi],
                                QuadTexturedGouraud::WORDS,
                            );
                            qi += 1;
                        } else if ti < TRAM_TRI_COUNT {
                            OT.add(
                                TRAM_TRI_OTZ[ti] as usize,
                                &mut TRAM_TRI_CACHE[ti],
                                TriTexturedGouraud::WORDS,
                            );
                            ti += 1;
                        }
                    }
                    np += TRAM_TRI_COUNT + TRAM_QUAD_COUNT;
                } else {
                    scene::load_rotation(&mr);
                    scene::load_translation(Vec3I32::new(et[0], et[1], et[2]));
                    set_view_fix(&mr, et);
                    let submodel_token = next_proj_token();
                    let (ff, nf) = m.submodel(m.tram_submodel);
                    TRAM_TRI_COUNT = 0;
                    TRAM_QUAD_COUNT = 0;
                    TRAM_CACHE_OVERFLOW = false;
                    TRAM_CACHE_BUILDING = TRAM_PACKET_CACHE;
                    // The c0a0 car has 341 faces but only 118 signed plane
                    // groups (some planes are shared by 12 faces). Reuse the
                    // world visibility bits after world emission and compute
                    // each tram-local facing verdict once per group.
                    clear_group_bits(group_seen);
                    for f in ff..ff + nf {
                        set_emit_face(&m, f, 0);
                        let (first, cnt) = m.face_tris(f);
                        let group = m.face_group(f);
                        if !scratch_bit(group_seen, group) {
                            scratch_bit_assign(group_seen, group, true);
                            let (fnrm, fd) = m.face_plane(f);
                            scratch_bit_assign(group_vis, group, dot_plane(fnrm, tram_eye) > fd);
                        }
                        if !scratch_bit(group_vis, group) {
                            model_culled_tris = model_culled_tris.saturating_add(cnt as u32);
                            continue;
                        }
                        emit_submodel_face(
                            &mut packets,
                            &m,
                            f,
                            first,
                            cnt,
                            submodel_token,
                            &mut np,
                        );
                    }
                    reset_emit_policy();
                    TRAM_CACHE_BUILDING = false;
                    if !TRAM_PACKET_CACHE || TRAM_CACHE_OVERFLOW {
                        TRAM_CACHE_VALID = false;
                    } else {
                        TRAM_CACHE_ROT = mr.m;
                        TRAM_CACHE_T = et;
                        TRAM_CACHE_EYE = tram_eye;
                        TRAM_CACHE_VALID = true;
                    }
                }
                scene::load_rotation(&rot); // restore the world transform for later draws
                set_view_fix(&rot, base_t);
                reset_emit_policy();
            }
            telemetry::stage_end(telemetry::stage::MODEL_DRAW);

            // Studio actors placed by map entities plus any runtime fallback
            // enemies. Models are baked to posed frames by the host cooker; the
            // PS1 path only chooses the current actor frame.
            telemetry::stage_begin(telemetry::stage::TEXTURED_MODEL_JOINTS);
            invalidate_actor_occlusion(have_pvs, cam_leaf, eye);
            // Brush/tram passes leave entity-local matrices behind. Restore the
            // camera once, then use one GTE MVMVA per actor sphere instead of
            // four repeated scalar dot products across the far/frustum tests.
            scene::load_rotation(&rot);
            scene::load_translation(Vec3I32::new(base_t[0], base_t[1], base_t[2]));
            let render_movers = core::slice::from_raw_parts(
                core::ptr::addr_of!(MOVERS).cast::<phys::Mover>(),
                MOVER_COUNT.min(MAX_ENTS + 1),
            );
            // Use the unused map/model tail for the contiguous actor stream.
            // Leave both weapon-cache regions and their guard untouched: a
            // later weapon switch may write them even if no cache is live yet.
            let tail_start = VM_TAIL_CACHE_WORDS + VM_TAIL_BACKUP_WORDS + VM_TAIL_GUARD_WORDS;
            let tail_words = vm_tail_capacity_words().saturating_sub(tail_start);
            let model_packet_capacity = packets.remaining_words();
            let use_model_tail = tail_words > model_packet_capacity;
            let mut model_packet_reservation = if use_model_tail {
                None
            } else {
                packets.reserve_packet_words(model_packet_capacity)
            };
            let mut empty_model_packet_words: [u32; 0] = [];
            let model_packet_words = if use_model_tail {
                core::slice::from_raw_parts_mut(
                    model_ptr().add(MODEL_RESIDENT_WORDS + tail_start),
                    tail_words,
                )
            } else if let Some(reservation) = model_packet_reservation.as_mut() {
                reservation.words_mut()
            } else {
                &mut empty_model_packet_words
            };
            let model_stream_start = model_packet_words.as_mut_ptr();
            let mut model_packets = ModelPacketWriter {
                words: model_packet_words,
                used_words: 0,
                packet_count: 0,
            };
            let actor_count = PROP_COUNT.min(CARRY_MAILBOX_FIRST);
            for pi in 0..actor_count {
                if PROP_ACTIVE[pi] == 0 {
                    continue;
                }
                let ty = PROP_KIND[pi];
                if ty == PROP_TYPE_HOLO && PROP_DORMANT[pi] & PROP_RUNTIME_RENDER_HIDDEN != 0 {
                    continue;
                }
                let sim_org = PROP_POS[pi];
                let (org, yaw) = prop_render_transform(pi);
                let cooked_leaf = PROP_LEAF[pi];
                let slot = TYPE_TO_SLOT[(ty as usize).min(N_MODEL_TYPES - 1)];
                if slot == MODEL_SLOT_NONE {
                    continue; // type not resident this map (overflow or missing)
                }
                let lm = LOADED_MODELS[slot as usize];
                if !lm.valid {
                    continue;
                }
                model_bounds_tests = model_bounds_tests.saturating_add(1);
                // PROP_LEAF is maintained by prop_set_pos on every move, so
                // movers (headcrabs included) are as fresh as their last step;
                // only a bad/unknown leaf falls back to a full BSP walk.
                let prop_leaf = if cooked_leaf > 0 {
                    cooked_leaf as i32
                } else {
                    camera_leaf(&m, sim_org)
                };
                let radius = prop_render_radius(pi, ty);
                // One authoritative query combines the current PVS snapshot
                // with the same camera planes used for world faces and brush
                // entities. Do authored pose/body/mouth work only after it.
                if !visibility.actor_bounds(&m, prop_leaf, org, radius) {
                    model_bounds_culled = model_bounds_culled.saturating_add(1);
                    continue;
                }
                let occ_slot = pi.min(MAX_PROPS - 1);
                let occ = PROP_OCC_VIS[occ_slot];
                if (occ & PROP_OCC_DIRTY != 0 || occ & PROP_OCC_VISIBLE == 0)
                    && (pi as u32).wrapping_add(sim_frame_no) % 4 == 0
                {
                    let gameplay = PROP_OCC_VIS[occ_slot] & PROP_OCC_GAMEPLAY_MASK;
                    PROP_OCC_VIS[occ_slot] = gameplay
                        | visibility.actor_occlusion(&m, render_movers, eye, ty, org) as u8;
                }
                if PROP_OCC_VIS[occ_slot] & PROP_OCC_VISIBLE == 0 {
                    model_bounds_culled = model_bounds_culled.saturating_add(1);
                    continue;
                }
                let packed_yaw = PROP_YAW[pi];
                let body = if ty == PROP_TYPE_BARNEY {
                    if PROP_STATE[pi] == PROP_STATE_DEAD || PROP_HEALTH[pi] == 0 {
                        2
                    } else if PROP_AI_TARGET[pi] != PROP_TARGET_NONE
                        || PROP_STATE[pi] == PROP_STATE_ATTACK
                    {
                        1
                    } else {
                        0
                    }
                } else {
                    prop_body_value(packed_yaw)
                };
                let mouth = if prop_is_human(ty) {
                    prop_mouth_open(pi, SIM_NOW, launch.room_id)
                } else {
                    0
                };
                // Passed every cull: only now parse the blob header for drawing.
                let md_owned = loaded_model(slot as usize);
                let md = &md_owned;
                let slots = &POOL_TEX[lm.tex_start..lm.tex_start + lm.n_tex];
                let face_indices = core::ptr::addr_of!(POOL_FACE_INDICES)
                    .cast::<u32>()
                    .add(lm.face_start);
                let face_payloads = core::ptr::addr_of!(POOL_FACE_PAYLOADS)
                    .cast::<ModelRenderFacePayload>()
                    .add(lm.face_start);
                let face_runs = core::ptr::addr_of!(POOL_FACE_RUNS)
                    .cast::<u32>()
                    .add(lm.run_start as usize);
                let face_count = lm.n_faces;
                model_draws = model_draws.saturating_add(1);
                let (sf, sf2, sfrac) = if ty == PROP_TYPE_ITEM_SUIT || ty == PROP_TYPE_ITEM_BATTERY
                {
                    (0, 0, 0)
                } else {
                    prop_anim_frame(&m, md, PROP_STATE[pi], PROP_HIT_FLASH[pi], sim_frame_no, pi)
                };
                let base_shade = if ty == PROP_TYPE_ITEM_SUIT || ty == PROP_TYPE_ITEM_BATTERY {
                    128
                } else if ty == PROP_TYPE_HOLO {
                    96
                } else if pi < MAX_PROPS && PROP_HIT_FLASH[pi] > 0 {
                    MODEL_HIT_SHADE
                } else {
                    MODEL_SHADE
                };
                let shade = flashlight_model_shade(
                    base_shade,
                    [org[0], org[1] + model_def(ty).target_h / 2, org[2]],
                    eye,
                    &rot,
                );
                model_projected_vertices = model_projected_vertices.saturating_add(draw_model(
                    &mut model_packets,
                    md,
                    slots,
                    face_indices,
                    face_payloads,
                    face_runs,
                    lm.n_runs as usize,
                    face_count,
                    org,
                    yaw,
                    prop_authored_tilt(&m, pi),
                    body,
                    mouth,
                    sf,
                    sf2,
                    sfrac,
                    if ty == PROP_TYPE_HOLO {
                        BlendMode::Add
                    } else {
                        BlendMode::Opaque
                    },
                    shade,
                    eye,
                    &rot,
                    &mut np,
                ));
                // HMD8 projection leaves the final bone affine resident. The
                // next actor's GTE sphere test needs the world camera again.
                scene::load_rotation(&rot);
                scene::load_translation(Vec3I32::new(base_t[0], base_t[1], base_t[2]));
            }
            if DBG_MODEL_SHOWCASE {
                let mut k = 0i32;
                for slot in 0..MAX_LOADED_MODELS {
                    let lm = LOADED_MODELS[slot];
                    if !lm.valid || lm.type_id < 5 {
                        continue; // enemies only (skip NPCs/items)
                    }
                    let md = loaded_model(slot);
                    let slots = &POOL_TEX[lm.tex_start..lm.tex_start + lm.n_tex];
                    let face_indices = core::ptr::addr_of!(POOL_FACE_INDICES)
                        .cast::<u32>()
                        .add(lm.face_start);
                    let face_payloads = core::ptr::addr_of!(POOL_FACE_PAYLOADS)
                        .cast::<ModelRenderFacePayload>()
                        .add(lm.face_start);
                    let face_runs = core::ptr::addr_of!(POOL_FACE_RUNS)
                        .cast::<u32>()
                        .add(lm.run_start as usize);
                    let fwd = rot.m[2];
                    let right = rot.m[0];
                    let side = k * 130 - 130;
                    let pos = [
                        eye[0] + ((fwd[0] as i32 * 240 + right[0] as i32 * side) >> 12),
                        eye[1] + ((fwd[1] as i32 * 240 + right[1] as i32 * side) >> 12) - 40,
                        eye[2] + ((fwd[2] as i32 * 240 + right[2] as i32 * side) >> 12),
                    ];
                    draw_model(
                        &mut model_packets,
                        &md,
                        slots,
                        face_indices,
                        face_payloads,
                        face_runs,
                        lm.n_runs as usize,
                        lm.n_faces,
                        pos,
                        0,
                        0,
                        0,
                        0,
                        {
                            // Tick-rate animation phase: presented-frame count
                            // no longer maps to time once presentation
                            // decouples from the simulation.
                            #[cfg(feature = "decoupled-present")]
                            let phase = sim_frame_no as usize;
                            #[cfg(not(feature = "decoupled-present"))]
                            let phase = frame_no as usize;
                            (phase / 8) % md.n_frames.max(1)
                        },
                        0,
                        0,
                        BlendMode::Opaque,
                        MODEL_SHADE,
                        eye,
                        &rot,
                        &mut np,
                    );
                    k += 1;
                }
            }
            let model_packet_words = model_packets.used_words;
            let model_packet_count = model_packets.packet_count;
            drop(model_packets);
            if let Some(reservation) = model_packet_reservation {
                let _ = reservation
                    .commit(model_packet_words, model_packet_count)
                    .expect("model packet stream exceeded its arena reservation");
            }
            // Both storage choices stay live until the next frame's DMA fence.
            insert_model_depth_stream(
                model_stream_start,
                model_stream_start.add(model_packet_words),
            );
            telemetry::stage_end(telemetry::stage::TEXTURED_MODEL_JOINTS);
            // ---- Sprite billboards (env_sprite / env_glow) ----
            // Independent compact records keep dense effects from consuming actor
            // slots. Drawn as camera-facing additive quads and PVS-culled by leaf.
            {
                let nsp = SPRITE_COUNT;
                let mut si = 0usize;
                while si < nsp {
                    let i = si;
                    let (org, leaf, _name, packed) = m.sprite_prop(i);
                    si += 1;
                    if !sprite_is_visible(i) {
                        continue;
                    }
                    let id = (packed & map::SPRITE_ID_MASK) as usize;
                    if id >= sprite::n_sprites() {
                        continue;
                    }
                    if !visibility.leaf(&m, leaf as i32) {
                        continue;
                    }
                    let d = sprite::def(id);
                    let nframes = d.n_frames.max(1) as usize;
                    let age = (sim_frame_no as u16).wrapping_sub(SPRITE_STARTED[i]) as usize;
                    let mut sprite_frame = age / 2; // GoldSrc sprites default to ~10 fps
                    if packed & map::SPRITE_ONCE != 0 && sprite_frame >= nframes {
                        sprite_set_visible(i, false, sim_frame_no as u16);
                        continue;
                    }
                    sprite_frame %= nframes;
                    let half = (packed >> 6) as i32;
                    let hh = if d.base_w > 0 {
                        half * d.base_h as i32 / d.base_w as i32
                    } else {
                        half
                    };
                    draw_billboard(
                        &mut packets,
                        &mut np,
                        org,
                        half,
                        hh,
                        id,
                        sprite_frame,
                        &rot,
                        base_t,
                    );
                }
            }
            // Animated explosion fireballs (weapon blasts + env_explosion), same
            // additive-billboard path as the placed sprites above.
            render_explosions(&mut packets, &mut np, &rot, base_t);
            queue_rpg_spot(&mut packets, &mut OT, &rot, base_t);
            telemetry::stage_end(telemetry::stage::MODEL_INSTANCES);
            telemetry::counter(telemetry::counter::MODEL_INSTANCE_DRAWS, model_draws);
            telemetry::counter(
                telemetry::counter::MODEL_INSTANCE_BOUNDS_TESTS,
                model_bounds_tests,
            );
            telemetry::counter(
                telemetry::counter::MODEL_INSTANCE_BOUNDS_CULLED,
                model_bounds_culled,
            );
            telemetry::counter(
                telemetry::counter::MODEL_INSTANCE_CULLED_TRIS,
                model_culled_tris,
            );
            telemetry::counter(
                telemetry::counter::MODEL_INSTANCE_SUBMITTED_TRIS,
                (np.saturating_sub(model_prims0) + nq.saturating_sub(model_quads0) * 2) as u32,
            );
            telemetry::counter(
                telemetry::counter::MODEL_INSTANCE_PROJECTED_VERTICES,
                model_projected_vertices,
            );
            #[cfg(any(feature = "emulator-telemetry", feature = "performance-telemetry"))]
            telemetry::counter(
                telemetry::counter::MODEL_INSTANCE_DROPPED_TRIS,
                MODEL_PACKET_DROPS,
            );

            let world_prims = np;
            let world_quads = nq;
            let mut viewmodel_screen_off = [0i16; 2];
            let draw_viewmodel_now = SHOW_VIEWMODEL && weapon.any_weapon();
            WEAPON_MUZZLE_SLOT = weapon.current;
            let viewmodel_draw = if draw_viewmodel_now {
                let vm_off = viewmodel_offset(recoil, sim_frame_no);
                viewmodel_screen_off = [
                    (vm_off[0] * VM_SCREEN_PX_PER_UNIT) as i16,
                    (vm_off[1] * VM_SCREEN_PX_PER_UNIT) as i16,
                ];
                let requested_wm = weapon_viewmodel(weapon.current, satchel_mode);
                let (vm_model, vm_slot, vm_n, vm_weapon) = viewmodel_for(requested_wm);
                let (vm_frame, vm_frame2, vm_frac16) = viewmodel_anim_frame(
                    &vm_model,
                    vm_weapon,
                    viewmodel_anim,
                    viewmodel_anim_start,
                    sim_frame_no,
                    (grenade_cooking
                        && weapon.current == W_GRENADE
                        && viewmodel_anim == VM_ANIM_ALT)
                        || (weapon.current == W_GAUSS
                            && weapon.gauss_charge != 0
                            && viewmodel_anim == VM_ANIM_ALT),
                );
                Some((vm_model, vm_slot, vm_n, vm_frame, vm_frame2, vm_frac16))
            } else {
                None
            };
            let draw_regular_hud =
                if launch.room_id == FINAL_ROOM_ID && sim_frame_no > ENDING_SCENE_TICKS {
                    // Outro: the G-Man scene has played out -- fade to white.
                    let t = (sim_frame_no - ENDING_SCENE_TICKS).min(ENDING_FADE_TICKS);
                    let w = (t * 255 / ENDING_FADE_TICKS) as u8;
                    unsafe {
                        DEATH_WASH = 0;
                        DEATH_OVERLAY = RectFlat::new(0, 0, 320, 240, w, w, w);
                        HUD_OT.add(0, &mut DEATH_OVERLAY, RectFlat::WORDS);
                    }
                    if t >= ENDING_FADE_TICKS {
                        return PlayExit::Ending;
                    }
                    false
                } else if death_ticks > 0 {
                    // Death: HL washes the view red and you keep watching the
                    // room. The blended pass lives in `draw_screen_fx`; here we
                    // only ramp its level over the death window.
                    DEATH_WASH = (((DEATH_TICKS - death_ticks) as u32) * 5).min(190) as u8;
                    false
                } else {
                    DEATH_WASH = 0;
                    true
                };
            queue_world_beams(&mut packets, &mut OT, &m, nlogic, &rot, base_t);

            // Present the previous frame at the last possible moment. Camera,
            // visibility, world emit, entities and models touch neither the
            // framebuffer nor any packet storage that is still live -- every
            // DMA walk completed at the end of the last iteration -- so the
            // whole build hides what is left of the previous frame's raster.
            // This must stay ahead of the clear that overwrites its buffer.
            // Non-decoupled late frames still present here with the blocking
            // edge wait: swapping mid-scanout tears on hardware and leaves an
            // accuracy compositor showing the buffer this frame is about to
            // clear -- black regions in gameplay.
            #[cfg(not(feature = "decoupled-present"))]
            if present_pending {
                telemetry::stage_begin(telemetry::stage::PRESENT);
                gpu::draw_sync();
                wait_vblank_edge();
                fb.swap();
                telemetry::stage_end(telemetry::stage::PRESENT);
                present_pending = false;
            }
            // Decoupled: the flip was queued before the build. At ride pace
            // the edge passed long ago and this is one volatile load; only a
            // frame built inside a single VBlank interval (the 60 fps cap
            // case) waits. Gating the clear on the applied flip is what keeps
            // the displayed buffer untouched -- never clear before the flip.
            #[cfg(feature = "decoupled-present")]
            if flip_queued {
                telemetry::stage_begin(telemetry::stage::PRESENT);
                while interrupts::gp1_queue_pending() {}
                telemetry::stage_end(telemetry::stage::PRESENT);
                // The VBlank handler consumes the queued flip only while the
                // GPU is idle. Program the new draw side here, after that
                // proof, so these GP0 writes can never collect the previous
                // frame's raster backlog at build start.
                fb.apply_draw_target();
                flip_queued = false;
            }
            telemetry::stage_begin(telemetry::stage::FRAME_CLEAR);
            fb.clear(0, 0, 0);
            draw_sky(&m, yaw, pitch);
            telemetry::stage_end(telemetry::stage::FRAME_CLEAR);

            // DEBUG: if the draw picked nothing under the crosshair (a quad or a
            // genuinely missing/culled triangle), sweep the PVS faces so it still
            // highlights + dumps. Reload the world GTE transform first -- the
            // entity passes left their own loaded.
            if DEBUG_XHAIR && XHAIR.valid == 0 && have_pvs {
                scene::load_rotation(&rot);
                scene::load_translation(Vec3I32::new(base_t[0], base_t[1], base_t[2]));
                set_view_fix(&rot, base_t);
                xhair_pick_pvs(&m, nv, proj_token);
            }

            // DEBUG: fill the crosshair tri bright magenta (a POLYGON -- the HW
            // renderer skips PS1 line prims, so an outline is invisible in the GUI)
            // at the front OT slot so it draws on top. Also resolve its world verts /
            // leaf / PVS state for the L1 dump.
            if DEBUG_XHAIR && XHAIR.valid != 0 {
                let mut cen = [0i32; 3];
                let mut k = 0;
                while k < 3 {
                    let vv = m.vert(XHAIR.idx[k] as usize);
                    XHAIR.v[k] = [vv.x as i32, vv.y as i32, vv.z as i32];
                    cen[0] += XHAIR.v[k][0];
                    cen[1] += XHAIR.v[k][1];
                    cen[2] += XHAIR.v[k][2];
                    k += 1;
                }
                XHAIR.leaf = camera_leaf(&m, [cen[0] / 3, cen[1] / 3, cen[2] / 3]);
                XHAIR.pvs_visible = visibility.known_leaf(&m, XHAIR.leaf) as u32;
                let v = XHAIR.sv;
                let fill = psx_gpu::prim::TriFlat::new([v[0], v[1], v[2]], 255, 0, 255);
                if let Some(pk) = packets.push(fill) {
                    OT.add(1, pk, psx_gpu::prim::TriFlat::WORDS);
                } else {
                    note_render_packet_drop(false);
                }
            }

            telemetry::stage_begin(telemetry::stage::WORLD_FLUSH);
            OT.submit_async();
            // HUD and effect projection only touch their own packet storage.
            // Build them while channel 2 walks the world list, hiding this CPU
            // work without changing either ordering table or draw order.
            if draw_regular_hud {
                let _ = hud::draw(
                    hud_mat,
                    suit_equipped,
                    flashlight,
                    flashlight_battery,
                    weapon.any_weapon(),
                    zoom_aim,
                    health,
                    armor,
                    weapon.clip_display(),
                    weapon.reserve_display(),
                    weapon.ammo[AMMO_ARGREN],
                    weapon.ammo_mode(),
                    pickup_kind,
                    pickup_ticks,
                    if weapon.any_weapon() {
                        weapon.current as i32
                    } else {
                        -1
                    },
                    weapon_icon_ticks,
                    train_hud_position(tram_controlling, tram_speed, unsafe {
                        TRACKTRAIN_USE_SPEED as i32
                    }),
                    &mut HUD_OT,
                    &mut HUD_PRIMS,
                );
            }
            let _ = render_impact_marks(&mut FX_OT, &mut IMPACT_MARK_RECTS, &rot, base_t);
            let _ =
                IMPACT_PARTICLES.render_into_ot(&mut FX_OT, &mut IMPACT_PARTICLE_RECTS, 0, (0, 0));
            render_projectiles(&mut FX_OT, &rot, base_t);
            render_debris(&mut FX_OT, &rot, base_t);
            // Hide CPU-only HMD8 projection/cull/sort behind the world's DMA.
            // Packet/cache storage is disjoint and remains live until the wait.
            if let Some((vm_model, vm_slot, vm_n, vm_frame, vm_frame2, vm_frac16)) = viewmodel_draw
            {
                telemetry::stage_begin(telemetry::stage::EQUIPMENT);
                draw_viewmodel(
                    &vm_model,
                    &VM_SLOTS[vm_slot..vm_slot + vm_n],
                    vm_frame,
                    vm_frame2,
                    vm_frac16,
                    false,
                );
                telemetry::stage_end(telemetry::stage::EQUIPMENT);
            }
            gpu::submit_linked_list_wait();
            FX_OT.submit();
            telemetry::stage_end(telemetry::stage::WORLD_FLUSH);
            telemetry::stage_begin(telemetry::stage::OT_SUBMIT);
            let draw_y = fb.buffer_y(fb.drawing) as i16;
            if viewmodel_screen_off != [0; 2] {
                gpu::set_draw_offset(
                    viewmodel_screen_off[0],
                    draw_y.saturating_add(viewmodel_screen_off[1]),
                );
            }
            if let Some((vm_model, vm_slot, vm_n, vm_frame, vm_frame2, vm_frac16)) = viewmodel_draw
            {
                telemetry::stage_begin(telemetry::stage::EQUIPMENT);
                let submitted = draw_viewmodel(
                    &vm_model,
                    &VM_SLOTS[vm_slot..vm_slot + vm_n],
                    vm_frame,
                    vm_frame2,
                    vm_frac16,
                    true,
                );
                telemetry::stage_end(telemetry::stage::EQUIPMENT);
                telemetry::counter(
                    telemetry::counter::EQUIPMENT_SUBMITTED_TRIS,
                    submitted as u32,
                );
            }
            if viewmodel_screen_off != [0; 2] {
                gpu::set_draw_offset(0, draw_y);
            }
            hud::prepare(hud_mat, &mut HUD_OT, &mut HUD_ENV);
            HUD_OT.submit();
            telemetry::stage_end(telemetry::stage::OT_SUBMIT);
            // Capture the overlay pass into a DMA chain instead of writing it
            // to GP0 a word at a time. Identical words in identical order; the
            // gain is that the CPU stops fencing on the frame's raster.
            fx_chain_reset();
            FX_ARENA = (&mut packets as *mut PrimitivePacketArena<'_>).cast();
            FX_CAPTURE = true;
            if SHOW_VIEWMODEL && recoil >= 13 && MUZZLE_FLASH_WEAPONS[weapon.current] {
                draw_muzzle_flash(sim_frame_no);
            }
            draw_damage_compass(health);
            draw_screen_fx(&m, suit_equipped);
            if settings::debug_on(settings::DEBUG_STATS) {
                draw_debug_stats(
                    launch.room_id as i32,
                    eye,
                    cam_leaf,
                    player.pos,
                    yaw as i32,
                    pitch as i32,
                );
            }
            FX_CAPTURE = false;
            fx_chain_submit();
            FX_ARENA = core::ptr::null_mut();

            // DEBUG: dump the crosshair tri + camera state to PSoXide's Play debug
            // terminal. Auto-fires whenever the aimed triangle (or valid state)
            // changes -- so you just aim, no controller button needed -- plus a
            // manual L1 re-dump. Lets the same tri be compared between a frame
            // where it shows and one where it is missing.
            if DEBUG_XHAIR {
                let dump_now = poll_port1().buttons.is_held(button::L1);
                let key = if XHAIR.valid != 0 {
                    XHAIR.tt
                } else {
                    u32::MAX - 1
                };
                // Fire on L1, on aimed-triangle change, AND every ~2s so steady
                // aim still produces a visible line.
                let periodic = frame_no % 16 == 0;
                if (dump_now && !XHAIR_DUMP_PREV) || key != XHAIR_DUMP_LAST || periodic {
                    xhair_dump(
                        eye,
                        yaw,
                        pitch,
                        cam_leaf,
                        (np + nq) as i32,
                        PVS_FACE_COUNT as i32,
                    );
                    XHAIR_DUMP_LAST = key;
                }
                XHAIR_DUMP_PREV = dump_now;
            }
            // Arena pressure excludes the separately resident viewmodel cache.
            // `remaining` is conservative GT4-sized capacity; the packet count
            // may exceed the old fixed-slot limit when compact GT3s reclaim
            // their former three-word padding.
            WORLD_AFFINE_LAST_FRAME_FREE = packets.remaining().min(u16::MAX as usize) as u16;
            WORLD_AFFINE_LAST_ACTUAL_EXTRA_EMITTED = WORLD_AFFINE_ACTUAL_EXTRA_EMITTED;
            telemetry::counter(telemetry::counter::TRI_PRIMITIVES, packets.len() as u32);
            telemetry::counter(
                telemetry::counter::WORLD_COMMANDS,
                (world_prims + world_quads) as u32,
            );
            telemetry::counter(
                telemetry::counter::ROOM_SURF_SPLIT_TRIS,
                room_affine_split_tris,
            );
            telemetry::counter(
                telemetry::affine_counter::ERROR_MAX_Q8,
                WORLD_AFFINE_ERROR_MAX_Q8,
            );
            telemetry::counter(
                telemetry::affine_counter::ERROR_P50_Q8,
                WORLD_AFFINE_ERROR_P50_Q8,
            );
            telemetry::counter(
                telemetry::affine_counter::ERROR_P95_Q8,
                WORLD_AFFINE_ERROR_P95_Q8,
            );
            telemetry::counter(
                telemetry::affine_counter::ERROR_P99_Q8,
                WORLD_AFFINE_ERROR_P99_Q8,
            );
            telemetry::counter(
                telemetry::affine_counter::SPLIT_CANDIDATES,
                WORLD_AFFINE_SPLIT_CANDIDATES,
            );
            telemetry::counter(
                telemetry::affine_counter::EXTRA_PACKETS_REQUESTED,
                WORLD_AFFINE_EXTRA_REQUESTED,
            );
            telemetry::counter(
                telemetry::affine_counter::EXTRA_PACKETS_EMITTED,
                WORLD_AFFINE_EXTRA_EMITTED,
            );
            telemetry::counter(
                telemetry::affine_counter::LOWEST_SELECTED_PRIORITY,
                WORLD_AFFINE_LOWEST_SELECTED_PRIORITY as u32,
            );
            telemetry::counter(
                telemetry::affine_counter::HIGHEST_REJECTED_PRIORITY,
                WORLD_AFFINE_HIGHEST_REJECTED_PRIORITY as u32,
            );
            telemetry::counter(
                telemetry::affine_counter::SPLIT_PATCHES,
                WORLD_AFFINE_SPLIT_PATCHES,
            );
            telemetry::counter(
                telemetry::affine_counter::ADDED_GTE_TRANSFORMS,
                WORLD_AFFINE_ADDED_GTE_TRANSFORMS,
            );
            telemetry::counter(
                telemetry::affine_counter::REMAINING_ERROR_MAX_Q8,
                WORLD_AFFINE_REMAINING_MAX_Q8,
            );
            telemetry::counter(
                telemetry::affine_counter::REMAINING_ERROR_P50_Q8,
                WORLD_AFFINE_REMAINING_P50_Q8,
            );
            telemetry::counter(
                telemetry::affine_counter::REMAINING_ERROR_P95_Q8,
                WORLD_AFFINE_REMAINING_P95_Q8,
            );
            telemetry::counter(
                telemetry::affine_counter::REMAINING_ERROR_P99_Q8,
                WORLD_AFFINE_REMAINING_P99_Q8,
            );
            telemetry::counter(
                telemetry::counter::ROOM_SURF_WHOLE_QUADS,
                WORLD_AFFINE_NATIVE_GT4,
            );
            telemetry::counter(
                telemetry::counter::TRI_PRIMITIVE_REMAINING,
                packets.remaining() as u32,
            );
            #[cfg(any(feature = "emulator-telemetry", feature = "performance-telemetry"))]
            telemetry::counter(
                telemetry::counter::ROOM_SUBMIT_PRIMITIVE_OVERFLOWS,
                RENDER_PACKET_DROPS,
            );
        }

        telemetry::stage_end(telemetry::stage::RENDER);
        // A frame that still has slack before the next simulation deadline
        // presents here, exactly as it always did: the CPU would only idle in
        // `wait_until_vblank` anyway, so fencing the GPU now is free and the
        // image reaches the screen at the earliest VBlank.
        //
        // A frame that is already late defers instead. Every DMA channel-2
        // walk has completed by this point -- the arenas and ordering tables
        // are free to rebuild and only rasterisation is outstanding -- so the
        // next simulation tick can run underneath the raster backlog rather
        // than behind it. That is where the time is: on a slow frame the GPU
        // tail is otherwise serialised after all of the CPU's work.
        #[cfg(feature = "decoupled-present")]
        {
            // Always defer: the present overlaps the next frame's entire CPU
            // build instead of spinning out the rest of this VBlank interval,
            // which the decoupled profile measured as ~40% of a typical frame.
            present_pending = true;
        }
        #[cfg(not(feature = "decoupled-present"))]
        if vblank_reached(interrupts::vblank_count(), next_sim_vblank) {
            present_pending = true;
        } else {
            telemetry::stage_begin(telemetry::stage::PRESENT);
            gpu::draw_sync();
            wait_vblank_edge();
            fb.swap();
            telemetry::stage_end(telemetry::stage::PRESENT);
        }
        // Match psx-engine's deadline semantics: a miss is a visual interval
        // that was due but could not be presented, not a permanent phase
        // offset from the boot-time VBlank origin. A one-off cold-cache frame
        // can otherwise leave every later on-time 3-VBlank frame reported as
        // late forever. Extra fixed ticks consumed above are the intervals
        // that this custom 20 Hz loop genuinely skipped.
        let missed_visual_intervals = ticks_this_visual.saturating_sub(1);
        let lateness_vblanks =
            missed_visual_intervals.saturating_mul(SIM_VBLANKS.min(u16::MAX as u32) as u16);
        telemetry::counter(telemetry::counter::VISUAL_FRAMES, 1);
        if missed_visual_intervals > 0 {
            telemetry::counter(telemetry::counter::VISUAL_DEADLINE_MISSES, 1);
        }
        telemetry::counter(
            telemetry::counter::VISUAL_MAX_LATENESS_VBLANKS,
            lateness_vblanks as u32,
        );
        telemetry::task_end(telemetry::task::VISUAL_RENDER);
    }
}
